  Item_10022_Desc = {
    Text = "당신은 불멸할 것이다.\n초월적 존재에서 나온 기억의 결정체로, 미사그 상점에서 상품으로 교환할 수 있다."
  },
  Item_10022_Name = {
    Text = "초월의 별 (이미 폐기됨)"
  },
  Item_10023_Desc = {
    Text = "기획자 실타래험용 R 등급 무기"
  },
  Item_10023_Name = {
    Text = "시작용 소도 (경계) 개발용"
  },
  Item_10023_StoryDesc = {Text = "미완성"},
  Item_10024_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n로탄을 반복 획득할 때 전환하여 로탄의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10024_Name = {
    Text = "파편 · 로탄"
  },
  Item_10024_StoryDesc = {
    Text = "중복으로 로탄 얻기 시 전환하여 획득하며, 로탄의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10025_Desc = {
    Text = "보유자가 생성하는 방패 능력을 증가시키고, 중독을 적용할 때 더 많은 배아 융합을 얻을 수 있습니다."
  },
  Item_10025_Name = {
    Text = "창백한 후예"
  },
  Item_10025_StoryDesc = {
    Text = "바람이 사방에서 몰려오고, 당신은 촛불을 들고 미로의 입구에 서 있습니다.\n당신은 약간 혼란스럽습니다.\n마치 지난 순간, 당신은 미사그의 식당에서 샤롯트가 도서관 지하 미로에 대한 전설을 이야기하는 것을 듣고 있던 것 같습니다.\n그리고 지금, 당신은 잠옷을 입고, 졸린 눈으로 하나하나의 통로를 걷고 있습니다.\n「샤롯트, 샤롯트……」\n바스락거리는 소리와 함께 흰색 거미들이 물결처럼 쏟아져 들어옵니다.\n그것들은 창백한 소녀로 응결됩니다. 그녀는 살덩어리로 조각된 그네에 앉아 흔들리고 있습니다.\n\n「너 왔구나.」 그녀가 말합니다.\n「나는 샤롯트를 찾으러 왔어, 내 친구. 그녀는 길을 잃었어, 나는 그녀를 찾아야 해……」\n당신은 거의 울음을 터뜨릴 것 같습니다.\n소녀는 깔깔 웃기 시작했습니다. 그녀는 그네에서 뛰어내려 당신 앞에 다가옵니다.\n「잊었니, 우리의 거래……」\n소녀는 손을 내밀어 당신의 배를 어루만지며 문득 깨달음을 얻습니다.\n「아, 맞다. 너는 이미 내 자식이 되었으니, 아무것도 기억하지 못하는구나.」\n「자식……?」\n당신은 자신들의 피부가 접촉하는 곳을 내려다봅니다.\n따뜻한 감촉이 거미줄처럼 피부 아래로 깊숙이 침투해 혈관의 가장 깊은 곳까지 퍼져 나갑니다.\n소녀는 신비롭게 눈을 깜빡이며, 당신의 귀에 가까이 다가가 조용히 말합니다:\n「샤롯트는 네 배 속에 있어.」"
  },
  Item_10026_Desc = {
    Text = "세트: \n진홍빛 심동Ⅰ\n진홍빛 심동Ⅱ\n진홍빛 심동Ⅲ\n진홍빛 심동Ⅳ\n진홍빛 심동Ⅴ\n진홍빛 심동Ⅵ"
  },
  Item_10026_Name = {
    Text = "진홍빛 심동"
  },
  Item_10027_Desc = {
    Text = "관화를 쓴 비너스는 이 어두운 그림자 속에서 오직 그녀의 가는 실타래루엣만이 빛나고 있습니다. \n·반격 능력을 방어막으로 변환, 독 주입 능력도 겸비\n·적을 유혹하여 공격을 유도"
  },
  Item_10027_Name = {Text = "완다"},
  Item_10029_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
