  },
  Item_10030_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다.\n당신의 본능, 당신의 이성, 심지어 당신의 영혼까지...\n결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_10030_Name = {
