  },
  Item_100316_Desc = {
    Text = "스테레오타입의 탐정이 반드시 가져야 하는 장식품입니다. 명상할 때 사용하세요. 비어 있어도 빨대를 문 것보다 멋집니다. \n“명탐정 수첩” 기간 동안 한정 판매됩니다."
  },
  Item_100316_Name = {
    Text = "탐정 파이프 의상"
  },
  Item_100317_Desc = {
    Text = "베레모를 쓰는 순간, 탐정의 눈빛도 날카로워졌다. 누구도 당신의 프로페셔널한 정체성을 의심하지 않는다. \n「명탐정 수첩」 기간 동안 한정 공급됩니다."
  },
  Item_100317_Name = {
    Text = "탐정 베레모 의상"
  },
  Item_100318_Desc = {
    Text = "풍우를 입으면 뒤에서 음악이 흐르는 분위기를 가질 수 있어요. 바람에 옷자락이 흩날리도록 하고, 멋진 추리 포즈를 취해보세요! \n“명탐정 수첩” 기간 한정으로 제공됩니다."
  },
  Item_100318_Name = {
    Text = "탐정 트렌치코트 의상"
  },
  Item_10032_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬:“영원한 집착”을 선택할 수 있습니다. \n\n그녀의 집착으로 미루어 보아, 나는 약간의 예감이 듭니다: 이 1만 년에 걸친 의식은 아직 종료되지 않았을 것입니다……"
  },
  Item_10032_Name = {
    Text = "영원한 집착"
  },
  Item_10032_StoryDesc = {
    Text = "그녀의 착취로 미루어 볼 때, 나는 암시적인 예감이 있다: 이 만 년을 넘는 의식은 아직 종료되지 않았다……"
  },
  Item_10033_Desc = {
    Text = "광기 충전 레벨 속성의 명륜이다."
  },
  Item_10033_Name = {Text = "탐욕"},
  Item_10033_StoryDesc = {
    Text = "쉿...... 여기, 내 앞을 넘어가지 마./n그 유래를 알려 하지 마."
  },
  Item_10034_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n툴루를 반복 획득 시 전환하여 기령을 얻습니다."
  },
  Item_10034_Name = {
    Text = "파편 · 툴루"
  },
  Item_10034_StoryDesc = {
    Text = "중복 획득 시 툴루 획득으로 전환되며, 툴루의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10035_Desc = {
    Text = "충분한 양의 은심을 담은 선물상자. 그 빛에 현혹되지 않도록 주의하라."
  },
  Item_10035_Name = {
    Text = "고급 은심 선물 상자"
  },
  Item_10036_Desc = {
    Text = "그 스포트라이트의 교차점에서, 광기의 마법사는 이미 그녀의 긴 모자에 손을 넣었다. \n·초원공간에서 카드를 꺼내다 \n·산출력 마법사 빛나는 등장하다"
  },
  Item_10036_Name = {Text = "카시아"},
  Item_10037_Desc = {
    Text = "소량의 은심을 담은 선물상자. 양은 적지만 사용하기에는 충분하다."
  },
  Item_10037_Name = {
    Text = "기본 은심 선물 상자"
  },
  Item_10038_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복 획득 시 변환하여 님피아를 획득하며, 이를 사용하여 님피아의 기령을 활성화합니다."
  },
  Item_10038_Name = {
