  },
  Item_10038_StoryDesc = {
    Text = "중복 획득 시 변환하여 닝피아를 획득하며, 이를 사용하여 닝피아의 기령을 활성화합니다."
  },
  Item_10039_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 미리암을 획득할 때 변환하여 미리암의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10039_Name = {
    Text = "파편 · 미리암"
  },
  Item_10039_StoryDesc = {
    Text = "중복으로 미리암을 획득할 때 변환하여 획득하며, 미리암의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10040_Desc = {
    Text = "배반과 감옥의 재앙이 반란의 불꽃을 부채질했고, 복수의 불길은 이미 메르시아를 태우고 있습니다. \n·생명이 낮을수록 데미지가 더 강력해집니다. \n·강력한 일격을 보유하고 있습니다."
  },
  Item_10040_Name = {Text = "히로"},
  Item_10041_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_10041_Name = {
    Text = "뒤틀린 쌍둥이·흑 Ⅱ"
  },
  Item_10041_StoryDesc = {
    Text = "진한 검은 피의 제물."
  },
  Item_10042_Desc = {
    Text = "그녀의 등불은 여행자들이 고향으로 돌아갈 수 있도록 안내했지만, 이제는 그곳에서 길을 잃은 자들의 혼란이 드러나고 있습니다. \n·맹독 \n·지원 팀"
  },
  Item_10042_Name = {Text = "파로스"},
  Item_10043_Desc = {
    Text = "세트: \n묘지의 속삭임Ⅰ\n묘지의 속삭임Ⅱ\n묘지의 속삭임Ⅲ\n묘지의 속삭임Ⅳ\n묘지의 속삭임Ⅴ\n묘지의 속삭임Ⅵ"
  },
  Item_10043_Name = {
    Text = "묘지의 속삭임"
  },
  Item_10044_Desc = {
    Text = "우리에게 미지의 인식을 부여한다.\n필린 시사의 특수 필름으로, 인간의 인식을 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_10044_Name = {
    Text = "인식 템플릿"
  },
  Item_10045_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_10045_Name = {
    Text = "36호실타래의 고리 Ⅱ"
  },
  Item_10045_StoryDesc = {
    Text = "회전하고, 잊는다ーー이것이 그녀의 삶 전부이다."
  },
  Item_10047_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 머피를 획득할 때 변환하여 머피의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10047_Name = {
    Text = "파편 · 머피"
  },
  Item_10047_StoryDesc = {
    Text = "중복으로 머피를 획득할 때 변환하여 머피의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10048_Desc = {
    Text = "수억 년 전, 그들은 따뜻한 바다에서 군림했다.\n높은줄기 바다백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_10048_Name = {
    Text = "높은줄기 바다백합"
  },
  Item_10051_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_10051_Name = {
    Text = "핏빛의 포옹 Ⅱ"
  },
  Item_10051_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 그가 빚어낸 존재를 두 손으로 끊어냈다."
  },
  Item_10052_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “머릿속의 목소리”를 선택할 수 있습니다.\n\n두 손이 맞잡는 순간, 당신들은 서로의 눈에서 혼란과 궁금증을 보았다.\n불완전한 음부가 여기서 교차하며, 당신들이 이미 과거를 잃어버렸기 때문이다.\n침묵의 악장이 곧 작곡될 것이며, 당신들이 미래로 떨어지기로 결심했기 때문이다."
  },
  Item_10052_Name = {
    Text = "머릿속의 목소리"
  },
  Item_10052_StoryDesc = {
    Text = "두 손이 맞잡는 그 순간, 당신들은 서로의 눈에서 혼란과 의문을 보았다. \n결함 있는 음부가 여기에서 교차하며, 당신들이 과거를 이미 잊어버렸기 때문이다. \n침묵의 악장이 곧 작곡될 것이며, 이는 당신들이 미래로 떨어지기로 결심했기 때문이다."
  },
  Item_10053_Desc = {
    Text = "미사그의 상징이 새겨진 간결한 은빛 배지.\n페이즈 체스에서 우수한 성적을 거둔 수밀인에게 수여되며, 교환 상점에서 다양한 상품으로 교환할 수 있다."
  },
  Item_10053_Name = {
    Text = "연습 배지"
  },
  Item_10055_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_10055_Name = {
    Text = "36호실타래의 고리 Ⅵ"
  },
  Item_10055_StoryDesc = {
    Text = "회전하고, 잊는다ーー이것이 그녀의 삶 전부이다."
  },
  Item_10056_Desc = {
    Text = "결국 서로를 신뢰하게 될 것이다.\n수호자와 깨어남체의 정신적 동조율이 높아질수록 깨어남체의 기록에서 더 많은 이야기를 해금할 수 있다."
  },
  Item_10056_Name = {Text = "동조율"},
  Item_100577_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “아름다운 꿈의 순간”을 선택할 수 있습니다. \n아름답고 완벽하며 부드러운 모든 것이 사람을 빠져들게 하지만, 당신은 자신의 처형자가 되기를 선택하고, 스스로 영혼을 꿈의 번식지에서 잘라냅니다. \n허위의 막을 찢어낸 후, 당신은 뒤를 돌아보며, 그 웃는 얼굴들이 창백한 선들 속에 잠금되어 당신의 진정한 귀환을 기다리고 있습니다."
  },
  Item_100577_Name = {
    Text = "아름다운 꿈의 순간"
  },
  Item_100577_StoryDesc = {
    Text = "아름답고, 완전하며, 부드러운 모든 것이 사람을 빠져들게 하지만, 당신은 스스로의 처형자가 되기로 선택하고, 직접 영혼을 꿈의 번식지에서 잘라냅니다.\n거짓된 커튼을 찢고 돌아보니, 그 웃는 얼굴들이 창백한 선 안에 잠금되어 당신의 진정한 귀환을 기다리고 있습니다."
  },
  Item_10057_Desc = {
    Text = "주 속성으로 치명타 확률, 치명타 피해, 은열쇠 충전 레벨과 광기 충전 레벨 중 랜덤으로 1개를 획득한다."
  },
  Item_10057_Name = {
    Text = "먼 곳의 잔치 Ⅰ"
  },
  Item_10057_StoryDesc = {
    Text = "즐겁게 잔치를 즐겨라, 노랫소리 속에서."
  },
  Item_10058_Desc = {
    Text = "구빈원에 산일된 감정 입자로, 접촉하면 \"감사합니다\"라는 저어가 들리는 듯합니다.\n수호자가 조사 이벤트 「동구 비사」에서의 공명을 높이는 데 사용됩니다.\n「동구 비사」 관문 첫 클리어 보상에서 획득할 수 있습니다."
  },
  Item_10058_Name = {
    Text = "감사의 심장"
  },
  Item_10059_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_10059_Name = {
    Text = "기계장치의 신 Ⅱ"
  },
  Item_10059_StoryDesc = {
    Text = "기계는 완전히 순수하다."
  },
  Item_10060_Name = {
    Text = "살인자의 발자국"
  },
  Item_10061_Desc = {
    Text = "세트: \n생명력 착취Ⅰ\n생명력 착취Ⅱ\n생명력 착취Ⅲ\n생명력 착취Ⅳ\n생명력 착취Ⅴ\n생명력 착취Ⅵ"
  },
  Item_10061_Name = {
    Text = "생명력 착취"
  },
  Item_10062_Desc = {
    Text = "이제는 아무도 이걸로 길흉을 점치지 못할 거야. \n융해진흙으로 덮인 보라색 수정, 초월계역의 깨어남체 스킬 레벨을 올리는데 사용됩니다."
  },
  Item_10062_Name = {
    Text = "부서진 광석"
  },
  Item_10063_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 엘바를 획득할 때 전환하여 기령을 활성화하는 데 사용됩니다."
  },
  Item_10063_Name = {
    Text = "파편 · 엘바"
  },
  Item_10063_StoryDesc = {
    Text = "중복으로 획득한 엘바는 변환되어 기령 활성화에 사용됩니다."
  },
  Item_10064_Desc = {
    Text = "미사그 대학의 설립자가 개발한 약재로, 깨어남체의 능력을 향상시킨다. \n은심과 비밀의 약을 섞어 독특한 색을 띠고 있다.\n사용 시 깨어남체의 경험치가 500 증가한다."
  },
  Item_10064_Name = {
    Text = "영지 비약Ⅰ"
  },
  Item_10065_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “작은 소원”을 선택할 수 있습니다.\n\n여자아이는 여섯 살 생일날 소원을 빌었습니다:\n“뽀뽀”라는 이름의 인형곰을 갖고 싶었고, 사랑도 — 많이 필요하지 않았습니다, 한 점만 있으면 충분했습니다.\n여자아이는 상상력이 풍부한 사람도 아니었고, 탐욕스러운 사람도 아니었습니다."
  },
  Item_10065_Name = {
    Text = "작은 소원"
  },
  Item_10065_StoryDesc = {
    Text = "소녀는 여섯 살 생일날 소원을 빌었다:\n“뽀뽀”라는 이름의 인형곰을 갖고 싶었고, 사랑도 — 많이 필요하지 않았다, 한 점만 있으면 충분했다.\n소녀는 상상력이 풍부한 사람도 아니었고, 탐욕스러운 사람도 아니었다."
  },
  Item_10066_Desc = {
    Text = "영지가 무한히 증폭되면, 진실타래의 한 구석에 닿게 될 것이다.\n은심으로 구동되는 특수 장치. 설정값에 따라 깨어남체의 능력을 영구적으로 향상시킬 수 있다.\n수호자 레벨 40에 도달하면, 임의의 깨어남체를 선택하여 다음 강화 효과를 부여할 수 있습니다:\n·레벨 50으로 상승\n·계령 등급 4로 상승"
  },
  Item_10066_Name = {
    Text = "영지 증폭기 Ⅴ"
  },
  Item_10067_Desc = {
    Text = "전설에 따르면 최초의 마우를 창조한 이가 자신의 손으로 마우를 살해했습니다. \n스칼렛 애매트 미스터리 세트 부품이 랜덤 드롭됩니다."
  },
  Item_10067_Name = {
    Text = "핏빛의 포옹"
  },
  Item_10068_Desc = {
    Text = "영지가 무한히 증폭되면, 진실타래의 한 구석에 닿게 될 것이다.\n은심으로 구동되는 특수 장치. 설정값에 따라 깨어남체의 능력을 영구적으로 향상시킬 수 있다.\n수호자 레벨 50에 도달하면, 임의의 깨어남체를 선택하여 다음 강화 효과를 부여할 수 있습니다:\n·레벨 60으로 상승\n·계령 등급 5로 상승"
  },
  Item_10068_Name = {
    Text = "영지 증폭기 Ⅵ"
  },
  Item_10069_Desc = {
    Text = "생존 및 지속 능력을 전면적이고 종합적으로 향상시키며, 추가적인 스칼렛 용광로 저장 상한과 피해 성장으로 더 많은 가능성을 가져옵니다."
  },
  Item_10069_Name = {
    Text = "신언의 석판"
  },
  Item_10069_StoryDesc = {
    Text = "창조의 아버지 신은 별빛 속에서 왔다. \n 그때의 땅은 붉은 불꽃의 뜨거운 땅, 맹렬한 불길이 타올랐다. 아버지 신의 발이 불 위에 닿았다. \n 아버지 신은 말하였다, 불은 결국 꺼질 것이니, 불은 그렇게 하였다. \n 흐르는 흙이 땅이 되었고, 아버지 신은 땅에 신언을 기록하였다: \n 땅은 생명의 기초가 될 것이다. \n 계곡은 계곡이 되었고, 평원은 평원이 되었다. \n 신언은 견고하다, 이것이 첫 번째 석판이다. \n\n 아버지 신은 구름이 무겁다고 보았다, 그리고 말하였다, 구름은 결국 비를 내릴 것이니, 구름은 그렇게 하였다. \n 비는 흐르는 물로 모였다, 아버지 신은 그 위에 신언을 기록하였다: \n 물은 온실타래이 될 것이다. \n 물은 호수가 되고, 바다가 되어, 바다는 땅을 잠식하였다. \n 신언은 견고하다, 이것이 두 번째 석판이다. \n\n 아버지 신은 물이 흐릿하다고 보았다, 그래서 말하였다, 빛이 강림해야 하니, 빛은 그렇게 하였다. \n 빛이 물 위에 떨어졌고, 아버지 신은 빛 위에 신언을 기록하였다: \n 빛은 생명력을 줄 것이다. \n 빛은 따뜻함을 가져왔다. \n 신언은 견고하다, 이것이 세 번째 석판이다. \n\n 아버지 신은 땅, 물, 빛이 모두 생겼음을 보았다, 그래서 말하였다, 생명이 임할 것이다. \n 그는 자신의 피를 흘리게 하였고, 그 위에 신언을 기록하였다: \n 피는 신생을 잉태할 것이다. \n 아버지 신의 피가 흩어져 생명을 가진 것들이 되어, 바다에서 번식하였다. \n 신언은 견고하다, 이것이 네 번째 석판이다. \n\n 아버지 신은 생명이 생겼음을 보았다, 변화도 생겼다고 말하였다, 생물은 영원히 변화할 것이다. 생물은 그렇게 하였다. \n 미세한 물체가 물러난 바닷가의 땅 위로 기어올랐다. \n 아버지는 변화하는 물체 위에 신언을 기록하였다: \n 변화는 멈출 수 없다. \n 육지로 기어올라간 물체는 뿌리와 줄기를 내고, 사지를 자라게 하며, 다양한 형태로 변하였다. \n 신언은 견고하다, 이것이 다섯 번째 석판이다. \n\n 아버지 신은 생명이 생겼고, 변화도 생겼다고 보았다, 그래서 말하였다, 죽음도 올 것이다. 죽음이 왔다. \n 노쇠한 자가 죽고, 병약한 자가 죽었다. 아버지 신은 죽음 위에 신언을 기록하였다: \n 죽는 자는 처음으로 돌아갈 것이다. \n 죽은 자의 몸은 천천히 사라져 아버지 신의 품으로 돌아갔다. \n 신언은 견고하다, 이것이 여섯 번째 석판이다. \n\n 아버지 신은 생명, 죽음, 변화가 모두 생겼음을 보았다, 그래서 말하였다, 이것들은 모두 나의 유물이다, 나는 축복을 남길 것이다. \n 아버지 신은 자신의 뼈를 꺼내어 그 위에 신언을 기록하였다: \n 만물의 끝에 내 뼈를 사용할 수 있고, 나의 권한을 대행할 것이다. \n 혈육의 대가로 생기를 부여하리라. \n 신언은 견고하다, 이것이 일곱 번째 석판이다. \n\n 아버지 신은 모든 것이 생겼음을 보고, 멈추어 휴식하였다. \n 물이 아버지 신을 감싸고, 빛이 아버지 신에게 따뜻함을 제공하며, 땅이 아버지 신을 덮었다. \n 그리고 아버지 신은 깊은 잠에 빠졌고, 만물은 아버지 신의 말씀에 따라 생존하였다, 그것이 지금의 세계이다."
  },
  Item_10070_Desc = {
    Text = "영지가 무한히 증폭되면, 진실타래의 한 구석에 닿게 될 것이다.\n은심으로 구동되는 특수 장치. 설정값에 따라 깨어남체의 능력을 영구적으로 향상시킬 수 있다.\n수호자 레벨 20에 도달하면, 임의의 깨어남체를 선택하여 다음 강화 효과를 부여할 수 있습니다:\n·레벨 30으로 상승\n·계령 등급 2로 상승"
  },
  Item_10070_Name = {
    Text = "영지 증폭기 Ⅲ"
  },
  Item_10071_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 회복, 검은 인장 드롭율, 은열쇠 충전 중 무작위 1개를 획득합니다."
  },
  Item_10071_Name = {
    Text = "소녀의 번데기 Ⅳ"
  },
  Item_10071_StoryDesc = {
    Text = "순수한 그릇을 바칩니다."
  },
  Item_10072_Desc = {
    Text = "\"걱정 마세요, 저희는 언제나 수호자님의 가장 든든한 후원자가 되어드리겠습니다.\"\n\n\n미사그 대학의 귀중한 특수 장치. 강력한 정신력을 내재하고 있어 순간적으로 깨어남체의 잠재력을 자극해 상태를 회복시킨다.\n\n\n\n매일 오전 9시, 현재 남은 횟수가 5회 미만일 경우 자동으로 1회 충전된다."
  },
  Item_10072_Name = {
    Text = "응급 영지체"
  },
  Item_10073_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_10073_Name = {
    Text = "정신 집중"
  },
  Item_10073_StoryDesc = {
    Text = "조사원 사이에는 불문율이 있습니다: \n\n요총 의식 이후의 그 밤, 경력이 더 많은 조사원이 신입 조사원을 데리고 기숙사 뒷마당에서 모임을 엽니다. \n그들은 촛불을 켜고 자신의 은 열쇠를 중심으로 원을 그리며 앉습니다. \n경험 많은 조사원은 각 신입에게 그들 손에 쥐어진 유일한 번호를 가진 열쇠가 어떤 이야기를 가지고 있는지 말해줍니다. \n\n이런 활동은 결국 어떤 이야기 대회로 변하게 되고, I-0001과 K-0001, 이 두 개의 “초대”를 대표하는 열쇠는 자연스럽게 논의의 중심이 됩니다. \n아는 사람이 드문 것은, 초대 수호자가 손수 제작한 K-0001호 은 열쇠가 현재 그 주인과 함께 지하에 영원히 묻혀 있으며, 낮과 밤을 구별할 수 없는 긴 대기 속에서 그 사람이 이미 지나간 이들에게 저어하는 소리를 듣고 있다는 것입니다. \n\n“너는 그가 정말 여기 있는 게 아니라는 걸 알고 있지, 알리스타르.” 돌이 말했습니다. “그것은 아마 너의 선생님의 은심으로 만들어졌겠지만, 그의 영혼으로 여겨져서는 안 돼.” \n“이건 단지 집중력의 한 방식일 뿐이야, 돌.” 알리스타르가 웃으며 말했습니다. “걱정 마, 나는 안정적이야. 우리의 신입 수호자가 성장하기 전에 쓰러질 수는 없어, 맞지?”"
  },
  Item_10074_Desc = {
    Text = "적당량의 은심을 담은 선물상자. 수호자의 노고에 대한 보답이다."
  },
  Item_10074_Name = {
    Text = "중형 은심 선물상자"
  },
  Item_10075_Desc = {
    Text = "피해 증폭 속성의 명륜입니다."
  },
  Item_10075_Name = {
    Text = "절단과 상처"
  },
  Item_10075_StoryDesc = {
    Text = "의사의 천직은 본래 환자를 치료하는 것입니다. \n\n하지만 우연히도 그런 치료 방법이 있어야만 가장 날카로운 칼날로 피부를 베고, 조직을 찔러 가슴을 열고 병소를 제거한 다음, 인체가 자기 치유 능력으로 재생되기를 기원해야 합니다. \n\n이것은 본래 그녀의 죄가 아니어야 했습니다. \n하지만 매번 수술을 마친 후, 그녀는 어쩔 수 없이 그 여자아이에게 이야기를 해주었습니다. \n그녀는 좋은 이야기꾼이 아니었고, 말이 산만했지만, 그 허구의 이야기들은 여전히 그 여자아이를 진지하게 집중하게 만들었습니다. \n그녀가 직접 잘라낸 곳은 마치 느리고 강인하게 그 말의 힘을 흡수하며, 점차 자연스럽게 치유되고 있는 것처럼 보였습니다…"
  },
  Item_10076_Desc = {
    Text = "밀랍인형관에 산일된 감정 입자로, 접촉하면 \"오지 마세요\"라는 놀람의 외침이 들리는 듯합니다.\n수호자가 조사 이벤트 「밀랍인형의 이름으로」에서의 공명을 높이는 데 사용됩니다.\n「밀랍인형의 이름으로」 관문 첫 클리어 보상에서 획득할 수 있습니다."
  },
  Item_10076_Name = {
    Text = "경련의 심장"
  },
  Item_10077_Desc = {
    Text = "검은 인장 드롭율 속성의 명륜입니다."
  },
  Item_10077_Name = {
    Text = "모험 가방"
  },
  Item_10077_StoryDesc = {
    Text = "누구나 태어날 때부터 선장은 아니며, 적어도 엘튼은 아니다.\n\n선장이 되기 전, 그는 해군과 상선 사이를 전전하며 여러 차례 해적이 될 뻔했지만, 결국 그는 한 탐험선에서 안정을 찾았다.\n\n탐험선은 극지 대륙을 항해하며, 매번 상륙할 때마다 새로운 모험을 의미했다.\n그의 임무는 허약한 과학자들을 위해 짐을 지는 것이었고, 그는 이를 자랑스럽게 여겼다—짐 속에 담긴 것은 세상을 바꿀 수 있는 것일지도 모른다.\n그리고 그들은 어쩌면 역사를 새롭게 쓸 사람들이었다.\n\n얼음 폭풍이 그들을 얼음 동굴에 가두기 전, 신비한 교단이 그들을 깊은 밤에 습격하기 전까지, 엘튼은 그렇게 생각해왔다."
  },
  Item_10078_Desc = {
    Text = "크리티컬 확률 속성의 명륜입니다."
  },
  Item_10078_Name = {
    Text = "죽음의 해부"
  },
  Item_10078_StoryDesc = {
    Text = "그는 항상 조용하고 근면한 학생이었습니다.\n\n아침 8시, 다른 연구원들이 빵을 물고 급히 도착할 때, 그는 이미 실타래험 보고서를 한 편 작성 완료했습니다.\n밤 12시, 실타래험 건물의 불이 모두 꺼질 때까지 그는 천천히 짐을 정리하고 떠났습니다.\n\n그렇습니다, 그는 매일 근처의 작은 고양이에게도 먹이를 줍니다.\n나중에 작은 고양이가 사라졌고, 아무도 그들이 어디로 갔는지 알지 못했습니다.\n\n멘토 크라우리는 그의 실타래험 기록과 보고서를 분석하고 있습니다.\n간결하고, 세심하며, 어떤 반짝임도 없었습니다——하지만 어떤 약점도 없었습니다.\n이 학생은 그를 혼란스럽게 했습니다.\n하지만 혼란은 항상 좋은 것입니다. 그것은 종종 호기심으로 가는 스위치가 되곤 합니다.\n\n물론, 그때의 크라우리는 예상하지 못했습니다: 그것이 죽음으로 가는 스위치가 될 수도 있다는 것을."
  },
  Item_10079_Desc = {
    Text = "크리티컬 피해 속성의 명륜입니다."
  },
  Item_10079_Name = {
    Text = "나의 소중한 친구에게"
  },
  Item_10079_StoryDesc = {
    Text = "“무의식 중에 당신은 이렇게 오랫동안 떠나 있었군요.\n\n나는 여전히 꿈 속에서 그날로 돌아갑니다. 왼팔 총상에서 느껴지는 고통, 출혈로 인한 환각과 혼란, 난폭한 쥐 떼의 추격…\n그 혼란 속에서 미사그 교복을 입은 당신이 나타나, 나를 그 이미 오래전부터 불길한 기운이 감도는 고성에서 구해주었습니다.\n\n그 꿈의 끝에서 당신은 병상 앞에 서서 나에게 말했습니다. 조사원에게 죽음은 항상 그림자처럼 따라온다고.\n이제 나는 그것이 진실타래인지 내 환상인지 판단할 수 없습니다.\n이럴 때마다 나는 왼팔을 만지려고 합니다. 차가운 정교한 금속 표면을 만질 수 있다면, 그것이 현실타래입니다.\n\n하지만 더 많은 꿈 속에서는 나는 오직 허공만을 움켜잡고 있습니다.”"
  },
  Item_10080_Desc = {
    Text = "죽음 저항 속성의 명륜입니다."
  },
  Item_10080_Name = {
    Text = "기억증후군"
  },
  Item_10080_StoryDesc = {
    Text = "크라울리는 재직 기간 동안 '가장 인기 있는 멘토'라는 영예로운 칭호를 차지했습니다.\n\n그의 다소 어색한 콘스탄스 서부 억양과 진솔한 미소는 수많은 학생들, 그 중에서도 헤버트를 포함한 많은 학생들의 호감을 샀습니다.\n\nA.F.2@1년, 크라울리는 반대 의견을 뚫고 눈에 띄지 않는 헤버트를 자신의 제자로 삼았습니다.\n헤버트는 그와 함께 높은 산을 넘고, 계곡을 건너고, 사막을 지나며 하나하나의 융식 균열에 발자국을 남겼습니다.\n그는 처음 융식 균열을 보았을 때의 충격을 아직도 기억합니다.\n\n크라울리는 증발하는 검은 안개 앞에 서 있었고, 그의 모습은 그렇게 작아 보였습니다.\n「쉿—— 너는 들었니?」\n헤버트는 두 눈을 감고, 고요한 바다가 끊임없이 일렁이는 소리만 들었습니다. 세상은 그에게서 멀어지는 듯했습니다.\n크라울리는 매우 흥분하며 말했습니다:\n「이건 시야. 우주에서 가장 신비롭고 깊은 시야야.」\n\n몇 년 후, 헤버트는 크라울리에 대한 기억이 이미 흐릿해졌습니다.\n그들이 어떻게 협력하고, 논쟁했는지, 그가 어떻게 그를 '실타래수로' 죽였는지 같은 것들 말입니다.\n하지만 그는 영원히 그 검은 안개 아래의 미소를 기억합니다.\n그 순간, 그는 시를 보았습니다."
  },
  Item_10081_Desc = {
    Text = "기어가고, 왜곡되고, 우리는 어두운 곳을 기어다닙니다……스……스……\n감염당한 번데기. 혈육 경계역의 깨어남체 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_10081_Name = {
    Text = "원생 번데기"
  },
  Item_10082_Desc = {
    Text = "사용하면 임의의 보라색 운명의 휠을 중첩할 수 있습니다. (개발용)"
  },
  Item_10082_Name = {
    Text = "보라색 운명의 휠 중첩 재료 (개발용)"
  },
  Item_10083_Desc = {
    Text = "당신은 불멸할 것이다.\n초월적 존재에서 나온 기억의 결정체로, 미사그 상점에서 상품으로 교환할 수 있다."
  },
  Item_10083_Name = {
    Text = "PVP 코인 (이미 폐기됨)"
  },
  Item_10084_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다. 당신의 본능, 당신의 이성, 심지어 당신의 영혼까지... 결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_10084_Name = {
    Text = "연마된 이성"
  },
  Item_10085_Desc = {
    Text = "권력으로 물든 가시가 어느새 단풍단백로의 꽃창을 꽉 감쌌다. \n·다단 데미지 \n·흡수로 생명 회복"
  },
  Item_10085_Name = {Text = "소렐"},
  Item_10086_Desc = {
    Text = "금기 지식의 간단한 묘사는 미스터리를 강화할 수 있습니다."
  },
  Item_10086_Name = {
    Text = "밀키트레이스(이미 폐기됨)"
  },
  Item_10087_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_10087_Name = {
    Text = "소녀의 번데기 Ⅲ"
  },
  Item_10087_StoryDesc = {
    Text = "순수한 그릇을 바칩니다."
  },
  Item_10088_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n카시아를 반복 획득할 때 전환하여 기령을 활성화하는 데 사용됩니다."
  },
  Item_10088_Name = {
    Text = "파편 · 카시아"
  },
  Item_10088_StoryDesc = {
    Text = "카시아를 중복으로 획득할 때 전환하여 획득하며, 카시아의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10089_Name = {
    Text = "배 구조도"
  },
  Item_10090_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_10090_Name = {
    Text = "무구의 계시록 Ⅵ"
  },
  Item_10090_StoryDesc = {
    Text = "그것은 영원하고 무구한 진실타래의 한 순간이다."
  },
  Item_10091_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_10091_Name = {
    Text = "환형의 시편 Ⅱ"
  },
  Item_10091_StoryDesc = {
    Text = "환형 시간의 틈새를 떠다니는 것."
  },
  Item_10092_Desc = {
    Text = "신비로운 보라색 휘광을 반짝이며, 캄브리안 계곡에 운석이 추락할 때 남은 파편이라고 전해집니다. \n 초원차원 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_10092_Name = {
    Text = "유성의 파편"
  },
  Item_10093_Desc = {
    Text = "전문가의 도움을 받아 열어주세요. \n 무광의 경계에서 획득 가능한 고대 미스터리를 포장된 신비한 나무 상자입니다. \n 왜곡된 쌍둥이 백미스터리 세트 구성품을 얻을 수 있습니다."
  },
  Item_10093_Name = {
    Text = "무질서 계약 그릇 Ⅲ"
  },
  Item_10094_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_10094_Name = {
    Text = "생명력 착취 Ⅲ"
  },
  Item_10094_StoryDesc = {
    Text = "탯줄은 끝없는 미래와 연결되어 있다."
  },
  Item_10095_Desc = {
    Text = "인류의 존속을 위해.\n\n\n\n액자에 보관된 기억. 혈육 영역 깨어남체의 승급 재료."
  },
  Item_10095_Name = {
    Text = "기억 복사본"
  },
  Item_10096_Desc = {
    Text = "우리에게 미지의 인식을 부여한다.\n필린 시사의 특수 필름으로, 인간의 인식을 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_10096_Name = {
    Text = "인식 템플릿"
  },
  Item_10097_Desc = {
    Text = "꽃말: 내게 멀리 떨어져. \n낮은줄기 바다백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_10097_Name = {
    Text = "낮은줄기 바다백합"
  },
  Item_10098_Desc = {
    Text = "젠킨은 그녀의 쥐 동료 브라운과 같이 민첩하고 신속하며, 행방이 불분명합니다. \n·초원차원 점프를 통해 대량의 데미지를 입힙니다. \n·상황에 맞춰 데미지를 줄 수 있는 능력을 보유하고 있습니다"
  },
  Item_10098_Name = {Text = "젠킨"},
  Item_10099_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_10099_Name = {
    Text = "생명력 착취 Ⅰ"
  },
  Item_10099_StoryDesc = {
    Text = "탯줄은 끝없는 미래와 연결되어 있다."
  },
  Item_10100_Desc = {
    Text = "광기 폭발을 사용하면 추가적으로 광기를 얻고 임시 크리티컬 피해가 증가하며, 운이 좋다면 팀원에게 자신의 행운을 나누어 줄 수 있습니다."
  },
  Item_10100_Name = {
    Text = "행운의 시간"
  },
  Item_10100_StoryDesc = {
    Text = "템스 강을 따라 아래로 가다가, 베크맨 스트리트로 오른쪽으로 돌고 약 100 피트 정도 걷다 보면 그 평범한 모퉁이에서 “라이커 탐정 사무소”를 볼 수 있습니다.\n\n렌티니언에서 가장 높은 사건 해결률을 자랑하는 탐정 사무소로서, 이곳은 전문 서적이 가득한 큰 책장이 없고, 신문 스크랩으로 가득한 벽도 없으며, 정교한 오후 차도 없습니다.\n당신은 대개 문 앞에 걸려 있는 “외출 중” 간판과 옆에 누워 있는 지친 늙은 개를 보게 될 것입니다.\n\n운이 좋다면, 맑은 날의 어떤 일요일 아침에 당신은 숙취에서 돌아오는 유명한 탐정 선생님을 만날 수 있을지도 모릅니다.\n그는 방금 전 도박을 끝내고 주머니에 돈이 몇 푼 남지 않은 상태로, 당신은 그에게 고양이를 찾거나, 사이비 종교에 빠진 어머니를 구출하거나, 남편의 외도 증거를 모아달라는 무리한 부탁을 마음껏 할 수 있습니다…\n당신이 원하는 것이라면 그는 무엇이든 받아들입니다.\n\n“나는 죽음 직전의 순간을 즐기기 때문에 나는 반드시 도박꾼이 될 운명이다.”\n“그렇다면 탐정이 되는 것은? 솔직히 말해서, 고양이를 찾는 것과 죽음 사이의 연관성을 잘 모르겠네요.”\n“아니, 당신은 이해하지 못해… 진실타래을 찾는 과정 자체가 충분히 매력적이야, 크고 작음에 관계없이. 마치… ”\n“마치 죽음과의 약속을 지키러 가는 것처럼.”"
  },
  Item_10101_Desc = {
    Text = "더 많은 광기와 중독을 유발하면서 적의 생명을 희생하여 임시 치명타 피해로 전환할 수 있으며, 경건한 신앙이 더 많은 촉수를 이끌어냅니다."
  },
  Item_10101_Name = {
    Text = "신앙의 힘"
  },
  Item_10101_StoryDesc = {
    Text = "스크류 사라짐의 도미니언이여, 내 기도를 들어주소서.\n당신의 예언을 내리시고, 나에게 계시를 주시어,\n당신의 나라를 복원할 수 있게 하소서.\n이 신앙 없는 땅에서, 이 바다에 둘러싸인 얼음 평원에서,\n당신의 돌 기둥을 세우고, 당신의 신전을 세우소서.\n\n심연의 주님이여, 무대 위의 것은 당신을 위한 헌물입니다.\n순수한 혈육은 보름달의 어린 양에서 나오고, 강한 마음은 성년의 수소에서 나오며,\n날아다니는 독수리의 날카로운 눈, 순항하는 고래의 단단한 뼈가 있습니다.\n청금석은 당신의 왕좌이고, 골드는 당신의 관입니다.\n부디 나에게 당신의 꿈을 주시고, 나에게 성경을 알려주셔서,\n당신의 몸을 복원할 수 있게 하소서.\n이 얼음 아래의 심연에서, 이 바다 아래의 영역에서,\n올바른 순간에 태어날 어머니를 헌신하겠습니다.\n\n만사를 통달하는 리모리아의 왕이여, 내 기도에 응답하소서.\n당신이 바다에 잠든 이후로, 이미 천백 년이 지났습니다.\n나는 당신의 이름으로, 당신의 일을 행하며, 당신의 아름다운 이름을 선포해 왔습니다, 결코 게으르지 않았습니다.\n확고한 것은 나의 신앙, 성실타래한 것은 나의 마음입니다.\n당신은 유일한 신왕이며, 불사의 화신입니다,\n내 대기를 끝내시고, 세상에 다시 오시어, 당신의 지혜의 말을 들을 수 있게 하소서."
  },
  Item_10102_Desc = {
    Text = "주 속성으로 광기 충전 레벨, 죽음 저항, 은열쇠 충전 레벨과 피해 증폭 효과 중 랜덤으로 1개를 획득한다."
  },
  Item_10102_Name = {
    Text = "진홍빛 심동 Ⅴ"
  },
  Item_10102_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 자신의 혈액으로 골렘을 길러냈다."
  },
  Item_10103_Desc = {
    Text = "주 속성으로 치명타 확률, 치명타 피해, 은열쇠 충전 레벨과 광기 충전 레벨 중 랜덤으로 1개를 획득한다."
  },
  Item_10103_Name = {
    Text = "진홍빛 심동 Ⅰ"
  },
  Item_10103_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 자신의 혈액으로 골렘을 길러냈다."
  },
  Item_10104_Desc = {
    Text = "대량의 은심을 담은 선물상자입니다. 그것들은 오직 기적을 창조하는 역할만 합니다."
  },
  Item_10104_Name = {
    Text = "최고급 은심 선물 상자"
  },
  Item_10105_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_10105_Name = {
    Text = "소녀의 번데기 Ⅰ"
  },
  Item_10105_StoryDesc = {
    Text = "순수한 그릇을 바칩니다."
  },
  Item_10106_Desc = {
    Text = "코르트 대리 학장 특별 승인의 풍부한 보급품입니다.\n귀중한 재료가 담긴 나무 상자로, 밀경과실타래의 일일 시험 훈련과 주간 훈련 임무를 수행하는 수호자에게 도움을 제공합니다.\n다음 소재 중 하나를 선택하세요:\n순백의 비편*12\n정신을 연마하다*12\n의식 부본*12\n영지 템플릿*12"
  },
  Item_10106_Name = {
    Text = "Ⅱ급 보급 (이미 폐기됨)"
  },
  Item_10107_Desc = {
    Text = "미스터리의 본질은 금기의, 인식하기 어려운 지식이다. 타블렛을 사용하여 다시 묘사하면 미스터리의 힘이 더욱 강화된다."
  },
  Item_10107_Name = {
    Text = "밀키트 작성(이미 폐기됨)"
  },
  Item_10108_Desc = {
    Text = "왕국 화폐의 우아한 별칭. 어디서나 얻을 수 있고, 모든 일에 쓰인다."
  },
  Item_10108_Name = {
    Text = "장미 금권"
  },
  Item_10110_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_10110_Name = {
    Text = "기계장치의 신 Ⅵ"
  },
  Item_10110_StoryDesc = {
    Text = "기계는 완전히 순수하다."
  },
  Item_10111_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_10111_Name = {
    Text = "36호실타래의 고리 Ⅰ"
  },
  Item_10111_StoryDesc = {
    Text = "회전하고, 잊는다ーー이것이 그녀의 삶 전부이다."
  },
  Item_10112_Desc = {
    Text = "깨어남 의식 후 “블랙풀”에 남아 있는 거품. 다른 차원의 상인들이라면 그 가치를 알아볼 수 있지 않을까?"
  },
  Item_10112_Name = {
    Text = "근원 거품(이미 폐기됨)"
  },
  Item_10113_Desc = {
    Text = "바람이 새는 집. 그래도 없는 것보다는 낫다.\n유적에 남겨진 번데기 껍질. 혈육 경계역 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다。"
  },
  Item_10113_Name = {
    Text = "마른 번데기"
  },
  Item_10114_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 “24”를 획득할 때 전환하여 “24”의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10114_Name = {
    Text = "파편 · 「24」"
  },
  Item_10114_StoryDesc = {
    Text = "중복으로 “24”를 획득하면 전환하여 얻으며, 이를 통해 “24”의 기령을 활성화하는 데 사용됩니다."
  },
  Item_10115_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_10115_Name = {
    Text = "진홍빛 심동 Ⅱ"
  },
  Item_10115_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 자신의 혈액으로 골렘을 길러냈다."
  },
  Item_10116_Desc = {
