  },
  Item_116596_Name = {
    Text = "참배 의식"
  },
  Item_116597_Desc = {
    Text = "성자를 알현하기 위해 반드시 필요한 증명서. 성자에게 빛을 향한 당신의 결의를 보여라.\n\n최소 {s1}개 드롭"
  },
  Item_116597_Name = {
    Text = "참배 의식"
  },
  Item_116715_Desc = {
    Text = "덩굴 고리와 새 깃털로 만든 간이 꿈잡이는 그리 신뢰할 수 없는 영성을 가지고 있으며, 사용 후 대부분의 경우 실타래패하게 됩니다. 가끔은 꿈의 잔여 조각을 건져 올릴 수 있지만, 대개는 빠르게 스쳐 지나가는 장면들일 뿐입니다."
  },
  Item_116715_Name = {
    Text = "어두운 드림캐처"
  },
  Item_116716_Desc = {
    Text = "이상한 고대 새 뼈로 엮어진 꿈 포착망은 꿈을 섬세하게 당신의 머릿속에 드러내어 마치 당신이 실타래제로 그 이야기들을 경험하고 꿈속의 사람들을 만난 것처럼 보이게 합니다. 좋은 꿈은 좋지만, 과도하게 빠지지 않도록 조심하세요."
  },
  Item_116716_Name = {
    Text = "신기루 드림캐처"
  },
  Item_116717_Desc = {
    Text = "사슴 가죽 끈과 크리스탈로 장식된 꿈 포착망, 눈알처럼 생긴 보석이 그것에 더 나은 영성을 부여하며, 사용 후에는 흐릿하면서도 완전한 꿈을 엿볼 수 있다. 현실타래을 피하는 자여, 노력하여 아름다운 꿈을 건져내라."
  },
  Item_116717_Name = {
    Text = "영광의 드림캐처"
  },
  Item_116762_Desc = {
    Text = "의상 「환몽의 휴일」 획득 시 개방됩니다. \n「수호자, 나랑 같이 해변가에서 바람이라도 쐬지 않을래?」"
  },
  Item_116762_Name = {
    Text = "회귀·라모나·환몽의 휴일"
  },
  Item_116763_Desc = {
    Text = "환행·라모나는 삶을 짧고 반복적인 시련으로 간주한다. \n훈련하고, 수수께끼를 해결하며, 세계가 미래로 나아갈 확률을 계산한 뒤 그녀가 구하고자 했던, 지키고자 했던 아름다운 것들이 파괴되는 모습을 직접 목격한다. \n다시 한 번, 또 다시 한 번. \n그리고 나서, 삶은 고독하며 끝나지 않는 기다림으로 변했다. \n희망을 잃은 붕괴된 세계에서, 그녀는 끝없이 펼쳐진 순수한 검은색 밤하늘을 올려다보며 먼 차원에서 들려오는 호출에 가슴을 기대며 기다렸다. \n하루 또 하루. \n이것이 그녀의 운명이었으며, 그녀는 이 운명에 익숙해지고 받아들였다. 그러던 어느 날—— \n“라모나, 우리 휴가 중인데 너무 진지하지 마, 웃어봐~” \n“라모나, 봤어? 릴리랑 애들이 성을 모래로 쌓았어. 우리도 같이 해볼까?” \n“라모나, 여름에 아이스크림은 꼭 있어야 해! 오늘은 내가 사줄게, 자, 이거 네 거야.” \n“라모나……” \n“라모나.” \n“라모나!” \n익숙한 부름이 이어지는 가운데, 여름 햇살은 거리낌 없이 모든 것을 뜨겁게 달구었다. \n그녀는 해변의 ‘성’이 햇살 아래 빛나는 모습을 바라보았고, 아이스크림이 손에서 녹아내리며 남긴 끈적끈적한 촉촉함도 느꼈다. \n바닷물은 차갑고, 모래는 따뜻하며, 머피가 준비한 추로스는 달콤하고, 레크가 대접한 키니네 워터는 쌉싸름했다. \n이 모든 것이 너무나 새로웠고, 그녀는 더 많은 것을 느끼고, 더 많이 맛보고 싶다는 갈망을 누를 수 없었다. \n무엇보다 중요한 것은, 그 사람이 아직 곁에 있다는 것. 이렇게 생생하고, 이렇게 현실타래적이라는 점이었다. \n마치 과거의 그 모든 파멸, 붕괴, 고통, 절망이 환상처럼 느껴지는 것이다. \n“……” \n화창한 해변에서 환행·라모나는 말을 멈추고, 천천히 그러나 단호하게 미소를 지어 보였다. \n“그래, 우리는 휴가 중이야. 그러니 비밀지기여, 나와 함께 걸으며 바닷바람 좀 쐬지 않을래?” \n동시에, 저 끝없는 순수한 검은 밤하늘 아래의 그녀도 눈물을 적신 안대를 쓰고, 깨어나고 싶지 않은 자각몽 속에서 똑같은 미소를 지어 보였다. \n이번에는, 그녀는 수없이 부서졌던 그 아름다움을 드디어 가질 수 있었다. \n설령, 그것이 단지 하나의 환상이더라도."
  },
  Item_116763_Name = {
    Text = "환몽의 휴일"
  },
  Item_116764_Desc = {
    Text = "해제 후, “각인된 출발”의 모든 임무를 완료하면 추가 보상을 받을 수 있습니다"
  },
  Item_116764_Name = {
    Text = "각인의 출발"
  },
  Item_116792_Desc = {
    Text = "“와봐, 즐기자~”"
  },
  Item_116792_EmojiName = {Text = "유혹"},
  Item_116792_Name = {
    Text = "테이스·유혹"
  },
  Item_116872_Name = {
    Text = "에리카의 나무 인간"
  },
  Item_116873_Name = {
    Text = "릴리방수인"
  },
  Item_116874_Name = {
    Text = "오를라 방 나무 사람"
  },
  Item_116875_Name = {
    Text = "나의 방나무인"
  },
  Item_116878_Desc = {
    Text = "영역 숙련 속성의 명륜입니다."
  },
  Item_116878_Name = {
    Text = "다시 만날 거야"
  },
  Item_116878_StoryDesc = {
    Text = "당신과 라모나는 다시 만날 약속을 한 적이 없었습니다.\n문살이 눈앞에서 천천히 닫히던 그 순간, 두 사람의 마음속에 새겨진 이별의 기한은 이미 영원으로 정해져 있었습니다.\n\n그러니, 그녀가 시간의 틈새에서, 순식간에 스쳐 지나가는 만남 속에 살며시 당신의 새끼손가락을 걸어왔을 때……\n이것은 이미 기대 밖의, 충분히 행운인 재회였습니다.\n\"당신은 조금도 변하지 않았네요.\" 그녀가 말했습니다.\n\n이 한마디를 위해, 손끝의 희미한 온기를 위해……설령 두 세계가 가로막혀 있다 해도, 당신은 모든 것을 바쳐 은하를 넘어 그녀를 만나러 가고 싶었습니다.\n내년 오늘, 새끼손가락을 걸고 맹세합니다."
  },
  Item_117263_Desc = {
    Text = "누군가의 꿈속에서 흩어진 감정 입자로, 만지면 누군가가 지나온 길을 돌아볼 때의 방황하는 속삭임이 들리는 듯하다.\n조사 이벤트 「낙원」에서 수호자의 공명을 높이는 데 사용됩니다."
  },
  Item_117263_Name = {
    Text = "방황하는 마음"
  },
  Item_117843_Desc = {
    Text = "미사그는 정기적으로 태양 흑점 방사선 측정을 실타래시하여 깨어남체의 정신적 간섭을 배제한다."
  },
  Item_117843_Name = {
    Text = "방사선 감시"
  },
  Item_117844_Desc = {
    Text = "미사그는 정기적으로 달 거리 측정을 실타래시하여 검은 연못 내 은심의 안정성을 확인한다."
  },
  Item_117844_Name = {
    Text = "월거리 원적외선"
  },
  Item_117845_Desc = {
    Text = "미사그는 정기적으로 조수 수위 측정을 실타래시하여 심해 내 은심의 풍부도 지표 변화를 모니터링한다."
  },
  Item_117845_Name = {
    Text = "조류 검사"
  },
  Item_118128_Desc = {
    Text = "이 열쇠를 기록한 후, 편성 시 열쇠 능력: 「편항선」을 선택할 수 있습니다.\n\n심해의 사도가 경건하게 소녀의 계단 아래에 무릎 꿇고, 충정이라는 이름의 입맞춤을 바칩니다.\n잘못된 항로 위에서, 그녀는 이미 너무 멀리 나아가 버렸습니다."
  },
  Item_118128_Name = {
    Text = "기울어진 배"
  },
  Item_118128_StoryDesc = {
    Text = "바다의 사도가 경건히 소녀의 계단 아래에 무릎 꿇고, 충정이라는 이름의 입맞춤을 바친다.\n잘못된 항로 위에서, 그녀는 이미 너무 멀리 나아가 버렸다."
  },
  Item_118305_Desc = {
    Text = "심잠 경험치가 일정 수치에 도달하면 심잠 등급이 상승한다. 환몽 심잠에서 획득할 수 있다."
  },
  Item_118305_Name = {
    Text = "심잠 경험치"
