  Item_119011_Desc = {
    Text = "순차 선택 모드 경험치가 일정 값에 도달 시 순차 선택 모드 레벨이 상승합니다. 페이즈 체스 모드에서 획득 가능합니다."
  },
  Item_119011_Name = {
    Text = "회전 선택 경험치"
