  Item_119012_Name = {
    Text = "사전 편성 경험치"
  },
  Item_119149_Desc = {
    Text = "혼돈 공간에서 진행된 기밀 실타래험을 기록한 신비한 고서이다.\n이곳에서 「스타즈 챕터」의 「혼돈」 영역에 속한 제한된 명륜 중 하나를 무료로 선택하여 얻을 수 있다."
  },
  Item_119149_Name = {
    Text = "카오스 실타래험·스타즈 챕터"
  },
  Item_119150_Desc = {
    Text = "우주에서 수많은 운명의 축소판을 기록한 신비한 고서.\n이곳에서 무료로 「스타즈 챕터」의 랜덤 제한된 명륜을 하나 얻을 수 있다."
  },
  Item_119150_Name = {
    Text = "운명 잠금·스타즈 챕터"
  },
  Item_119151_Desc = {
    Text = "정신 차원에서 깨어남 장치의 앵커 포인트 위치를 삭제하고, 정신 링크 장치만으로 원질 포착을 하면 순간적인 미지의 공진을 일으킬 수 있습니다. \n 그로부터 무료로 1개의 “스타즈 챕터”에 속한 랜덤 한정 깨어남체를 깨어남할 수 있습니다."
  },
  Item_119151_Name = {
    Text = "세피로트 캡처·스타즈 챕터"
  },
  Item_119152_Desc = {
    Text = "당신이 익숙한 세계에서 초차원 영역으로 방향을 잡아 깨어남하는 세피로트 캡처 기술입니다. \n그로부터 1개의 “스타즈 챕터”에 속한 “초차원” 영역 한정 깨어남체를 무료로 깨어남할 수 있습니다."
  },
  Item_119152_Name = {
    Text = "초원차원 매핑·스타즈 챕터"
  },
  Item_119153_Desc = {
    Text = "혈육의 피부에 쓰인 암호를 기록한 신비한 고서이다.\n이곳에서 「스타즈 챕터」의 「혈육」 영역에 속한 제한된 명륜 중 하나를 무료로 선택하여 얻을 수 있다."
  },
  Item_119153_Name = {
    Text = "혈육의 비밀·스타즈 챕터"
  },
  Item_119154_Desc = {
    Text = "심해에서 오래전부터 전해 내려오는 비밀을 기록한 신비한 고서이다.\n이곳에서 「스타즈 챕터」의 「심해」 영역에 속한 제한된 명륜 중 하나를 무료로 선택하여 얻을 수 있다."
  },
  Item_119154_Name = {
    Text = "심해 비전서·스타즈 챕터"
  },
  Item_119155_Desc = {
    Text = "그 가치는 빛나는 외관에 걸맞습니다. \n광휘의 은핵을 보관하는 보급 상자로, 태스크를 수행하는 수호자에게 지원을 제공합니다."
  },
  Item_119155_Name = {
