  },
  Item_119157_Name = {
    Text = "혈육의 탄생·스타즈 챕터"
  },
  Item_119158_Desc = {
    Text = "당신이 익숙한 세계에서 카오스 경계역으로 깨어남하기 위한 원질 포착 기술입니다. \n그 중에서 1개의 “스타즈 챕터”에 속한 “혼돈” 경계역 한정 깨어남체를 무료로 깨어남할 수 있습니다."
  },
  Item_119158_Name = {
    Text = "혼돈의 메아리·스타즈 챕터"
  },
  Item_119159_Desc = {
    Text = "당신이 잘 아는 세계에서 심해 영역으로 깨어남하기 위한 세피로트 캡처 기술을 정향시킵니다. \n그로부터 1개의 “스타즈 챕터”에 속한 “심해” 영역 한정 깨어남체를 무료로 깨어남할 수 있습니다."
  },
  Item_119159_Name = {
    Text = "심해의 그림자·스타즈 챕터"
  },
  Item_119432_Desc = {
    Text = "펜촉을 끌로 삼고, 먹물을 벽돌 삼아 언어의 틈새에서 하늘을 향한 탑을 재건한다."
  },
  Item_119432_Name = {
    Text = "바벨탑의 장"
  },
  Item_119432_StoryDesc = {
    Text = "현지화 자원봉사자 아바타 프레임"
  },
  Item_119689_Desc = {
    Text = "의상 「광욕의 연회」 획득 시 개방됩니다. \n「자, 작은 묘목아. 욕망을 드러내고, 끝나지 않는 환락에 동참하렴!」"
  },
  Item_119689_Name = {
    Text = "광욕의 연회"
  },
  Item_119690_Desc = {
    Text = "팡... 팡...\n아란의 가장 뛰어난 사냥꾼으로서, 나는 다양한 열악한 환경에 이미 익숙하다 — 사막, 열대우림, 늪지, 심지어는 위산으로 가득 찬 거대한 괴물의 배속에서도 조금의 동요도 느끼지 않는다.\n하지만 알 수 없는 이유로, 몸에 이 찐득한 액체를 느낄 때 나는 불편하게 몸을 떨었다, 마치 인간이 절대 접촉할 수 없는 더러운 것처럼.\n「착한 아이야... 착한 아이야...」\n내가 아기라고? 지금은 확신할 수 없지만, 내 몸에 무언가 변화가 일어난 것이다.\n따뜻한 두 손이 나를 부드럽게 안아올리고, 뒤에 있는 양육자의 품속으로 사라지며, 한가득 욕망이 나를 감싸고, 마치 양수처럼 따뜻해 나를 편안하게 해준다.\n나는 몇 번 시도하다가, 마침내 눈을 떴지만, 눈앞에 아찔한 광경이 나를 본능적으로 비틀거리게 했고, 온 몸을 풍만한 유방 속에 파묻으려고 했다.\n그것은 촉수가 왜곡되어 얽혀있는 뿔, 머리를 세로로 가르는 거대한 입, 끊임없이 떨어지는 녹색 점액이었고, 나는 이런 공포스러운 괴물을 본 적이 없다…… 시선을 돌리고 싶었지만, 마치 마법에 걸린 듯, 나는 눈앞의 기형적인 것에 시선을 잠금할 수밖에 없었다.\n그들도 나를 응시하고 있었고, 나는 그들의 눈빛에서 나의 육체에 대한 갈망을 쉽게 읽었다.\n하지만 왜…… 그 미친 눈빛 속에는 그런 순수한 기대가 담겨 있을까?\n「착한 아이야... 두려워하지 마...」\n어머니처럼 부드러운 말소리가 내 귀에 울려 퍼졌고, 따뜻한 손바닥이 내 전신을 스치는 느낌, 이 순간 내 기분은 갑자기 평온해졌고, 마치 뒤에 있는 사람이 진짜 내 어머니인 듯, 나는 지금 가장 안전한 항구에 있는 것 같다.\n비록 내 이성이 이럴 리가 없다고 말하지만, 나는 여전히 애교 섞인 듯 그녀가 내 머리카락을 빗겨주는 것을 만지작거리다…… 잠시만, 머리카락을 빗는다고?\n무언가를 깨닫고 나서, 나는 내 몸을 만지려고 했고, 눈앞에 있는 것은 흉터 투성이의 손이 아니라, 검은 양발이었다.\n아… 이렇게… 이게 바로 나의 본래 모습이었고, 이것이 어머니가 나에게 주었던 것이다……\n내가 이 점을 깨닫는 순간, 혈맥의 가장 깊은 곳에 묻혀 있는 모든 것이 순간적으로 눈앞에 떠올랐고, 나는 내 정체성, 내 사명, 그리고…… 나의 억누를 수 없는 욕망을 이해했다.\n「어어——————!!」\n나는 어머니의 품에서 뛰어내리며, 귀청이 찢어질 듯한 분노의 포효를 내지르고, 형제자매들 속으로 날아갔다.\n나는 내 책임을 수행할 것이고, 어머니의 의지를 이행할 것이다.\n\n「어어——————————!!!!!!!!!!」\n나의 합류와 함께, 모든 형제자매들이 동시에 흥분한 외침을 내지르며, 이 외침은 천지를 진동시키며 잔치의 시작을 알렸다.\n우리는 핥고, 얽히고, 굵은 촉수로 서로의 모든 구석을 깊이 파고들고, 이어서 서로를 물어뜯으며, 서로의 혈육이 섞이는 것으로 내버려두었다.\n우리는 외향으로 달려가고, 눈앞의 모든 것을 무차별적으로 삼킴으로써, 우리는 광욕의 어머니가 내리신 불길한 자식이며, 이 타락한 잔치의 유일한 주인공이다.\n우리는 자신의 욕망을 억누를 필요가 없고, 우리는 속세의 외피를 벗어던졌고, 우리는 마음껏 삼키고, 마음껏 번식하고, 마음껏 어머니에게서 전해진 무상한 욕망을 방출한다.\n이것은 어머니에게 바치는 잔치이며, 우리는 이 세상을 더러운 혈육으로 변신시켜, 최고의 어머니께 바칠 것이다!\n\n타이스는 잔치의 중앙에 서서 세상이 삼켜지는 비명소리를 듣고 있었다.\n「그래, 바로 그거야.」\n완전히 축제에 참여한 자식들을 바라보며, 자애로운 어머니는 가장 본질적인 광기를 드러냈다.\n「가라, 가라, 더 이상 그 약한 것들로 가장할 필요 없다, 세상에 너희의 진정한 모습을 보여줘라！」\n얇은 스카프가 춤추며 공중에서 날아다니고, 그 안에서 희미하게 드러나는 꿀빛이 보인다.\n「너희는 원초의 사도이며, 누구에게도 인정받을 필요가 없고, 이제는 더 이상 세속적으로 인정받지 못하는 욕망을 억누를 필요가 없다！」\n이것은 멈추지 않는 춤이며, 이것은 멈추지 않는 타락 잔치다.\n「이 세상을 너희의 형제자매들로 모두 변화시켜라!」"
  },
  Item_119690_Name = {
    Text = "광욕의 연회"
  },
  Item_119952_Desc = {
    Text = "이 키를 기록한 후, 편성할 때 키 능력:「소원 재회」를 선택할 수 있습니다.\n\n수많은 그리움이 유성으로 변해, 여러분과 다시 만날 수 있도록 달려갑니다."
  },
  Item_119952_Name = {
