  Item_120472_Desc = {
    Text = "과학은 스펙트럼 분석이고, 예술은 광합성입니다.\n랜덤으로 광합제 의식 비밀 계약 세트 부품이 드롭됩니다."
  },
  Item_120472_Name = {
