  },
  Item_120491_Desc = {
    Text = "이 키링을 기록한 후, 편성 시 키링 스킬: 「안개 속에서 온」을 선택할 수 있습니다.\n\n그 세계의 안개 경계 조사단 선봉 「모카」는 바로 그녀이다.\n이 세계에서 은과 피의 세례를 받은 「모카」도 그녀이다.\n이 「고향」의 기운이 담긴 명찰은 이 차원을 넘어서는 여행의 영원한 증거이다."
  },
  Item_120491_Name = {
