  Item_120491_StoryDesc = {
    Text = "그 세계의 안개 경계 조사단 선봉 「모샤」는 바로 그녀이다.\n이 세계에서 은과 피의 세례를 받은 「모샤」도 그녀이다.\n이 「고향」의 기운이 담긴 명찰은 이 차원을 넘어서는 여행의 영원한 증거이다."
  },
  Item_120492_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
