  Item_120964_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「미사그 내부에서 발행한 한정 우표로, 수밀인의 곁에서만 이 극히 희귀한 차원 행자를 볼 수 있다고 합니다.」"
