  },
  Item_120965_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「미사그 내부에서 발행한 한정 우표로, 동시에 어느 클럽의 입장권이기도 하며 특정 여성에게 한 번의 기묘한 서비스를 교환할 수 있습니다.」"
