  Item_122409_Desc = {
    Text = "「안개」 외곽에서 흘러나온 물질로, 무셰트가 이것들을 수집하여 안개의 원천에게 제공할 양분으로 사용한다고 한다.\n\n최소 {s1}개 드롭"
  },
  Item_122409_Name = {
    Text = "안개의 시선"
  },
  Item_122410_Desc = {
    Text = "활동 「안개 속의 제물 의식」을 완료하여 성취를 획득합니다.\n「나는 모샤라고 해, 이번에는 꼭 기억해 줘.」"
  },
  Item_122410_Name = {
    Text = "은열쇠의 이름으로: 모샤"
  },
  Item_122410_StoryDesc = {
    Text = "모샤 플레이 이벤트"
  },
  Item_123321_Desc = {
    Text = "해금 후, 「은서 기행」의 모든 태스크를 완료하면 다음과 같은 추가 보상을 획득할 수 있습니다"
  },
  Item_123321_Name = {
    Text = "은상 기행"
  },
  Item_123478_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「순전무죄한 창백한 사자여, 부신께서 그대가 걸을 길을 보호하시길.」"
  },
  Item_123478_Name = {
    Text = "결코 색이 바래지 않는 어제: 살바도르"
  },
  Item_123478_StoryDesc = {
    Text = "제28기 학기 과제"
  },
  Item_123481_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「비밀 수호자, 어제 내가 보낸 목도리…… 마음에 들어?」"
  },
  Item_123481_Name = {
    Text = "영원히 색이 바래지 않는 어제: 에이지스"
  },
  Item_123481_StoryDesc = {
    Text = "제28기 학기 과제"
  },
  Item_123482_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「죽여! 죽여! 죽여!! 하하하! 송어 피의 향기!」"
  },
  Item_123482_Name = {
    Text = "결코 바래지 않는 어제: 유우하시"
  },
  Item_123482_StoryDesc = {
    Text = "제27기 학기 과제"
  },
  Item_123483_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「나를 속박했던 이 쇠사슬로, 나에게 족쇄를 채우려는 모든 자를 찢어버리겠어!」"
  },
  Item_123483_Name = {
    Text = "결코 바래지 않는 어제: 혈연·시로"
  },
  Item_123483_StoryDesc = {
    Text = "제26기 학기 과제"
  },
  Item_123484_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「장미가 피어난 풍경은 여전히 이토록 눈이 즐겁군, 한 잔 함께하세, 나의 벗이여.」"
  },
  Item_123484_Name = {
    Text = "결코 바래지 않는 어제: 소렐"
  },
  Item_123484_StoryDesc = {
    Text = "제27기 학기 과제"
  },
  Item_123485_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「오늘 아이들은 뭘 가져올까?」"
  },
  Item_123485_Name = {
    Text = "결코 바래지 않는 어제: 아그리파"
  },
  Item_123485_StoryDesc = {
    Text = "제27기 학기 과제"
  },
  Item_123486_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「아…… 더 많은 고통을 내려주세요~」"
  },
  Item_123486_Name = {
    Text = "결코 희미해지지 않는 어제: 레야"
  },
  Item_123486_StoryDesc = {
    Text = "제29기 학기 과제"
  },
  Item_123487_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「밤이 깊었구나, 작은 묘목아. 자, 어젯밤 다 하지 못한 일을 계속하자꾸나~」"
  },
  Item_123487_Name = {
    Text = "영원히 바래지지 않는 어제: 테이스"
  },
  Item_123487_StoryDesc = {
    Text = "제28기 학기 과제"
  },
  Item_123552_Desc = {
    Text = "「아름다운 설탕 눈꽃이네요…… 어? 누가 내가 원한다고 했나요! 하지만 받지 않으면 실타래망하겠죠…… 고마워요.」"
  },
  Item_123552_Name = {
    Text = "진저브레드 파티·카이커스"
  },
  Item_123553_Desc = {
    Text = "「은서리 밤 즐거워요, 수호자. 자, 이것은 선물입니다.」"
  },
  Item_123553_EmojiName = {
    Text = "당신에게 선물"
  },
  Item_123553_Name = {
    Text = "폴룩스·당신에게 선물"
  },
  Item_123554_Desc = {
    Text = "「아이구 아이구, 마법사님이 던진 상자 안에, 선물인지 폭탄인지 맞춰봐?」"
  },
  Item_123554_EmojiName = {Text = "던지다"},
  Item_123554_Name = {
    Text = "카시아·던지기"
  },
  Item_123555_Desc = {
    Text = "「당신이 저와 함께 숲에서 한 시간 동안 머물러 주실타래 수 있나요? 저는… 사탕집의 향기를 다시 느끼고 싶어요.」"
  },
  Item_123555_Name = {
    Text = "진저브레드 파티·오를라"
  },
  Item_123556_Desc = {
    Text = "「나는 모두의 은서리 밤을 밝히기 위해 노력할 것입니다.」"
  },
  Item_123556_EmojiName = {Text = "빛나는"},
  Item_123556_Name = {
    Text = "팔로스·발광"
  },
  Item_123557_Desc = {
    Text = "「오늘 밤, 우리는 생강빵과 메이플 시럽을 마시며 이 위대한 파티를 축하하자!」"
  },
  Item_123557_Name = {
    Text = "진저브레드 파티·도어세인"
  },
  Item_123558_Desc = {
    Text = "「겨울 건너절 축제 잘 보내세요, 은인님. 아…… 모자가 깃털을 눌렀네요」"
  },
  Item_123558_EmojiName = {
    Text = "겨울 건너절 축제 잘 보내세요"
  },
  Item_123558_Name = {
    Text = "카스토르·겨울 건너절 축제 잘 보내세요"
  },
  Item_123559_Desc = {
    Text = "알려지지 않은 존재가 당신의 메일박스에 이 초대장과 생강 향이 나는 부스러기를 남겼습니다——\n 사용 후 아직 얻지 못한 「생강빵 파티」 시리즈 아바타를 선택할 수 있습니다."
  },
  Item_123559_Name = {
    Text = "진저브레드 파티 초대장"
  },
  Item_123560_Desc = {
    Text = "전설에 따르면 은상밤 저녁에 양말을 침대 머리맡에 걸어두면 동지 축제 아침에 신비한 선물을 받을 수 있습니다. 꼭 씻은 양말을 걸어두세요. \n사용 후 아직 얻지 못한「미사그 겨울나기」시리즈 감정 표현 중 하나를 선택할 수 있습니다."
  },
  Item_123560_Name = {
    Text = "겨울나기 기념 교환권"
  },
  Item_123561_Desc = {
    Text = "「뭐 하는 거야, 너는 어찌 감히 이런 불경한 표정으로 본 신모를 쳐다보는 거냐?!」"
  },
  Item_123561_EmojiName = {Text = "양말"},
  Item_123561_Name = {
    Text = "환상·머피·양말"
  },
  Item_123638_Desc = {
    Text = "아이들이 은서리 밤 전날 준비한 소원 상자, 그 위에는 받고 싶은 선물에 대한 쪽지가 붙어 있다. \n \"나는 벌써 1년 동안 착한 아이였으니, 이제 겨울 건너절 사자가 나에게 선물을 줘야겠지!\""
  },
  Item_123638_Name = {
    Text = "은상기도상자"
  },
  Item_123639_Desc = {
    Text = "겨울 건너절 아침에만 나타나는 특별한 선물 상자는 열면 급속히 사라지기 때문에 아는 사람이 드뭅니다. \n \"쉿, 이건 착한 아이와 겨울 건너절 사자 사이의 비밀이에요.\""
  },
  Item_123639_Name = {
    Text = "겨울 건너절 선물상자"
  },
  Item_123757_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「감, 감사합니다…… 아! 가까이 오지 마세요…… 다, 다치실타래 수 있어요……」"
  },
  Item_123757_Name = {
    Text = "결코 바래지 않는 어제: 파인트"
  },
  Item_123757_StoryDesc = {
    Text = "제29기 학기 과제"
  },
  Item_124899_Desc = {
    Text = "이 열쇠 지령을 기록한 후, 배치 시 열쇠 지령 능력: \"운명의 궤적\"을 선택할 수 있습니다.\n\n직물, 측정, 그리고 판별.\n운명의 신은 슬픔도 기쁨도 없으며, 운명의 방적기는 영원히 멈추지 않습니다."
  },
  Item_124899_Name = {
    Text = "운명의 궤적"
  },
  Item_124899_StoryDesc = {
    Text = "방직, 측량, 그리고 재단.\n운명의 신은 슬픔도 기쁨도 없고, 운명의 물레는 영원히 쉬지 않는다."
  },
  Item_125136_Desc = {
    Text = "피해 증폭 속성의 명륜입니다."
  },
  Item_125136_Name = {
    Text = "백합의 미끼"
  },
  Item_125136_StoryDesc = {
    Text = "그것은 내가 아버지와 함께 해성으로 이사한 두 번째 해였다. 이블린의 편지 속 눈물 어린 호소는 나를 불안하게 했고, 나는 그녀와의 이별을 결심했다. 이것은 비단과 흑단으로 장식된 부유한 땅으로, 모든 식체자들은 그것이 잠들 때의 혼란을 감지했다. 지폐의 액면가로 동등한 무게의 금을 교환할 수 있으며, 그 항로를 장악하면 극소의 비용으로 천만 배의 재산을 쟁취할 수 있다. \n 그러나 이블린은 아마도 그녀의 애매하고 추적하기 힘든 기괴한 혈통 때문인 신경질적인 이 여자는 조상들의 전언을 굳게 믿고 있었다. 동양에는 그들의 방계가 믿는 이질적인 신이 있으며, 심해의 어떤 어류처럼 맛있는 미끼를 흔들어 놓아, 먹이를 조용히 천천히 먹어들이는 장면으로 끌어들인다. \n 그녀는 틀렸다. 해성에는 바다의 짭짤한 맛이 전혀 없다. \n 오직 층층이 쌓인, 매혹적이고도 두려운 백목련만이 있을 뿐이다. \n 나와 아버지를 동시에 빠뜨린 백목련. \n 그녀를 처음 보았을 때, 「서」라는 이름의 여자의 모습이 내 시야에 나타난 첫 순간, 나는 영원히 이 고대의 땅에서 벗어날 수 없게 되었다. \n 그녀는 가까이하고 싶게 만들었고, 소유하고 싶게 만들었고, @3 하고 싶게 만들었다. \n 그녀는 그녀는 그녀는 그녀는 그녀는 원하고 원하고 원하고 원하고 원하고 \n\n 잘라내고 쪼개고 파내고 영원히 영원히 영원히 영원히 영원히……@2@3@2!! \n 아, 나는 왜 여기에 왔는가? 나는 무엇을 가져가야 하는가? 나는…… 누구인가? \n 더 이상 중요하지 않다. 그녀가 나를 초대했으며, 나는 그 대저택의 테이블 앞에 앉았다. \n 이미 나와 마찬가지로 미친 아버지는 순종적인 미소를 띠고 있었고, 다채로운 반찬들이 식탁을 가득 채우고 있었으며, 금속 뚜껑이 있는 접시는 불협화음처럼 보였다. \n\n 서는 빛을 거슬러 저녁 햇살 속에 앉아 있었고, 광채가 그녀에게 부드러운 금 테두리를 더해주었으며, 천천히 그 검은 부채를 내려놓았다. \n 이블린 같고, 나의 어린 시절 친구 같고, 흐릿한 만남 같고…… 나의 어머니 같았다. \n 그것은 마치 사원 안의 금도금된 신상처럼 단정하고 아름다운 얼굴이었다. \n 나는 흡입하는 소리를 듣지 못했으며, 아버지에게서 나는 비린내를 맡지 못했지만, 그 얼굴과 그 얼굴의 주인이 하얀 손으로 접시를 열고 적당한 고기를 집어 올리는 것을 매료되어 바라보았다. 그녀는 나를 부르며, 구워진 동물의 기름이 내 입가에 떨어졌다. \n 「젊은 선생님, 당신은 뭔가를 먹어야 합니다.」 \n 나는 온순하고 무감각하게 입을 벌렸다. \n 백목련이 이미 피었고, 그것이 나를 향해 조용히 늘어져 있었다. \n ——「무명자의 손기록」"
  },
  Item_125137_Desc = {
    Text = "남자들은 앞다투어 진귀한 보물을 바쳤지만, 모두 매일 가장 진하고 달콤한 배사탕 한 솥을 사오라는 요구를 받았다.\n그녀는 그것이 아가씨의 이를 부식시키도록 내버려두지 않을 것이니, 마치 사신이 늘 나쁜 소원을 들어주기 좋아하듯.\n\n최소 {s1}개 드롭"
  },
