  },
  Item_125189_Name = {Text = "배사탕"},
  Item_125190_Desc = {
    Text = "이 키오링을 기록한 후, 편성 시 키오링 능력: 「심집순이의 옛 이야기」를 선택할 수 있습니다.\n\n깊은 집안에는 너무 많은 비밀이 숨겨져 있습니다. 권력에 관한 것, 집착에 관한 것, 욕망에 관한 것.\n사악한 신이 세상에 던진 한 번의 시선은 「즐거움」과 「왜곡」이 가득한 사랑을 담고 있습니다."
  },
