  Item_127058_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「미사그 내부에서 발행한 한정 우표로, 위에 인쇄된 것은……정의! 정의!! 절대적인 정의!」"
