  Item_127059_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「미사그 내부에서 발행한 한정 우표로, 선택받은 자는 그 위에서 억만 광휘로 빛나는 진리를 보게 될 것입니다.」"
