  Item_127067_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「미사그 내부에서 발행한 한정 우표로, 한 번만 바라봐도 마음이 치유되는 느낌을 받을 수 있습니다.」"
