  },
  Item_127070_StoryDesc = {
    Text = "제29기 페이즈 대결"
  },
  Item_127087_Desc = {
    Text = "「너의 마음을 보여줘~」"
  },
  Item_127087_EmojiName = {Text = "심리학"},
  Item_127087_Name = {
    Text = "클레멘타인·심리학"
  },
  Item_127524_Desc = {
    Text = "「휴대가 매우 편리하고 성능도 떨어지지 않습니다. 돌 교수님이 독립적으로 개발한 휴대용 단말기를 선택하세요!」"
  },
  Item_127524_Name = {
    Text = "에리카·휴대용 단말기"
  },
  Item_127524_StoryDesc = {
    Text = "모바일 로그인 이벤트 프로필"
  },
  Item_127525_Desc = {
    Text = "「성능 좋고, 반응 빠릅니다. 돌 교수님 이름으로 허가된 대형 단말기를 선택해 주세요!」"
  },
  Item_127525_Name = {
    Text = "웬코르·대형 터미널"
  },
  Item_127525_StoryDesc = {
    Text = "PC단 로그인 이벤트 프로필"
  },
  Item_128552_Name = {Text = "차표"},
  Item_128659_Desc = {
    Text = "기세절 당일뿐만 아니라, 그 이후의 정확히 반달 동안 판룡 고국 곳곳에는 기쁨의 분위기가 넘쳐 흐릅니다.\n사람들은 선물을 들고 여기저기 친척과 친구를 방문합니다. 모든 부와 기쁨, 그리고 축복의 의미를 상징하는 좋은 것들은 가장 좋은 소망과 함께 이 선물 상자에 담깁니다."
  },
  Item_128659_Name = {
    Text = "기원 행운 상자"
  },
  Item_128660_Desc = {
    Text = "판룡 고국에서, 모든 아이들은 기세절의 도래를 기다리고 있습니다. \n 대추 반죽 과자, 땅콩 과자, 아몬드 사탕, 그리고 부모님과 조부모님이 준비한 세뱃돈, 이렇게 한분 선물을 받으면 반드시 길하고 순조로운 한 해를 보낼 수 있을 것입니다."
  },
  Item_128660_Name = {
    Text = "기원 길상상자"
  },
  Item_129143_Desc = {
    Text = "환락 열차에 흩어진 감정 입자로, 만질 때 어린「N」의 웃음소리가 들리는 듯하다.\n「질주하는 환락 전용열차」에서 수호자의 공명을 높이는 데 사용된다."
  },
  Item_129143_Name = {
    Text = "기억의 마음"
  },
  Item_129498_Desc = {
    Text = "VIP 포인트가 일정 값에 도달하면, 「객실타래 등급」 이 상승합니다. 「질주하는 환희 특급 열차」에서 획득할 수 있습니다."
  },
  Item_129498_Name = {
    Text = "귀빈 포인트"
  },
  Item_129499_Desc = {
    Text = "이 키오링을 기록한 후, 편성 시 키오링 스킬: 「세말의 꽃불」을 선택할 수 있습니다. \n\n해마다 꽃은 비슷하고, 해마다 재회를 기다립니다. \n오늘 밤 기원하며, 한 꿈을 꿉니다. 나의 작은 재스민 꽃이 구인 곁에서, 함께 만천하의 불꽃놀이를 감상할 때, 나의 정을 잊지 말기를 바랍니다."
  },
  Item_129499_Name = {
    Text = "연말 불꽃"
  },
  Item_129499_StoryDesc = {
    Text = "해마다 꽃은 비슷하고, 해마다 우리는 재회를 기다립니다.\n오늘 밤 기도를 드리며, 한 꿈을 꿉니다. 나의 작은 모란꽃이 구인 곁에 있어, 함께 수많은 불꽃놀이를 감상할 때, 나의 정과 의리를 잊지 않기를 바랍니다."
  },
  Item_129628_Desc = {
    Text = "속성이 있는 은열 충전 등급의 명륜입니다."
  },
  Item_129628_Name = {
    Text = "진창을 밟고 있는 장미"
  },
  Item_129628_StoryDesc = {
    Text = "기록할 수 없는 어떤 루프 속에서, 회귀·라모나가 종탑 뒤의 화단을 밟았다. \n여유로운 시선으로 장미 정원에서 무리 지어 피어나는 꽃들을 보았다. \n드물게 잠깐 멈춘 후, 그녀는 모든 쓸데없는 생각을 던져버리고 최후의 전장으로 계속 달려갔다. \n진흙이 피처럼 짙은 꽃잎에 튀어 오르고, 순식간에 검은색 융식점액에 포식당해 오직 바람 속에서 당당한 뒷모습만 남았다."
  },
  Item_129898_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「우아한 요리에는 시간이 필요하지, 아~ 기대하고 있어, 네가 풍기는 그 잊을 수 없는 향기를.」"
  },
  Item_129898_Name = {
    Text = "영원히 사라지지 않을 어제: 두레인"
  },
  Item_129898_StoryDesc = {
    Text = "제29기 학기 과제"
  },
