  Item_130038_Desc = {
    Text = "어디서 왔는지 알 수 없는 인분으로, 사야의 묘포와 신비로운 공명을 일으키는 것 같다.\n사야에게 가져다주면 그녀로부터 보상을 받을 수 있다.\n\n최소 {s1}개 드롭"
  },
  Item_130038_Name = {
    Text = "붉은 비늘 가루"
  },
  Item_130039_Desc = {
    Text = "검은 인장 드롭율 속성의 명륜입니다."
  },
  Item_130039_Name = {
    Text = "진흙 속의 동화"
  },
  Item_130039_StoryDesc = {
    Text = "책장에는 딱딱한 연구 문헌 외에도, 재미있어 보이는 동화책 몇 권이 있었다.\n《신데렐라》, 《백설공주》, 《인어공주》, 《라푼젤》……그 주인이 왜 이 책들을 책장에 꽂아두었는지——이제는 알 길이 없다.\n\n그 이야기들은 현실타래과는 전혀 다른 줄거리를 엮어내고 있었다. 「왕자」, 「공주」, 「사랑」……이 단어들은 소녀의 마음을 두근거리게 했다.\n\n밤하늘에 반짝이는 무수한 빛이 대지 위로 쏟아져, 마치 흐르는 빛의 강을 이룰 것만 같았다.\n쏟아지는 달빛 속에서, 소녀는 살며시 발끝을 세우고, 투명한 유리 구두를 신은 척했다. 마치 줄곧 기다려온 것처럼——이 깊고 고독한 기나긴 밤이 마침내 밝아오기를……"
  },
  Item_130040_Desc = {
    Text = "순결하고 흠 없이 친근감을 주는 인분으로, 사야의 묘포와 신비로운 공명을 일으키는 것 같다.\n사야에게 가져다주면 그녀로부터 보상을 받을 수 있다.\n\n최소 {s1}개 드롭"
  },
