    Text = "붉은 비늘 가루"
  },
  Item_130063_Desc = {
    Text = "이 열령을 기록하면, 편대 시 열령 스킬: 「새로운 세계에 바치는 선물」을 선택할 수 있습니다.\n\n피어나라, 피어나라, 온 세상을 기쁨의 색으로 물들여라.\n그것은 오랜 치유, 영원한 지복, 사야가 곧 막을 올릴 새로운 세계에 보내는 마지막 선물."
