  },
  Item_130107_Name = {
    Text = "찬란한 비늘 가루"
  },
  Item_130224_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식이다. 미사그는 신비로운 의식을 통해 깨어남체의 영식을 깨우고, 깨달음을 받은 깨어남체는 정신 능력이 영구적으로 강화된다.\n사야를 반복적으로 얻을 때 전환하여 얻으며, 사야의 기령을 활성화하는 데 사용된다."
  },
  Item_130224_Name = {
    Text = "파편 · 사야"
  },
  Item_130224_StoryDesc = {
    Text = "중복으로 사야를 획득할 때 전환하여 획득하며, 사야의 기령을 활성화하는 데 사용됩니다."
  },
  Item_130225_Name = {Text = "사야"},
  Item_130363_Desc = {
    Text = "획득 깨어남체 「사토구아」 후에 해금"
  },
  Item_130363_Name = {
    Text = "차토구아"
  },
  Item_130364_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비로운 의식을 통해 깨어남체의 영식을 깨우며, 깨달음을 얻은 깨어남체는 정신 능력이 영구적으로 강화됩니다.\n반복적으로 사토구야를 획득할 때 변환하여 사토구야의 기령을 활성화하는 데 사용됩니다."
  },
  Item_130364_Name = {
    Text = "파편 · 사토구야"
  },
  Item_130364_StoryDesc = {
    Text = "중복으로 사토구야를 획득할 때 전환하여, 사토구야의 기령을 활성화하는 데 사용됩니다."
  },
  Item_130366_Name = {
    Text = "차토구아"
  },
  Item_130367_Name = {
    Text = "차토구아"
  },
  Item_130468_Desc = {
    Text = "속성이 있는 은열 충전 등급의 명륜입니다."
  },
  Item_130468_Name = {
    Text = "사토구야SR(임시 텍스트)"
  },
  Item_130468_StoryDesc = {
    Text = "사토구야SR(임시 텍스트)"
  },
  Item_130542_Name = {
    Text = "미사그 막간극: 오지에"
  },
  Item_130543_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「그 무의미하고 평범한 대본은 버려. 내가 연극을 어떻게 하는 건지 가르쳐 줄게.」"
  },
  Item_130543_Name = {
    Text = "미사그 막간극: 융해·돌"
  },
  Item_130543_StoryDesc = {
    Text = "제33기 학기 과제"
  },
  Item_130544_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「각본대로 싸우자니, 정말 통쾌하지 않군.」"
  },
  Item_130544_Name = {
    Text = "미사그 막간극: 로탄"
  },
  Item_130544_StoryDesc = {
    Text = "제36기 학기 과제"
  },
  Item_130545_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「촛불이 소품이냐고? 직접 한번 시험해 보면 알 수 있잖아~」"
  },
  Item_130545_Name = {
    Text = "미사그 막간극: 판디아"
  },
  Item_130545_StoryDesc = {
    Text = "제32기 학기 과제"
  },
  Item_130546_Name = {
    Text = "미사그 막간극: 엘바"
  },
  Item_130547_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「저기...... 저, 아니... 「우리」는 많은 배역들을 연습할 수 있어요—— 만약 당신이 필요로 한다면요.」"
  },
  Item_130547_Name = {
    Text = "미사그 막간극: 「24」"
  },
  Item_130547_StoryDesc = {
    Text = "제36기 학기 과제"
  },
  Item_130548_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「연구 시간을 낭비해서 연극이라니……아니, 싫다는 말은 안 했어. 에헴, 대본에 이 표정이라고 적혀 있는 건가?」"
  },
  Item_130548_Name = {
    Text = "미사그 막간극:돌"
  },
  Item_130548_StoryDesc = {
    Text = "제31기 학기 과제"
  },
  Item_130549_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「이건 로즈마리예요, 추억을 의미하죠. 또 팬지는 사려를 의미하기도 하고...... 아, 죄송해요. 대사를 읊고 있었네요. 꽃을 들고 오르는 이 장면, 정말 좋다고 생각해요.」"
  },
  Item_130549_Name = {
    Text = "미사그 막간극: 님피아"
  },
  Item_130549_StoryDesc = {
    Text = "제37기 학기 과제"
  },
  Item_130550_Desc = {
