  Item_130700_Desc = {
    Text = "작은 석탄 공, 싫어, 모스, 좋아! 작은 석탄 공, 제출, 보상~\n\n최소 {s1}개 드롭"
  },
  Item_130700_Name = {
    Text = "해태리 3호"
  },
  Item_130701_Desc = {
    Text = "작은 석탄 공, 좋아! 모스, 좋아! 수집, 많을수록 좋아~\n\n최소 {s1}개 드롭"
  },
  Item_130701_Name = {
    Text = "해각 1호"
  },
  Item_130702_Desc = {
    Text = "친구, 좋아, 모스, 수집! 도움, 보상! 친구에게 줘~\n\n최소 {s1}개 드롭"
  },
  Item_130702_Name = {
    Text = "해태 2호"
  },
  Item_130703_Desc = {
    Text = "이 키오링을 기록한 후, 편성 시 키링 스킬: 「익사한 순수」을 선택할 수 있습니다.\n\n비록 반드시 익사할 것임을 알고 있지만, 그녀는 여전히 망설임 없이 차가운 바다에 몸을 던집니다.\n왜냐하면 이것이 그녀의 순수한 사고 속에서 친구를 구하는 유일한 방법이기 때문입니다."
  },
  Item_130703_Name = {
    Text = "익사한 순수"
  },
  Item_130703_StoryDesc = {
    Text = "비록 죽음에 빠질 운명임을 깊이 알면서도, 그녀는 여전히 주저하지 않고 차가운 바다에 몸을 던졌다.\n왜냐하면 그것이 그녀의 순수한 사고 속에서 친구를 구하는 유일한 방법이기 때문이다."
  },
  Item_130704_Desc = {
    Text = "사용자의 광기 폭발의 명륜에 집중하면 탐색 중에 주기적으로 광기를 회복하고 그 광기 폭발 피해를 증가시키며, 몰아치는 파도 자세로 전환할 때 대량의 영역 숙련을 제공합니다."
  },
  Item_130704_Name = {
    Text = "먼 곳의 에덴"
  },
  Item_130704_StoryDesc = {
    Text = "이곳은 어떤 해도에도 기록되지 않은 섬이다.\n이 섬이 탄생한 이래, 「문명」이라는 바이러스는 단 한 번도 이 정토를 밟은 적이 없다.\n이곳에는 오직 모래사장, 정글, 끝이 보이지 않는 바다, 그리고…… 한 명의 작은 소녀만이 있을 뿐.\n………………………………\n「아빠, 엄마, 물고기!」\n「아오~~」\n두 마리의 돌고래가 느긋하게 소녀의 발치로 헤엄쳐 와 아름답고 맑은 울음소리를 냈다.\n그중 한 마리가 소녀를 등에 태우고, 다른 한 마리는 소녀의 손에서 막 기절시킨 물고기를 받아 한입에 삼켰다.\n「아오~~」\n「헤헤, 모스! 대단해!」\n세상물정 모르는 아이처럼, 소녀는 힘찬 동작을 취하며 「아빠」 「엄마」의 칭찬에 화답했다.\n「오늘, 태양! 좋아!」\n「모스! 아빠! 엄마! 산책!」\n소녀의 말을 들은 돌고래가 가볍게 한 번 울고는, 작은 섬을 돌며 천천히 헤엄치기 시작했다.\n따스한 햇살이 소녀에게 내리쬐어 며칠 전부터 가시지 않던 축축한 한기를 몰아냈고, 부드러운 바람이 소녀의 머리카락을 스치며 바다의 나른한 숨결을 실타래어왔다.\n웃음소리, 물 치는 소리, 장난치는 소리, 세상과 격리된 작은 섬에는 「문명」이 가져오는 번뇌 따위 없고, 가장 원시적이고 가장 순수한 웃음만이 남아 있었다.\n두 마리 짐승과 한 사람은 늘 그렇듯, 원시적이고 근심 없는 하루를 보냈다.\n………………………………\n그 끝없는 부름이 이 고요를 완전히 삼켜버리기 전까지는.\n「돌아와…… 돌아와……」\n「@1에게 네가 필요해…… @2…… @4…… 네가 필요해……」"
  },
  Item_130705_Desc = {
    Text = "친구, 좋아, 모스, 수집! 도움, 보상! 친구에게 줘~\n\n최소 {s1}개 드롭"
