  Item_130765_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 Mosk를 획득할 때 변환하여 획득하며, Mosk의 기령을 활성화하는 데 사용됩니다."
