  Item_131369_StoryDesc = {
    Text = "화려한 클럽 입구에서, 흰 셔츠를 입은 안내원이 한 손을 들어 레이크를 정중히 막았다. \n「선생님, 초대장이 없고 저희 회원도 아니신데 들어가실타래 수 없습니다.」 \n「그렇군요… 이거 곤란하네요…」 \n레이크는 손으로 턱을 만지며 생각하는 척 했다. 사실타래 그는 단지 기다리고 있었다. \n사건의 용의자를 기다리고 있었다. \n운명이 주는 가호을 기다리고 있었다. \n역시,그는 기다렸다.—— \n「이게 바로 유명한 렌티니언의 운 좋은 탐정이군요! 자, 자, 제가 당신의 추천인이 되겠습니다.」 \n「전 당신의 전설적인 운을 보고 싶었어요, 실타래망시키지 말아주세요…」 \n신사는 그렇게 말하며, 온화해 보이지만 악의가 가득한 미소를 지었다. \n이런 표정은 클럽에서 흔히 볼 수 있는 것이었다. 결국, 환락을 추구하는 도박꾼들이 규칙을 지킬 것이라고 기대할 수는 없으니까. 그래서 자신이 함정에 빠졌다는 것을 깨달았을 때, 레이크는 개의치 않고 단지 입꼬리를 올리며 여유롭게 휘스터 카드를 집어 들었다. \n서두르지 말자, 게임은 이제 시작일 뿐이니까, 그렇지? \n그래서 첫 번째 라운드, 두 번째 라운드, 세 번째 라운드… 한 판 한 판씩 이어졌다. \n결국 레이크는 모든 칩을 잃어버렸다. \n「운 좋은 탐정, 오늘 운이 좋지 않은 것 같군요. 아무래도 아무도 운명의 가호을 영원히 받을 수는 없죠…」 \n「계속 하시겠습니까? 탐정, 안타깝게도 당신은 이제 아무것도 남지 않았습니다.」 \n「아무것도 없다? 그렇지 않다.」 연패를 당한 탐정은 미소를 지으며 자신을 가리켰다. 「저는 이 잘 어울리는 정장과 이 비싼 지팡이, 그리고…」 \n탐정은 잠시 멈추고 정장의 가슴 주머니에서 작은 기계를 꺼내어 낮은 목소리로 미소 지으며 만졌다. 「당신의 속임수 기술이 매우 정교하다는 것을 인정합니다. 이 클럽의 주인조차도 이를 풀지 못하고 저에게 도움을 요청했죠. 하지만 아무리 정교한 기술이라도 시간과 조작, 협력이 필요합니다.」 \n「정말 안타깝게도, 이 미사그에서 나온 작은 장치는 당신과 당신의 동료들이 방금 클럽에서 속임수를 쓴 증거를 명확히 기록했습니다.」 \n신사는 잠시 멈칫하며 놀란 표정을 지었다. 그의 동료는 부끄러움을 느끼며 탐정에게 교훈을 주고 싶어했지만, 많은 사람들 앞에서 신사는 함부로 행동할 수 없었다. 더욱이 탐정은 그에게 선택을 주었다, 거절할 수 없는 선택. \n「한 번 더 배팅해보는 게 어때요? 만약 당신이 이기면 이 작은 장치와 제 목숨이 당신의 것이 됩니다. 제 뜻을 이해하셨죠?」 \n「그럼 제가 지면요?」 \n「지면 자수하셔야죠.」 레이크는 미소 지으며 어깨를 으쓱했다. 날카로운 송곳니를 드러내며, 「당신은 지겠습니까? 진정한 도박꾼은 자신이 이길 것이라고 믿기만 합니다.」 \n맞다, 모든 도박꾼은 자신이 이길 것이라고 생각한다. 그래서 누구도 이 도박을 거절할 수 없다. \n그래서 휘스터 카드가 다시 테이블 위를 돌고, 카드를 내고, 패를 깔고, 마지막으로 승패가 결정되었다. \n「Lucky~」 \n패자에게 한 번도 눈길을 주지 않고, 레이크는 웃으며 손을 들어 그가 딴 돈을 공중에 던졌다. 그러자 본래 시끌벅적한 클럽은 더욱 열광적으로 변해, 사람들의 쟁탈전의 외침, 부를 얻은 기쁨의 비명과 웃음으로 가득 찼다. \n그리고 그 외침, 비명, 웃음 속에서 레이크는 미사그에서 수여한, 각자 하나씩 받은 장신구를 가슴 주머니에 다시 넣고, 자신의 이름이 적힌 초대장을 주머니에서 두드리며, 입꼬리를 올리고 모자를 눌렀다. \n진정한 도박꾼은 자신이 이길 것이라고 믿기만 한다. \n그는 무엇을 하든지 간에 운명의 가호이 항상 그와 함께할 것이라고 확신하고 있다. \n"
  },
