  Item_132664_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「미사게 내부에서 발행한 한정 우표로, 발매되자마자 천문학적인 가격으로 치솟았다. 역시, 누구도 런디니엔에서 가장 빛나는 보석을 거부할 수 없으니까.」"
