  Item_132665_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「미사그 내부에서 발행한 한정 우표로, 우표 가장자리에서 따뜻한 백염이 끊임없이 타오르고 있습니다. 이것을 들어 올려 창백함에서 오는 자비를 느껴 보세요.」"
