  Item_132904_Desc = {
    Text = "임시 텍스트"
  },
  Item_132904_Name = {
    Text = "임시 텍스트"
  },
  Item_132905_Desc = {
    Text = "연약한 화채가 반짝이는 은심 결정.\n은심을 반복적으로 정제할 때 우연히 나타나며, 일정 시간 동안 상위 존재의 의지와 연결할 수 있다."
  },
  Item_132905_Name = {
    Text = "공환의 은핵"
  },
  Item_132906_Desc = {
    Text = "환의 「임시 텍스트」 획득 후 해금됩니다.\n「임시 텍스트」"
  },
  Item_132906_Name = {
    Text = "아라크네·임시 텍스트"
  },
  Item_133338_Desc = {
    Text = "폭발적으로 치명타 피해 버프를 제공하는 보조형 명륜"
  },
  Item_133338_Name = {
    Text = "은밀한 오후 휴식 시간"
  },
  Item_133338_StoryDesc = {
    Text = "아침 승마에서는 군의 신사들과 나란히 말을 달리며 개혁안에 대한 입장을 탐문해야 하고, 냉찬회에서는 각 가문의 부인들과 격식 있는 칭찬을 주고받아야 하며, 긴 만찬에서는 은촛대의 빛 아래 장황하고 위선적인 식전 기도를 경청해야 하고, 오페라가 끝난 후에는 특별석 복도에서 끝없는 사교적 인사를 감당해야 한다.\n\n「오직 후원 잔디밭 위의 오후 차 시간만이, 진정으로 나만의 시간이에요.」\n「이건 제가 처음으로 오후 차 손님을 초대하는 거예요. 화제를 선택할 권한을 당신에게 양도하겠어요.」\n\n소레이유가 갓 따른 홍차를 들어 올렸다.\n「드 크레메 백작이 최근 제출한 의회 개혁안에 대한 입장을 알고 싶으신가요? 아니면 보몽나 가문이 양당 사이에서 벌이는 미묘한 베팅? 혹은 순수하게 어느 자작 영애의 비밀에 관심이 있으신 건가요?」\n「전부 필요 없다고요? 그저 제 테이블 위의 분홍색 디저트 맛이 궁금하다고요?」\n그녀가 한 모금 홀짝이며, 원래 먼 곳을 바라보던 시선을 당신에게로 돌렸다.\n「그럼 잘 음미해 보세요.」\n「어떤 맛은, 직접 손을 대야만 진정으로 공감할 수 있는 법이니까요.」\n「그렇지 않나요, 존경하는 — 그분?」\n\n미사그 교복을 입은 방문객의 옷깃과 소매에서 검은 안개가 피어올랐고, 안개는 곧 짙은 혼돈의 덩어리로 뭉쳤다.\n「히히히, 정말로 자신이 숙명에서 벗어날 수 있다고 생각하나요?」\n「햇살이 좋으니, 먼저 드문 한가로운 시간을 즐기고 싶어요. 요즘 유행하는 홍차와 스펀지 케이크를 맛보고 싶으시다면 마음대로 하세요. 다른 일은, 오후 휴식 시간이 끝난 후에 다시 와주세요.」"
  },
  Item_133339_Desc = {
    Text = "해금 후, 「퐁텐 차향」의 모든 임무를 완료하면 아래 보상을 추가로 획득할 수 있습니다"
  },
  Item_133339_Name = {
    Text = "퐁텐 차향"
  },
  Item_133355_Desc = {
    Text = "지속적으로 은열쇠 에너지를 제공하는 명륜으로, 만개 시 더욱 강력한 효과를 발휘합니다."
  },
  Item_133355_Name = {
    Text = "벚꽃 아래의 미혹"
  },
  Item_133355_StoryDesc = {
    Text = "미사그의 우등생으로서, 라모나는 이성과 합리를 행동의 절대적 논리로 삼는 데 성공하여, 냉정함을 유지하고, 유머를 유지하고, 비할 데 없는 신뢰성을 유지해 왔다.\n하지만 가끔, 이런 라모나도 사색에 빠질 때가 있다. 세계의 절대적인 공포, 혹은 절대적인 찬란함 앞에서——\n끝없이 펼쳐져 시야를 가득 채운 분홍빛을 바라보며, 라모나는 말없이 침묵했다.\n그녀가 아는 바로는, 3주도 채 되지 않아 벚꽃은 처음 피어나서 모두 지고 만다. 그러니 가지를 묵직하게 뒤덮은 이 꽃들, 종횡으로 무성한 가지와 잎사귀도 곧 시들어, 황량함과 쓸쓸함에 빠지게 될 것이다.\n그리고 인간의 예상 수명은 3주보다 훨씬 길고, 3년보다 훨씬 길고, 30년보다도 훨씬 길지만, 이 벚나무들처럼 단 한 번뿐이다.\n인간의 가장 큰 착각은 자신이 영원히 살 것이라 믿는 것이다.\n라모나는 알고 있다.\n꽃이 피고 지는 것은 자연계에서 지극히 평범한 법칙이며, 인간의 삶과 죽음도 결국 자연계의 현상에 불과하다는 것을.\n라모나는 그것도 알고 있다.\n하지만 인간으로 태어난 이상, 자신의 존재에 의미를 부여하고 싶어 하는 법이며, 모든 신입생도 바로 그 때문에 미사그의 문을 두드린 것이다.\n그들은 융식에 맞서는 선봉이자, 인류의 미래를 지켜보는 중요한 방어선이다.\n그들의 생명은 단순히 객관적인 자연 현상이 아니며, 설령 소멸이 정해져 있다 해도, 이 세계의 궤적을 실타래질적으로 바꾸고 있다.\n그리고 그 과정에서, 그들은 어깨를 나란히 하고 싸우며, 비바람 속을 함께 걸어간다.\n마치 한 나무 위의 한 송이 꽃이 다른 한 송이 꽃에 기대어, 함께 봉오리를 맺고, 함께 흔들리며 떨어지고, 함께 피어나고 시드는 것처럼.\n이제, 돌아가야 할 때다.\n그녀가 기댈 수 있고, 그녀가 기대할 가치가 있는 그 꽃이, 아직 그녀를 기다리고 있으니."
  },
  Item_133404_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「짜잔～주문하신 미식 소품 세트입니다～」"
  },
  Item_133404_Name = {
    Text = "미사그 막간극: 카렌"
  },
  Item_133405_Name = {
    Text = "미사그 막간극: 타비"
  },
  Item_133406_Desc = {
    Text = "「아아아! 나는 이걸 보고 싶지 않아!」"
  },
  Item_133406_Name = {
    Text = "수밀인·충격"
  },
  Item_133406_StoryDesc = {
    Text = "제32기 학기 과제"
  },
  Item_133477_Desc = {
    Text = "아직 움직일 수 있는 오른손이 소녀의 부서진 몸을 끌며, 천천히 칠흑의 진흙을 향해 기어갔다.\n쇠사슬이 엇갈리며 내는 소리가 텅 빈 감옥에 울려 퍼졌다. 아무도 노예 하나의 생사 따위 신경 쓰지 않았고, 이 모든 것을 지켜본 건 벽 구석에 쌓인 백골뿐이었다.\n자신이 저 백골 중 하나가 될지는 알 수 없었다. 다만 그녀가 아는 것은, 사람들이 그것의 힘을 그토록 두려워한다는 사실타래뿐이었다.\n\n「적어도…… 지금보다 더 나빠지진 않겠지……」\n\n진흙이 소녀의 가느다란 검지를 따라 거슬러 올라오더니, 순식간에 소녀의 온몸을 뒤덮었다.\n진흙은 요동치기 시작했고, 끓어오르기 시작했다. 마치 마침내 운명의 주인을 찾은 듯 광희에 빠진 것 같았다.\n한참이 지나 감옥 안에 다시 고요가 찾아왔고, 뒤틀린 두 손이 고치 모양의 진흙을 뚫고 나와, 그녀와 세상을 가로막던 마지막 장벽을 찢어발겼다.\n소녀는 이미 검은 농액으로 변이한 사지를 고요히 바라보았다. 사지와 목에 감긴 쇠사슬은 새로운 힘 앞에서 너무나 허약했고, 그녀는 태어나 처음으로 이토록 가벼움을 느꼈다.\n그녀는 감옥 안의 공기를 욕심스럽게 들이마셨다. 비록 지금 주위에는 생물의 시체와 배설물의 악취가 가득했지만, 그녀는 전혀 개의치 않았다.\n왜냐하면 그녀는 마침내 맛보았기 때문이다. 태어난 이래로 꿈에 그리던 것을—자유의 맛을.\n감옥은 부서졌고, 복수의 여신은 날카로운 발톱을 휘두르며 모든 노예주에게 복수를 시작했다.\n……………………\n사람들이 울부짖었다.\n「살, 살려줘! 이 노예가 미쳤어! 위병! 위병은 어디 있어?!」\n사람들이 애원했다.\n「죽이지 마! 제발 살려줘…… 나, 내 돈을 전부 줄게!」\n사람들이 도망쳤다.\n「왕이 죽었다! 도망쳐, 어서 도망쳐! 저건 사람이 아니야…… 사람이 아니라고!」\n사람들이 침묵했다.\n「…으…………윽………」\n……………………\n소녀는 학살을 멈추고, 일그러진 얼굴의 머리를 아무렇게나 내던졌다. 이물질이 기도를 막아 질식사한 모습이었다.\n분노를 쏟아낸 뒤, 소녀는 생각하기 시작했다. 자신이 대체 무엇을 해야 하는지를.\n바람이 진흙과 핏물을 휘감아, 시체가 즐비한 도시국가를 제멋대로 물들였다.\n마침내, 소녀는 발걸음을 내디뎠다.\n그녀는 전사로서, 결코 멈추지 않는 전사로서, 자유의 씨앗을 심으러 갈 것이다.\n그녀는 북으로, 북으로, 극지의 끝까지 나아갈 것이다."
  },
  Item_133477_Name = {
    Text = "속박을 깨는 순간"
  },
  Item_133478_Desc = {
    Text = "환의 「속박 해방의 순간」 획득 후 해금됩니다.\n「나는 이미 속박을 벗어났다.」"
  },
  Item_133478_Name = {
    Text = "시로·속박 해방의 순간"
  },
  Item_133705_Desc = {
    Text = "환의 「나선 잔향」 획득 후 해금됩니다.\n「전에 당신을 본 적이 있나요?……있었겠죠?」"
  },
  Item_133705_Name = {
    Text = "노디라·나선 잔향"
  },
  Item_133706_Desc = {
    Text = "「아주 오래, 아주아주 오래전, 인류가 아직 태어나지 않았을 때부터 앵무조개는 존재했단다.」\n「그 껍데기는 해류의 방향, 바닷물의 온도, 육지와 바다의 변천을 기억했어.」\n「모든 소리도 기억했지. 들어봐.」\n어린 노디라는 호기심에 소라를 귀에 갖다 대었다. 눈앞에서는 파도가 암초에 부딪치고, 소라 속에서 들려오는 파도 소리가 노디라의 귓가에 부딪쳤다.\n그녀는 놀라 눈을 크게 떴다.\n「엄마, 내가 이 소라에게 말을 하면, 다음에 다시 만났을 때 나를 기억해줄까?」\n그 다정한 대답은 나중에 해변의 바람과 함께 흩어져 버렸고, 답은 아무도 알지 못했다. 작은 노디라는 소라에게 한참 동안 중얼중얼 이야기를 했지만, 이 작은 껍데기에 너무 많은 것을 담을 수 없을까 봐 걱정이 되어, 생각하고 또 생각한 끝에 가장 중요한 한마디만 남기기로 했다.\n「안녕, 소라야. 나는 위대한 모험가가 되어서 다시 너를 찾으러 갈 거야. 다시 만나면 내가 꼭 너를 기억할 수 있을 테니까, 약속이야, 너도 나를 기억해줘야 해!」\n그 후, 그 후……\n그 후에 무슨 일이 있었을까, 그건 이미 아주 오래전 일이었다.\n노디라는 자신이 무언가 중요한 것을 잊어버린 것 같았지만, 소라가 앵무조개를 대신해 기억해주듯, 노디라는 자신의 친구를 구했다. 그렇게 해야 할 것 같았다. 누군가가 예전에 자신을 위해 그렇게 해준 것 같았으니까.\n그래서 그녀의 위대한 모험은 갑작스레 멈추었다. 모든 모험가에게 느닷없는 결말이 찾아오듯, 그녀는 깊은 바다 속으로 가라앉아 갔다.\n용식장에 삼켜지려는 앵무조개를 보았을 때, 노디라는 무언가 떠오른 것 같았다.\n이것은 아주 오래전 어느 오후에, 자신이 바다에 놓아준 소라인 것 같았다.\n「다음에 다시 만났을 때, 나를 기억해줄까?」\n고통스러운 질식이 찾아오기 전에, 마지막 한 모금의 공기가 수압에 의해 폐에서 밀려나기 전에, 노디라는 온 힘을 다해 손을 뻗어 소라를 귀에 갖다 대었다.\n소라는 부드러운 복족을 내밀었다.\n노디라는 아무것도 들을 수 없었다."
  },
  Item_133706_Name = {
    Text = "나선의 메아리"
  },
  Item_133766_Desc = {
    Text = "영혼의 공명과 함께하는 것, 이제는 윤곽의 조각만이 남아 있다. 각지에 흩어진 희망의 집합이 현실타래을 꿰뚫는 증폭을 가져오길 바란다.\n「제련실타래」에서 「영혼 회귀의 핵」를 합성할 수 있다."
  },
  Item_133766_Name = {
    Text = "영혼 회귀 파편"
  },
  Item_133767_Desc = {
    Text = "운명의 파편을 엿볼 수 있는 나선형 창, 이제는 윤곽의 잔편만이 남아 있다. 각지에 흩어진 희망의 집합이 현실타래을 꿰뚫는 증폭을 가져오길 바란다.\n「제련실타래」에서 「운명 회귀의 핵」을 합성할 수 있다."
  },
  Item_133767_Name = {
    Text = "운명 회귀 파편"
  },
  Item_134300_Name = {
