  Item_140209_Desc = {
    Text = "「ㅠㅠㅠ 장난치면 안 됐던 건데(사실타래 다음에 또 할 거지롱).」"
  },
  Item_140209_EmojiName = {
    Text = "거짓된 눈물"
  },
  Item_140209_Name = {
    Text = "사야·거짓된 눈물"
  },
  Item_140212_Desc = {
    Text = "「좋아!」"
  },
  Item_140212_EmojiName = {Text = "기대"},
  Item_140212_Name = {
    Text = "사야·기대"
  },
  Item_140213_Desc = {
    Text = "「미사그의 냉장고엔 뭐가 있으려나~?」"
  },
  Item_140213_EmojiName = {
