  },
  Item_140213_Name = {
    Text = "사야·몰래 냠냠"
  },
  Item_140405_Desc = {
    Text = "미사그에서 정기적으로 실타래시하는 블랙풀 심층장 스캔으로, 블랙풀 내부 심층 구조의 안정도와 활성성을 탐사하기 위해 사용된다."
  },
  Item_140405_Name = {
    Text = "심층장 스캔"
  },
  Item_140406_Desc = {
    Text = "미사그에서 정기적으로 실타래시하는 에너지 붕괴 검측으로, 깨어남체 정신 링크의 자연 퇴화를 예방하기 위해 사용된다."
  },
  Item_140406_Name = {
    Text = "붕괴 검출"
  },
  Item_140407_Desc = {
    Text = "미사그에서 정기적으로 실타래시하는 공명 주파수 교정으로, 은심 신호의 동기화 안정성을 유지하기 위해 사용된다."
  },
  Item_140407_Name = {
    Text = "공진 교정"
  },
  Item_140415_Desc = {
    Text = "장미가 활활 타오르듯 만개한다. 묘수에 의해 영성을 부여받은 시편도 불바다 속으로 몸을 던져, 그녀의 투명한 그림자와 하나가 된다."
  },
  Item_140415_Name = {
    Text = "불타버린 꽃의 송가"
  },
  Item_140416_Desc = {
    Text = "「영혼을 악기 삼아, 우주의 공명을 연주한다.\n이 혼돈스럽고, 무질서하며, 광란에 찬 음악은 세계의 진상을 밝히기 위해 울려 퍼진다.」"
  },
  Item_140416_Name = {
    Text = "불협화음 합주"
  },
  Item_140416_StoryDesc = {
    Text = "V2.5.1 아바타 선물 패키지"
  },
  Item_140417_Desc = {
    Text = "제1악장, 시작. 높이 치켜든 그의 두 손이 정적에 내려앉기 전, 온 우주가 종말의 소나타로 울려 퍼진다."
  },
  Item_140417_Name = {
    Text = "환천상의 공명"
  },
  Item_140418_Desc = {
    Text = "「장미가 선혈을 떨어뜨리며, 불꽃 속에서 마지막 시편으로 화한다. 우아함, 낭만, 그리고 소리 없이 흐르는 눈물.」"
  },
  Item_140418_Name = {
    Text = "장미의 시편"
  },
  Item_140418_StoryDesc = {
    Text = "V2.5.1 아바타 선물 패키지"
  },
  Item_140459_Desc = {
    Text = "지휘봉을 들어 올리기 전, 세상은 혐오스러운 소음으로 가득했다.\n아버지의 가혹한 손바닥이 수없이 건반 덮개를 내리쳤고, 궁정 복도의 모기 같은 자들이 수군거렸으며, 신문은 그에 관한 이야기를 쉴 새 없이 떠들어댔다.\n「조용히.」\n@3왕립 오페라 극장, @3년 봄.\n젊은 궁정 악사가 처음으로 수석 지휘자의 단상에 올랐다. 의심과 기대의 목소리가 팽팽히 맞섰다. 그는 너무나 젊고 과묵했으며, 눈부시게 타오르는 재능을 지닌 채, 마치 세상에 나오는 것이 허락되지 않았던 도자기 같았다. 이제 그 도자기가 처음으로 진홍빛 무대 위에서 지휘봉을 들어 올렸다.\n지휘봉이 올라가는 순간, 극장 전체의 공기가 보이지 않는 힘에 사로잡혔다. 그것은 중력이자 조류였으며, 음악의 우주에서 거스를 수 없는 공리였다.\n지휘봉이 내려오자 음표들이 고요의 장막을 찢었고, 수석 바이올리니스트의 활이 가볍게 떨렸다. 그는 이미 눈앞에 선 이가 자신보다 쉰 살이나 어린 아이라는 사실타래을 잊어버렸다. 지휘봉의 궤적이 그를 이끌었고, 그의 손가락은 더 이상 자신의 것이 아니었다.\n현악이 밀려들고, 금관이 화답하며, 팀파니가 정확한 지점에서 폭발했다. 모든 성부가 보이지 않는 실타래에 이끌려 지휘대 위의 우아한 궤적에 복종했다.\n하멜린의 입술이 냉담한 호선을 그렸고, 창백하고 젊은 얼굴은 정교하여 거의 비현실타래적으로 보였다. 지휘봉의 모든 움직임에는 의심할 여지 없는 명령이 담겨 있었다. 처음 지휘봉을 쥐었을 때부터 그는 분명히 알고 있었다. 음악이란 연주되는 것이 아니라 지배되는 것이라는 사실타래을.\n악장이 카덴차에 이르자, 하멜린은 꼭두각시 같은 연주자들을 바라보았다. 그의 눈에는 아무도 없었다. 음악의 무대 위에서 그는 유일한 독재자였다.\n종악장. 마지막 음표가 고요 속으로 사라지고, 긴 침묵 끝에 박수가 파도처럼 밀려왔다.\n오늘의 헤드라인은 하멜린의 것이었다. 젊은 천재는 누구도 얻지 못했던 명성과 찬사를 거머쥐었다. 생애 처음으로 수많은 이들의 열광적인 환호를 받으면서도, 젊은 지휘자의 얼굴에는 미소 한 점 없었다.\n그는 고개를 숙여 인사하고, 천천히 지휘봉을 내려놓은 뒤, 인생 처음으로 올랐던 무대를 떠났다. 궁정의 연회를 사양하고 자신의 연습실타래로 돌아갔다.\n평범한 연주자들, 충분히 정확하지 않은 트릴, 8분의 1박자만큼 어긋난 호흡——모든 결함은 음악에 대한 모독이었다. 만당의 갈채 속에서 그는 유일한 진실타래의 소리를 들었다. 머리 위 저 닿을 수 없는 궁륭 너머에서, 무언가가 그를 위해 울려 퍼지고 있었다. 그것은 그를 부르고, 꾸짖고, 기다렸다. 그들은 반드시 만날 것이었고, 그 만남의 순간에 그는 완벽해야만 했다.\n그날, 악마 악사의 서곡이 그의 첫 번째 무대를 정복했다.\n그리고 신에게로 향하는 그 길고 긴 악장은, 이제 막 울려 퍼지기 시작했다."
  },
  Item_140459_Name = {
    Text = "만뢰서곡"
  },
  Item_140460_Desc = {
    Text = "환의 「만뢰서곡」 획득 후 해금.\n「8분의 1박자 느렸다. 실타래패한 공연이다.」"
  },
  Item_140460_Name = {
    Text = "하멜린·만뢰서곡"
  },
  Item_140510_Name = {
    Text = "군성의 만개·보조형"
  },
  Item_140511_Name = {
    Text = "군성의 만개·방어형"
  },
  Item_140512_Name = {
    Text = "군성의 만개·공격형"
  },
  Item_140558_Desc = {
    Text = "「이것은 그녀가 기꺼이 바친 순결, 사랑, 그리고 충성이다.」"
  },
  Item_140558_Name = {
    Text = "소원 성취"
  },
  Item_140559_Desc = {
    Text = "「전설적인 조사원의 생존 비결: 그녀는 결코 준비 없이 싸우지 않는다.」"
  },
  Item_140559_Name = {
    Text = "살아있는 전설"
  },
  Item_140560_Desc = {
    Text = "「문자 메시지의 발신자 표시는 그것이 어느 휴대폰에서 발송되었는지만을 나타낼 뿐이다.」"
  },
  Item_140560_Name = {
    Text = "발신인 불명"
  },
  Item_140561_Desc = {
    Text = "「그는 평생 우물 바닥의 달빛을 그리워한 적이 없었다.」"
  },
  Item_140561_Name = {
    Text = "달빛이 참 아름답다"
  },
  Item_140562_Desc = {
    Text = "「꿈속에서 그녀의 목소리를 듣고, 그녀의 모습을 쫓으면서, 계속 기다린다.」"
  },
  Item_140562_Name = {
    Text = "순백의 세계"
  },
  Item_140563_Desc = {
    Text = "「네 눈에 비친 나는, 어느 쪽의 진실타래일까?」"
  },
  Item_140563_Name = {
    Text = "단면의 진리"
  },
  Item_140570_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있다.\n「리모리아 인도의 땅……이 빛줄기의 끝에 있다.」"
  },
  Item_140570_Name = {
    Text = "영원히 빛바래지 않는 어제: 팔로스"
  },
  Item_140570_StoryDesc = {
    Text = "제34기 학기 과제"
  },
  Item_141152_Desc = {
    Text = "누구나 알다시피, 심연의 물고기는 마구잡이로 자라나며, 지나치게 거대한 것도 정상이고, 인간과 닮은 것도……정상이다.\n\n최소 {s1}개 드롭"
  },
  Item_141152_Name = {
    Text = "거대한 「사냥감」"
  },
