  Item_141169_Desc = {
    Text = "이벤트 「영원한 에포얀스」에서 업적을 완료하여 획득.\n「자, 숙제는 악몽 감금들한테 맡기고, 내가 제일 좋아하는 꼬마야, 어디서 놀고 싶어?」"
