  Item_141173_Desc = {
    Text = "누구나 알다시피, 심연의 물고기는 마구잡이로 자라나며, 지나치게 거대한 것도 정상이고, 인간과 닮은 것도……정상이다.\n\n최소 {s1}개 드롭"
  },
  Item_141173_Name = {
    Text = "거대한 「사냥감」"
  },
  Item_141174_Desc = {
    Text = "이 키오더를 기록하면, 편성 시 은열쇠 능력:「공허인」을 선택할 수 있습니다.\n\n당신이 평생 경험한 이야기를 들려드리겠습니다, 그 이야기는 더 이상 메아리치지 않을 거예요.\n마치 바닷물이 심연으로 흘러들어, 영원히 그곳에 머무는 것처럼."
  },
  Item_141174_Name = {
    Text = "마음이 허한 사람"
  },
  Item_141174_StoryDesc = {
    Text = "당신이 평생 경험한 이야기를 들려드리겠습니다, 그 이야기는 더 이상 메아리치지 않을 거예요.\n마치 바닷물이 심연으로 흘러들어, 영원히 그곳에 머무는 것처럼."
  },
  Item_141175_Desc = {
    Text = "눈을 감고, 귀를 막고, 나와 함께 속으로 되뇌어라, 이것은 물고기, 이것은 물고기.\n맞다, 사냥터 안에 있는 것은 모두 물고기다.\n\n최소 {s1}개 드롭"
  },
  Item_141175_Name = {
