  Item_141204_Name = {
    Text = "거대한 「사냥감」"
  },
  Item_141205_Desc = {
    Text = "보유자가 가하는 힘 감소 효과를 증폭시키고, 특정 타이밍에 팀의 크리티컬 피해를 증폭시킬 수 있는 명륜. 처치 후 자신의 턴 종료 시 획득하는 광기도 증가시킬 수 있다."
  },
  Item_141205_Name = {
    Text = "살아있는 감옥"
  },
  Item_141205_StoryDesc = {
    Text = "만약 소원이 정말로 이루어질 수 있다면, 폰토스는 이별이 찾아오기 전에 인사라도 나눌 수 있기를 바랐다.\n그의 부모는 소리 없이 사라졌고, 어느 평온한 오후, 누나 레이사가 돈을 내어 인력거를 불렀다. 그리고 길고 긴, 그때는 아직 알지 못했던 철제 괴물이 경유 냄새와 굉음 속에 그를 그 해변 마을로 데려다주었다.\n부모의 행방에 대해 레이사는 한 마디도 하지 않았고, 격렬한 다툼 끝에 그는 짭조름한 냄새가 가득한 항구로 뛰쳐나갔다.\n눈 간격이 지나치게 넓은 해민들이 기묘한 형태의, 사람의 힘으로는 결코 닿을 수 없는 심연에서 온 물고기들을 팔고 있었다.\n\"여보세요, 좀 멀리 떨어지세요, 저 물고기들은 잡아온 것들과 마찬가지로 저주에 물들었을지도 몰라요.\"\n행인이 목소리를 낮췄다. 아무도 이 처음 온 잘생긴 청년이 혼탁한 물에 발을 담그는 것을 보고 싶지 않았다.\n그는 습관적으로 상대에게 미소를 지었지만, 시선은 자신도 모르게 그 어둡고 부패한 루어에 떨어졌다. 크게 벌린 입 안에는 날카로운 이빨이 가득했고, 추하고, 왜곡되고, 과시적이었으며, 어떤 망상 속의 목소리가 이 죽은 물체의 일생을 이야기했다.\n어둡고 빛 없는 해저에서 그것은 유혹하고, ndaltə하고, 수단과 방법을 가리지 않았다. 그것의 몸은 견고한 감옥이 되어 자식들, 연인들, 원수들, 그리고 먹잇감들을 가두었다.\n그것의 삶 속 아름다운 것들은 본래 순식간에 사라져야 했지만, 그것은 그들 모두를 붙잡아 두었다. 그들은 그것의 몸을 매개로 긴밀히 의지하며, 영원히 분리되지 않았다.\n폰토스는 갑자기 고개를 세차게 흔들며, 귀 옆에서 날카롭게 울리는 소음 속에서 공포에 질려 주위를 둘러보았다.\n소리는 파도처럼 사라졌고, 그는 모든 것을 한순간의 멍함으로 여기며 속으로 자신의 신경질적인 반응을 비웃었다.\n그리고 아무것도 눈치채지 못한 채 정해진 숙명 속으로 떨어져 갔다."
  },
  Item_141206_Desc = {
    Text = "물고기가 왜 육지에서 달리는지는 묻지 마라, 여기는 에포양스다.\n\n최소 {s1}개 드롭"
  },
  Item_141206_Name = {
    Text = "신선한 「사냥감」"
  },
  Item_141207_Desc = {
    Text = "누구나 알다시피, 심연의 물고기는 마구잡이로 자라나며, 지나치게 거대한 것도 정상이고, 인간과 닮은 것도……정상이다.\n\n최소 {s1}개 드롭"
  },
  Item_141207_Name = {
    Text = "거대한 「사냥감」"
  },
  Item_141208_Desc = {
