  Item_141228_Desc = {
    Text = "누구나 알다시피, 심연의 물고기는 마구잡이로 자라나며, 지나치게 거대한 것도 정상이고, 인간과 닮은 것도……정상이다.\n\n최소 {s1}개 드롭"
  },
  Item_141228_Name = {
    Text = "거대한 「사냥감」"
  },
  Item_141229_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식이다. 미사그는 신비로운 의식을 통해 깨어남체의 영식을 일깨우며, 일깨워진 깨어남체는 영구적으로 정신 능력이 강화된다.\n폰토스를 중복 획득 시 변환하여 획득하며, 폰토스의 기령을 활성화하는 데 사용된다."
  },
  Item_141229_Name = {
    Text = "파편 · 폰토스"
  },
