  Item_141233_Desc = {
    Text = "눈을 감고, 귀를 막고, 나와 함께 속으로 되뇌어라, 이것은 물고기, 이것은 물고기.\n맞다, 사냥터 안에 있는 것은 모두 물고기다.\n\n최소 {s1}개 드롭"
  },
  Item_141233_Name = {
    Text = "오래된 「사냥감」"
  },
  Item_141508_Desc = {
    Text = "장착자를 깊은 잠에 빠져들게 하고, 깨어난 후 광기 폭발을 강화시키는 전술형 명륜."
  },
  Item_141508_Name = {
    Text = "이상한 나라의 릴리"
  },
  Item_141508_StoryDesc = {
    Text = "전설에 따르면 아이가 숲속에서 야생 토끼를 쫓아 달리기만 하면 이세계로 통하는 나무 구멍에 빠질 확률이 있다고 한다.\n릴리의 매끄러운 작은 발이 조약돌 오솔길을 밟았다.\n「릴리는 이곳이 좋아……바닥에 유리 조각도 없고, 공기 중에 소독약 냄새도 없어.」\n릴리는 신선한 공기를 깊이 들이마셨고, 숲 사이를 스치는 바람이 기묘한 꽃향기를 실타래어 왔다.\n머리 위의 나뭇잎 지붕은 스테인드글라스 같은 천장을 이루었고, 부서진 햇살은 마치 온 바닥에서 뛰노는 보석 같아, 화려하고 몽환적인 풍경에 릴리는 어느 방향을 봐야 할지 거의 알 수 없었다.\n「아, 아까 그 토끼 씨!」\n풀숲에서 익숙한 회색 긴 귀가 불쑥 나타났고, 릴리는 급히 뒤를 쫓았다.\n발아래 이끼는 한 걸음 밟을 때마다 작은 은빛 꽃을 피웠지만, 릴리는 신경 쓸 겨를이 없었다. 그녀에게는 토끼 씨에게 꼭 해야 할 더 중요한 말이 있었다.\n꿀빛 광채가 흐르는 시냇물을 건너고, 노래하는 갈대밭을 지나.\n숨을 헐떡이던 릴리는 마침내 토끼 씨의 솜뭉치 같은 꼬리를 붙잡았다.\n「토끼 씨, 리사와 친구가 되어 줄 수 있어?」\n「리사는 내 친구인데, 다른 사람들은 지금 모두 그녀를 무서워해……토끼 씨라면 분명 그녀와 친구가 될 수 있을 거야!」\n토끼 씨가 고개를 돌리는 순간, 하늘 가득 반딧불이 피어올랐다.\n「물론이지, @2은 모든 사람의 친구야. 그런데, 지금은 네가 휴식을 취해야 할 시간이야.」\n그리하여 릴리는 이미 친구가 된 토끼 씨를 안고, 숲 깊은 곳의 크고 높은 거목 아래로 기어갔다.\n흩날리는 반딧불이의 따뜻한 품 속에서, 릴리는 거목의 뿌리에 기대어 조용히 잠들었다.\n「피험자: 릴리. 임상 소견: 호흡 안정, 안구 회전 속도 정상. 제359차 의식 간섭 실타래험, 성공.」\n그것은 꿈처럼 아름다운 환상의 세계였다."
  },
  Item_141529_Desc = {
    Text = "해금 후, 「이상한 나라 여행기」 모든 임무를 완료하면 추가로 다음 보상을 획득할 수 있음"
  },
  Item_141529_Name = {
    Text = "이상한 나라 여행기"
  },
  Item_141666_Desc = {
    Text = "도금된 사과일까, 아니면 진짜 황금 사과일까……? 그 답은 요정만이 안다. 요정님께 바치면 약간의 보상을 얻을 수 있다.\n\n적어도 {s1}개 드롭"
  },
  Item_141666_Name = {
    Text = "황금 사과"
  },
  Item_141667_Desc = {
    Text = "어째서 사과 사탕이 황금 사과보다 귀할까? 거짓말 아래에도 진심이 조금은 묻혀 있는 것은 아닐까? 이 질문을 떠올리는 순간, 너는 이미 진짜 거짓말의 덫에 걸려든 것이다. 얼른 요정님께 가져가 실타래속 있는 보상으로 바꾸는 게 좋을 것같다!\n\n적어도 {s1}개 드롭"
  },
  Item_141667_Name = {
    Text = "사과 사탕"
