  Item_141896_Desc = {
    Text = "「통신 연동」 이벤트에서 지정 임무를 완료하여 획득.\n「미사그 내부 발행 한정 우표로, 위에 인쇄된 사람은 이름이 많습니다. 하지만 여기에는 그 많은 사람을 담을 수 없어서, 우표 면에는 당신 자신만 인쇄되어 있습니다.」"
