  Item_144286_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식이다. 미사그는 신비로운 의식을 통해 깨어남체의 영식을 계령하며, 계령을 받은 깨어남체는 영구적으로 정신 능력이 강화된다.\n태세를 중복 획득 시 전환하여 획득하며, 태세의 계령을 활성화하는 데 사용된다."
  },
