  Item_144521_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「미사그 내부에서 발행된 한정 우표입니다. 양도 금지, 분실타래 금지. 이는 당신의 신변의 안전을 위한 조치이니까요.」"
  },
