  Item_145277_Desc = {
    Text = "검은 인장 드롭율 속성의 명륜입니다."
  },
  Item_145277_Name = {
    Text = "불멸의 곯은 뼈"
  },
  Item_145277_StoryDesc = {
    Text = "로탄의 생애에서 가장 고통스럽고도 충만했던 그날, 그녀의 손에 쥔 칼날은 폭풍처럼 눈앞의 신명을 향해 내리쳤다. 거대한 검과 리바이어던의 행성처럼 웅장한 몸체가 함께, 이 폭풍 속에서 산산이 부서졌다.\n선혈의 왕관을 그분 기사단의 노예에게 건넨 후, 그 대가로 로탄은 단 하나의 요구만을 했다: 새로운 무기가 필요하다고.\n로탄에 대한 두려움과 경외심을 품은 새 국왕은 사람을 시켜 리바이어던의 뼈를 가져오게 하여, 그녀를 위해 비할 데 없는 한 쌍의 거대한 검을 주조하게 했다. 여섯 나라 최고의 대장장이들이 밤낮없이 주조하고 담금질하는 가운데, 죽은 신명의 유골은 신을 죽인 자의 손 안에서 신생을 얻었다.\n기억될 만한 가치가 있는 상대방 한 명이 일찍이 이 불멸의 검날을 증언한 적이 있었다. 그의 거대한 망치는 로탄의 갑옷과 거대한 검을 산산조각 냈고, 균열은 거미줄처럼 검신을 따라 확산되었으며, 유백색의 파편이 핏빛 공기 속에 튀어 올랐다, 마치 그녀가 리바이어던을 찌르던 그날처럼. 그는 자신이 약점을 찾았다고 생각했다. 그러나, 그는 로탄이 자신의 앞에 다시 일어서는 것을 보았고, 부서졌어야 할 그 거대한 검이 그의 가슴을 꿰뚫으며 그의 혈육을 흡입했다. 새로운 뼈가 부서진 곳에서 솟아올라, 이전보다 더욱 날카롭고 더욱 치밀해졌다. 단면은 마디마디 자라나, 마치 황야에서 미친 듯이 자라는 첨예한 가시덤불처럼. 그는 선명하게 느꼈다, 자신의 HP가 저 백골로 주조된 칼날에 씹히고 삼켜지고 있음을.\n알고 보니, 일찍이 별과 하늘을 포식했던 그 거대한 짐승은 결코 죽지 않았던 것이다. 계약이 맺어진 그 순간부터, 그것은 그녀와 하나로 합쳐졌다. 로탄이 거대한 검을 들어 올릴 때마다, 검신의 뼈 첨예한 가시가 피어나기 시작하여, 날카로운 첨예한 가시로 상대방을 향해 잔인한 환호를 보냈다.\n그것은 그녀의 무기였다. 그녀는 그것의 두 발이었다. 그녀와 그것은, 처음부터 끝까지 같은 갈망에 빠져 있었다. 그녀들은 죽지도 않고 멸하지도 않으며, 영원히 만족을 모른다.\n멈추지 않는 전장, 그것이 그녀들의 유일한 귀착지였다."
  },
