  },
  Item_145300_StoryDesc = {
    Text = "태어난 그 순간부터, 그 존재는 영원한 허기에 빠져 있었다.\n\n항성의 시체가 그 이빨 사이에서 부서져 내리고, 문명의 잔해가 그 배 속에서 썩어갔다. 그 존재의 허기은 시간보다 더 오래된 저주였다. 그 존재는 거듭해서 힘을 삼키고, 부하들을 부추겨 권력의 유희를 벌이게 했지만, 자신의 의미가 대체 무엇인지는 결코 알지 못했다.\n\n어느 날, 로탄이라는 전사가 그 존재 앞에 다가설 때까지는.\n\n「레비아탄.」\n\n자신의 이름을 마지막으로 들은 것이 언제였는지 기억나지 않았다. 엎드려 절한 왕들은 감히 그 이름을 입에 올리지 못했고, 미친 제사장들은 찬송가로만 그 이름을 대신했으니까.\n\n그런데 그녀는 쉽게 그 존재를 불렀다. 마치 오랜 숙적을 부르듯이.\n\n「네가 나설 차례다!」\n\n그 존재는 만 이천 년을 살아왔다. 이 기나긴 영원 속에서, 행성은 식량이었고, 생명체는 개미와 같았으며, 수많은 강자들은 그저 잠깐의 오락거리에 불과했다. 그 어떤 것도 그 존재를 배부르게 할 수 없었고, 그 어떤 것도 그 존재를 두렵게 할 수 없었다. 오늘까지는.\n\n이 필멸의 인간, 이 전사가 거대한 검을 들어 올려, 폭풍처럼 그 존재에게 덤벼들었다.\n\n거대한 검이 비늘 갑옷을 찢었다. 그 존재의 귀에, 자신이 혼돈 속에서 태어날 적의 포효가 울려 퍼졌다. 그 존재의 분노는 천체를 무너뜨렸고, 그 존재의 허기은 성운을 삼켰다.\n\n거대한 검이 발톱을 잘라냈다. 그 존재는, 흰 베일을 두른 「신」이 자신 앞에 나타나, 자신의 힘과 의지를 분리해 갔던 순간을 떠올렸다.\n\n거대한 검이 심장을 꿰뚫는 그 순간, 레비아탄은 웃음을 터뜨렸다.\n\n만 이천 년. 잃어버렸던 의지가, 마침내 다시 자신 앞에 도래하여, 자신을 베고, 자신을 정복하고, 자신을 삼켰다. 그녀는 자신을 이끌어, 모든 영역을 밟고 지나가며, 더 먼 별의 바다로 나아가, 모든 강력한 존재들을 정복할 것이다.\n\n그날, 태고의 혼돈의 짐승이 다시 태어났다. 그녀에게로 귀환한 그 순간, 그 존재는 완전히 깨달았다. 그와 그녀는, 순수하고 철저한 힘을 위해 태어났다는 것을.\n\n힘 그 자체가, 곧 모든 의미였다."
  },
  Item_145301_Desc = {
    Text = "활동 「레비아탄의 놀음」에서 업적을 완료하여 획득.\n「또 누가 있어!!」"
  },
  Item_145301_Name = {
    Text = "은열쇠의 이름으로: 침식·로탄"
  },
  Item_145301_StoryDesc = {
