  Item_145606_Desc = {
    Text = "「돌진! 돌진!」"
  },
  Item_145606_EmojiName = {
    Text = "오토바이 운전"
  },
  Item_145606_Name = {
    Text = "노틸라·오토바이 운전"
  },
  Item_145606_StoryDesc = {
    Text = "제36기 학기 과제"
  },
  Item_145970_Desc = {
    Text = "이 열쇠 지령을 기록한 후, 편성 시 열쇠 지령 스킬 「거짓이 아닌 것」을 선택할 수 있습니다.\n\n악명 높은 뱀이 에덴동산의 순수하고 무지한 인간을 유혹하는 데 썼고, 질투에 가득 찬 왕후가 새하얀 무고한 공주를 속이는 데 썼으며, 지혜만 지닌 평범한 사람도 그것으로 야생의 사냥꾼과의 달리기 시합에서 이겼다.\n그러나 이 물건은 거짓이 아니다.\n그것은 단지 모든 인간의 마음 밑바닥에 자리한, 입 밖에 낼 수 없는 한 점의 욕망일 뿐이다."
  },
  Item_145970_Name = {
    Text = "거짓이 아닌 것"
  },
  Item_145970_StoryDesc = {
    Text = "악명 높은 뱀이 에덴동산의 순수하고 무지한 인간을 유혹하는 데 썼고, 질투에 가득 찬 왕후가 새하얀 무고한 공주를 속이는 데 썼으며, 지혜만 지닌 평범한 사람도 그것으로 야생의 사냥꾼과의 달리기 시합에서 이겼다.\n그러나 이 물건은 거짓이 아니다.\n그것은 단지 모든 인간의 마음 밑바닥에 자리한, 입 밖에 낼 수 없는 한 점의 욕망일 뿐이다."
  },
  Item_146353_Desc = {
    Text = "초승달 설산에 흩어진 감정 입자, 닿으면 계락에 성공한 듯한 웃음소리가 귀에 들어오는 것 같다."
  },
  Item_146353_Name = {
    Text = "축복의 심장"
  },
  Item_146538_Desc = {
    Text = "해금 후, 「북쪽 끝 여행기」의 모든 임무를 완료하면 다음 보상을 추가로 획득할 수 있습니다"
  },
  Item_146538_Name = {
    Text = "최북단 기행"
  },
  Item_146539_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
  },
  Item_146539_Name = {
    Text = "조사 과정 특전·성신편 Ⅵ"
  },
