  Item_146947_Desc = {
    Text = "이 은열쇠를 기록하면, 편성 시 은열쇠 스킬:「영속 새 장」을 선택할 수 있습니다.\n\n어제가 어떠했든, 태양이 다시 떠오르면 이야기를 다음 페이지로 넘기세요, 그것은 또 다른 새로운 장이 될 것입니다."
  },
  Item_146947_Name = {
    Text = "영속 새 챕터"
  },
  Item_146947_StoryDesc = {
    Text = "어제가 어떠했든, 태양이 다시 떠오르면 이야기를 다음 페이지로 넘겨요, 그것은 또 새로운 한 편이 될 테니까요."
  },
