  },
  Item_147229_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비로운 의식을 통해 각성체의 영식을 일깨우며, 일깨워진 각성체는 영구적으로 정신 능력이 강화됩니다.\n저무는 별·틴커트를 중복 획득 시 전환하여 얻으며, 저무는 별·틴커트의 계령을 활성화하는 데 사용됩니다."
  },
