  Item_147300_Name = {
    Text = "저무는 별·틴커트"
  },
  Item_147549_Desc = {
    Text = "이 은열쇠를 기록하면, 편성 시 은열쇠 스킬:「임시 텍스트」를 선택할 수 있습니다.\n\n(은열쇠 플레이버 텍스트 추가 예정.)"
  },
  Item_147549_Name = {
    Text = "임시 텍스트"
  },
  Item_147549_StoryDesc = {
