  Item_147598_Name = {
    Text = "툴루 왕관"
  },
  Item_148117_Desc = {
    Text = "사용 시 행동력을 획득하고, 손에 남겨두면 HP 회복과 광기 자원을 축적하며, 소생 기회를 한 번 제공하는 종합형 명륜입니다."
  },
  Item_148117_Name = {
    Text = "영혼의 동조"
  },
  Item_148117_StoryDesc = {
    Text = "텅 빈 실험실 안에서, 각종 정밀 기기들이 가지런히 놓여 있었고, 오직 수많은 관선(管線)만이 뒤엉켜 마치 구불구불 감긴 뱀처럼 바닥에 엎드리고 공중에 매달려 있었다.\n사유의 신호는 마치 아무도 볼 수 없는 강물과 같았지만, 천재는 이미 그것을 다루는 데 익숙해져 있었다. 뇌가 그것들의 발원지이고, 기계적인 관선을 따라 흘러, 마침내 이 새로 만들어진 육체 속에 모여들었다.\n의식이 전달되는 동시에, 오랫동안 봉인되어 있던 많은 기억들도 오랜만에 꺼내졌다. 가족, 미사그, 미완성의 실험……어렴풋한 가운데, 천재는 수년 전, 아직 최초의 육신이라는 굴레를 벗어나지 못했을 때, 한 따분한 학생이 흥미롭다는 듯 그녀 주위를 맴돌며 호기심이라는 이름의 빛을 눈 속에 반짝이던 것을 떠올렸다.\n「선생님은, 인공적인 육체가 진정한 영혼을 담을 수 있다고 생각하십니까?」\n범인(凡人)들은 언제나 자신들의 시야를 훨씬 뛰어넘는 것들을 상상하기 좋아한다. 진부한 질문이었다. 하지만 교사로서, 그녀는 눈 하나 깜짝하지 않으면서도 몇 마디 대답을 내놓았다.\n「네 몸도 인공적인 것이 아니라고 할 수 없어. 심장, 사지, 오감 같은 기관들의 작동이 기계와 무슨 차이가 있지?」\n「됐어, 그런 쓸데없는 생각을 하느니, 차라리 시간을 내서 녹슨 네 뇌를 제대로 단련시키는 게 낫겠어. 그렇지 않으면, 피가 흐르는 그 육체는 더욱 쓸모없어질 뿐이야.」\n이제, 질문을 던졌던 그 사람은 이미 시간의 모래에 묻혀 더 이상 존재하지 않는다. 오직 지혜를 담은 뇌 탱크만이 여전히 사유하고, 영원히 사유한다.\n세상 사람들이 말하는 이른바 영혼이란 860억 개의 뉴런이 교차하여 이루어진 전기화학적 활동에 불과하다. 혈육이든, 기계든, 원재료의 차이는 그것들이 단지 담체(擔體)에 불과하다는 본질을 바꾸지 못한다.\n그렇다, 범인은 어쩔 수 없지만, 천재인 그녀는 할 수 있었고, 이미 해냈다 — 오직 그래야만, 세계의 진리를 해명하고 지식의 정점에 도달할 수 있다.\n시각이란, 빛이 안구를 통과하여 최종적으로 망막 위에 초점을 맺는 것에 불과하다.\n후각이란, 냄새 분자가 수용체와 결합하여 신경을 스치는 화학적 감지 경로에 불과하다.\n청각이란, 음파가 달팽이관에서 변환되어 피질로 전달되는 전기 신호로 바뀌는 것에 불과하다.\n인형이 있는 곳은 너무나 어두웠고, 희미한 불빛이 흔들려 그림자조차 비추지 못했다. 그녀는 두 눈을 살며시 감았다. 설령 눈을 떠도 눈에 들어오는 것은 변함없는 풍경뿐임을 알고 있었기 때문이다.\n방은 티끌 하나 없이 청소되어 있었고, 병과 단지 속의 약액도 단단히 봉인되어 있었다. 기체(機體)는 호흡이 필요 없고, 감각을 시험하기 위해 이 무미건조한 공기를 흡입할 필요도 없었다.\n오직 차가운 기계음 하나만이, 텅 빈 실험실 안에 울려 퍼졌다.\n「의식 동조 완료, 기체 가동 확인.」\n충분하다.\n무기질적인 소리이지만, 듣기에는 오히려 친근하게 느껴졌다. 마치 물질 세계의 실재를 닻처럼 고정시켜 주는 것 같기도 하고, 그저 짧은 휴식이 끝났으니 새로운 연구에 몸을 던질 시간이 되었다고 단순히 상기시켜 주는 것 같기도 했다."
  },
  Item_148118_Desc = {
    Text = "해금 후, 「방과 후 시간」의 모든 임무를 완료하면 다음 보상을 추가로 획득할 수 있습니다"
  },
  Item_148118_Name = {
    Text = "강의 외의 시간"
  },
  Item_148403_Desc = {
    Text = "이것은 당신과 각성체 「피차위아」의 증명입니다.\n각성체 동조율이 Lv20에 도달했을 때 획득하며, 해당 각성체 카드 면에 자동으로 장착되어 표시됩니다."
  },
  Item_148403_Name = {Text = "광채"},
  Item_148404_Desc = {
    Text = "같은 마음이라는 것을 보여주는 최종적인 증표. 서로를 바라보는 눈빛 속 더 이상 「타인」이라는 건 없다. 오직 두 개의 형체와, 하나의 영혼만이 남아 있을 뿐이다."
  },
  Item_148404_Name = {
    Text = "동심의 증표"
  },
  Item_148479_Name = {
    Text = "아라크네의 실"
  },
  Item_148480_Name = {
    Text = "황금 사과"
  },
  Item_148481_Name = {
    Text = "낡은 은열쇠"
  },
  Item_148482_Name = {
    Text = "히로의 눈알"
  },
  Item_148483_Name = {
    Text = "금화 주머니"
  },
  Item_148484_Name = {
    Text = "검은 깃털"
  },
  Item_20124_Name = {
    Text = "평범한 사진"
  },
  Item_20468_Name = {
    Text = "질병 기록"
  },
  Item_20469_Name = {
    Text = "멤피스 의식 거울"
  },
  Item_20470_Name = {
    Text = "해와 달의 암호"
  },
  Item_20481_Desc = {
    Text = "쿵, 쿵. \n무광의 경계 곳곳에 흩어진 작은 심장들은 “그분들”이 가장 좋아하는 음식이다. \n명륜과 무구의 은핵 등의 상품을 교환할 때 사용된다."
  },
  Item_20481_Name = {
    Text = "검은 공물"
  },
  Item_20482_Desc = {
    Text = "레오 왕국의 장미 상징이 새겨진 금빛 배지. 암시장에서 좋은 가격에 팔 수 있다.\n조사 작전에서 우수한 성적을 거둔 수호자들에게 수여되며, 교환 상점에서 다양한 상품으로 교환할 수 있다."
  },
  Item_20482_Name = {
    Text = "조사 배지"
  },
  Item_21764_Name = {
    Text = "조각 연습작"
  },
  Item_21775_Desc = {
    Text = "그들의 육체, 영식, 그리고 기억은 모두 이곳에 봉인되어 있으며, 깨어나는 순간을 기다리고 있다.\n아래의 「영역 연구」에서 깨어남체 1명을 선택하여 깨어남할 수 있습니다:\n노틸라, 님피아, 판디아, 엘바, 카렌, 골리아, 파로스, 카이커스, 산, 셀레스트, 히로, 아그리파, 우브하시, 레이아, 파인트, 리즈, 틴커트, 웬코르, 젠킨, 카시아."
  },
  Item_21775_Name = {
    Text = "원질의 낙원"
  },
  Item_21799_Desc = {
    Text = "거래 계정과 비밀번호를 제공해 주세요. \n왕국의 지하 시장에서 유통되는 거래 증명서로, 수호자는 이 증명서를 통해 희귀한 물품들을 구입할 수 있습니다."
  },
  Item_21799_Name = {
    Text = "밀은 거래 증명서"
  },
  Item_21898_Desc = {
    Text = "희귀한 명륜이 기록된 신비한 고서.\n다음 「윤전의 상」 중 SSR 명륜 1개를 선택하여 획득할 수 있습니다:\n\"기억의 나선\", \"부패의 선물\", \"떠도는 욕망\", \"견고한 의지\", \"소리 없는 잔치\", \"거인의 검\", \"폭우 속에서\", \"상처받은 지느러미\", \"산호 여인의 죽음\", \"인도하는 돛\", \"족쇄를 벗어던진 날\", \"창백한 후예\", \"혈육의 광연\", \"탐식의 이야기\", \"삼켜진 자장가\", \"돌고 도는 춤사위\", \"속박된 노래\", \"끝나지 않는 계산\", \"길 없는 길\", \"환희의 마법 공연\"."
  },
  Item_21898_Name = {
    Text = "회전의 책"
  },
  Item_22164_Desc = {
    Text = "사용 시 설명서를 준수하시고, 과다 복용을 피하세요. \n영지 제제 보급함은 임무를 수행하는 수호자에게 지원을 제공합니다."
  },
  Item_22164_Name = {
    Text = "조사 보급"
  },
  Item_22165_Desc = {
    Text = "영지 제제 하나면 해결되지 않는 것이 없다. 만약 그렇다면, 몇 개 더 사용하면 된다. \n영지 제제를 보관하는 보급 상자는 임무를 수행하는 수호자에게 지원을 제공합니다."
  },
  Item_22165_Name = {
    Text = "주간 비약 선물 상자"
  },
  Item_22166_Desc = {
    Text = "매주 얻을 수 있는 작은 도움입니다. \n특수허가약제를 보관한 보급상자로, 태스크를 수행하는 수호자에게 지원을 제공합니다."
  },
  Item_22166_Name = {
    Text = "주간 특별 선물 상자"
  },
  Item_22167_Desc = {
    Text = "충분한 후방 지원은 성공의 절반입니다. \n귀중한 보급품을 보관하는 보급 상자는 임무를 수행하는 수호자에게 도움을 제공합니다."
  },
  Item_22167_Name = {
    Text = "기간 한정 전역 보급"
  },
  Item_22168_Desc = {
    Text = "매달 얻을 수 있는 작은 행복.\n충분한 양의 영지 제제가 들어있는 보급 패키지로, 태스크를 수행하는 수호자에게 지원을 제공합니다."
  },
  Item_22168_Name = {
    Text = "월간 비약 선물 상자"
  },
  Item_22244_Desc = {
    Text = "번식하라, 번식하라. 모나무의 피를 흘리는 영혼들이 세상에 가득 차게 하라. \n랜덤 드롭 다시 진화하는 미스터리 세트 부품."
  },
  Item_22244_Name = {Text = "재진화"},
  Item_22717_Desc = {
    Text = "“환몽 심잠”과 “페이즈 체스”에서 획득한 수호자 경험치가 2배로 증가합니다! (일일 상한 240 유지)."
  },
  Item_22717_Name = {
    Text = "경험치 2배"
  },
  Item_23731_Desc = {
    Text = "“환몽 심잠”과 “페이즈 대결”을 통해 수호자 경험을 획득할 수 있으며, 매일 해당 경로를 통해 최대 {s1}점까지 획득할 수 있습니다. 오늘은 이미 {s2}점을 획득했습니다."
  },
  Item_23731_Name = {Text = "경험치"},
  Item_23899_Desc = {Text = "기본"},
  Item_23899_StoryDesc = {
    Text = "남성 기본 프로필"
  },
  Item_23900_Desc = {Text = "기본"},
  Item_23900_StoryDesc = {
    Text = "여성 기본 프로필"
  },
  Item_23904_Name = {
    Text = "여성의 초상화"
  },
  Item_23905_Name = {Text = "장미꽃"},
  Item_23906_Name = {Text = "샴페인"},
  Item_24056_Desc = {
    Text = "그 가치는 빛나는 외관에 걸맞습니다. \n광휘의 은핵을 보관하는 보급 상자로, 태스크를 수행하는 수호자에게 지원을 제공합니다."
  },
  Item_24056_Name = {
    Text = "광휘 깨어남 보급"
  },
  Item_24069_Desc = {
    Text = "충분한 후방 지원은 성공의 절반입니다. \n귀중한 보급품을 보관하는 보급 상자는 임무를 수행하는 수호자에게 도움을 제공합니다."
  },
  Item_24069_Name = {
    Text = "월간 보급"
  },
  Item_24072_Name = {Text = "찻잔"},
  Item_24073_Desc = {
    Text = "코르트 학장 대행 특별 승인의 풍부한 보급품입니다.\n귀중한 자재가 담긴 나무 상자로, 밀경과실타래의 일일 시험 훈련과 주간 훈련 임무를 수행하는 수호자에게 도움을 제공합니다.\n다음 소재 중 하나를 선택하세요:\n빛나는 결정 나비*9\n긴줄기 바다나리*9\n원생 번데기*9\n유성 파편*9"
  },
  Item_24073_Name = {
    Text = "Ⅰ급 보급"
  },
