  },
  Item_25124_Name = {Text = "리즈"},
  Item_25125_Desc = {
    Text = "깨어남체 「아그리파」 획득 후 해제"
  },
  Item_25125_Name = {
    Text = "아그리파"
  },
  Item_25126_Desc = {
    Text = "깨어남체 「레아」 획득 후 해제"
  },
  Item_25126_Name = {Text = "레아"},
  Item_25136_Desc = {
    Text = "귀중한 소재가 들어 있는 선물 주머니로, 밀경 과실타래의 일일 시련 및 주간 시련 임무를 수행하는 수호자에게 추가 지원을 제공합니다.\n과제 레벨이 50에 도달한 후, 매 레벨업 시 1개를 받을 수 있습니다.\n수령 시 다음 중 하나의 아이템을 무작위로 얻습니다:\n「특허약제」×1(20% 확률)\n「장미 금권」×5000(80% 확률)"
  },
  Item_25136_Name = {
    Text = "고급 과제 선물 백"
  },
  Item_25141_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「미사그 학생들 사이에서는 이런 말이 전해진다: 그가 있는 한, 그 누구도 다치지 않을 것이다.」"
  },
  Item_25141_Name = {
    Text = "은열쇠의 이름으로: 오지에"
  },
  Item_25141_StoryDesc = {
    Text = "제2기 과제 기록"
  },
  Item_25142_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「카다스 행성의 뒷면으로 향하든, 균열의 중심부로 깊숙이 들어가든, 그녀는 당신의 판단을 믿습니다.」"
  },
  Item_25142_Name = {
    Text = "은열쇠의 이름으로: 라모나"
  },
  Item_25142_StoryDesc = {
    Text = "제2기 과제 기록"
  },
  Item_25192_Name = {
    Text = "캠퍼스 고양이"
  },
  Item_25218_Desc = {
    Text = "그것은 세상의 규칙을 바꿀 것이다. 들여다보거나 만지지 말라. \n미사그 지하의 블랙풀에서 추출된 신비한 영핵으로, 상상할 수 없는 경지로 깨어남체를 끌어올릴 수 있다. 깨어남체가 60레벨에 도달했을 때 사용 가능합니다."
  },
  Item_25218_Name = {
    Text = "원초 영핵"
  },
  Item_25219_Desc = {
    Text = "그들은 블랙풀에 산재해 있으며, 신성한 완전함의 위대한 순간을 갈망하고 있습니다.\n미사그 지하에서 나온 신비한 파편으로, 원초 영핵을 합성할 수 있습니다."
  },
  Item_25219_Name = {
    Text = "영핵 파편"
  },
  Item_34698_Desc = {
    Text = "화려하게 장식된 나무 상자, 내부에는 초급 승격 재료가 들어 있습니다. \n후방 지원처에서 정성스럽게 준비하고 신경 써서 맞춘 세트로, 짧은 시간 내에 자원이 필요한 조사원과 수호자가 적합합니다."
  },
  Item_34698_Name = {
    Text = "초급 승격 상자"
  },
  Item_34699_Desc = {
    Text = "운명 조각을 엿볼 수 있는 나선형 창입니다. 명륜을 교환하는 데 사용됩니다.\n골드, 희토류, 은심……기대하는 운명에 비하면 아무리 비싼 재료라도 사소해집니다.\n사용 시 그중 하나의「회전의 상」, 과거 명륜 이벤트 깨어남 및 현재 명륜 이벤트 깨어남 중 SSR 명륜을 선택할 수 있습니다."
  },
  Item_34699_Name = {
    Text = "운명 회귀의 핵"
  },
  Item_34700_Desc = {
    Text = "화려하게 장식된 나무 상자, 내부에 중급 승격 재료가 포함되어 있다.\n물자 지원처에서 정성껏 준비하고 세심하게 구성한 세트로, 단기간 내에 특정 자원이 필요한 조사원과 수호자에게 적합하다."
  },
  Item_34700_Name = {
    Text = "중급 승격 상자"
  },
  Item_34701_Desc = {
    Text = "정교한 자수로 장식된 끈으로 묶은 가방으로, 고급 보급품이 들어 있습니다. \n 잘 들고 있어, 조금 무거울 수 있어. 기억해두세요: 절대 충격을 주지 마세요, 바닥에 떨어뜨리지 않도록 주의하세요."
  },
  Item_34701_Name = {
    Text = "고급 스킬 보급"
  },
  Item_34702_Desc = {
    Text = "화려하게 장식된 나무 상자로, 내부에는 고급 승격 재료가 포함되어 있습니다. \n후방 지원처에서 정성스럽게 준비하고 세심하게 구성한 세트로, 짧은 시간 내에 일정한 자원이 필요한 조사원, 수호자에게 적합합니다."
  },
  Item_34702_Name = {
    Text = "고급 승격 상자"
  },
  Item_34703_Desc = {
    Text = "기이한 소재로 제작된 특별한 장치로, 깨어남체와 명륜의 “회수”를 진행하는 데 사용됩니다.\n그것은 영혼의 인장을 씻어내고 정신의 상처를 지워버리며, 모든 것을 원점으로 되돌리고 최초의 영지를 회복하게 합니다.\n깨어남체 또는 상주 명륜에 “회수” 기능을 열 수 있습니다."
  },
  Item_34703_Name = {
    Text = "시간의 원점"
  },
  Item_34704_Desc = {
    Text = "정교한 자수로 장식된 끈으로 묶은 가방으로, 초급 보급품이 들어 있습니다. 조심하세요, 안의 물건은 아직 활성 상태일 수 있습니다."
  },
  Item_34704_Name = {
    Text = "초급 스킬 보급"
  },
  Item_34705_Desc = {
    Text = "정교한 자수로 장식된 끈으로 묶은 가방으로, 중급 보급품이 들어 있습니다. \n만약 당신의 가방이 아무도 없는 상황에서 조용히 움직이는 것을 발견한다면, 가능한 한 빨리 물자 관리처에 반환해 주세요."
  },
  Item_34705_Name = {
    Text = "중급 스킬 보급품"
  },
  Item_34706_Desc = {
    Text = "영혼과 공명하는 물체. 특정 깨어남체를 깨어남하는 데 사용됩니다.\n아마도 그것의 형태이거나, 아마도 그것의 재질 자체일 것입니다—— 이 차가운 물체는 장막을 뚫고 잠자는 정신을 현실타래로 끌어낼 수 있습니다.\n사용 시 1개의 「경계 연구」, 이전 캐릭터 이벤트 깨어남과 현재 캐릭터 이벤트 깨어남 중의 깨어남체를 선택할 수 있습니다."
  },
  Item_34706_Name = {
    Text = "영혼 회귀의 핵"
  },
  Item_34723_Desc = {
    Text = "“이야기의 마법” 이벤트에서 “스케줄 미스터리”를 클리어하거나 이벤트 업적을 완료하면 획득할 수 있는 아이템으로, “마법 스크립트 상점”에서 교환하는 데 사용됩니다.\n영감은 순식간에 사라지며, 밤하늘을 가로질러 지나가는 유성을 닮았습니다. 다른 점은, 당신이 그것을 영원히 남길 수 있는 방법을 가지고 있다는 것입니다."
  },
  Item_34723_Name = {
    Text = "흩날리는 영감"
  },
  Item_34724_Desc = {
    Text = "임시 촬영장에 산일된 감정 입자로, 접촉하면 아이들의 즐거운 웃음소리가 들리는 듯합니다.\n수호자가 활동 콘텐츠 「각본의 미로」와 특수임무 기록 「이야기의 마법」에서의 공명을 높이는 데 사용됩니다.\n한정 활동 「이야기의 마법」에서 업적 보상을 완료하여 획득할 수 있습니다."
  },
  Item_34724_Name = {
    Text = "연기의 심장"
  },
  Item_34832_Desc = {
    Text = "활동 “이야기의 마법”에서 성취를 완료하여 획득합니다. \n“미사그 깨어남체 관리처 힌트: 리리를 너무 많이 먹이지 말아요! 수호자도 더 이상 먹이면 안 됩니다!”"
  },
  Item_34832_Name = {
    Text = "은열쇠의 이름으로: 릴리"
  },
  Item_34832_StoryDesc = {
    Text = "리리 게임 방식 이벤트"
  },
  Item_34858_Desc = {
    Text = "죽음 저항 속성의 명륜입니다."
  },
  Item_34858_Name = {
    Text = "35mm의 마법"
  },
  Item_34858_StoryDesc = {
    Text = "이야기에는 마법이 존재하며, 프랜시스는 이렇게 릴리에게 말했습니다. \n그때 그녀는 이야기 책을 안고 창가에 앉아 있었고, 초여름의 햇살이 흰 가운을 살짝 데워 따뜻하고 부드러운 향기를 발산하고 있었습니다. \n그녀의 목소리는 부드럽고, 차분하게 이야기를 전했지만, 전날 밤 수술에 집중하느라 쌓인 피로로 인해 이야기가 끝나기 전에 프랜시스는 깊이 잠들어버렸습니다. \n릴리는 결코 어머니를 탓하지 않았습니다. 왜냐하면 창턱에 기대어 있는 어머니의 피곤한 잠 얼굴이 너무나도 편안했기 때문입니다. \n\n이제 필름이 책을 대신하여 이야기와 마법을 담고 있습니다. 아이들의 부주의로 노출되어 손상된 필름을 새로운 필름이 대신하듯, 새로운 친구들의 장난이 과거의 따뜻함과 아픔이 섞인 소식 시간을 대신하고 있습니다. \n그러나 그 안에 묻혀 있는 기억들은 여전히 노출된 필름처럼, 알려지지 않은 어딘가에서 잠들어 있으며, 비록 결코 빛을 보지 못하더라도 여전히 빛나고 있습니다."
  },
  Item_34908_Desc = {
    Text = "아포는 또 무엇을 잘못했을까, 그들은 단지 집이 필요할 뿐이었다. \n 벌레유충과 그의 아포 이웃. 혈육 경계역 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_34908_Name = {
    Text = "포자 중합체"
  },
  Item_34909_Desc = {
    Text = "그들은 바다백합이 만개한 봄에 함께 살육하기로 약속했다.\n유인타 백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_34909_Name = {
    Text = "유인타 백합"
  },
  Item_34910_Desc = {
    Text = "일부 평행 우주에서는 세상을 파괴할 수 있는 힘을 가지고 있습니다. \n먼 열대 지역에서 온 완벽한 광결정으로, 초원차원 경계역의 깨어남체 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_34910_Name = {
    Text = "유카탄의 별"
  },
  Item_34911_Desc = {
    Text = "날갯짓은 토네이도를 일으키거나 꽃가루 알레르기를 유발할 수 있다.\n나비 결정 무리. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_34911_Name = {
    Text = "혼돈의 결정 나비"
  },
  Item_35140_Desc = {
    Text = "「마법 대본 상점」에서 교환하는 데 사용하는 아이템.\n영감은 순식간에 사라집니다, 밤하늘을 가로질러 날아가는 유성처럼. 다른 점은, 당신에게는 그것을 영원히 남길 방법이 있다는 것입니다.\n최소 드롭:\n유영하는 영감* {s1}\n낮은 확률로 추가 유영하는 영감을 획득할 수 있습니다."
  },
  Item_35140_Name = {
    Text = "흩날리는 영감"
  },
