  Item_35148_Desc = {
    Text = "「마법 대본 상점」에서 교환하는 데 사용하는 아이템.\n영감은 순식간에 사라집니다, 밤하늘을 가로질러 날아가는 유성처럼. 다른 점은, 당신에게는 그것을 영원히 남길 방법이 있다는 것입니다.\n최소 드롭:\n유영하는 영감* {s1}\n낮은 확률로 추가 유영하는 영감을 획득할 수 있습니다."
  },
  Item_35148_Name = {
    Text = "흩날리는 영감"
  },
  Item_35711_Desc = {
    Text = "한 번의 기회로 직접 전진 방향을 결정할 수 있습니다. \n제한된 수량으로 제공되는 회전의 책이 태스크를 수행하는 수호자를 보호하기를 바랍니다."
  },
  Item_35711_Name = {
    Text = "특수 공급 회전의 책"
  },
  Item_35712_Desc = {
    Text = "누구도 100% 보장할 수 없어요. 봉인된 영식들이 자발적으로 깨어남한 것을. \n한정판 원질 놀이공원은 태스크를 수행하는 수호자들을 보호하기를 바랍니다."
  },
  Item_35712_Name = {
    Text = "특수 공급 원질의 낙원"
  },
  Item_35816_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「현재의 과제: 수호자의 외근 미션 안전 계수를 어떻게 높일 것인가.\n과제 난이도: ☆☆☆☆☆」"
  },
  Item_35816_Name = {
    Text = "은열쇠의 이름으로: 돌"
  },
  Item_35816_StoryDesc = {
    Text = "제3기 과제 기록"
  },
  Item_35817_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다. \n「지루해! 강물이 핏빛으로 물들때까지 싸우고 싶다고!」"
  },
  Item_35817_Name = {
    Text = "은열쇠의 이름으로: 로탄"
  },
  Item_35817_StoryDesc = {
    Text = "제6기 과제 기록"
  },
  Item_36018_Desc = {
    Text = "활동 '별의 정위'에서 업적을 얻다.\n'딸기 잼 스콘의 악마, 브라우니 공주, 미사그 식당 카트에서 새로운 파괴자——이미 여기에 강림했다!'"
  },
  Item_36018_Name = {
    Text = "은열쇠의 이름으로: 머피"
  },
  Item_36018_StoryDesc = {
    Text = "머피 플레이 이벤트"
  },
  Item_36782_Desc = {
    Text = "거래 계정과 비밀번호를 제공해 주세요. \n왕국의 지하 시장에서 유통되는 거래 증명서로, 수호자는 이 증명서를 통해 희귀한 물품들을 구입할 수 있습니다."
  },
  Item_36782_Name = {
    Text = "밀은 거래 증명서"
  },
  Item_36801_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬: “오레타의 보물”을 선택할 수 있습니다. \n\n유리통. 수족관. 궁전. \n\n무엇이라고 부르든, 그것은 모두 오레타의 친구들이 거주하는, 융식과 고통이 없는 작은 낙원입니다."
  },
  Item_36801_Name = {
    Text = "오레타의 보물"
  },
  Item_36801_StoryDesc = {
    Text = "유리항아리. 수족관. 궁전. \n\n그것을 무엇이라고 부르든, 그것은 오레타의 친구들이 거주하는, 융식과 고통이 없는 아늑한 공간입니다."
  },
  Item_36813_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “포효하는 피와 모래”를 선택할 수 있습니다.\n\n여명이 피처럼 빛나고, 먼지 날리기.\n\n무한한 사막 위에서, 타고난 전사가 주저 없이 자신의 손목을 물어뜯고, 그의 피를 하늘과 대지에 되돌려준다."
  },
  Item_36813_Name = {
    Text = "포효하는 피와 모래"
  },
  Item_36813_StoryDesc = {
    Text = "여명이 피처럼 빛나고, 먼지 날리기. \n\n무한한 사막 위에서, 타고난 전사가 주저 없이 자신의 손목을 물어뜯고, 그의 피를 하늘과 대지에 되돌려준다."
  },
  Item_36814_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “마지막 서약”을 선택할 수 있습니다.\n\n기사는 이 창으로 중요한 사람을 지키겠다고 서약했습니다. 지금 그는 주인의 가슴을 관통하여 위험을 밖으로 차단했습니다—— 이것은 기사가 실타래천한 마지막 서약입니다."
  },
  Item_36814_Name = {
    Text = "마지막 서약"
  },
  Item_36814_StoryDesc = {
    Text = "기사는 이 창으로 중요한 사람을 지키겠다고 서약했다. 지금 그는 주인의 가슴을 관통하여 위험을 밖으로 차단했다—— 이것은 기사가 실타래천한 마지막 서약이다."
  },
  Item_36815_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “순간의 영원”을 선택할 수 있습니다.\n\n기계로 만들어진 인형은 신생의 영혼이 약속한 영원을 거절했고, 핵심의 전류가 그녀의 영혼을 태웠다. 육체를 더 이상 지탱할 수 없게 되기 전, 그녀는 마지막으로 완수해야 할 일이 있었다——"
  },
  Item_36815_Name = {
    Text = "순간의 영원"
  },
  Item_36815_StoryDesc = {
    Text = "기계로 만들어진 인형은 신생의 영혼이 약속한 영원을 거절했고, 핵심의 전류가 그녀의 영혼을 태웠다. 육체를 더 이상 지탱할 수 없게 되기 전, 그녀는 마지막으로 완수해야 할 일이 있었다——"
  },
  Item_36847_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “뼈를 침식하는 포옹”을 선택할 수 있습니다.\n\n혈육이 깊은 바다에 녹아내리고, 뼈가 산으로 굳어졌다. 그녀의 시선은 뜨겁고, 너를 안고, 너를 조각한다.\n\n그녀는 너에게 약속했다. 함께 집으로 돌아가자고."
  },
  Item_36847_Name = {
    Text = "뼈를 침식하는 포옹"
  },
  Item_36847_StoryDesc = {
    Text = "혈육이 깊은 바다에 녹아내리고, 뼈가 산으로 굳어졌다. 그녀의 시선은 뜨겁고, 너를 안고, 너를 조각한다. \n\n그녀는 너에게 약속했다. 함께 집으로 돌아가자고."
  },
  Item_36848_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “호숫가의 회상”을 선택할 수 있습니다.\n\n캄브리아 강곡의 호수는 반짝이고 맑아서 바닥이 보입니다.\n\n미로 속의 소란이 갑자기 멀어지고, 이 순간의 평화를 즐기는 것은 너와 자유를 되찾은 소녀뿐이다."
  },
  Item_36848_Name = {
    Text = "호숫가의 회상"
  },
  Item_36848_StoryDesc = {
    Text = "캄브리안 강곡의 호수는 반짝이고 맑아서 바닥이 보인다. \n\n미로 속의 소란이 갑자기 멀어지고, 이 순간의 평화를 즐기는 것은 너와 자유를 되찾은 소녀뿐이다."
  },
  Item_36849_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “회귀의 문을 넘어”를 선택할 수 있습니다. \n\n소녀는 자신이 겪은 환생의 횟수를 세어볼 수 없고, 바꾼 역사도 기억할 수 없다. \n\n이 마지막 기회, 마지막 회고에서 그녀의 검이 타비의 영핵을 관통했지만, 손을 잡을 시간조차 없었고, 함께 블랙풀에 빠져들었다."
  },
  Item_36849_Name = {
    Text = "회귀의 문을 넘어"
  },
  Item_36849_StoryDesc = {
    Text = "소녀는 자신이 겪은 환생의 횟수를 세어볼 수 없고, 바꾼 역사도 기억할 수 없다. \n\n이 마지막 기회, 마지막 회고에서 그녀의 검이 타비의 영핵을 관통했지만, 손을 잡을 시간조차 없었고, 함께 블랙풀에 빠져들었다."
  },
  Item_36850_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬:“부패의 연회”를 선택할 수 있습니다.\n\n잔치가 절정에 이르렀을 때, 캄브리안의 여왕은 크게 웃으며, 열광하는 인파와 튀어오르는 융식점액을 가로질러 당신에게 잔을 들어 경의를 표했습니다."
  },
  Item_36850_Name = {
    Text = "부패의 연회"
  },
  Item_36850_StoryDesc = {
    Text = "잔치가 절정에 이르렀을 때, 캄브리안의 여왕은 크게 웃으며, 열광하는 군중들과 튀어오르는 융해진흙을 가로질러 당신에게 잔을 들어 경의를 표했다."
  },
  Item_36857_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬:“신적 강림”을 선택할 수 있습니다. \n\n치유의 신적 강림이 광기로 더럽혀진 성당에 내려오며, 자발적으로 헌신한 자, 결함 없는 자비로운 자의 피를 대가로 합니다."
  },
  Item_36857_Name = {
    Text = "기적의 강림"
  },
  Item_36857_StoryDesc = {
    Text = "치유의 신적 기적이 광기로 더럽혀진 성당에 강림하여, 자발적으로 헌신한 자와 흠 없는 자비로운 자의 피를 대가로 받습니다."
  },
  Item_36858_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “거인의 패도”를 선택할 수 있습니다. \n\n강자의 길, 포기하지 않고, 패배를 거부한다. \n\n지평선이 이미 빛을 삼켰더라도, 그는 완력으로 꺼지지 않는 태양을 짊어지고 일어설 것이다."
  },
  Item_36858_Name = {
    Text = "거인의 패도"
  },
  Item_36858_StoryDesc = {
    Text = "강자의 길, 포기하지 않고, 패배를 거부한다. \n\n지평선이 이미 빛을 삼켰더라도, 그는 거력으로 꺼지지 않는 태양을 짊어지고 일어설 것이다."
  },
  Item_36859_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “그녀의 전부”를 선택할 수 있습니다.\n\n전부의 24가 하나로 융합되어 별빛으로 사라졌다.\n\n그녀의 인격은 분리되어 완전해졌고, 그녀의 육체는 분열되어 살아남았다.\n\n이 세상에는 오직 하나의 24만이 존재하며, 그것이 전부 그녀의 것이다."
  },
  Item_36859_Name = {
    Text = "그녀의 전부"
  },
  Item_36859_StoryDesc = {
    Text = "전부의 24가 하나로 융합되어 별빛으로 사라졌다. \n\n그녀의 인격은 분리되어 완전해졌고, 그녀의 육체는 분열되어 살아남았다. \n\n이 세상에는 오직 하나의 24만이 존재하며, 그것이 전부 그녀의 것이다."
  },
  Item_36860_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “장미의 승리”를 선택할 수 있습니다. \n\n우아한 장미는 그녀의 완전한 승리를 거두었다. \n\n그녀는 모두의 주목을 받으며 인파 속으로 회귀한 고귀한 장미로, 당신에게 향하는 시선만이 오페라 하우스에서 겪은 숨겨진 여정을 나타내고 있다."
  },
  Item_36860_Name = {
    Text = "장미의 승리"
  },
  Item_36860_StoryDesc = {
    Text = "우아한 장미는 그녀의 완전한 승리를 거두었다. \n\n그녀는 모두의 주목을 받으며 인파 속으로 회귀한 고귀한 장미로, 당신에게 향하는 시선만이 오페라 하우스에서 겪은 숨겨진 여정을 나타내고 있다."
  },
  Item_36861_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “회무진용”을 선택할 수 있습니다.\n\n미풍이 그녀의 긴 머리를 날리며, 회색 안개 바다의 반영이 순간적으로 나타나서 곧 형체 없이 사라진다. 당신 앞에 여전히 우아하고 침착한 그녀가 있지만, 당신은 그것이 당신의 환각이 아니라는 것을 안다."
  },
  Item_36861_Name = {
    Text = "회색 안개의 진상"
  },
  Item_36861_StoryDesc = {
    Text = "미풍이 그녀의 긴 머리를 날리며, 회색 안개 바다의 반영이 순간적으로 나타나서 곧 형체 없이 사라진다. 당신 앞에 여전히 우아하고 침착한 그녀가 있지만, 당신은 그것이 당신의 환각이 아니라는 것을 안다."
  },
  Item_36862_Desc = {
    Text = "이 키링을 기록한 후, 배치 시 키링 스킬: “중하의 꿈”을 선택할 수 있습니다. \n\n그것은 짧고 환상적인 한밤의 꿈으로, 가볍고 부드럽게 흐르며 필름에 담겨 있지는 않지만 각 촬영자의 기억 속에서 살아 숨쉬고 있습니다."
  },
  Item_36862_Name = {
    Text = "한여름의 꿈"
  },
  Item_36862_StoryDesc = {
    Text = "그것은 짧고 환상적인 한밤의 꿈이었으며, 가볍고 부드러워 필름에 남지 않았지만, 촬영자의 기억 속에서 흐르고 있었다."
  },
  Item_36863_Desc = {
    Text = "터치하면 새로운 모험에 뛰어들 수 있으며;\n안아주면 가장 황당한 꿈으로 빠져듭니다.\n은심을 보관하는 새로운 장치로 특파대 기록과 의식 잠수를 해금할 수 있습니다."
  },
  Item_36863_Name = {
    Text = "현실타래의 시작점"
  },
  Item_36889_Desc = {
    Text = "캄브리아에 산일된 감정 입자로, 접촉하면 레드 와인과 잿더미가 연소되는 냄새가 나는 듯합니다.\n수호자가 활동 콘텐츠 「호수 속의 도시」에서의 공명을 높이는 데 사용됩니다.\n한정 활동 「불타는 군연」에서 업적 보상을 완료하여 획득할 수 있습니다."
  },
  Item_36889_Name = {
    Text = "희락의 심장"
  },
  Item_38702_Desc = {
    Text = "“어두운 속박”에서 교환에 사용되는 아이템입니다. \n이사라우의 바람에 산재한 거대한 바위 잔해입니다. \n그들은 정지된 채로, 사라진 도시를 위해 엄숙히 애도하고 있습니다."
  },
  Item_38702_Name = {
    Text = "나선 유적"
  },
  Item_38703_Desc = {
    Text = "“유적의 수호자”에서 교환에 사용되는 아이템입니다. \n 탄산칼슘이 둘러싼 꿈의 고리. 이사라우의 책의 비밀을 풀어드립니다."
  },
  Item_38703_Name = {Text = "원엽석"},
  Item_38704_Desc = {
    Text = "“등가시의 파동”에서 교환에 사용되는 아이템입니다. \n척추 재료 중 하나로, 이를 다듬어 인간의 가슴에 꽂으면 모든 것을 지배할 수 있습니다. \n의지와 감정? 불과 생물의 손상 코드일 뿐입니다."
  },
  Item_38704_Name = {
    Text = "원생 경골"
  },
  Item_39313_Desc = {
    Text = "이벤트 “타오르는 군연”에서 상점 교환으로 획득 가능합니다. \n“나에게 복종하고, 나에게 엎드리라! 아니면, 다시 척추가 뽑히는 달콤씁쓸한 고통을 맛보고 싶으냐?”"
  },
  Item_39313_Name = {
    Text = "은열쇠의 이름으로: 완다"
  },
  Item_39313_StoryDesc = {
    Text = "완다 플레이 이벤트"
  },
  Item_39379_Desc = {
    Text = "「완다의 진귀한 보물 상자」에서 교환하는 데 사용하는 아이템.\n이사라우의 바람 속에 흩어진 거대한 돌 잔해들.\n그것들은 움직이지 않고, 장엄하게 사라진 도성을 애도합니다.\n\n최소 {s1}개 드롭, 공명 「필요성 원정」 활성화 시 추가 50% 드롭 보너스 적용"
  },
  Item_39379_Name = {
    Text = "나선 유적"
  },
  Item_39380_Desc = {
    Text = "「완다의 진귀한 보물 상자」에서 교환하는 데 사용하는 아이템.\n등가시의 원재료 중 하나입니다. 이것으로 다듬어진 등가시가 인간의 흉강에 박히면 모든 것을 지배할 수 있습니다.\n의지와 감정? 그저 생물의 손상된 코드에 불과합니다.\n\n최소 {s1}개 드롭, 공명 「영토 확장」 활성화 시 추가 50% 드롭 보너스 적용"
  },
  Item_39380_Name = {
    Text = "원생 경골"
  },
  Item_39381_Desc = {
    Text = "「완다의 진귀한 보물 상자」에서 교환하는 데 사용하는 아이템.\n 겹겹이 쌓인 탄산칼슘으로 이루어진 꿈. 이사라우의 서의 비밀을 풀어드립니다.\n\n최소 {s1}개 드롭, 공명 「비강제 수용」 활성화 시 추가 50% 드롭 보너스 적용"
