  Item_39453_Desc = {
    Text = "「완다의 진귀한 보물 상자」에서 교환하는 데 사용하는 아이템.\n이사라우의 바람 속에 흩어진 거대한 돌 잔해들.\n그것들은 움직이지 않고, 장엄하게 사라진 도성을 애도합니다.\n\n최소 {s1}개 드롭, 공명 「필요성 원정」 활성화 시 추가 50% 드롭 보너스 적용"
