  Item_39460_Name = {Text = "원엽석"},
  Item_39461_Desc = {
    Text = "「완다의 진귀한 보물 상자」에서 교환하는 데 사용하는 아이템.\n등가시의 원재료 중 하나입니다. 이것으로 다듬어진 등가시가 인간의 흉강에 박히면 모든 것을 지배할 수 있습니다.\n의지와 감정? 그저 생물의 손상된 코드에 불과합니다.\n\n최소 {s1}개 드롭, 공명 「영토 확장」 활성화 시 추가 50% 드롭 보너스 적용"
  },
  Item_39461_Name = {
    Text = "원생 경골"
  },
  Item_39462_Desc = {
    Text = "「완다의 진귀한 보물 상자」에서 교환하는 데 사용하는 아이템.\n이사라우의 바람 속에 흩어진 거대한 돌 잔해들.\n그것들은 움직이지 않고, 장엄하게 사라진 도성을 애도합니다.\n\n최소 {s1}개 드롭, 공명 「필요성 원정」 활성화 시 추가 50% 드롭 보너스 적용"
  },
  Item_39462_Name = {
    Text = "나선 유적"
  },
  Item_41327_Name = {
    Text = "등불 교회 부호"
  },
  Item_41379_Desc = {
    Text = "피해 증폭 속성의 명륜입니다."
  },
  Item_41379_Name = {
    Text = "이살라우의 주시"
  },
  Item_41379_StoryDesc = {
    Text = "첫 번째 왕부는 이사라우 출신입니다.\n그는 이사라우 사람 특유의 눈를 가지고 있으며, 연한 금색으로 멀리 어두운 밤 하늘에서 희미한 빛을 발하고 있습니다.\n하지만 그 빛은 이사라우가 함락되면서 사라졌고, 완다는 칠흑 같은 진흙에서 마지막의 매개체를 건져내어 소중히 간직했습니다.\n그녀는 두 번째와 세 번째 왕부와 프랑 고지에서 만났습니다.\n그들은 탐욕스러운 쌍둥이 영주들로, 완다는 그들의 힘을 빌려 잃어버린 호수 속의 도시를 재건하고자 했습니다.\n그녀는 속았고, 그래서 등가시는 그들의 뼈속 깊숙이 박혔습니다. 마비 상태에서 완다는 그 두 쌍의 비천하고 무례한 눈을 빼내고, 그 후 그것들을 남겨두어 자신이 지나갔다는 흔적을 남겼습니다.\n네 번째 왕부, 완다는 그를 '존'이라고 기억합니다.\n그는 무미건조한 벙어리였지만, 그녀를 편안하게 모셨습니다. 더 기쁜 것은 '존' 또한 그녀와 거의 똑같은 연한 금색의 눈을 가지고 있다는 것이었습니다.\n\n“왕부의 눈을 도려내 버려.”\n“당신의 바람을 따르겠습니다…… 하지만, 왕부가 무슨 잘못을 했나요?”\n완다는 컵 속의 흐릿한 물을 흔들며 독소가 혀끝에서 유영하는 것을 느꼈습니다. 정말 바보 같은 자, 독을 내리는 것도 이렇게 서투르다니.\n'존'의 융식으로 뒤덮인 몸을 보며, 그녀는 먼 별 너머에서 고향을 떠나는 그녀를 지켜보던 죽은 듯한 눈들에 대해 떠올렸습니다.\n그리고 '존'의 지금 눈과 똑같았습니다.\n“……그는 유머 감각이 부족하다고 말해줘.”"
  },
  Item_43605_Desc = {
    Text = "기간 한정의 손발이 뒤죽박죽 되어, 이러한 무질서하게 증식하는 결정체를 수납하기 위해 연구원이 며칠간 야근을 했습니다.\n불정기적으로 폭발하는 모방 결정체, 한정 공급으로 임무를 수행하는 수호자에게 지원을 제공합니다."
  },
  Item_43605_Name = {
    Text = "모방 폭발의 밤"
  },
  Item_44174_Desc = {
    Text = "성당 내에 산일된 감정 입자로, 접촉하면 누군가의 기도와 저어가 들리는 듯합니다.\n수호자가 활동 콘텐츠 「성당의 길」과 특수임무 기록 「피의 색」에서의 공명을 높이는 데 사용됩니다.\n한정 활동 「영혼의 목자」에서 업적 보상을 완료하여 획득할 수 있습니다."
  },
  Item_44174_Name = {
    Text = "참회의 심장"
  },
  Item_44265_Desc = {
    Text = "이벤트 “영혼의 목자”에서 “성당의 길”, “시민의 선의” 및 “성취 보상”을 통해 얻어지는 아이템으로, “자선 판매 현장”에서 상품을 구매하는 데 사용됩니다. \n\n당신의 사랑을 의미 있는 판매권으로, 당신의 돈을 다른 사람의 미래로 바꾸세요. \n서로 돕는 것이 아버지 신이 바라는 길입니다."
  },
  Item_44265_Name = {
    Text = "자선 판매권"
  },
  Item_44481_Desc = {
    Text = "활동 '영혼의 목자'에서 업적을 얻다.\n'아버지 신은 모든 이의 영혼의 광휘를 볼 수 있다…… 물론 너의 것도, 비밀 지키는 사람이여.'"
  },
  Item_44481_Name = {
    Text = "은열쇠의 이름으로: 살바도르"
  },
  Item_44481_StoryDesc = {
    Text = "살바도르 플레이 이벤트"
  },
  Item_44482_Desc = {
    Text = "활동 “비 마을의 그림자”에서 성취를 완료하여 획득합니다. \n“세상에 자동으로 문제를 푸는 기계는 없단다, 내 사랑스러운 손님. 퍼즐을 풀고 싶다면 먼저 옆에 있는 파트너에게 물어볼래?”"
  },
  Item_44482_Name = {
    Text = "은열쇠의 이름으로: 다포딜"
  },
  Item_44482_StoryDesc = {
    Text = "다프다일 플레이 이벤트"
  },
  Item_44483_Desc = {
    Text = "활동 “신왕 부활”에서 업적을 완료하여 획득합니다. \n“포기해, 오후 4시 이후에는 내가 어떤 상주문도 읽지 않을 거다——수호자가 제출한 것이라도 안 본다.”"
  },
  Item_44483_Name = {
    Text = "은열쇠의 이름으로: 툴루"
  },
  Item_44483_StoryDesc = {
    Text = "툴루 플레이 이벤트"
  },
  Item_44576_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
  },
  Item_44576_Name = {
    Text = "조사 과정 특전 Ⅱ"
  },
