  },
  Item_44581_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
  },
  Item_44581_Name = {
    Text = "조사 과정 특전 Ⅵ"
  },
  Item_44809_Desc = {
    Text = "외근 기간 동안 일일 시련 대리 계획을 신청할 수 있습니다.\n대리 증명서를 제시하면 일일 시련 보상을 직접 수령할 수 있습니다.\n주의사항: 장기간 시련에 결석하지 않도록 하여 전투 기술을 잊지 않도록 하세요."
  },
  Item_44809_Name = {
    Text = "대리 증명서"
  },
  Item_44832_Desc = {
    Text = "검은 인장 드롭율 속성의 명륜입니다."
  },
  Item_44832_Name = {
    Text = "거울 속의 사람"
  },
  Item_44832_StoryDesc = {
    Text = "그 미스터리한 여자는 장례식 후 그녀를 찾아왔다. \n“불쌍한 아이야,” 그녀가 말했다. “넌 이런 어이없는 재난을 당할 필요가 없었어.” \n“모르니? 밀리를 죽이고 나서, 톰슨이 그를 찾아갔잖아. 에드워드라는 그 쓰레기, 그는 작년에 죽었어야 했는데 어떤 누군가가 그를 도와줬지.” \n“왜냐고? 오, 그건 나도 몰라. 아마도, 그들은 애초에 한통속이었거나, 아니면… 그 죄인은 자신이 저지른 일을 죄라고도 몰랐겠지. 그는 뭐라고 했더라? 맞아, 용서. 죄인을 용서하고, 그들이 저지른 죄를 용서하는 것.” \n“그는 모두가 두 번째 기회를 받아야 한다고 믿어. 넌 어떻게 생각해? 에드워드에게 또 한 번 기회를 줘야 할까? 그가 밀리를 죽이고, 네 언니와 어머니를 죽였는데?” \n“그래 맞아. 이런 사람은 바뀌지 않아, 절대 바뀌지 않아. 그래서, 뭘 해야 할지 알겠지?” \n그래. 이런 사람은 바뀌지 않아. 이런 사람을 끝장내고, 이런 악을 끝장내고, 이런 비극을 끝장내려면… \n그들의 욕망을 드러내고, 그들의 추태를 철저히 드러내며, 그들이 서로를 물고 뜯게 하고, 철저히 정화시키는 거야—— \n죄 없는 정토로 나아가는 거야."
  },
  Item_44841_Name = {
    Text = "리본 방울"
  },
  Item_44842_Name = {
    Text = "뱀의 허물"
  },
  Item_44928_Desc = {
    Text = "「의미 있는 판매 현장」에서 교환하는 데 사용하는 아이템.\n당신의 사랑을 의미 있는 판매권으로, 당신의 재물을 타인의 미래로 바꾸세요.\n서로 돕는 것이야말로 아버지 신이 바라는 길입니다.\n\n최소 {s1}개 드롭"
