    Text = "「의미 있는 판매 현장」에서 교환하는 데 사용하는 아이템.\n당신의 사랑을 의미 있는 판매권으로, 당신의 재물을 타인의 미래로 바꾸세요.\n서로 돕는 것이야말로 아버지 신이 바라는 길입니다.\n\n최소 {s1}개 드롭"
  },
  Item_44960_Name = {
    Text = "자선 판매권"
  },
  Item_44961_Desc = {
    Text = "「의미 있는 판매 현장」에서 교환하는 데 사용하는 아이템.\n당신의 사랑을 의미 있는 판매권으로, 당신의 재물을 타인의 미래로 바꾸세요.\n서로 돕는 것이야말로 아버지 신이 바라는 길입니다.\n\n최소 {s1}개 드롭"
  },
  Item_44961_Name = {
    Text = "자선 판매권"
  },
  Item_44962_Desc = {
    Text = "「의미 있는 판매 현장」에서 교환하는 데 사용하는 아이템.\n당신의 사랑을 의미 있는 판매권으로, 당신의 재물을 타인의 미래로 바꾸세요.\n서로 돕는 것이야말로 아버지 신이 바라는 길입니다.\n\n최소 {s1}개 드롭"
  },
  Item_44962_Name = {
    Text = "자선 판매권"
  },
  Item_45297_Desc = {
    Text = "크리티컬 확률 속성의 명륜입니다."
  },
  Item_45297_Name = {
    Text = "은빛 물고기의 결심"
  },
  Item_45297_StoryDesc = {
    Text = "<Bold:은코다24>\n매번 그 튀김 생선 식당을 지나칠 때마다, 나는 소리치고 싶어 견딜 수가 없어요.\n왜 다치는 것은 항상 은코다일까요? 우리는 심지어 진짜 대구도 아니잖아요!\n살이 탄탄하고 맛이 뛰어난 것도 우리의 잘못인가요?\n\n<Bold:고양이24>\n흡입흡입……야옹, 야옹야옹(찬성)!\n\n<Bold:은코다24>\n레이왕국에서는 매 분마다 한 마리의 은코다가 비명횡사하여 인간의 접시에 올라갑니다.\n그래요, 우리가 이야기하는 간격 사이에 이미 10마리의 은코다가 비극적으로 희생되었어요.\n정확히 10마리! 아버지 신이시여, 그들의 비명소리를 들으셨나요?\n\n<Bold:고양이24>\n어… 야옹? 야옹야옹, 야옹야옹(어디서)?\n\n<Bold:은코다24>\n그건 단지 비유일 뿐이에요, 바보야. 너는 조금 멍청하긴 하지만, 고양이의 본능과 단기적인 시각을 이겨낼 수 있는 금 같은 마음을 가지고 있어요.\n들어봐, 다음에 내가 계획이 있어. 너와 함께 실타래행해야 해……\n\n—— 《대존 존 튀김 생선 식당 폭발 사건·사건 요약: 증언 B-03》에서 발췌. 해당 시기에 베들레헴 정신병원이 만원이라, 용의자는 수용이 거부되었고, 렌티니언 타워에 23일 동안 구금된 후 석방되었습니다."
  },
  Item_45298_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬: “봄의 헌시”를 선택할 수 있습니다. \n\n이 시를 받아들이세요, 봄이 정원에 바치는 시를. \n우리의 황량한 생명 속에서 장미가 짙은 빨강으로 피어나고 있습니다."
  },
  Item_45298_Name = {
    Text = "봄의 헌시"
  },
  Item_45298_StoryDesc = {
    Text = "이 시를 받아주세요, 봄이 정원에 바치는 시입니다\n우리의 황량한 생명에서 장미가 짙은 빨강으로 피어나고 있다."
  },
  Item_45299_Desc = {
    Text = "이 열쇠를 기록한 후, 편성 시 열쇠 기술:「검은 백조의 무브」를 선택할 수 있습니다.\n\n풍부한 발걸음. 뛰어오르며 자르기. 회전. 무곡의 절정에서 불길 속으로 뛰어들어라.\n타올라라. 타오름은 춤의 유일한 해답이다."
  },
  Item_45299_Name = {
    Text = "검은 백조의 춤사위"
  },
  Item_45299_StoryDesc = {
    Text = "우아한 발걸음. 점프 컷. 회전. 춤곡의 절정에서, 불꽃 속으로 뛰어 들었다.\n타오르라. 타오르는 것이 춤의 유일한 해답이다."
  },
  Item_45300_Desc = {
    Text = "이 키링을 기록한 후, 배치 시 키링 스킬: “해의 제전”을 선택할 수 있습니다. \n\n리모리아의 주제사는 바다의 응답을 기대하지 않습니다. \n\n그녀는 모든 것을 바다에 바쳤지만, 이는 바다와 관련이 없습니다."
  },
  Item_45300_Name = {
    Text = "바다의 의식"
  },
  Item_45300_StoryDesc = {
    Text = "리모리아의 주제사는 바다의 응답을 기대하지 않는다. \n\n그녀는 모든 것을 바다에 바쳤으나, 이는 바다와는 관련이 없다."
  },
  Item_45301_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “한 발의 총성”을 선택할 수 있습니다.\n\n“뱅——”\n한 발의 총소리가 음모의 배후 주모자의 심장을 관통했다.\n\n죽음은 생명의 끝이 아니며, 퍼즐이 반전되는 절정일 뿐이다."
  },
  Item_45301_Name = {
    Text = "한 발의 총성"
  },
  Item_45301_StoryDesc = {
    Text = "“뱅——”\n한 발의 총소리가 음모의 배후 주모자의 심장을 관통했다.\n\n죽음은 생명의 끝이 아니며, 퍼즐이 반전되는 절정일 뿐이다."
  },
  Item_45302_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “산맥의 각오”를 선택할 수 있습니다.\n\n극한의 빙하 산맥은 영웅적인 전사와 광기 어린 야수를 흡수하여, 결백한 눈으로 스토리의 잔해를 덮었습니다.\n하지만 이듬해 봄이 오면, 미약한 생기가 결국 눈보라를 넘어설 것입니다. 산맥은 이미 각오를 다졌습니다."
  },
  Item_45302_Name = {
    Text = "산맥의 각오"
  },
  Item_45302_StoryDesc = {
    Text = "극한의 빙하 산맥은 영웅적인 전사와 광기 어린 야수를 흡수하여, 결백한 눈으로 스토리의 잔해를 덮었다. \n하지만 이듬해 봄이 오면, 미약한 생기가 결국 눈보라를 넘어설 것이다. 산맥은 이미 각오를 다졌다."
  },
  Item_46606_Desc = {
    Text = "“인격 분석”에서 교환에 사용되는 아이템입니다. \n\n모든 기억이 충성스럽고 신뢰할 수 있는 것은 아닙니다. \n비밀을 하나 알려드리죠: β는 철저한 거짓말쟁이이며, 지금도 거짓말을 하고 있습니다."
  },
  Item_46606_Name = {
    Text = "기억 퍼즐 α"
  },
  Item_46607_Desc = {
    Text = "“인격 분석”에서 교환에 사용되는 아이템입니다. \n\n진실타래: α와 β는 모두 거짓말을 하고 있습니다. \n지금 나는 완전히 소멸될 위험을 무릅쓰고 당신에게 이 사실타래을 알려주고 있습니다.@#¥%……&"
  },
  Item_46607_Name = {
    Text = "기억 퍼즐 γ"
  },
  Item_46608_Desc = {
    Text = "“인격 분석”에서 교환에 사용되는 아이템입니다. \n\n아, 시기! 너는 소문의 어머니다. \n나는 α에 대한 혐의를 깊이 유감스럽게 생각합니다. 나에게 알려진 바로는, 그것이 거짓말을 한 놈이라고 합니다."
  },
  Item_46608_Name = {
    Text = "기억 퍼즐 β"
  },
