    Text = "「인격 해석」에서 교환하는 데 사용하는 아이템.\n\n진실: α와 β 모두 거짓말을 하고 있습니다.\n이제 완전히 소멸될 위험을 무릅쓰고 이것을 알려드립니다 @#¥%……&\n\n최소 {s1}개 드롭"
