  Item_47302_Desc = {
    Text = "「인격 해석」에서 교환하는 데 사용하는 아이템.\n\n아, 질투여! 당신은 소문의 어머니입니다.\nα에 대한 고발에 깊이 유감을 표합니다. 제가 아는 한, 거짓말을 한 것은 바로 그쪽입니다.\n\n최소 {s1}개 드롭"
  },
  Item_47302_Name = {
    Text = "기억 퍼즐 β"
  },
  Item_47303_Desc = {
    Text = "「인격 해석」에서 교환하는 데 사용하는 아이템.\n\n모든 기억이 충성스럽고 믿을 만한 것은 아닙니다.\n비밀을 하나 알려드리죠: β는 철두철미한 거짓말쟁이로, 거짓말을 하고 있습니다.\n\n최소 {s1}개 드롭"
  },
  Item_47303_Name = {
    Text = "기억 퍼즐 α"
  },
  Item_47304_Desc = {
    Text = "밀랍인형관에 흩어진 감정 입자로, 만질 때 눈물과 붉은 리본, 그리고 안개 속의 론디니움이 보이는 듯하다.\n활동 콘텐츠「기억 인코딩」과 특수 파견 기록「고요한 분열」에서 수호자의 공명을 높이는 데 사용된다.\n한정 활동「다중 치유」에서 업적 보상으로 획득할 수 있다."
  },
  Item_47304_Name = {
    Text = "분열의 심장"
  },
  Item_47519_Desc = {
    Text = "크리티컬 피해 속성의 명륜입니다."
  },
  Item_47519_Name = {
    Text = "심연의 부름"
  },
  Item_47519_StoryDesc = {
    Text = "왕좌의 환몽에서, 왕은 신성의 계시를 듣습니다: \n리모리아의 폭풍이 가라앉을 것입니다. 리모리아의 심연이 사라질 것입니다. \n꿈을 정원으로 삼고, 별들을 촛불로 삼습니다. 왕은 그의 선한 백성을 보호하고 신의 왕국을 가져올 것입니다. \n\n주님의 신도여, 당신의 마음을 열고 주님을 받아들이십시오. \n먼 어두운 심연에서, 고대의 위대한 영혼이 깊은 잠하고, 신들의 저어를 듣고 있습니다. \n그의 의지는 별들의 그물처럼 얽혀 있으며, 그는 영원한 공허에서 당신이 꿈속으로 들어가기를 기다리고 있습니다. \n\n폭풍은 잠잠하고, 물결은 일지 않으며; \n지진은 가라앉고, 대지는 평안합니다. \n재앙은 그의 평온한 꿈속에서 공허로 변하고, \n백성들은 그의 보호 아래에서 안전합니다. \n우리의 노래가 깊은 바다를 건너가기를, 그가 재앙으로부터 우리를 보호하는 신탁을 내려주시기를, \n우리를 끝없는 평화와 극락의 세계로 인도하여 주시기를. \n우리의 믿음이 그와 함께 하여, 별들이 사라질 때까지, 시간의 끝까지. \n"
  },
  Item_47520_Desc = {
    Text = "죽음 저항 속성의 명륜입니다."
  },
  Item_47520_Name = {
    Text = "지난날의 꽃과 시"
  },
  Item_47520_StoryDesc = {
    Text = "그녀의 시가 시테를 풍미하면서부터, 친구는 더욱 정성스러운 꽃다발을 그녀에게 보냈다./n「이렇게 많은 꽃은 필요없어, 코레트. 이건 너무 큰 낭비야.」/n오늘 들고 온 장미는 어제, 그저께, 엊그제의 것들과 한데 쌓였고, 심지어 더 오래된 꽃들은 붐비다 못해 썩어가고 있었다./n「어떻게 낭비겠어? 우리는 이전에 말한 대로, 내 꽃과 네 시를 바꾸는 거야.」/n코레트는 고개를 가로저으며, 약간 쑥쓰럽게 그녀를 바라보았다./n그렇다. 꽃으로 시를 교환하는 것. 이건 그녀 간의 약속이었다. 그녀는 어떠한 변화가 생겼다고는 느꼈지만, 그 뒤를 다시 생각하고 싶진 않았다./n그녀는 계속 시를 썼고, 거기에 밤낮이란 없었다. 한때 그녀의 시는 펜촉에서 자연스럽게 흘러나오던 것이었으나, 지금 그녀의 펜은 언뜻 조금씩 어색해져 갔다./n꽃을 가져오는 친구의 시선이 그녀를 점점 낯설게 했고, 방을 가득 채운 채 빠르게 썩어가는 장미를 보며, 그리고 그것들이 시들며 내는 썩은 내를 맡으면서 그녀의 안타까움은 실타래망으로 우러나왔다./n그럼에도 그녀는 손에 쥔 펜을 여지껏 놓지 않았다./n「난 이 작은 땅에서 난 꽃으로, 우리의 옷과 음식을 살 거야. 언젠간, 저기 솟아오른 건물의 집마저도, 내가 사고 말 거야!」/n「모든 사람은 태어나서 해야만 하는 일들이 있어. 나는 이 정원과, 저 집을 위해 노력하는 것...... 그리고 너는, 시를 쓰기 위해 태어난 거야.」/n「나만 믿어, 오를라! 오늘부터 네 시는 내가 모아서 소중히 보관할게. 앞으론, 내 꽃과 네 시를 맞바꾸는 거야!」/n꽃과 시, 그녀 간에 서로 맺은 약속./n그녀는 손에 든 펜을 영원히 멈추지 않을 것이다."
  },
  Item_47521_Desc = {
    Text = "광기 충전 레벨 속성의 명륜이다."
  },
  Item_47521_Name = {
    Text = "작별의 키스"
  },
  Item_47521_StoryDesc = {
    Text = "검은 피를 맞고 다시 태어난 소녀는, 사막에서 천 년을 맴도는 바람과 모래 속에서 풍성한 모나무의 신성한 피의 씨앗을 들어 올렸습니다.\n\n“이 씨앗이 세상에 존재하는 한, 나무의 혈맥은 끊어지지 않을 것입니다.”\n\n그 이후로 또 천 년이 지나, 이 씨앗은 나무의 후손과 함께 영광과 수치, 흥망을 목격하고, 방황과 잃어버림을 겪으며, 사라졌다가 다시 태어났으며, 드디어 거대한 강물이 끈적한 검은 피로 변할 때, 마지막 전승을 완수했습니다.\n그것은 뜨겁고 격렬하며 얽힌 키스였고, 채워지지 않은 갈증과 말로 표현할 수 없는 이별의 슬픔을 담고 있었으며, 따뜻한 심장박동과 함께 새로운 전승자를 감싸주었습니다.\n그 마노 같은 색채와 백옥 같은 광채는 생명의 고동과 함께 검은 종말을 넘어설 것입니다.\n그리고 새로운 세계의 첫 번째 나무 씨앗은 그녀의 축복을 받아 땅에서 솟아올라, 천지를 덮는 거대한 나무로 변할 것입니다."
  },
  Item_48014_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “머릿속의 목소리”를 선택할 수 있습니다.\n\n두 손이 맞잡는 순간, 당신들은 서로의 눈에서 혼란과 궁금증을 보았다.\n불완전한 음부가 여기서 교차하며, 당신들이 이미 과거를 잃어버렸기 때문이다.\n침묵의 악장이 곧 작곡될 것이며, 당신들이 미래로 떨어지기로 결심했기 때문이다."
  },
  Item_48014_Name = {
    Text = "잊혀지지 않은 새벽"
  },
  Item_48014_StoryDesc = {
    Text = "두 손이 맞잡는 순간, 당신들은 서로의 눈에서 혼란과 궁금증을 보았다. \n불완전한 음부가 여기서 교차하며, 당신들이 이미 과거를 잃어버렸기 때문이다. \n침묵의 악장이 곧 작곡될 것이며, 당신들이 미래로 떨어지기로 결심했기 때문이다."
  },
  Item_48113_Desc = {
    Text = "만약 인격이 분열되면 어떻게 하나? 걱정하지 마세요, 미사그는 이미 준비가 되어 있어요! \n수호자의 신체적, 정신적 건강을 보장하기 위한 좋은 방법으로, “다중 치유” 기간 동안 한정적으로 제공됩니다."
  },
  Item_48113_Name = {
    Text = "해리 급성 치료법"
  },
  Item_48114_Desc = {
    Text = "한 번의 치료가 효과가 없으면 어떻게 하나요? 그럼 다시 한 번의 치료를 해보세요! \n수호자의 신체적, 정신적 건강을 보장하기 위한 좋은 처방으로, “다중 치유” 기간 동안 한정 제공됩니다."
  },
  Item_48114_Name = {
    Text = "해리 강화 치료법"
  },
  Item_48115_Desc = {
    Text = "영원히 아버지 신, 《기하학 원론》, 그리고 의사의 처방을 의심하지 마십시오. \n보안관의 신체적, 정신적 건강을 보장하기 위한 좋은 처방으로, “다중 치유” 기간 동안 한정적으로 제공됩니다."
  },
  Item_48115_Name = {
    Text = "해리 회복 치료법"
  },
  Item_48594_Desc = {
    Text = "수호자의 세포 활성을 강화할 수 있으며, 「일일 시험 훈련」에서 무구의 핵, 은심 및 수호자 경험치을 두 배로 획득할 수 있고, 「페이즈 대결」에서는 모든 카드를 사용할 수 있습니다. 본 기 과제에서만 유효합니다.\n초과 활성화된 시냅스 활성화의 부작용은 미지수이며, 한정된 시간과 수량으로 과도한 섭취는 불가능합니다."
  },
  Item_48594_Name = {
    Text = "시냅스 활성 효소"
  },
  Item_48700_Desc = {
    Text = "“욕심이 낳은 죄악”에서 교환에 사용되는 아이템입니다. \n\n작고 둥근 씨앗 하나입니다. \n결국 발아하여 뿌리를 내리고 하늘을 가리는 울창한 나무로 자라날 것입니다."
  },
  Item_48700_Name = {
    Text = "풍요의 종자"
  },
  Item_48828_Desc = {
    Text = "죽음 저항 속성의 명륜입니다."
  },
  Item_48828_Name = {
    Text = "극야와 새벽"
  },
  Item_48828_StoryDesc = {
    Text = "그들은 어둠의 강에서 노를 젓고, 창백하고, 침묵하며, 지쳐있었다. \n 흐릿한 안개가 촉수를 뻗어 그들을 어둠으로 끌어당기며, 끝없는 영야를 떠돌았다. \n\n 후에, 그들은 한 줄기 빛을 보았다. \n 그것은 먼 강가에서 오는 여명으로, 깜빡이며 어두운 영혼을 비출 수 있을 만큼 충분했다. \n 그래서 그들은 빛을 따라, 어둠을 서툴게 헤치고 새벽의 여명 앞에 도달했다. \n 그리고 당신들 앞에도. \n\n 어쩌면 이것은 잠깐의 만남일 뿐이지만, 그들은 힘껏 두 손을 흔들며, 애타게 외쳤다. \n 모든 사람은 신성한 여명 아래에서 목욕하고, 모든 사람은 웃고 있었다. \n 그들은 말했다—— \n 모든 만남의 순간이 축제처럼 소중하길. \n 진정한 마음이 결코 뛰는 것을 멈추지 않길. \n 은열쇠가 앞길을 인도하길."
  },
  Item_48924_Desc = {
    Text = "레무바시 사막에 산일된 감정 입자입니다. 접촉하면 애매한 낮은 신음이 들리는 듯합니다.\n수호자가 조사 이벤트 「욕망의 강」에서의 공명을 높이는 데 사용됩니다."
  },
  Item_48924_Name = {
    Text = "애정의 심장"
  },
  Item_49204_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “유일한 씨앗”을 선택할 수 있습니다.\n\n그녀는 유일한 씨앗을 당신의 입술로 전달해주었습니다.\n혈통의 힘, 계승된 신념, 뛰어난 용기, 그리고 깊은 사랑… 그녀는 모든 것을 당신에게 맡겼습니다."
  },
  Item_49204_Name = {
    Text = "유일한 씨앗"
  },
  Item_49204_StoryDesc = {
    Text = "그녀는 유일한 씨앗을 당신의 입술로 전달해주었다. \n혈통의 힘, 계승된 신념, 뛰어난 용기, 그리고 깊은 사랑… 그녀는 모든 것을 당신에게 맡겼다."
  },
  Item_49263_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「냠냠…… 컵케이크 맛있어……」"
  },
  Item_49263_Name = {
    Text = "은열쇠의 이름으로: 수호자"
  },
  Item_49263_StoryDesc = {
    Text = "제5기 과제 기록"
  },
  Item_49264_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n수호자의 성별에 따라 달라집니다."
  },
  Item_49264_Name = {
    Text = "은열쇠의 이름으로: 수호자"
  },
  Item_49264_StoryDesc = {
    Text = "제5기 과제 기록"
  },
  Item_49265_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「윽…… 충치가 생긴 것 같은데?」"
  },
  Item_49265_Name = {
    Text = "은열쇠의 이름으로: 수호자"
  },
  Item_49265_StoryDesc = {
    Text = "제5기 과제 기록"
  },
  Item_49266_Name = {
    Text = "페이즈 통신·수호자·이런"
  },
  Item_49266_StoryDesc = {Text = "초기"},
  Item_49271_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다. \n「수호자에게 단 한 발짝도 다가오지 못하게 하겠어……!」"
  },
  Item_49271_Name = {
    Text = "은열쇠의 이름으로: 회귀·라모나"
  },
  Item_49271_StoryDesc = {
    Text = "제5기 과제 기록"
  },
  Item_49318_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
  },
  Item_49318_Name = {
    Text = "조사 과정 특전 Ⅶ"
  },
  Item_49464_Desc = {
    Text = "「다섯 개의 깃펜을 묶으면 밀계 필사 속도를 다섯 배로 높일 수 있어요. 수호자도 한번 시도해 보세요!」\n어떤 가련한 깨어남체가 이 꿀팁으로 벌쓰기를 피하다가 실타래비아의 분필에 이마를 정통으로 맞았습니다."
  },
  Item_49464_Name = {
    Text = "비밀 계약 추출집"
  },
  Item_49465_Desc = {
    Text = "“주의를 기울이세요. 성하의 부하 능력과 자가 조절 한계를 주목하고, 흙탕물 양이 비정상적인 원인을 파악하세요.”\n후방부는 수호자들이 성하의 지리적 탐사를 위해 특수 보급품을 제공합니다."
  },
  Item_49465_Name = {
    Text = "수문 관측 지원"
  },
  Item_49466_Desc = {
    Text = "“비밀은 반드시 지하에 있을 거야, 모나무 뿌리가 가장 깊게 퍼진 곳…… 거기에는 반드시 말할 수 없는 무언가가 있을 거야……” \n후방부는 수호자들이 성하의 지형을 조사하기 위해 특수 보급품을 제공했습니다."
  },
  Item_49466_Name = {
    Text = "지층 시추 지원"
  },
  Item_49467_Desc = {
    Text = "“A.F.225년 이후로 우리는 성하의 원천 위치를 더 이상 관측하지 못했습니다.”\n후지부는 수호자에게 성하 지리 탐사를 위한 특수 보급품을 제공합니다."
  },
  Item_49467_Name = {
    Text = "유역 조사 지원"
  },
  Item_49486_Desc = {
    Text = "활동 “욕망의 파도”에서 성취를 완료하여 획득합니다. \n“오세요, 나와 함께 아이를 낳고 영원한 즐거움을 누리세요……”"
  },
  Item_49486_Name = {
    Text = "은열쇠의 이름으로: 타이스"
  },
  Item_49486_StoryDesc = {
    Text = "테이스 게임 방식 이벤트"
  },
  Item_49639_Desc = {
    Text = "「욕망의 번식」에서 교환하는 데 사용하는 아이템.\n\n작고 동그란 씨앗 하나.\n결국 싹을 틔우고, 뿌리를 내리며, 하늘을 가리는 무성한 큰 나무로 성장할 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_49639_Name = {
    Text = "풍요의 종자"
  },
