  Item_49693_Desc = {
    Text = "「욕망의 번식」에서 교환하는 데 사용하는 아이템.\n\n작고 동그란 씨앗 하나.\n결국 싹을 틔우고, 뿌리를 내리며, 하늘을 가리는 무성한 큰 나무로 성장할 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_49693_Name = {
    Text = "풍요의 종자"
  },
  Item_50032_Name = {
    Text = "아래뼈 턱"
  },
  Item_51105_Desc = {
    Text = "“이야기의 마법·복제” 이벤트에서 “스케줄 미스터리”를 클리어하거나 이벤트 업적을 완료한 후 획득하는, “마법 스크립트 상점”에서 교환에 사용되는 아이템입니다.\n영감은 순식간에 사라지며, 밤하늘을 가로지르는 유성처럼 보입니다. 다르다면, 당신은 그것을 영원히 남길 수 있는 방법을 가지고 있습니다."
  },
  Item_51105_Name = {
    Text = "흩날리는 영감"
  },
  Item_51265_Desc = {
    Text = "「이야기의 마법·복각」 활동에서 「대본 미스터리」를 클리어하거나 활동 업적을 완료한 후 획득하며, 「마법 대본 상점」에서 교환하는 데 사용하는 아이템.\n영감은 순식간에 사라집니다, 밤하늘을 가로질러 날아가는 유성처럼. 다른 점은, 당신에게는 그것을 영원히 남길 방법이 있다는 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_51265_Name = {
    Text = "흩날리는 영감"
  },
  Item_51266_Desc = {
