  },
  Item_51295_Desc = {
    Text = "「이야기의 마법·복각」 활동에서 「대본 미스터리」를 클리어하거나 활동 업적을 완료한 후 획득하며, 「마법 대본 상점」에서 교환하는 데 사용하는 아이템.\n영감은 순식간에 사라집니다, 밤하늘을 가로질러 날아가는 유성처럼. 다른 점은, 당신에게는 그것을 영원히 남길 방법이 있다는 것입니다.\n\n최소 {s1}개 드롭"
  },
