  },
  Item_51318_Name = {
    Text = "흩날리는 영감"
  },
  Item_51840_Desc = {
    Text = "“기계장치의 신” 미스틱 트랜스크립트 시 부속성 하나를 잠글 수 있으며, 재료 치환에서 “천면인장”으로 치환할 수 있습니다. \n\n손상된 미스터리 파편으로, 어렵게 조합하여 컬렉션 추가된 상태입니다."
  },
  Item_51840_Name = {
    Text = "기계장치의 신·잔본"
  },
  Item_51841_Desc = {
    Text = "“진홍빛 심동” 미스틱 트랜스크립트로 전사 시 부속성 하나를 잠글 수 있으며, 재료 치환에서 “천면인장”으로 치환할 수도 있습니다.\n\n손상된 미스터리 파편은 간신히 이어붙인 후 스크랩북에 컬렉션 추가로 보관됩니다."
  },
  Item_51841_Name = {
    Text = "진홍빛 심동·잔본"
  },
  Item_51842_Desc = {
