  },
  Item_52037_Desc = {
    Text = "“영수단”에서 교환을 위해 사용되는 아이템입니다. \n당신의 골수를 바치세요, 제사장. 모든 소원은 신국이 들어줄 것입니다."
  },
  Item_52037_Name = {
    Text = "제사자의 골수"
  },
  Item_52038_Desc = {
    Text = "“고릴라:red:혈 제단”에서 교환에 사용되는 아이템입니다. \n당신의 피를 바치세요, 제사장. 모든 죄악은 신국이 징벌할 것입니다."
  },
  Item_52038_Name = {
    Text = "제사자의 피"
  },
  Item_52039_Desc = {
    Text = "“영누이 제단”에서 교환을 위해 사용되는 아이템입니다. \n당신의 눈물을 바치세요, 제사하는 사람. 모든 고통은 신국이 갚아줄 것입니다."
  },
  Item_52039_Name = {
    Text = "제사자의 눈물"
  },
  Item_52069_Desc = {
    Text = "레무리아에 흩어진 감정 입자로, 만질 때 누군가의 기도와 흐느낌이 들리는 듯하다.\n활동 콘텐츠「신국의 강림」에서 수호자의 공명을 높이는 데 사용된다.\n한정 활동「심연의 제사」에서 업적 보상으로 획득할 수 있다."
  },
  Item_52069_Name = {
    Text = "신앙의 심장"
  },
  Item_52070_Desc = {
