    Text = "「고릴라의 피로 물든 제단」에서 교환하는 데 사용하는 아이템.\n당신의 피를 바치세요, 제사를 드리는 자여. 모든 죄악을, 신국이 벌할 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_52174_Name = {
    Text = "제사자의 피"
  },
  Item_52175_Desc = {
    Text = "「고릴라의 피로 물든 제단」에서 교환하는 데 사용하는 아이템.\n당신의 피를 바치세요, 제사를 드리는 자여. 모든 죄악을, 신국이 벌할 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_52175_Name = {
    Text = "제사자의 피"
  },
  Item_52176_Desc = {
    Text = "「영수 제단」에서 교환하는 데 사용하는 아이템.\n당신의 골수를 바치세요, 제사를 드리는 자여. 모든 소원을, 신국이 허락할 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_52176_Name = {
    Text = "제사자의 골수"
  },
  Item_52177_Desc = {
    Text = "「영수 제단」에서 교환하는 데 사용하는 아이템.\n당신의 골수를 바치세요, 제사를 드리는 자여. 모든 소원을, 신국이 허락할 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_52177_Name = {
    Text = "제사자의 골수"
  },
  Item_52178_Desc = {
    Text = "「형루 제단」에서 교환하는 데 사용하는 아이템.\n당신의 눈물을 바치세요, 제사를 드리는 자여. 모든 고난을, 신국이 보상할 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_52178_Name = {
    Text = "제사자의 눈물"
  },
  Item_52304_Desc = {
    Text = "「주간 한 번으로 제한됩니다. 과다 공급은 건강에 부정적인 영향을 미칠 수 있으므로 당신의 안전에 대해 책임을 져야 합니다.」\n의료실타래에서 시르비아는 고민스럽게 흩어진 머리카락 끝을 쓸어 넘겼다."
  },
  Item_52304_Name = {
    Text = "주간 광휘 공급"
  },
  Item_52305_Desc = {
    Text = "그 깊고 어두운 곳에 깊은 잠한 왕의 탄생은 신식의 바다 전체를 왜곡할 것이다. \n이질적인 꿈의 침식에 저항하기 위한 의식은 “심연의 제사” 기간 한정으로 이용 가능합니다."
  },
  Item_52305_Name = {
    Text = "신왕 탄생 의식"
  },
  Item_52306_Desc = {
    Text = "깊은 바다에서 넘쳐흐르는 물결이 의식의 경계를 충격합니다. \n이상한 꿈의 침식을 막기 위한 의식은 “심연의 제사” 기간 동안 한정 제공됩니다."
  },
  Item_52306_Name = {
    Text = "침식 방어 의식"
  },
  Item_52307_Desc = {
    Text = "이몽시계의 천재도 정신 공명을 통해 수호자의 영지를 방해합니다. \n 이몽 침식에 저항하기 위한 의식은 “심연의 제사” 기간 동안 한정 제공됩니다."
  },
  Item_52307_Name = {
    Text = "재앙 경계 의식"
  },
  Item_53730_Desc = {
    Text = "「잘 돌아왔어요.」"
  },
  Item_53730_Name = {
    Text = "복학 초청"
  },
  Item_53746_Desc = {
    Text = "“금홍 축제”에서 교환에 사용되는 아이템입니다. \n\n소렐 부인의 수집품인 깃털 선풍기입니다. 주식 시세를 예측할 수 있다고 믿는 이들도 있습니다."
  },
  Item_53746_Name = {
    Text = "영혼의 깃털 부채"
  },
  Item_53766_Desc = {
    Text = "활동 “장미의 책”에서 업적을 완료하여 획득합니다. \n“이것이 권력의 향기인가? 나는 매우 만족스럽다.”"
  },
  Item_53766_Name = {
    Text = "은열쇠의 이름으로: 소렐"
  },
  Item_53766_StoryDesc = {
    Text = "소렐 플레이 이벤트"
  },
  Item_53767_Desc = {
    Text = "크리티컬 확률 속성의 명륜입니다."
  },
  Item_53767_Name = {
    Text = "무수한 총애의 시선"
  },
  Item_53767_StoryDesc = {
    Text = "그는 무한한 혼돈 속에서 기어 다니며, 가끔 세상에 엎드린 생명체들에게 한 줄기 시선을 던진다. \n\n 아직 눈에 들어오는 존재들, 예를 들어 소렐에게, 그는 그들에게 거부할 수 없는 “계약 조건”을 제시한다. \n 거칠고 따분한 존재들은 그의 육체가 벗겨지고, 다시는 눈물을 흘릴 수 없는 눈만 남는다. \n 이 눈들은 “받은 은총의 자”라 불린다. \n\n 그들은 동굴 안에서 희미하게 빛나고 어두워지며, 희망을 품고 있으면서도 절망으로 가득 차, 그의 소환을 기다린다. \n 그러나 천 년이 지나고 만 년이 지나도, 받은 은총의 자들은 여전히 어두운 구석에 잊혀져 있다. \n\n “그럼… 여러분은 어떤 이유로 남겨진 것일까요? 여러분의 사명은 무엇인가요?” \n “우리는 기다리고 있습니다.” \n “무엇을 기다리나요?” \n “그저 기다릴 뿐입니다.” \n “고통을 느끼나요?” \n “정반대입니다. 어른의 사랑이 우리 몸을 가득 채우고 있습니다. 이것이 우리가 할 수 있는 유일한 일이기 때문입니다.” \n “이 점을 이해해야 진정한 신도가 될 수 있습니다.”"
  },
  Item_53871_Desc = {
    Text = "「금홍 축전」에서 교환하는 데 사용하는 아이템.\n\n소렐 부인이 소장한 깃털 부채. 주식 흐름을 예측할 수 있다고 믿는 이들이 있다.\n\n최소 {s1}개 드롭"
  },
  Item_53871_Name = {
    Text = "영혼의 깃털 부채"
  },
