    Text = "영혼의 깃털 부채"
  },
  Item_53924_Desc = {
    Text = "「금홍 축전」에서 교환하는 데 사용하는 아이템.\n\n소렐 부인이 소장한 깃털 부채. 주식 흐름을 예측할 수 있다고 믿는 이들이 있다.\n\n최소 {s1}개 드롭"
  },
  Item_53924_Name = {
    Text = "영혼의 깃털 부채"
  },
  Item_54015_Desc = {
    Text = "나비목이 외로움, 사랑, 절망으로 죽어가고 있습니다. \n유기 형태의 미스터리 세트 부품이 랜덤으로 드롭됩니다."
  },
  Item_54015_Name = {
    Text = "유기 형태"
  },
  Item_54016_Desc = {
    Text = "회전하고, 그런 다음 잊어버리기——이것이 그녀의 생명의 전부이다. \n무작위로 36실타래의 고리 미스터리 세트 부품을 드롭한다."
  },
  Item_54016_Name = {
    Text = "36호실타래의 고리"
  },
  Item_54017_Desc = {
    Text = "필연적인, 우연적인. \n유한한, 무한한. \n랜덤 드롭으로 이율배반 미스터리 세트 부품 획득."
  },
  Item_54017_Name = {
    Text = "이율배반"
  },
  Item_54018_Desc = {
    Text = "천 년 전, 다섯 분은 사십 온스의 가는 모래였다. \n약재의 꿈 미스터리 세트 부품이 랜덤으로 드롭됩니다."
  },
  Item_54018_Name = {
    Text = "약재의 꿈"
  },
  Item_54032_Desc = {
    Text = "고위 인사의 장례식에서 연주된 미사곡으로, 생자가 망자에 대한 애도와 추모를 표현하며, 죽음이 종료가 아니라 영원한 생명으로의 시작이라는 믿음을 담고 있습니다. \n“장미 책과 함께” 기간 동안 한정 제공됩니다."
  },
  Item_54032_Name = {
    Text = "성제 애도 미사"
  },
  Item_54033_Desc = {
    Text = "고위 인사의 장례식에서 연주된 미사곡, 그녀의 영광과 깃발은 영원히 남아있습니다. \n“장미 책과 함께” 기간 동안 한정 제공됩니다."
  },
  Item_54033_Name = {
    Text = "명정 찬미 미사"
  },
  Item_54034_Desc = {
    Text = "고위 인사의 장례식에서 연주되는 미사곡으로, 고인의 영혼을 위로하며 안식을 기원합니다. \n“장미 책과 함께” 기간 동안 한정 제공됩니다."
  },
  Item_54034_Name = {
    Text = "축복 안식 미사"
  },
  Item_54104_Desc = {
    Text = "깨어남체 「하멜른」 획득 후 해제"
  },
  Item_54104_Name = {Text = "하멜른"},
  Item_54105_Desc = {
    Text = "손패의 카드를 연속적으로 사용하여 폭발적으로 전투 능력을 높이고, 최대 손패 매수 증가를 통해 은열쇠 에너지를 축적하여 유연하게 전술을 선택할 수 있습니다."
  },
  Item_54105_Name = {
    Text = "감춰진 수레바퀴"
  },
  Item_54105_StoryDesc = {
    Text = "한 사람이 모든 과거와 미래를 알게 될 때, 그를 기다리는 것은 전지전능의 기쁨이 아니라 끝없는 연민과 절망이다. \n 그녀의 두 눈은 만사 만물 뒤에 있는 실타래을 볼 수 있다. 실타래의 한 쪽은 과거에 연결되어 있고, 다른 쪽은 미래에 연결되어 있다. \n 그 실타래은 사람들에게 운명이라고 불린다. \n 그녀는 그녀 곁에 있는 사람들을 어떻게 바라볼까? \n 사람들은 착하고 인정이 많으며, 사람들은 자만하고 의심이 많다. \n 하지만 그 사람들의 운명과 인류의 운명은 매번 만남의 시작에서 이미 정해져 있다. \n 그녀는 반드시 그들을 사랑하고 있어야 한다. 그렇지 않다면 왜 한 번 또 한 번 손을 내밀어 화종을 주겠는가? \n 그녀는 반드시 그들을 기대하고 있어야 한다. 그렇지 않다면 왜 파멸 속에서 굳건히 윤회의 그림자로 걸어가겠는가? \n 사랑으로 인해 그녀는 슬픔을 품고 있다. \n 기대 때문에 그녀는 자주 실타래망한다. \n 그녀는 검은 진흙탕에 깊이 빠져 수많은 검은 실타래 속에서 끊임없이 정리하고 있다. 귀찮을 정도로. \n 운명의 룰렛은 한 번 또 한 번 돌아간다. \n 그녀는 탐욕의 불꽃이 하늘을 휩쓸고 가는 것을 본다. \n 그녀는 맹목적인 편집증이 자기 파멸로 나아가는 것을 본다. \n 그녀는 미친 망상이 파멸을 가속화하는 것을 본다. \n 무질서한 혼돈은 항상 느리게 다가온다. \n 희망과 절망은 헛되이 돌고, 끝이 없다. \n 그녀가 어둠 속에서 한 순간의 별빛을 보게 될 때까지. \n 그 빛은 약하지만 그녀는 어둠 속에 너무 오랫동안 있었다. \n 똑바로 바라본 그 순간, 그녀는 눈물을 흘리기까지 했다. \n"
  },
  Item_54106_Name = {Text = "타비"},
  Item_54107_Name = {Text = "하멜른"},
  Item_54108_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 타비를 획득할 때 전환하여 타비의 기령을 활성화하는 데 사용됩니다."
  },
  Item_54108_Name = {
    Text = "파편 · 타비"
  },
  Item_54108_StoryDesc = {
    Text = "중복으로 타비를 획득할 때 전환하여 획득하며, 타비의 기령을 활성화하는 데 사용됩니다."
  },
  Item_54109_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n혈쇄·히로를 반복 획득 시 전환하여 혈쇄·히로의 기령을 활성화하는 데 사용됩니다."
  },
  Item_54109_Name = {
    Text = "파편 · 혈쇄·히로"
  },
  Item_54109_StoryDesc = {
    Text = "중복 획득 시 혈쇄·히로를 전환하여 획득하며, 혈쇄·히로의 기령을 활성화하는 데 사용됩니다."
  },
  Item_54110_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n하멜른을 반복 획득할 때 전환하여 하멜른의 기령을 활성화하는 데 사용됩니다."
  },
  Item_54110_Name = {
    Text = "파편 · 하멜른"
  },
  Item_54110_StoryDesc = {
    Text = "함린을 중복 획득 시 전환하여 사용 가능하며, 이를 통해 함린의 기령을 활성화할 수 있습니다."
  },
  Item_54111_Desc = {
    Text = "깨어남체 「타비」 획득 후 해제"
  },
  Item_54111_Name = {Text = "타비"},
  Item_54112_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 웨이크업 바디는 정신 능력을 영구적으로 강화시킵니다.\n중복 획득 시 융해·돌으로 전환되어 융해·돌의 기령을 활성화하는 데 사용됩니다."
  },
  Item_54112_Name = {
    Text = "파편 · 융해·돌"
  },
  Item_54112_StoryDesc = {
    Text = "중복 획득 시 융해·돌으로 전환됩니다. 융해·돌의 기령을 활성화하는 데 사용됩니다."
  },
  Item_54113_Desc = {
    Text = "광기 폭발을 사용한 후 대량의 광기를 환원해 광기 순환을 가속하고, 추가로 중독 및 치료 능력을 향상시킬 수 있습니다."
  },
  Item_54113_Name = {
    Text = "허무로 추락하는 인형"
  },
  Item_54113_StoryDesc = {
    Text = "사람들은 항상 자신의 척도로 경계를 규정하고 기호를 정하려고 한다.\n세상은 인류의 육체 안에 갇혀 있어 얼마나 좁고, 어리석고, 슬픈가.\n그녀는 일찍이 육체를 버렸지만, 여전히 진정한 경계에 닿지 못했다.\n지식의 강은 혼란스럽고 끝이 없으며, 검은 공허가 다시 그녀를 추격하고 있다.\n그녀는 조용히 그것과 눈을 마주쳤다. 만약 어떤 유형의 면도 세상의 전모를 엿볼 수 없다면, 공허의 뒤에는 진정한 답이 있을까?\n그녀는 자신의 생명으로 이 생에서 가장 미친 배팅을 했다.\n그녀는 마침내 종말을 보았다.\n진실타래의 대문이 활짝 열리고, 세상의 모습이 순식간에 뒤집혔다.\n그렇게, 그렇게.\n그녀는 모든 사람이 이 공허의 진실타래을 보도록 간절히 원하며, 헛된 투쟁에서 해방되기를 바랐다.\n한때 그녀는 물결의 정점에 서서 세상을 이끌었다.\n이제 그녀는 여전히 양치기의 가죽 채찍을 휘두르며, 경쾌한 발걸음으로 세상을 심연으로 인도하고 있다.\n사람들은 두려워하며 그녀를 내쫓고, 그녀를 악의 광인으로 여겼다.\n참 이상하다, 그녀는 생각했다.\n하지만 내 눈 속의 너희들도 그렇게 보인다.\n"
  },
  Item_54114_Desc = {
    Text = "피해를 가함과 동시에 더 많은 은열쇠 에너지를 획득하고, 은열쇠를 발동할 때 크리티컬 피해가 영구적으로 증가하며, 유연한 「은열쇠의 새벽빛」이 더 많은 선택지를 제공합니다."
  },
  Item_54114_Name = {
    Text = "영원한 진혼곡"
  },
  Item_54114_StoryDesc = {
    Text = "그는 항상 자신을 혹독하게 책망했으며, 그 혹독함으로 모든 동료들을 밀어냈다. 그는 음악의 극치를 추구하며 영원히 혼자 걷게 될 것이라고 생각했다. \n 높은 곳은 춥기만 하니, 그는 이 운명을 받아들였다. \n 그러다가 그는 그 사람의 연주를 들었다. \n 그 사람의 연주는 완벽과는 거리가 멀었고, 지나치게 즉흥적인 음악은 그 사람 자신과 같았다. 가끔 악보와 어긋나는 실타래수가 나타나기도 했고, 심지어 특정 부분을 갑자기 잊어버리기도 했다. 이때 그의 두 손은 항상 즉흥적으로 기발하고 생동감 넘치는 음을 만들어내어, 관객의 놀라움과 찬사를 얻었다. \n 그는 그 사람을 바라보며, 마치 음악의 정령이 음표 사이에서 자유롭게 놀고 있는 듯한 느낌을 받았다. \n 이것이 아버지가 말한 천재성일 것이다. 정말로 그는 모든 사람과 마찬가지로 깊이 매료되었지만, 그의 걸음을 바꿀 수는 없었다. \n 그는 그렇게 평범하고 어리석은 사람이었기에, 힘들게 포장된 길 위에서만 걸을 수 있었다. \n 모든 사람이 그 사람을 따라갔고, 그는 점점 멀어졌다. \n 그는 그와 가까워지기를 갈망했지만, 연주 외에는 아무것도 할 수 없었다. \n 어떻게 그와 대화할 수 있을까, 어떤 악보를 사용해야 그의 마음을 얻을 수 있을까. \n 그는 악보를 만들며, 마치 시작 인사를 고민하듯 했다. 그러나 그는 더 이상 입을 열 기회를 잃었다. \n 깊은 후회가 그를 잠식했고, 모든 것이 갑자기 의미를 잃었다. \n 눈에는 떠나간 영혼에게 보낼 미완성의 편지만 남아 있었다. \n 그는 심혈을 기울여 결국 그 악보 앞에 쓰러졌고, 꿈속에서도 그 길 끝의 빛을 만지지 못했다. \n 만약 내가 그 길의 끝에 도달할 수 없다면, 내 평생의 집착은 무엇을 위한 것인가? \n 먼 곳에서 피리 소리가 그 빛에서 흘러나와, 그의 질문으로 가득 찬 영혼을 위로했다. \n 그는 어렴풋이 그 피리를 집어 들며, 자신의 진정한 사명을 알게 되었다. \n 그의 영원히 끝없는 연주로 영원한 평화를 가져오는 것이었다. \n"
  },
  Item_54115_Desc = {
    Text = "소유자가 가하는 기본 피해를 대폭 증가시키는 동시에, 미쳐날뛰는 폭발을 방출해 자신의 카드를 안정적으로 추출하고 크리티컬 데미지를 증가시킬 수 있습니다."
  },
  Item_54115_Name = {
    Text = "진홍빛으로 가라앉다"
  },
  Item_54115_StoryDesc = {
    Text = "그녀는 한밤중에 왜 이 끝없는 고통을 견뎌야 하는지 만 번도 더 질문했다.\n누구도 대답하지 않았다.\n밀담이 거칠어진 목소리를 지나 조각으로 변해, 어떤 신의 귀에도 전해지지 않았다.\n그녀의 고통은 오래도록 사라지지 않았고, 점차 고름으로 발효되어 점점 더 짙은 증오로 변했다.\n어느 날 갑자기, 그녀는 주변 사람들의 몸에서 검은 액체가 스며나오기 시작한 것을 발견했다. 그것은 자신에게서 흐르는 피와 너무나 닮았다.\n그들은 곧 미치게 변했으며, 자신과 같은 모습이었다.\n아마도 그것이 그들의 고통이었고, 그녀는 차가운 눈으로 지켜보며 미세한 쾌감을 느꼈다.\n하지만 만약 그것이 고통이라면, 자신은 이미 검은색에 잠식당하지 않았겠는가.\n그녀는 남겨진 검은색에 가까이 다가갔지만, 의외로 자유를 얻었다.\n자유는 그녀에게 해방을 가져다주지 않았고, 그녀는 지옥에서 천 년을 유배당한 악귀처럼, 마음속의 소원은 이미 증오에 의해 부식되어 사라졌다.\n그녀의 몸은 족쇄에 박혔고, 그녀의 영혼은 납덩이로 가득 차 있었다.\n오직 그 절규의 외침만이 그녀의 무거운 영혼을 씻어주어, 그녀가 마음껏 숨 쉴 수 있게 해주었다.\n자, 와서 내가 맛본 것을 맛보아라, 너를 나로 만들어라.\n그녀는 빨간색이 얼마나 아름다운 색인지 깨달았다.\n그녀는 마침내 고통에 이유가 없다는 것을 이해했다.\n스스로 마시든지, 남을 초대하든지.\n오늘 밤 그녀는 쓴 술을 가득 채우고, 온 마을을 초대했다.\n"
  },
  Item_54123_Desc = {
