  },
  Item_54136_Desc = {
    Text = "“너의 고통은 정말 맛있어.”"
  },
  Item_54136_EmojiName = {
    Text = "고통을 맛보다"
  },
  Item_54136_Name = {
    Text = "페이즈 통신: 알비노·고통을 맛보다"
  },
  Item_54136_StoryDesc = {
    Text = "제11기 과제 기록"
  },
  Item_54470_Desc = {
    Text = "활동 '만상문'에서 성취를 완료하여 획득합니다. \n“푸두푸두푸두… 은 열쇠를 블랙풀에 버린 건 너야?”"
  },
  Item_54470_Name = {
    Text = "은열쇠의 이름으로: 타비"
  },
  Item_54470_StoryDesc = {
    Text = "타비 플레이 이벤트"
  },
  Item_54471_Desc = {
    Text = "“フン, 지갑을 잘 챙기세요. 한 번 성공할 수 있으면 두 번째도 가능해요. 아직 아무도 나를 막을 수 없어, 렌티니언 동구 최고의 도둑이니까!”"
  },
  Item_54471_Name = {
    Text = "은열쇠의 이름으로: 젠킨"
  },
  Item_54471_StoryDesc = {
    Text = "Steam 예약 이벤트"
  },
  Item_54472_Desc = {
    Text = "“아아……오늘도 바다가 눈부시네요……네? 제가 내는 빛이 반사된 거라고요?”"
  },
  Item_54472_Name = {
    Text = "은열쇠의 이름으로: 파로스"
  },
  Item_54472_StoryDesc = {
    Text = "제3기 과제 기록"
  },
  Item_54473_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「흑흑…… 아이기스는 바빠서 못 한단 말이에요……」"
  },
  Item_54473_Name = {
    Text = "은열쇠의 이름으로: 아이기스"
