  Item_54497_StoryDesc = {
    Text = "제12기 과제 기록"
  },
  Item_54578_Desc = {
    Text = "수호자 경험을 얻을 때, 추가로 20%의 수호자 경험을 얻습니다. 여러 효과가 있을 경우 가장 높은 값을 취하며, 중복 적용할 수 없습니다.\n\n《원액의 정신 영향 보고서》에 따르면, 원액 추출 작업에 참여한 개인은 작업이 끝난 후 일정 정도의 정신력, 지능 등의 강화가 나타납니다. 추출 시간이 길어질수록 추출된 원액의 양이 많아지고, 효과가 더욱 뚜렷해집니다.\n이산된 입자에 불과하더라도, 원액에 담긴 힘은 여전히 무시할 수 없습니다."
  },
  Item_54578_Name = {
    Text = "지고의 찬양·Ⅱ"
  },
  Item_54579_Desc = {
    Text = "극소수의 수호자만이 가질 수 있는 신분 표시입니다.\n원액 추출 시, 미세한 입자들이 흩날리며 날아다닙니다. 이유는 알 수 없지만, 이들은 금속 물체를 특히 좋아해 수호자가 착용한 신분 표시가 부드러운 은백색으로 물들게 됩니다.\n이러한 인장이 특별한 효능을 가지고 있다고 전해집니다."
  },
  Item_54579_Name = {
    Text = "은백 척도"
  },
  Item_54579_StoryDesc = {
    Text = "누적 충전 보상: 프로필 프레임"
  },
  Item_54580_Desc = {
    Text = "비밀 지키는 경험을 얻을 때, 추가로 30%의 비밀 지키는 경험을 획득합니다. 여러 효과가 있을 경우 최고 값을 취하며, 중첩할 수 없습니다.\n\n《원액의 정신 영향 보고서》에 따르면, 원액 추출 작업에 참여한 개인은 작업 종료 후 일정 정도의 정력, 지능 등의 강화가 나타납니다. 추출 시간이 길어질수록 추출된 원액의 양이 많아지고, 효과가 더욱 뚜렷해집니다.\n단순히 이산된 입자일지라도, 원액에 담긴 힘은 결코 무시할 수 없습니다."
  },
  Item_54580_Name = {
    Text = "지고의 찬양·Ⅲ"
  },
  Item_54581_Desc = {
    Text = "수호자 경험을 얻을 때, 추가로 10%의 수호자 경험을 얻습니다. 여러 효과가 있을 경우 최고 값을 취하며, 중첩할 수 없습니다.\n\n《원액의 정신 영향 보고서》에 따르면, 원액 추출 작업에 참여하는 개인은 작업이 끝난 후 일정 정도의 정력, 지력 등의 강화가 나타납니다. 추출 시간이 길어질수록 추출된 원액의 양이 많아지고, 효과가 더 뚜렷해집니다.\n단지 이산된 입자일지라도, 원액에 함유된 힘은 결코 가볍게 볼 수 없습니다."
