  },
  Item_54595_Desc = {
    Text = "수호자 경험을 얻을 때, 추가로 60%의 수호자 경험을 얻습니다. 여러 효과가 있을 경우 최고 값을 취하며, 중첩할 수 없습니다.\n\n《원액의 정신 영향 보고서》에 따르면, 원액 추출 작업에 참여한 개인은 작업 종료 후 일정 정도의 에너지, 지능 등의 강화가 나타납니다. 추출 시간이 길어질수록 추출된 원액의 양이 많아지고 효과가 더욱 뚜렷해집니다.\n심지어 이산된 입자일지라도, 원액에 내포된 힘은 여전히 간과할 수 없습니다."
  },
  Item_54595_Name = {
    Text = "지고의 찬양·Ⅴ"
  },
  Item_55126_Desc = {
    Text = "후회는 계개의 꽃말입니다. \n정원의 재에서 발견된 시문으로, ‘계개화원’에서 물자를 교환하는 데 사용됩니다."
  },
  Item_55126_Name = {
    Text = "유감의 시문"
  },
  Item_55127_Desc = {
    Text = "환희는 장미의 꽃말입니다. \n정원의 재에서 발견된 시, “장미 정원”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_55127_Name = {
    Text = "환희의 시문"
  },
  Item_55128_Desc = {
    Text = "감상적은 아이리스의 꽃말입니다. \n정원의 재에서 발견된 시, “아이리스 정원”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_55128_Name = {
    Text = "애상의 시문"
  },
  Item_55129_Desc = {
    Text = "불길이 꺼지고, 온 땅에 재가 남았습니다, 한때 장미가 가득 피어 있던 그곳에.\n수호자의 활동 플레이 「정원의 옛 이야기」와 특수 파견 기록 「장미의 안식처」에서의 공명을 높이는 데 사용합니다.\n한정 활동 「봄이 쇠락하기 전에」에서 업적 보상을 완료하여 획득할 수 있습니다."
  },
  Item_55129_Name = {
    Text = "회진의 심장"
  },
