  },
  Item_55303_Name = {
    Text = "유감의 시문"
  },
  Item_55304_Desc = {
    Text = "환희는 장미의 꽃말입니다. \n정원의 재에서 발견된 시, 「장미 정원」에서 물자를 교환하는 데 사용됩니다. \n\n최소 720개가 드롭됩니다."
  },
  Item_55304_Name = {
    Text = "환희의 시문"
  },
  Item_55305_Desc = {
    Text = "슬픔은 붓꽃의 꽃말이다.\n정원 유적에서 발견된 시문은「붓꽃 화원」에서 자원을 교환하는 데 사용된다.\n\n최소 1014개 떨어진다"
  },
  Item_55305_Name = {
    Text = "애상의 시문"
  },
  Item_55471_Desc = {
    Text = "필요해요 시를 읊어야만 열리는 신비한 상자입니다. \n꽃의 꿈을 설명하면 장미 한 다발을 선물합니다. \n“봄이 시들기 전에” 기간 동안 한정 판매됩니다."
  },
  Item_55471_Name = {
    Text = "꽃과 시의 꿈"
  },
  Item_55472_Desc = {
    Text = "필요해요 시를 암송해야만 시작되는 신비한 상자입니다. \n의상이 적절할 경우, 진실타래을 보여줍니다. \n“봄이 시들기 전에” 기간 동안 한정 판매됩니다."
  },
  Item_55472_Name = {
    Text = "의미와 시의 꿈"
  },
  Item_55473_Desc = {
    Text = "필요해요 시를 읊어야만 시작되는 신비한 상자입니다. \n그것에게 당신의 과거를 설명하면, 회상 하나를 선물로 드립니다. \n“봄이 시들기 전에” 기간 동안 제한적으로 공급됩니다."
  },
  Item_55473_Name = {
    Text = "마음과 시의 꿈"
  },
  Item_55891_Desc = {
    Text = "그는 장꿈에서 영성이 풍부한 이들에게 신의 계시를 내립니다: 금기의 학식은 허영심 많은 자들의 저주이며, 무지는 어리석은 자들에게 주어진 은혜입니다. \n “신왕 부활” 기간 동안 한정 판매됩니다."
  },
  Item_55891_Name = {
    Text = "권태의 몽마 신상"
  },
  Item_55892_Desc = {
    Text = "그는 장꿈에서 영성이 풍부한 이들에게 신의 계시를 내린다: 신성은 결코 뜻을 남기지 않았으며, 기도와 소원은 모두 헛된 것이다.\n“신왕 부활” 기간 동안 한정 판매됩니다."
  },
  Item_55892_Name = {
    Text = "태만의 몽마 신상"
  },
  Item_55893_Desc = {
    Text = "그는 장꿈에서 영적인 힘을 가진 이들에게 신의 계시를 내렸다: 그는 별들로부터 왔으며, 그의 나라는 결국 떠오르리라. \n “신왕 부활” 기간에 한정 제공됩니다."
  },
  Item_55893_Name = {
    Text = "섬망의 몽마 신상"
  },
  Item_55894_Desc = {
    Text = "만약 인격이 분열되면 어떻게 하나? 걱정하지 마세요, 미사그는 이미 준비가 되어 있어요! \n수호자의 신체적, 정신적 건강을 보장하기 위한 좋은 방법으로, “다중 치유” 기간 동안 한정적으로 제공됩니다."
  },
  Item_55894_Name = {
    Text = "해리 급성 치료법"
  },
  Item_55895_Desc = {
    Text = "한 번의 치료가 효과가 없으면 어떻게 하나요? 그럼 다시 한 번의 치료를 해보세요! \n수호자의 신체적, 정신적 건강을 보장하기 위한 좋은 처방으로, “다중 치유” 기간 동안 한정 제공됩니다."
  },
  Item_55895_Name = {
    Text = "해리 강화 치료법"
  },
  Item_55896_Desc = {
    Text = "영원히 아버지 신, 《기하학 원론》, 그리고 의사의 처방을 의심하지 마십시오. \n보안관의 신체적, 정신적 건강을 보장하기 위한 좋은 처방으로, “다중 치유” 기간 동안 한정적으로 제공됩니다."
  },
  Item_55896_Name = {
    Text = "해리 회복 치료법"
  },
  Item_55897_Desc = {
    Text = "고난받은 영혼이여, 당신은 보상을 받을 것입니다. 자비로운 주교가 아버지 신의 축복을 내려줄 것입니다. \n“영혼의 목자·복제” 기간 동안 한정 제공됩니다."
  },
  Item_55897_Name = {
    Text = "미사 후의 축복"
  },
  Item_55898_Desc = {
    Text = "고난받는 영혼이여, 절대로 희망을 잃지 마세요. 자비로운 주교가 당신을 위해 아버지 신께 기도를 올릴 것입니다. \n「영혼의 목자·복제」 기간 동안 한정 제공됩니다."
  },
  Item_55898_Name = {
    Text = "미사 중의 기도"
  },
  Item_55899_Desc = {
    Text = "고난을 겪는 영혼이여, 혼란스러움이 필요하지 않아요. 자비로운 주님의 교회가 당신에게 방향을 제시할 것입니다. \n“영혼의 목자·복제” 기간 동안 한정 제공됩니다."
  },
  Item_55899_Name = {
    Text = "미사 전의 인도"
  },
  Item_55900_Desc = {
    Text = "당신은 무수한 우주에서 무수한 외침을 듣습니다. 그들은 당신의 이름을 부르고 있습니다. \n당신은 양손을 꽉 쥐고 크게 응답합니다. \n「만상문」 기간 동안 한정 제공됩니다."
  },
  Item_55900_Name = {
    Text = "반향의 문"
  },
  Item_55901_Desc = {
    Text = "허구적인 문살이 당신에게 다가오고, 무수한 우주가 부서지며 다시 시작됩니다.\n문살의 빛이 반짝이고, 당신은 그것이 당신을 선택했음을 압니다. 그것은 모든 것을 당신에게 맡깁니다.\n「만상문」 기간 동안 한정 제공됩니다."
  },
  Item_55901_Name = {
    Text = "운명의 문"
  },
  Item_55902_Desc = {
    Text = "당신은 무수한 우주에서 무수한 사람들을 봅니다. 그들은 모두 당신과 관련이 있습니다. \n 무수한 손이 당신에게 다가오고, 그들은 앞다투어 당신을 높이 들어올립니다. \n 「만상문」 기간 동안 한정 제공됩니다."
  },
  Item_55902_Name = {
    Text = "환상의 문"
  },
  Item_55904_Desc = {
    Text = "교향곡의 마지막 장, 곡의 주제가 여기서 결정됩니다. 희망에 찬 승리의 노래를 감상해 주세요. \n 「무형의 교향곡」 기간 동안 한정 제공됩니다."
  },
  Item_55904_Name = {
    Text = "론도 악보"
  },
  Item_55905_Desc = {
    Text = "엘워스 산 정상에서 새로 태어난 두루미꽃의 씨앗, 동토에서 자란 작은 야초가 활기차게 자라고 있습니다. \n“눈이 녹을 때”기간 동안 한정 제공됩니다."
  },
  Item_55905_Name = {
    Text = "설산 민들레 씨앗"
  },
  Item_55906_Desc = {
    Text = "엘워스 산 정상에서 새로 나온 상록수의 씨앗, 강인한 묘목은 결국 바람과 서리, 비와 눈을 넘어 거대한 나무로 자라날 것입니다. \n“눈이 녹을 때” 기간 동안 한정 제공됩니다."
  },
  Item_55906_Name = {
    Text = "설산 상록수 씨앗"
  },
  Item_55907_Desc = {
    Text = "엘워스 산 정상에서 새로 피어난 순백한 꽃의 씨앗, 얼음과 눈이 그의 줄기와 잎이 되고, 혹한도 그 향기를 꺾을 수 없다. \n“눈이 녹을 때” 기간 동안 한정 판매됩니다."
  },
  Item_55907_Name = {
    Text = "설산 서리꽃 씨앗"
  },
  Item_55908_Desc = {
    Text = "교향곡의 서막, 극적인 핵심이 이곳에서 펼쳐집니다. 서로 다른 주제가 서로 견제하며 경합하는 모습을 감상해보세요. \n “무형의 교향곡” 기간 동안 한정 제공됩니다."
  },
  Item_55908_Name = {
    Text = "소나타 악보"
  },
  Item_55910_Desc = {
    Text = "베레모를 쓰는 순간, 탐정의 눈빛도 날카로워졌다. 누구도 당신의 프로페셔널한 정체성을 의심하지 않는다. \n「명탐정 수첩」 기간 동안 한정 공급됩니다."
  },
  Item_55910_Name = {
    Text = "탐정의 베레모 복장"
  },
  Item_55911_Desc = {
    Text = "풍우를 입으면 뒤에서 음악이 흐르는 분위기를 가질 수 있어요. 바람에 옷자락이 흩날리도록 하고, 멋진 추리 포즈를 취해보세요! \n“명탐정 수첩” 기간 한정으로 제공됩니다."
  },
  Item_55911_Name = {
    Text = "탐정의 코트 복장"
  },
  Item_55912_Desc = {
    Text = "스테레오타입의 탐정이 반드시 가져야 하는 장식품입니다. 명상할 때 사용하세요. 비어 있어도 빨대를 문 것보다 멋집니다. \n“명탐정 수첩” 기간 동안 한정 판매됩니다."
  },
  Item_55912_Name = {
    Text = "탐정의 파이프 복장"
  },
  Item_55914_Desc = {
    Text = "통증은 아픔이 곧 사랑이다. 여왕의 사랑을 느낄 때, 여왕의 이름을 크게 외치는 것을 잊지 말라. \n“타오르는 군연” 기간 동안 한정 제공됩니다."
  },
  Item_55914_Name = {
    Text = "채찍의 애정"
  },
  Item_55915_Desc = {
    Text = "당신의 머리를 숙이고 여왕의 발아래 엎드려라. 당신은 여왕의 영광스러운 의자와 발받침이 될 것이다. \n「타오르는 군연」 기간 동안 한정 제공됩니다."
  },
  Item_55915_Name = {
    Text = "밟히는 애정"
  },
  Item_55916_Desc = {
    Text = "여왕의 시험을 받아 당신의 충성을 보여주세요, 당신은 단지 복종하면 됩니다. \n여왕의 얼굴에 미소가 떠오를 때, 당신은 그녀 곁의 영광스러운 위치를 획득하게 될 것입니다. \n\"타오르는 군연\" 기간 동안 한정 제공됩니다."
  },
  Item_55916_Name = {
    Text = "명령의 애정"
  },
  Item_55917_Desc = {
    Text = "모나무에서 따온 임신한 여인을 닮은 나무 혹, 그 안에서 느껴지는 번성하고 무한한 활력을 감지할 수 있다. 자세히 들으면, 그것은 어머니의 부름이다. \n“욕망의 파도·복제” 기간 동안 한정 판매됩니다."
  },
  Item_55917_Name = {
    Text = "어머니 지모수 기형종"
  },
  Item_55918_Desc = {
    Text = "모나무에서 따온 소녀를 닮은 나무 혹, 그 안에서 가늘고 부드러운 활력을 느낄 수 있다. 자세히 들으면, 그것은 풋풋한 초대다. \n“욕망의 파도·복제” 기간 동안 한정 제공됩니다."
  },
  Item_55918_Name = {
    Text = "소녀 지모수 기형종"
  },
  Item_55919_Desc = {
    Text = "모나무에서 딴 영아와 비슷한 나무 혹으로, 생명력이 느껴지며, 자세히 들으면 신생의 울음소리가 들립니다.\n“욕망의 파도·복제” 기간 동안 한정 판매됩니다."
  },
  Item_55919_Name = {
    Text = "영아 지모수 기형종"
  },
  Item_55920_Desc = {
    Text = "어떤 숙녀와 같은 우산으로, 펼칠 때 숙녀가 결코 고개를 숙이지 않는 자신감을 얻을 수 있습니다. \n“별들이 제자리에 있습니다” 기간 동안 한정 판매됩니다."
  },
  Item_55920_Name = {
    Text = "숙녀의 양산 선물"
  },
  Item_55921_Desc = {
    Text = "교향곡의 서정적인 부분 이후의 오락 장면은 마치 생명의 강한 맥박 같습니다. 조용히 관찰하고 명상한 후의 자유롭고 유머러스한 재미를 즐겨보세요. \n “무형의 교향곡” 기간 동안 한정 제공됩니다."
  },
  Item_55921_Name = {
    Text = "미뉴에트 악보"
  },
  Item_55922_Desc = {
    Text = "어떤 숙녀가 보내준 오후 차회 초대장, 맛있는 디저트를 즐겨보세요. 양인형과 작은 곰과 함께 춤추기 바랍니다. \n“별들이 제자리에 있습니다” 축제 기간 동안 한정 제공됩니다."
  },
  Item_55922_Name = {
    Text = "숙녀의 초대장 선물"
  },
  Item_55923_Desc = {
    Text = "어떤 숙녀와 같은 양장 드레스로, 착용하면 숙녀의 우아하고 고귀한 기품을 획득할 수 있습니다. \n“별들이 제자리에 있습니다” 기간 동안 한정 판매됩니다."
  },
  Item_55923_Name = {
    Text = "숙녀의 드레스 선물"
  },
  Item_56483_Desc = {
    Text = "시대 최첨단 기술을 대표하는 정밀한 기어는 인형의 낡은 부분을 대사할 수 있습니다. \n 돌이 육체를 수리하기 위해 사용하는 기어 부품입니다. 상점에서 필요한 물자를 교환하는 데 사용됩니다."
  },
  Item_56483_Name = {
    Text = "인형 부품"
  },
  Item_56484_Desc = {
    Text = "평범한 카지노 칩 하나가 당신의 인생을 뒤바꿔 줄 것입니다. \n “럭키 클럽”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_56484_Name = {Text = "결승 칩"},
  Item_56485_Desc = {
    Text = "원초의 음표, 시작의 땅에서 전체 밴드를 최종적인 클라이맥스로 이끕니다. “안면 궁전”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_56485_Name = {
    Text = "고창 악장"
  },
  Item_56486_Desc = {
    Text = "포인터 회전은 멈추지 않고, 무회자와 함께 앞으로 나아갑니다.\n종말의 순간에 도달하면 모든 문살이 당신을 위해 열리고, 모든 악장이 당신을 위해 연주될 것입니다.\n궁극의 문 앞의 정밀한 포인터는 “반향”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_56486_Name = {
    Text = "종말 지침"
  },
  Item_56487_Desc = {
    Text = "그의 영지는 여전히 심연에서 깊은 잠하고 있습니다. \n깊은 바다에서 떠다니는 태아, “성태 부화”에서 물자 교환에 사용됩니다."
  },
  Item_56487_Name = {
    Text = "무식의 태아"
  },
  Item_56488_Desc = {
    Text = "그는 모든 것을 삼키고, 결코 배부르지 않습니다. \n깊은 바다에서 떠다니는 태아로, “성태 부화”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_56488_Name = {
    Text = "무염의 태아"
  },
  Item_56489_Desc = {
    Text = "그분은 이 세상에 욕심이 없습니다. \n깊은 바다에서 떠다니는 태아로, “성태 부화”에서 물자 교환에 사용됩니다."
  },
  Item_56489_Name = {
    Text = "무욕의 태아"
  },
  Item_56490_Desc = {
    Text = "얼음과 눈이 그것을 청란색으로 덮어, 굴하지 않는 생명의 탄생을 축하합니다. \n엘워스 산 정상에서 신생된 꽃봉오리로, “삼키는 야심”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_56490_Name = {
    Text = "한동 꽃봉오리"
  },
  Item_56491_Desc = {
    Text = "달빛이 은백색으로 물들여주며, 굴하지 않는 생명의 탄생을 축하합니다. \n엘워스 산 정상에서 피어난 신생의 꽃봉오리로, \"복수의 전의\"에서 물자를 교환하는 데 사용됩니다."
  },
  Item_56491_Name = {
    Text = "은서리 꽃봉오리"
  },
  Item_56492_Desc = {
    Text = "일광이 그것에 주황빛을 입혀, 굴하지 않는 생명의 탄생을 축하합니다. \n엘워스 산 정상에서 새로 피어난 꽃눈으로, “재생의 희망”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_56492_Name = {
    Text = "햇빛 꽃봉오리"
  },
  Item_56493_Desc = {
    Text = "엘워스 설산에 흩어진 감정 입자다. 만질 때 짐승이 물어뜯고 삼키는 소리가 들리는 듯하다.\n활동 콘텐츠「산맥의 거대한 아가리」와 특수 파견 기록「엘워스로 돌아온 자」에서 수호자의 공명을 높이는 데 사용된다.\n한정 활동「설산이 녹아내릴 때」에서 업적 보상으로 획득할 수 있다."
  },
  Item_56493_Name = {
    Text = "포식의 심장"
  },
  Item_56494_Desc = {
    Text = "궁극의 문 내부에 산일된 감정 입자로, 접촉하면 모든 차원과 시공간의 속삭임이 들리는 듯합니다.\n수호자가 조사 이벤트 「긴 꿈이 끝날 때」에서의 공명을 높이는 데 사용됩니다."
  },
  Item_56494_Name = {
    Text = "궁극의 심장"
  },
  Item_56495_Desc = {
    Text = "미사그 캠퍼스에 산일된 감정 입자로, 접촉하면 수많은 절규와 탄식이 들리는 듯합니다.\n수호자가 조사 이벤트 「종말 교향곡」에서의 공명을 높이는 데 사용됩니다."
  },
  Item_56495_Name = {
    Text = "결의의 심장"
  },
  Item_56635_Desc = {
    Text = "피해 증폭 속성의 명륜입니다."
  },
  Item_56635_Name = {
    Text = "설산이 녹을 때까지"
  },
  Item_56635_StoryDesc = {
    Text = "그녀는 산봉우리 위에 서서 손에 든 검은 가시를 들어올렸다. \n 온통 바람과 눈 속에서, 그녀는 그 미친 산맥에 맞서고, 버림받고, 배신당하고, 짓밟힌 자신의 운명에 맞서고 있다. \n 그녀는 결국 승리할 것이며, 얼음과 눈은 결국 소멸할 것이다. 그때 그녀는 새로운 모습으로 세상에 재현될 것이다. 그녀는 이렇게 말했다. \n 엘워스는 극한의 땅으로, 그곳의 바람과 눈은 항상 멈추지 않는다. 이것은 상식이다. 강력한 전사도 고귀한 존재와 맞설 수 없고, 강한 사람도 자신의 운명을 이길 수 없다. \n 하지만 그 눈산은 결국 소멸했지, 그렇지 않나?"
  },
  Item_56636_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “문의 답”을 선택할 수 있습니다. \n\n모든 것의 진실타래은 문 뒤로 숨겨져 있습니다. \n그녀는 여기 고요히 머물며 모든 질문을 받아들이고, 침묵으로 응답합니다. \n그녀가 기다리는 이는 결국 자신의 답을 작성할 것입니다."
  },
  Item_56636_Name = {
    Text = "문을 여는 답"
  },
  Item_56636_StoryDesc = {
    Text = "모든 것의 진실타래은 문 뒤로 숨겨져 있다. \n그녀는 여기 고요히 머물며 모든 질문을 받아들이고, 침묵으로 응답한다. \n그녀가 기다리는 이는 결국 자신의 답을 작성할 것이다."
  },
  Item_56637_Desc = {
    Text = "광기 충전 레벨 속성의 명륜이다."
  },
  Item_56637_Name = {
    Text = "목동의 지팡이"
  },
  Item_56637_StoryDesc = {
    Text = "무수한 양떼가 무수히 넓은 초원을 배회한다./n세상에는 많고 많은 양들이 있었고, 양들은 태어날 때부터 목자의 인도를 필요로 한다./n그녀는 항상 이 세계의 선지자였고, 손에는 지식의 지팡이를 들고 있었다./n그녀는 항상 좋은 목자였고, 언제나 양떼를 바른 길로 인도하겠노라 결심했었다./n그녀는 그 지팡이로 어린 양을 가르쳤었고, 그 지팡이로 승냥이들을 내쫓았었다./n그녀에게는 앞길이 보였기 때문에, 양치기의 지팡이를 높게 들고 있었다./n그녀는 일찍이 풍족한 물길, 신선한 목초가 있는 곳으로 양떼들을 인도했다./n지금의 그녀는 세계의 진실타래을 목도했고, 그렇기에 양떼들을 종말의 품으로 인도한다./n여기로 가자, 돌아볼 필요는 없어./n그녀는 웃으며 지혜의 지팡이를 흔들었다./n그렇게 양들은 눈 앞의 낭떠러지를 볼 수 없었다./n한마리, 두 마리./n양들은 떨어졌고, 목자는 즐거이 노래했다./n선량한 목자를 따라오세요, 그녀는 이미 당신에게 가장 확실타래한 앞길을 제시했다./n사망의 음침한 골짜기로 다닐지라도 해를 두려워하지 않을 것은 그녀의 지팡이가 여전히 함께 있음이라./n함께 소멸의 심연에 이를 때까지."
  },
  Item_56638_Desc = {
    Text = "기록한 키오링 후, 배치 시 키링 스킬:“네번째 악장”을 선택할 수 있습니다. \n\n음표가 모여 별들로 이루어진 바다를 이루고, 주제는 웅장한 심연의 우주에서 춤을 춥니다. \n 닫힌 눈으로 들어보세요. 우주의 종말과 절정을."
  },
  Item_56638_Name = {
    Text = "네번째 악장"
  },
  Item_56638_StoryDesc = {
    Text = "음표가 별의 바다로 모여들고, 주제는 웅장한 우주에서 춤을 춥니다. \n 눈을 감고 들어보세요. 우주의 종언을, 우주의 절정을."
  },
  Item_56639_Desc = {
    Text = "크리티컬 확률 속성의 명륜입니다."
  },
  Item_56639_Name = {
    Text = "끝없는 연주"
  },
  Item_56639_StoryDesc = {
    Text = "“아직 완벽하지 않아, 오늘 밤 열 번 더 연습해. 너의 재능은 평범하니, 오케스트라에 들어가려면 더 열심히 해야 해, 알겠니?”\n“네, 아버지.”\n어떤 연주가 완벽하다고 할 수 있을까?\n그의 두 손은 끊임없이 날아다니며 실타래수를 용납하지 않는다.\n그는 자신의 잡념을 꾸짖고, 자신의 평범함을 경멸한다.\n수많은 음표가 눈앞을 맴돌고, 매일, 매일, 그의 삶에서 음악만이 존재한다.\n다행히 그는 매일 완벽한 연주에 더 가까워지고 있으며, 꿈속의 길 끝에 있는 빛을 바라보지만, 그 빛은 영원히 닿지 않을 것처럼 보인다.\n완벽에 대한 갈망은 그의 영혼에 새겨져 있지만, 모든 사람이 이렇게 하기를 원하는 것은 아니다.\n“폐하와 세상을 위해 가장 완벽한 음악을 선사하는 것이 오케스트라의 의무가 아닌가?”\n그는 불만을 품고 있는 얼굴을 바라보며, 마치 과거의 자신을 경멸하는 듯하다.\n아버지, 궁정 오케스트라도 이러할 뿐이다.\n그는 한때 바라보던 목표를 버리고, 고집스럽게 완벽을 추구하는 길을 계속 걷는다.\n그는 그들의 손을 잡기 위해 손을 멈출 수 없으며, 마치 과거의 자기 자신을 멈출 수 없는 것처럼.\n매일, 매일, 그는 끊임없이 연주하고 있다.\n음악은 그의 삶이다.\n음악 외에는 그가 가진 것이 없다."
  },
  Item_56640_Desc = {
    Text = "검은 인장 드롭율 속성의 명륜입니다."
  },
  Item_56640_Name = {
    Text = "운명의 룰렛"
  },
  Item_56640_StoryDesc = {
    Text = "모두가 운명을 이기고 싶어 하지만, 모두가 운명을 두려워합니다.\n용감한 이들은 전투의 분노를 외치고, 겁쟁이들은 순종의 낮은 신음소리를 냅니다. 그러나 오직 그만이 운명을 이길 비밀을 발견했습니다.\n그것은 끊임없이 운명을 초대하여 도박판에 나가게 하고, 운명이 다음 판을 열도록 재촉하는 것입니다.\n그는 결코 운음을 두려워하지 않았습니다. 왜냐하면 그는 자신이 지지 않을 것이라고 믿었기 때문입니다.\n그는 무엇을 배팅할지 묻지 않았고, 어떤 칩을 올리든 주저하지 않았습니다. 자신의 생명조차 포함해서요.\n그는 룰렛 총으로 수많은 도박에 눈이 먼 패배자들을 물리치고, 렌티니언의 악명 높은 도박광이 되었습니다.\n정말 안타깝습니다, 대등한 상대가 없다는 것은 얼마나 외로운 일인가요.\n그가 그 남자를 만날 때까지 말입니다.\n그는 수많은 인간을 이기고 마침내 운명의 도박판에 앉았습니다.\n곧 그는 모든 것을 잃었고, 원금과 이자를 함께 되찾았습니다.\n야수로 다시 태어날 때까지, 그는 마침내 마지막 총알을 발사한 총을 땅에서 보았습니다.\n그는 한 발의 총알을 다시 장전하고 자신의 머리를 향해 다시 방아쇠를 당겼습니다.\n조용한 가운데, 그는 입을 벌렸습니다.\n그는 아직 지지 않았습니다. 그러므로 언젠가는 반드시 승리할 것입니다.\n그는 항상 이렇게 믿어왔습니다. 비록 모든 것을 걸어야 하더라도."
  },
  Item_56641_Desc = {
    Text = "속성이 은빛 충전인 명륜."
  },
  Item_56641_Name = {
    Text = "빙하 아래에 잠든"
  },
  Item_56641_StoryDesc = {
    Text = "“그 순간”을 기다리기 위해 소녀는 빙하의 바닥에서 잠들어 있다. 엘워스의 천 길 얼음은 그녀의 육체를 얼려버렸지만, 그녀의 신식은 완전히 봉인하지 못했다.\n그 신식은 아이에게서 오고, 어머니에게서도 온다. 그녀의 딸의 어두운 자궁 속에서 신은 만고의 긴 꿈을 이어간다.\n25년의 세월 동안 그녀는 무엇을 생각했으며, 무엇을 그리워했고, 무엇을 기대했을까?\n오늘날 이 질문에 대답할 수 있는 이는 아무도 없다. 그 소녀 본인은… 그녀는 곁에 있는 사람에게 진심을 털어놓을까? 모든 것을 시간과 미래에 맡기자."
  },
  Item_56642_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_56642_Name = {
    Text = "진리의 문"
  },
  Item_56642_StoryDesc = {
    Text = "그녀의 이름은 지혜의 화신을 의미한다./n그녀는 세상의 모든 지식을 알고 있으며, 이는 미사그의 학자들이 동경하는 궁극이기도 하다./n몇 마디 말만 들을 수 있다면, 더 많은 깨달음을 얻을 수 있었을 것이다./n그러나 그녀는, 자신은 단지 문지기라고만 말했다./n그것은 어떤 문인가?/n누구도 그 문을 보지 못했기에, 학자들은 그것을 진리라고 불렀다./n그녀는 진리의 문지기이며, 미사그를 수호하는 아테나이다./n타비는 이러한 추측을 부정하지 않은 채, 한결같이 이곳을 바라보았고, 세상을 바라보았다./n말없이 비애에 찬 눈으로./n당신에게 그 문을 목도할 날이 도래한다면, 당신은 문 위에서 익히 알던 눈을 보게 될 것이다./n그 시선은 고요하고도 영원하다./n그 시선은 시간을 꿰뚫고, 당신의 영혼을 꿰뚫는다."
  },
  Item_56643_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬: “무속역병”을 선택할 수 있습니다. \n\n그 광기의 눈을 직접 바라보지 말아요. 조심하세요, 이미 감염되었을지도 모릅니다."
  },
  Item_56643_Name = {
    Text = "허무의 역병"
  },
  Item_56643_StoryDesc = {
    Text = "공허는 진실타래이 가져온 역병으로, 모든 색을 지우고 모든 것을 회색으로 칠하려 한다. \n그 광기의 눈을 보지 말아요, 조심해요. 그가 이미 당신을 감염시켰을지도 몰라요."
  },
  Item_57171_Desc = {
    Text = "그의 영식은 아직 심연 속 깊은 잠에 빠져 있다.\n심해를 떠도는 배아로, 「성태 부화」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
  Item_57171_Name = {
    Text = "무식의 태아"
  },
  Item_57172_Desc = {
    Text = "그는 만물을 포식하며, 영원히 만족할 줄 모른다.\n심해를 떠도는 배아로, 「성태 부화」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
