  },
  Item_57473_Name = {Text = "결승 칩"},
  Item_58149_Desc = {
    Text = "“영혼의 목자” 이벤트에서 “성당의 길”, “시민의 선의” 및 “성취 보상”을 통해 획득한 아이템으로, “자선 판매 현장”에서 상품을 구매하는 데 사용됩니다. \n\n 당신의 사랑을 의미 있는 판매권으로, 당신의 돈을 다른 사람의 미래로 바꾸세요. \n 서로 돕는 것이 아버지 신이 바라는 길입니다."
  },
  Item_58149_Name = {
    Text = "자선 판매권"
  },
  Item_58150_Desc = {
    Text = "이벤트 “영혼의 목자”에서 “성당의 길”, “시민의 선의” 및 “성취 보상”을 통해 얻은 아이템으로, “자선 판매 현장”에서 상품을 구매하는 데 사용됩니다.\n\n당신의 사랑을 의미 있는 판매권으로 바꾸고, 당신의 돈을 다른 사람의 미래로 바꾸세요.\n서로 돕는 것이 아버지 신이 바라는 길입니다."
  },
