  Item_61294_Desc = {
    Text = "「등가시의 손아귀」에서 교환하는 데 사용하는 아이템.\n등가시의 원재료 중 하나. 이것으로 다듬어진 등가시가 인간의 흉강을 파고들면, 모든 것을 지배할 수 있다.\n의지와 감정? 그저 생물의 손상된 코드에 불과할 뿐.\n\n최소 {s1}개 드롭"
  },
  Item_61294_Name = {
    Text = "원생 경골"
  },
  Item_61295_Desc = {
    Text = "「어둠의 속박」에서 교환하는 데 사용하는 아이템.\n이사라우의 바람 속에 흩어진 거석의 잔해.\n그것들은 고요히 멈춰 서서, 사라진 도성을 위해 엄숙하게 애도한다.\n\n최소 {s1}개 드롭"
  },
  Item_61295_Name = {
    Text = "나선 유적"
  },
  Item_61296_Desc = {
    Text = "「유적의 수호」에서 교환하는 데 사용하는 아이템.\n 겹겹이 쌓인 탄산칼슘으로 이루어진 꿈. 이사라우의 서의 비밀을 풀어드립니다.\n\n최소 {s1}개 드롭"
  },
  Item_61296_Name = {Text = "원엽석"},
  Item_61391_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_61391_Name = {
    Text = "순은의 초심"
  },
  Item_61391_StoryDesc = {
    Text = "그것은 은백색, 맑고, 티끌 하나 없는 심장입니다.\n순은으로 만들어져 기계 구조의 심장에서 질서 있게 뛰고 있습니다.\n한때 혈육에 의해 부식되었고, 한때 오물에 의해 더러워졌습니다.\n하지만 죽음의 먹구름이 덮쳐올 때, 결국 그것은 본래의 모습으로 돌아갔습니다."
  },
  Item_61941_Desc = {
    Text = "달빛이 그것을 은백색으로 물들이며, 굴하지 않는 HP이 이곳에서 탄생함을 축하한다.\n엘워스 산꼭대기에서 새로 피어난 꽃봉오리로, 「복수의 전의」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
  Item_61941_Name = {
    Text = "은서리 꽃봉오리"
  },
  Item_61942_Desc = {
    Text = "햇빛이 그것을 주황빛으로 물들이며, 굴하지 않는 HP이 이곳에서 탄생함을 축하한다.\n엘워스 산꼭대기에서 새로 피어난 꽃봉오리로, 「재생의 희망」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
  Item_61942_Name = {
    Text = "햇빛 꽃봉오리"
  },
  Item_61943_Desc = {
    Text = "눈과 얼음이 그것을 그윽한 청색으로 물들이며, 굴하지 않는 HP이 이곳에서 탄생함을 축하한다.\n엘워스 산꼭대기에서 새로 피어난 꽃봉오리로, 「삼킴의 야망」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
