  },
  Item_62000_Name = {
    Text = "한동 꽃봉오리"
  },
  Item_65615_Desc = {
    Text = "깊은 바다에서 넘쳐흐르는 물결이 의식의 경계를 충격합니다. \n이상한 꿈의 침식을 막기 위한 의식은 “심연의 제사” 기간 동안 한정 제공됩니다."
  },
  Item_65615_Name = {
    Text = "침식 방어 의식"
  },
  Item_65616_Desc = {
    Text = "그 깊고 어두운 곳에 깊은 잠한 왕의 탄생은 신식의 바다 전체를 왜곡할 것이다. \n이질적인 꿈의 침식에 저항하기 위한 의식은 “심연의 제사” 기간 한정으로 이용 가능합니다."
  },
  Item_65616_Name = {
    Text = "신왕 탄생 의식"
  },
  Item_65618_Desc = {
    Text = "이몽시계의 천재도 정신 공명을 통해 수호자의 영지를 방해합니다. \n 이몽 침식에 저항하기 위한 의식은 “심연의 제사” 기간 동안 한정 제공됩니다."
  },
  Item_65618_Name = {
    Text = "재앙 경계 의식"
  },
  Item_65752_Desc = {
    Text = "「인격 해석」에서 교환하는 데 사용하는 아이템.\n\n모든 기억이 충성스럽고 믿을 만한 것은 아닙니다.\n비밀을 하나 알려드리죠: β는 철두철미한 거짓말쟁이로, 거짓말을 하고 있습니다.\n\n최소 {s1}개 드롭"
  },
  Item_65752_Name = {
    Text = "기억 퍼즐 α"
  },
  Item_65753_Desc = {
    Text = "「인격 해석」에서 교환하는 데 사용하는 아이템.\n\n아, 질투여! 당신은 소문의 어머니입니다.\nα에 대한 고발에 깊이 유감을 표합니다. 제가 아는 한, 거짓말을 한 것은 바로 그쪽입니다.\n\n최소 {s1}개 드롭"
  },
  Item_65753_Name = {
    Text = "기억 퍼즐 β"
  },
  Item_65754_Desc = {
    Text = "「인격 해석」에서 교환하는 데 사용하는 아이템.\n\n진실: α와 β 모두 거짓말을 하고 있습니다.\n이제 완전히 소멸될 위험을 무릅쓰고 이것을 알려드립니다 @#¥%……&\n\n최소 {s1}개 드롭"
  },
  Item_65754_Name = {
