  },
  Item_66103_Name = {
    Text = "제사자의 눈물"
  },
  Item_66386_Desc = {
    Text = "너희들은 서로를 신뢰할 것이다. \n수호자와 깨어남체의 정신적 동조 정도에 따라 더 많은 깨어남체의 아카이브 스토리를 해금할 수 있다."
  },
  Item_66386_Name = {Text = "동조율"},
  Item_66763_Desc = {
    Text = "바늘은 쉼 없이 돌아가며, 돌아오지 않는 자들과 함께 앞으로 나아간다.\n종말의 순간에 이르면, 모든 문이 당신을 위해 열리고, 모든 악장이 당신을 위해 울려 퍼질 것이다.\n극한의 문 앞에 있는 정밀한 바늘로, 「에코」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
  Item_66763_Name = {
    Text = "종말 지침"
  },
  Item_66764_Desc = {
    Text = "바늘은 쉼 없이 돌아가며, 돌아오지 않는 자들과 함께 앞으로 나아간다.\n종말의 순간에 이르면, 모든 문이 당신을 위해 열리고, 모든 악장이 당신을 위해 울려 퍼질 것이다.\n극한의 문 앞에 있는 정밀한 바늘로, 「에코」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
