  Item_66814_Name = {
    Text = "종말 지침"
  },
  Item_66815_Desc = {
    Text = "바늘은 쉼 없이 돌아가며, 돌아오지 않는 자들과 함께 앞으로 나아간다.\n종말의 순간에 이르면, 모든 문이 당신을 위해 열리고, 모든 악장이 당신을 위해 울려 퍼질 것이다.\n극한의 문 앞에 있는 정밀한 바늘로, 「에코」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
  Item_66815_Name = {
    Text = "종말 지침"
  },
  Item_66816_Desc = {
    Text = "바늘은 쉼 없이 돌아가며, 돌아오지 않는 자들과 함께 앞으로 나아간다.\n종말의 순간에 이르면, 모든 문이 당신을 위해 열리고, 모든 악장이 당신을 위해 울려 퍼질 것이다.\n극한의 문 앞에 있는 정밀한 바늘로, 「에코」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
  Item_66816_Name = {
    Text = "종말 지침"
  },
  Item_67085_Desc = {
    Text = "수많은 세계에서 흩어진 듣을 수 없는 몽유, 인지하는 순간 무질서한 혼란이 마음을 차지할 것이다."
  },
  Item_67085_Name = {
    Text = "혼돈의 몽언"
  },
  Item_67086_Desc = {
    Text = "수많은 세상에서 흩어진 듣을 수 없는 꿈속의 속삭임, 인지하는 순간 원초의 탄생이 마음을 차지할 것이다."
  },
  Item_67086_Name = {
    Text = "원초의 몽언"
  },
  Item_67087_Desc = {
    Text = "수많은 세계에서 흩어진 듣을 수 없는 몽언, 인지하는 순간 완전한 어둠이 마음을 차지할 것이다."
  },
  Item_67087_Name = {
    Text = "우둔한 몽언"
  },
  Item_67377_Desc = {
    Text = "수호자에게 있어 신분 표시나 은심 통신에서 감정을 표현하는 조형물은 정신력만큼이나 중요하다—무형자가 이렇게 말했다.\n일정 수량을 수집한 후 사용하면, 전용 아바타, 감정 표현, 또는 이전 과제 기록과 페이즈 대결 시즌의 아바타, 감정 표현 중 하나를 무작위로 얻을 수 있다."
  },
  Item_67377_Name = {
    Text = "형체 없는 자의 증표"
  },
  Item_67378_Desc = {
    Text = "교활하고 변덕스러운. 당신은 무형자에게 자신의 가치를 증명했습니다. 곧, 그가 당신에게 초대를 보낼 것이며, 당신은 세상의 모든 것의 화신이자 무형의 궁극적인 존재가 될 것입니다. \n 일정 수량을 모은 후 사용하면, “형체 없는 자의 증표”에서 획득하지 못한 아바타나 대전 이모티콘 중 하나를 선택할 수 있습니다."
  },
  Item_67378_Name = {
    Text = "형체 없는 자의 초대장"
  },
  Item_68281_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
  },
  Item_68281_Name = {
    Text = "조사 과정 특전 Ⅸ"
  },
  Item_68341_Desc = {
    Text = "구매 후, 모든 예약 구매 보상을 순차적으로 받을 수 있습니다."
  },
  Item_68341_Name = {
    Text = "별들 너머·한정 예약 구매"
  },
  Item_68419_Desc = {
    Text = "긴 시간이 지나면, 이 슬픔은 결국 평온해질 것이다. \n신왕의 감정이 인식의 차원에 남긴 흔적으로, “비수한 해저”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_68419_Name = {
    Text = "비애의 감정"
  },
  Item_68420_Desc = {
    Text = "축하할 필요 없어요, 기쁨도 공허에 불과해요. \n신왕의 감정이 인식의 차원에 남긴 자국으로, “환열해심”에서 물자를 교환하는 데 사용됩니다."
  },
  Item_68420_Name = {
    Text = "환희의 감정"
  },
  Item_68421_Desc = {
    Text = "피곤함이 찾아와, 그는 다시 영원한 잠에 빠질 것이다. \n신왕의 감정이 인식의 차원에 남긴 흔적은 ‘지친 해구’에서 물자를 교환하는 데 사용됩니다."
  },
  Item_68421_Name = {
    Text = "피로의 감정"
  },
  Item_68682_Desc = {
    Text = "광기 충전 레벨 속성의 명륜이다."
  },
  Item_68682_Name = {
    Text = "청석 왕좌"
  },
  Item_68682_StoryDesc = {
    Text = "끝없는 심연 속, 푸른 옥좌가 우뚝 서있어,/n하늘은 저물고, 별들은 떨었으며, 만물은 침묵했다./n/n옛되고 신비로운 존재는 이미 떠났고,/n대대손손 중생들은 꿈 속에서 찬송했다./n깊고 어두운 물 속, 먼지 쌓인 비밀,/n그대의 속삭임이 밀물이 되어 마음의 계곡은 잠겨든다./n/n이 끝없는 꿈 속에서 선지자와 광인은 함께 헤엄치고,/n보이지 않는 영혼을 쫓은 곳에서 공포와 경외가 교차한다./n파란 해조가 휘감은 궤적은 운명의 안배과 같이,/n길 잃은 자들의 마음을 푸른 왕좌로 인도한다./n아아, 우주의 부조리와 진리, 꿈과 현실타래이 교차하는 곳,/n그곳에서 영원하고도 찬란한 빛이 반짝인다."
  },
  Item_68683_Desc = {
    Text = "피해 증폭 속성의 명륜입니다."
  },
  Item_68683_Name = {
    Text = "마녀의 모자"
  },
  Item_68683_StoryDesc = {
    Text = "마녀와 넓은 챙 모자의 인과 관계는 때때로 닭과 계란의 관계처럼, 모자가 마녀를 완성했는지, 아니면 마녀가 모자를 완성했는지 구분할 수 없습니다.\n어쨌든, 다프다일은 이렇게 충분히 우아한 넓은 챙 모자를 가지고 있습니다.\n이 모자는 처음에 예전 주인에게 속했으며, 그때 다프다일의 이름은 아직 다프다일에게 속하지 않았고, 그녀는 단지 방금 제압된, 혼란스러운 유령이었으며, 머릿속은 멍한 야수였습니다.\n항상 미소를 짓고 있는 그 여자는 그녀를 데리고, 마치 아이를 교육하듯, 인내심 있게 조금씩 그녀에게 '인간'이 되는 방법과 사람들과 소통하는 비밀을 가르쳤습니다.\n항구 도시의 상업이 번창하며, 그 당시 인류 문화의 가장 풍부한 결정체가 모였습니다. 교환 상점이 위치한 거리에는 다양한 상점들이 거의 모든 것을 포함하고 있으며, 상점 주인은 항상 신기하게 모든 가게와 오랜 친구처럼 수다를 떨 수 있었습니다.\n「그녀는 정말 대단해.」그때의 다프다일은 생각했습니다.「하지만 이상할 것도 없어, 누구도 그녀를 싫어할 리가 없지.」\n상점 주인은 쇼핑을 좋아했기에, 그리하여 천 년 동안 그녀가 자른 머리의 인간 역할을 계속해온 다프다일은 처음으로 자신의 의견을 내놓으라는 요청을 받았습니다.\n「어떤 것이 더 예쁘다고 생각해? 이 작은 모자, 아니면 이 넓은 챙 모자?」\n여자는 거울을 보며, 다채로운 모자들을 이리저리 써보았습니다. 원래 다프다일에게 이들은 단지 몸을 감싸고 자신을 더 인간답게 꾸미기 위한 도구에 불과했습니다.\n하지만 그날, 그녀는 상점 주인 머리 위에 마치 거대한 꽃처럼 피어난 넓은 챙 모자를 보며, 갑자기 여자가 그런 모자를 쓰고 해변에서 산책하는 모습이 떠올랐습니다.\n「이거야.」그녀가 갑자기 입을 열었습니다.「바로 이거야.」\n상점 주인은 약간 놀란 듯 돌아보며, 그녀가 이렇게 확실타래하게 자신의 취향을 표현할 줄은 몰랐던 것 같습니다.\n「좋아, 정말 좋은 모자야. 네가 나를 위해 고른 거니까, 나는 반드시 소중히 할 거야.」\n다프다일을 격려하기 위한 것인지, 이 모자는 상점 주인이 약속한 대로 그녀의 머리 위에 항상 장식으로 남아 있었고, 결국 그녀의 손에서 서서히 미끄러져 내려와 다프다일에게 직접 건네주며, 그녀의 미소 짓는 머리와 함께했습니다.\n「정말 좋은 모자야, 나는 반드시 소중히 할 거야.」\n화려하게 피어난 자주색 꽃이 마침내 새로운 주인의 머리 위에 만개했습니다."
  },
  Item_68688_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_68688_Name = {
    Text = "본원 툴루 SR (임시 텍스트)"
  },
  Item_68688_StoryDesc = {
