  },
  Item_68689_Name = {
    Text = "최면 진자"
  },
  Item_68689_StoryDesc = {
    Text = "신생을 얻은 클레멘타인은 마치 어리숙한 유충처럼, 인간 세계를 가로지르며, 그녀의 종족에 속하지 않는 화려한 세계를 떠돌며, 혼란스럽고, 당황스러움을 느꼈다.\n그때, 깨달음을 주는 듯한 목소리가 울려 퍼졌다——\n“실타래례합니다, 당신이 샬럿 의사인가요? 저는 샬럿 의사에게 심리 상담을 받으러 왔습니다…”\n클레멘타인은 마침내 정신을 차렸다. 그녀는 샬럿이 누구인지 신경 쓰지 않았고, 단지 오는 이의 입에서 나온 새로운 용어인 “심리 상담”이 궁금했다.\n하지만 그녀는 성숙한 사냥꾼이었기에 자신의 무지를 드러내지 않을 것이었다. 그래서 그녀는 웃었다, 마치 그녀가 샬럿이고, 오는 이가 말한 구원인 것처럼.\n눈물, 고통, 무력감, 자극할 필요도 없이, 오는 이는 이미 영혼 깊은 곳의 고통을 짜냈다.\n떠나기 전, 상대방은 한결 편안한 표정으로 클레멘타인을 바라보며 말했다: “이런 이야기를 들어줘서 고마워요. 기분이 훨씬 좋아졌어요.”\n그리고 문을 닫는 소리와 함께, 클레멘타인이 처음으로 달콤함을 맛보며 터뜨린 웃음이 울려 퍼졌다.\n그 웃음은 처음에는 약간의 소리로, 마치 유충의 윙윙거림처럼, 점점 커지며 성충의 외침처럼 되었다.\n그리고 이 웃음 속에서, 클레멘타인이라는 이름의 인섹토이드도 빠르게 성숙해졌다.\n이후의 모든 것은 자연스러운 수순이었다. 그녀는 심리 의사가 되어, 웃음과 진자를 가지고 하나하나 환자의 내면으로 깊이 들어갔다.\n그녀는 여전히 인간 세계를 걸어다니고, 여전히 이 화려한 세계에 속하지 않지만, 더 이상 혼란스럽고 당황스럽지 않았다.\n왜냐하면 전체 인간 세계와 세계가 그녀의 최면 사냥터였기 때문이다."
  },
  Item_68705_Desc = {
    Text = "축하할 필요 없다, 기쁨도 허무일 뿐이다.\n신왕의 감정이 인지의 차원에 남긴 낙인으로, 「환희의 해연」에서 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
  Item_68705_Name = {
    Text = "환희의 감정"
  },
