  },
  Item_68851_StoryDesc = {
    Text = "제12기 과제 기록"
  },
  Item_68852_Desc = {
    Text = "“채식주의 주스? 채식주의 주스가 무엇인지 모르겠어요. 저는 채식주의 주스가 없어요.”"
  },
  Item_68852_EmojiName = {
    Text = "소질 사라짐"
  },
  Item_68852_Name = {
    Text = "미친 미사그: 제킨·소질 소실타래"
  },
  Item_68852_StoryDesc = {
    Text = "제13기 과제 기록"
  },
  Item_68853_Desc = {
    Text = "“인간은 정말 복잡한 생물이야……”"
  },
  Item_68853_EmojiName = {Text = "창백"},
  Item_68853_Name = {
    Text = "쉬운 미사그: 다프데일·창상"
  },
  Item_68853_StoryDesc = {
    Text = "제12기 페이즈 대결"
  },
  Item_68854_Desc = {
    Text = "“나는 사랑받지 못하는 물고기……”"
  },
  Item_68854_EmojiName = {Text = "구석"},
  Item_68854_Name = {
    Text = "미친 미사그: 케이커스·구석"
  },
  Item_68854_StoryDesc = {
    Text = "제13기 페이즈 대결"
  },
  Item_68855_Desc = {
    Text = "“아, 그렇군요. 말씀하신 대로입니다. 잘 생각해볼게요.”"
  },
  Item_68855_EmojiName = {
    Text = "확실타래하게"
  },
  Item_68855_Name = {
    Text = "오를라·확실타래히"
  },
  Item_68855_StoryDesc = {
    Text = "제13기 과제 기록"
  },
  Item_68856_Desc = {
    Text = "“와, 주인 정말 대단해!”"
  },
  Item_68856_EmojiName = {Text = "숭배"},
  Item_68856_Name = {
    Text = "쉬운 미사그: 릴리·숭배"
  },
  Item_68856_StoryDesc = {
    Text = "제13기 페이즈 대결"
  },
  Item_68857_Desc = {
    Text = "“안녕히 계세요, 엄마. 오늘 밤에 떠나겠어요!”"
  },
  Item_68857_EmojiName = {
    Text = "농땡이를 피우다"
  },
  Item_68857_Name = {
    Text = "머피·농땡이를 피우다"
  },
  Item_68857_StoryDesc = {
    Text = "제13기 과제 기록"
  },
  Item_68858_Desc = {
    Text = "“주군, 함께 말을 타러 가시겠어요?”"
  },
  Item_68858_EmojiName = {Text = "기쁘다"},
  Item_68858_Name = {
    Text = "오지르·행복"
  },
  Item_68858_StoryDesc = {
    Text = "제12기 페이즈 대결"
  },
  Item_68859_Desc = {
    Text = "“방문해 주셔서 감사합니다.”"
  },
  Item_68859_EmojiName = {Text = "아듀"},
  Item_68859_Name = {
    Text = "쉬운 미사그: 소렐·아듀"
  },
  Item_68859_StoryDesc = {
    Text = "제12기 과제 기록"
  },
  Item_69844_Desc = {
    Text = "고위 인사의 장례식에서 연주되는 미사곡으로, 고인의 영혼을 위로하며 안식을 기원합니다. \n“장미 책과 함께” 기간 동안 한정 제공됩니다."
  },
  Item_69844_Name = {
    Text = "축복 안식 미사"
  },
  Item_69845_Desc = {
    Text = "고위 인사의 장례식에서 연주된 미사곡, 그녀의 영광과 깃발은 영원히 남아있습니다. \n“장미 책과 함께” 기간 동안 한정 제공됩니다."
  },
  Item_69845_Name = {
    Text = "명정 찬미 미사"
  },
  Item_69846_Desc = {
    Text = "고위 인사의 장례식에서 연주된 미사곡으로, 생자가 망자에 대한 애도와 추모를 표현하며, 죽음이 종료가 아니라 영원한 생명으로의 시작이라는 믿음을 담고 있습니다. \n“장미 책과 함께” 기간 동안 한정 제공됩니다."
  },
  Item_69846_Name = {
    Text = "성제 애도 미사"
  },
  Item_69851_Desc = {
    Text = "앨워스 산 정상의 새롭게 싹튼 민들레 씨앗으로, 얼어붙은 땅에서 자라난 작은 들풀이 생기발랄한 생명을 뿜어냅니다.\n「설산 소멸 시·복각」기간 동안 한정 공급."
  },
  Item_69851_Name = {
    Text = "설산 민들레 씨앗"
  },
  Item_69852_Desc = {
    Text = "앨워스 산 정상에서 새로 태어난 상록수의 씨앗, 강인한 묘목은 결국 바람과 서리 비와 눈을 넘어서 거대한 나무로 자랄 것입니다.\n'눈산이 녹을 때·재현' 기간 한정 공급."
  },
  Item_69852_Name = {
    Text = "설산 상록수 씨앗"
  },
  Item_69853_Desc = {
    Text = "앨워스 산 정상에서 새로 태어난 순백의 꽃의 씨앗, 얼음과 눈은 그것의 가지와 잎을 이루고, 혹한도 그것의 향기를 꺾지 못합니다.\n'눈산이 녹을 때·재현' 기간 한정 공급."
  },
  Item_69853_Name = {
    Text = "설산 서리꽃 씨앗"
  },
  Item_69854_Desc = {
    Text = "필요해요 시를 읊어야만 열리는 신비한 상자입니다. \n꽃의 꿈을 설명하면 장미 한 다발을 선물합니다. \n“봄이 시들기 전에” 기간 동안 한정 판매됩니다."
  },
  Item_69854_Name = {
    Text = "꽃과 시의 꿈"
  },
  Item_69855_Desc = {
    Text = "필요해요 시를 암송해야만 시작되는 신비한 상자입니다. \n의상이 적절할 경우, 진실타래을 보여줍니다. \n“봄이 시들기 전에” 기간 동안 한정 판매됩니다."
  },
  Item_69855_Name = {
    Text = "의미와 시의 꿈"
  },
  Item_69856_Desc = {
    Text = "필요해요 시를 읊어야만 시작되는 신비한 상자입니다. \n그것에게 당신의 과거를 설명하면, 회상 하나를 선물로 드립니다. \n“봄이 시들기 전에” 기간 동안 제한적으로 공급됩니다."
  },
  Item_69856_Name = {
    Text = "마음과 시의 꿈"
  },
  Item_69860_Desc = {
    Text = "분명 인형에게는 없지만, 스스로 회전하는 기어 세트는 가까워지면 미세한 마찰 소리가 속삭임처럼 들린다."
  },
  Item_69860_Name = {
    Text = "이중나선 인형 부품"
  },
  Item_69861_Desc = {
    Text = "해우소점에서 판매하는 선물상자는 백화점에서 파는 최신 상품보다 더 정교하며, 진짜 머리를 사용해 교환해야 합니다. \n“비 마을의 그림자” 기간 동안 한정 공급됩니다."
  },
  Item_69861_Name = {
    Text = "잡다한 마녀 선물 상자"
  },
  Item_69862_Desc = {
    Text = "해우상점에서 판매하는 선물상자로, 전 세계 각지의 희귀한 보물들을 찾을 수 있으며, 신선하고 완전한 머리로 교환해야 합니다.\n“비 마을의 그림자” 기간 한정으로 제공됩니다."
  },
  Item_69862_Name = {
    Text = "신기한 마녀 선물 상자"
  },
  Item_69863_Desc = {
    Text = "해우소점에서 판매하는 선물상자는 점주 개인 창고에서 꺼낸 비밀 보물로, 들어본 적 없는 신기한 물품들로 가득 차 있습니다. 수집할 가치가 있는 아름다운 머리로 교환해야 합니다.\n“비 마을의 그림자” 기간 동안 한정 공급됩니다."
  },
  Item_69863_Name = {
    Text = "비장의 마녀 선물 상자"
  },
  Item_69867_Desc = {
    Text = "어떤 숙녀가 보내준 오후 차회 초대장, 맛있는 디저트를 즐겨보세요. 양인형과 작은 곰과 함께 춤추기 바랍니다. \n“별들이 제자리에 있습니다” 축제 기간 동안 한정 제공됩니다."
  },
  Item_69867_Name = {
    Text = "숙녀의 초대장 선물"
  },
  Item_69868_Desc = {
    Text = "어떤 숙녀와 같은 양장 드레스로, 착용하면 숙녀의 우아하고 고귀한 기품을 획득할 수 있습니다. \n“별들이 제자리에 있습니다” 기간 동안 한정 판매됩니다."
  },
  Item_69868_Name = {
    Text = "숙녀의 드레스 선물"
  },
  Item_69869_Desc = {
    Text = "어떤 숙녀와 같은 우산으로, 펼칠 때 숙녀가 결코 고개를 숙이지 않는 자신감을 얻을 수 있습니다. \n“별들이 제자리에 있습니다” 기간 동안 한정 판매됩니다."
  },
  Item_69869_Name = {
    Text = "숙녀의 양산 선물"
  },
  Item_69870_Desc = {
    Text = "유명한 상업 항로가 그려진 해도 한 장으로, 왕래하는 상인들이 순조롭게 항구에 도착할 수 있도록 안내합니다.\n「폭우 속에서 흔들림」기간 동안 한정 공급."
  },
  Item_69870_Name = {
    Text = "금빛 항로의 인도"
  },
  Item_69871_Desc = {
    Text = "클레멘타인의 심리 클리닉을 위해 특별 제작된 약제처방은, 장기적으로 재발하는 정신적 장애를 억제할 수 있습니다. 「기억의 깊은 곳에 묻혀 있을 때」 한정적으로 공급됩니다."
  },
  Item_69871_Name = {
    Text = "부정성 광기 처방전"
  },
  Item_69872_Desc = {
    Text = "클레멘타인의 심리 클리닉의 특제 약방은 영원히 광기의 심연에 빠진 사람을 구할 수 있습니다.「기억 아래 묻힌」기간 동안 한정 공급됩니다."
  },
  Item_69872_Name = {
    Text = "영구 광기 처방전"
  },
  Item_69873_Desc = {
    Text = "클레멘타인의 심리 클리닉의 특제 약방은 일시적인 심리적 상처를 치유할 수 있습니다.「기억 아래 묻힌」기간 동안 한정 공급됩니다."
  },
  Item_69873_Name = {
    Text = "응급 광기 처방전전"
  },
  Item_69874_Desc = {
    Text = "깊은 바다에서 넘쳐흐르는 물결이 의식의 경계를 충격합니다. \n이상한 꿈의 침식을 막기 위한 의식은 “심연의 제사” 기간 동안 한정 제공됩니다."
  },
  Item_69874_Name = {
    Text = "침식 방어 의식"
  },
  Item_69875_Desc = {
    Text = "그 깊고 어두운 곳에 깊은 잠한 왕의 탄생은 신식의 바다 전체를 왜곡할 것이다. \n이질적인 꿈의 침식에 저항하기 위한 의식은 “심연의 제사” 기간 한정으로 이용 가능합니다."
  },
  Item_69875_Name = {
    Text = "신왕 탄생 의식"
  },
  Item_69876_Desc = {
    Text = "이몽시계의 천재도 정신 공명을 통해 수호자의 영지를 방해합니다. \n 이몽 침식에 저항하기 위한 의식은 “심연의 제사” 기간 동안 한정 제공됩니다."
  },
  Item_69876_Name = {
    Text = "재앙 경계 의식"
  },
  Item_69877_Desc = {
    Text = "숨겨진 항로가 그려진 해도 한 장으로, 항로를 따라 가면 쉴 수 있는 작은 섬을 발견할 수 있습니다.\n「폭우 속에서 흔들림」기간 동안 한정 공급."
  },
  Item_69877_Name = {
    Text = "푸른 바다의 피난처"
  },
  Item_69885_Desc = {
    Text = "정교하고 세밀한 인형 부품, 기술과 광기의 반짝임."
  },
  Item_69885_Name = {
    Text = "정제된 인형 부품"
  },
  Item_69889_Desc = {
    Text = "주문으로 봉인된 청동 상자로, 그 안에는 상공에서 올린 물자가 들어 있다. 이미 기초 제령 의식을 거쳤으므로 개봉자에게 어떠한 위험도 초래하지 않는다.\n그곳은 너무 가난해서, 최고의 공물이라 해도 이 정도 수준밖에 안 돼. ——케디구라"
  },
  Item_69889_Name = {
    Text = "청동이 바치는 「선물」"
  },
  Item_69890_Desc = {
    Text = "심연의 기운을 내뿜는 거대한 상자로, 그 위에 짙은 붉은 안개가 감돌고 있다. 안에는 막대한 양의 물자가 들어 있지만, 개봉 시 반드시 전문 인력에게 알려 협조를 받아야 한다.\n그렇게 긴장하지 않아도 돼, 위에 있던 위험은 이미 제거했어. 다만 이 시각 효과만 남겨둔 거야, 그래야 이게 어디서 왔는지 알 수 있으니까. ——케디구라"
  },
  Item_69890_Name = {
    Text = "진홍 심연의 「선물」"
  },
  Item_69891_Desc = {
    Text = "금빛 광휘가 반짝이는 용기로, 용기 가장자리에서 액체 황금이 끊임없이 흐르는 것을 볼 수 있으며, 안에는 값비싼 공물이 들어 있다.\n솔직히 말하면, 이 상자가 안에 든 것보다 비싸다고 생각해. 하지만 물건이 너에게 줄 수 있는 도움은 한계가 있잖아, 그렇지? ——케디구라"
  },
  Item_69891_Name = {
    Text = "황금이 흐르는 「선물」"
  },
  Item_69892_Desc = {
    Text = "영원히 아버지 신, 《기하학 원론》, 그리고 의사의 처방을 의심하지 마십시오. \n보안관의 신체적, 정신적 건강을 보장하기 위한 좋은 처방으로, “다중 치유” 기간 동안 한정적으로 제공됩니다."
  },
  Item_69892_Name = {
    Text = "해리 회복 치료법"
  },
  Item_69893_Desc = {
    Text = "한 번의 치료가 효과가 없으면 어떻게 하나요? 그럼 다시 한 번의 치료를 해보세요! \n수호자의 신체적, 정신적 건강을 보장하기 위한 좋은 처방으로, “다중 치유” 기간 동안 한정 제공됩니다."
  },
  Item_69893_Name = {
    Text = "해리 강화 치료법"
  },
  Item_69894_Desc = {
    Text = "만약 인격이 분열되면 어떻게 하나? 걱정하지 마세요, 미사그는 이미 준비가 되어 있어요! \n수호자의 신체적, 정신적 건강을 보장하기 위한 좋은 방법으로, “다중 치유” 기간 동안 한정적으로 제공됩니다."
  },
  Item_69894_Name = {
    Text = "해리 급성 치료법"
  },
  Item_69895_Desc = {
    Text = "고대 항로가 그려진 해도 한 의뢰, 그 곳에는 전설적인 보물이 숨겨져 있다고 한다.\n「폭우 속에서 흔들리다」 동안 한정 공급됩니다."
  },
  Item_69895_Name = {
    Text = "심해에 숨겨진 보물"
  },
  Item_69896_Desc = {
    Text = "장사자 도시 왕가의 연회 음식은, 식인귀의 왕이 직접 만든 메인 요리로, 모든 손님이 꿈꾸는 요리입니다.\n「죽은 자의 미학」 기간 동안 한정 공급됩니다."
  },
  Item_69896_Name = {
    Text = "제신절 메인 코스"
  },
  Item_69897_Desc = {
    Text = "장사자 도시 왕가의 연회 음식은, 모든 수프가 엄선된 재료로 조리됩니다.\n「죽은 자의 미학」 기간 동안 한정 공급됩니다."
  },
  Item_69897_Name = {
    Text = "제신절 수프"
  },
  Item_69898_Desc = {
    Text = "장사자 도시 왕가의 연회 음식은, 심지어 전채도 정성이 담긴 작품입니다.\n「죽은 자의 미학」 기간 동안 한정 공급됩니다."
  },
  Item_69898_Name = {
    Text = "제신절 전채"
  },
  Item_69899_Desc = {
    Text = "스토리의 시작, 마법의 은심 필름이 사라졌다. 이는 여자아이와 주인의 미스터리 스토리다. \n “이야기의 마법” 기간 동안 한정 제공됩니다."
  },
  Item_69899_Name = {
    Text = "미스터리 스토리 필름"
  },
  Item_69900_Desc = {
    Text = "스토리의 간주, 우스꽝스러운 아마추어 배우가 빛나는 등장, 이것은 여자아이와 괴도의 코미디 스토리입니다.\n“이야기의 마법” 기간 동안 한정 제공됩니다."
  },
  Item_69900_Name = {
    Text = "코미디 스토리 필름"
  },
  Item_69901_Desc = {
    Text = "이야기의 결말, 동료의 석양 속 그림자 모습이 앨범에 담겼습니다. 이는 소녀와 고래의 환상적인 이야기입니다. \n “이야기의 마법” 기간 동안 한정 판매됩니다."
  },
  Item_69901_Name = {
    Text = "판타지 스토리 필름"
  },
  Item_69902_Desc = {
    Text = "부식된 인형의 부품을 어떻게 부식시켜야 할지 모르겠는데, 녹슬어 보이는 금속 상처에서 검은색 농혈이 흘러나오고 있다."
  },
  Item_69902_Name = {
    Text = "녹슨 인형 부품"
  },
  Item_69985_Desc = {
    Text = "궁극의 문살이 열리며, 원초에 더욱 가까운 힘을 가져온다—— 누구도 그를 두려워하지 않으며, 누구도 그를 동경하지 않는다. \n 미사그 지하 블랙풀에서 생산된 신비로운 영핵은 문 뒤로부터의 힘에 의해 정제되어 원초의 본질에 더욱 가까워지며, 깨어남체가 상상할 수 없는 높은 수준으로 향상될 수 있도록 돕는다."
  },
  Item_69985_Name = {
    Text = "원초 영핵 정수"
  },
  Item_69986_Desc = {
    Text = "흑수지에 산재한 파편들은 궁극의 문이 비추는 빛 속에서 원초의 힘이 도래하기를 기다리고 있다. \n미사그 지하에서 산출된 신비로운 파편들은 문 뒤로로부터의 힘에 의해 정제되어 정수 원초 영핵을 합성할 수 있다."
  },
  Item_69986_Name = {
    Text = "영핵 정수 파편"
  },
  Item_70143_Desc = {
    Text = "「욕망의 번식」에서 교환하는 데 사용하는 아이템.\n\n작고 동그란 씨앗 하나.\n결국 싹을 틔우고, 뿌리를 내리며, 하늘을 가리는 무성한 큰 나무로 성장할 것입니다.\n\n최소 {s1}개 드롭"
  },
  Item_70143_Name = {
    Text = "풍요의 종자"
  },
  Item_70144_Desc = {
    Text = "「욕망의 번식」에서 교환하는 데 사용하는 아이템.\n\n작고 동그란 씨앗 하나.\n결국 싹을 틔우고, 뿌리를 내리며, 하늘을 가리는 무성한 큰 나무로 성장할 것입니다.\n\n최소 {s1}개 드롭"
