  Item_70292_Desc = {
    Text = "“별을 넘어 · 한정 예약 구매”에서 획득할 수 있습니다. \n“별들이 올바른 위치에 도달할 때, 위대한 @1이 세상에 강림합니다.”"
  },
  Item_70292_Name = {
    Text = "별들이 교차하는 순간"
  },
  Item_70292_StoryDesc = {
    Text = "V2.0 버전 예약 구매 이벤트"
  },
  Item_70919_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “별들의 가호”를 선택할 수 있습니다.\n\n그는 그 왕관을 선택했고, 그 왕관도 그를 선택했다.\n새 왕과 고대 신의 영혼이 한순간 공명하며, 하늘을 가리는 거대한 그림자가 그의 뒤에 드리워져 국가에 영원한 안녕을 가져다주었다."
  },
  Item_70919_Name = {
    Text = "별들의 가호"
  },
  Item_70919_StoryDesc = {
    Text = "그는 그 왕관을 선택했고, 그 왕관도 그를 선택했다. \n새 왕과 고대 신의 영혼이 한순간 공명하며, 하늘을 가리는 거대한 그림자가 그의 뒤에 드리워져 국가에 영원한 안녕을 가져다주었다."
  },
  Item_71281_Desc = {
    Text = "고난받는 영혼이여, 절대로 희망을 잃지 마세요. 자비로운 주교가 당신을 위해 아버지 신께 기도를 올릴 것입니다. \n「영혼의 목자·복제」 기간 동안 한정 제공됩니다."
  },
  Item_71281_Name = {
    Text = "미사 중의 기도"
  },
  Item_71282_Desc = {
    Text = "고난받은 영혼이여, 당신은 보상을 받을 것입니다. 자비로운 주교가 아버지 신의 축복을 내려줄 것입니다. \n“영혼의 목자·복제” 기간 동안 한정 제공됩니다."
  },
  Item_71282_Name = {
    Text = "미사 후의 축복"
  },
  Item_71283_Desc = {
    Text = "고난을 겪는 영혼이여, 혼란스러움이 필요하지 않아요. 자비로운 주님의 교회가 당신에게 방향을 제시할 것입니다. \n“영혼의 목자·복제” 기간 동안 한정 제공됩니다."
  },
  Item_71283_Name = {
    Text = "미사 전의 인도"
  },
  Item_71393_Desc = {
    Text = "시대 최첨단 기술을 대표하는 정밀 톱니바퀴로, 인형의 노후화된 부분을 교체할 수 있다.\n돌이 신체 수리에 사용하는 톱니바퀴 부품. 상점에서 필요한 물자를 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
