  Item_72089_Desc = {
    Text = "\"도토리는 모험의 시작을 상징합니다. 우리는 더 많은 도토리가 필요해요!\" — 이그나티스. 이그나티스의 마력으로 응축된 도토리로, \"라운드 특별상\"에서 물자를 교환하는 데 사용됩니다."
  },
  Item_72089_Name = {
    Text = "마법의 도토리"
  },
  Item_72089_StoryDesc = {
    Text = "역전의 턴 연동"
  },
  Item_72095_Desc = {
    Text = "이 열쇠를 기록한 후, 「페이즈 대결」 편성 시 열쇠 능력: 「주점의 문」을 선택할 수 있습니다.\n\n한 세계가 막을 내리면, 다른 세계의 서막이 시작됩니다. 스토리는 미주와 함께 끊임없이 사람들에 의해 전해지지만, 시간은 모든 일에 대한 답을 써 내려갑니다."
  },
  Item_72095_Name = {
    Text = "주점의 문"
  },
  Item_72095_StoryDesc = {
    Text = "한 세계가 막을 내리면, 다른 세계에서 막이 오른다. 이야기들은 좋은 술과 함께 끊임없이 사람들에 의해 전해지겠지만, 시간이 이 모든 일의 답을 써내려갈 것이다."
  },
  Item_72824_Desc = {
    Text = "헤플랜드 대륙에 위치한 작은 주점에는 다른 세계를 연결하는 차원의 문이 있습니다. \n주점 주인 이그나티스는 과거 영웅들의 이야기를 전하기 위해 '만상패'라는 카드 게임을 만들었습니다."
  },
  Item_72824_Name = {
