    Text = "케이시·--)"
  },
  Item_73463_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73464_Desc = {
    Text = "우…… 페이즈 대결이 너무 어렵다…… 가장 어려운 곡을 연주하는 것보다 더 어렵다! 리아 누나, 초보자 카드 덱 추천해 줘……"
  },
  Item_73464_EmojiName = {Text = "우는"},
  Item_73464_Name = {
    Text = "베티·울음"
  },
  Item_73464_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73465_Desc = {
    Text = "히히, 내 차례야! 역시 페이즈 대결이나 만상패도 중요하지만, 결국은 마지막에 판세를 뒤집는 이 턴이 핵심이야!"
  },
  Item_73465_EmojiName = {
    Text = "내 차례야"
  },
  Item_73465_Name = {
    Text = "이그나티스·내 차례야"
  },
  Item_73465_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73466_Desc = {
    Text = "이세계의 우정과 만상주관의 모든 분들을 위해, 건배!"
  },
  Item_73466_EmojiName = {
    Text = "나의 턴·건배"
  },
  Item_73466_Name = {
    Text = "나의 턴·건배"
  },
  Item_73466_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73467_Desc = {
    Text = "차원 파동 방정식? 은심 추출 원리? 그것이 무엇인가요? 미안해요… 빛의 여신은 저에게 그런 것을 가르쳐주지 않았습니다."
  },
  Item_73467_EmojiName = {Text = "의혹"},
  Item_73467_Name = {
    Text = "보니·의아함"
  },
  Item_73467_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73468_Desc = {
    Text = "연결이 때때로……조금 불안정한 경우가 있지만, 의심의 여지 없이 이는 훌륭한 대결이었습니다! 끝나고 나서 친구로 추가하고 추천을 눌러 주시면 어떨까요?"
  },
  Item_73468_EmojiName = {
    Text = "역전의 턴: 잘했어"
  },
  Item_73468_Name = {
    Text = "역전의 턴: 잘했어"
  },
  Item_73468_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73469_Desc = {
    Text = "이 카드가 페이즈 대결에서 어떻게 이런 효과가 있어! 불복 불복, 한 번 더 해볼까! 다음에는 꼭 이길 거야!"
  },
  Item_73469_EmojiName = {
    Text = "기분 나쁘다"
  },
  Item_73469_Name = {
    Text = "아비스·불복기"
  },
  Item_73469_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73471_Desc = {
    Text = "와! 어떻게 또 이렇게 됐어! 끝장났어 와!! 사장님께서 절대로 놓아두지 않으실타래 거야 아아아! 그저… 은심모만 찾으면 되는데……"
  },
  Item_73471_EmojiName = {Text = "충격"},
  Item_73471_Name = {
    Text = "라이트·쇼크"
  },
  Item_73471_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73472_Desc = {
    Text = "원래 이 명령 장치의 동작 원리는 이렇게 되어 있었군요. 정말 흥미롭네요, 프리다도 분명 관심을 가질 거예요!"
  },
  Item_73472_EmojiName = {
    Text = "아하! 이해가 되네요"
  },
  Item_73472_Name = {
    Text = "두란·화연개랑"
  },
  Item_73472_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73473_Desc = {
    Text = "이미 사장님이 그렇게 말씀하셨으니……히히히! 그렇다면 카드 마스터……아니, 그렇다면 수호자님, 많이 가르쳐 주세요!"
  },
  Item_73473_EmojiName = {
    Text = "아, 나도 올라가야 돼"
  },
  Item_73473_Name = {
    Text = "리아·에이, 나도 올라가야 돼"
  },
  Item_73473_StoryDesc = {
    Text = "턴 역전 연동 이벤트"
  },
  Item_73582_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_73582_Name = {
    Text = "아직 보내지 않은 꽃"
  },
  Item_73582_StoryDesc = {
    Text = "너무 오랫동안 방치되어 시들어버린 꽃 한 다발.\n주인을 기다려보지만 영원히 돌아오지 않는다."
  },
  Item_74093_Desc = {
    Text = "먼 별들이 반짝일 때 남긴 부서진 꿈. 그 속의 영성을 감지하면 육안으로 관측할 수 없는 미래를 엿볼 수 있다."
  },
  Item_74093_Name = {
    Text = "분열된 꿈"
  },
  Item_74143_Desc = {
    Text = "먼 별들이 반짝일 때 남긴 완전한 꿈. 고대의 영혼들은 예정된 미래를 드러낸다——별들이 곧 교차하리라."
  },
  Item_74143_Name = {
    Text = "별들의 잔영"
  },
  Item_74200_Desc = {
    Text = "잿빛 안개 도시에 산일된 감정 입자로, 접촉하면 누군가의 절망적인 포효가 들리는 듯합니다.\n수호자가 조사 이벤트 「안개 도시로의 귀환」에서의 공명을 높이는 데 사용됩니다."
  },
  Item_74200_Name = {
    Text = "절멸의 심장"
  },
  Item_75778_Desc = {
    Text = "바싹 마르고 창백한 야수의 두개골로, 가끔 이를 가는 듯한 딸깍 소리를 낸다. 아마도 착각이겠지.\n저 가게 주인의 마음에 들 것 같다.\n\n최소 {s1}개 드롭"
  },
  Item_75778_Name = {
    Text = "창백한 야수의 두개골"
