  Item_75840_Name = {
    Text = "진홍빛 야수의 두개골"
  },
  Item_76215_Desc = {
    Text = "해금 후, “강림 기행”의 전부 태스크를 완료하면 다음과 같은 추가 보상을 획득할 수 있습니다"
  },
  Item_76215_Name = {
    Text = "강림 기행"
  },
  Item_76216_Desc = {
    Text = "해금 후, “이세기 행”의 전부 태스크를 완료하면 추가로 다음과 같은 보상을 획득할 수 있습니다."
  },
  Item_76216_Name = {
    Text = "이세계 기행"
  },
  Item_76294_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
  },
  Item_76294_Name = {
    Text = "조사 과정 특전·성신편 Ⅰ"
  },
  Item_77858_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 흑파라오를 획득할 경우 전환되어 사용되며, 흑파라오의 기령을 활성화하는 데 사용됩니다."
  },
  Item_77858_Name = {
    Text = "파편 · 네프렌카"
  },
  Item_77858_StoryDesc = {
    Text = "중복으로 흑파라오를 획득할 경우 전환되어 사용되며, 흑파라오의 기령을 활성화하는 데 사용됩니다."
  },
  Item_77859_Desc = {
    Text = "일상적으로 방패 획득을 안정적으로 늘리고 초차원 턴 동안 폭발적으로 광기를 얻으며, 기회가 왔을 때 팀에 대량의 크리티컬 데미지를 제공합니다."
  },
  Item_77859_Name = {
    Text = "견딜 수 없는 자유"
  },
  Item_77859_StoryDesc = {
    Text = "오늘날까지도 카스토르는 자유의 진정한 의미를 말할 수 없다.\n 그는 쌍둥이 중 더 어리석은 쪽이라고 자주 느끼며, 소년 시절부터 둔하게 폴룩스 뒤를 따르며 동생이 한없이 기발한 기상천외의 아이디어를 이야기하는 것을 듣곤 했다.\n 지루하고 무감각한 수행 생활 속에서 그는 그 한 줄기 편안한 밝은 색을 가지는 것이 가장 행복한 일이라고 생각했지만, 유리에트가 폴룩스에게 정기적인 변형 의식을 명령하기 전까지였다.\n 끝없는 고통이 온전히 폴룩스 한 사람에게 쏟아지자, 카스토르는 어쩔 줄 몰라하며 동생의 곁에 있었고, 그 얼굴에 떠오르던 미소가 점점 줄어드는 것을 보면서 자신이 할 수 있는 일이 아무것도 없다는 것을 깨달았다.\n “자유가 무엇인지 아는가?” 깊은 밤, 폴룩스는 두 사람이 이미 낡아버린 사본을 품에 안고 조용히 카스토르에게 물었다.\n 카스토르는 고개를 흔들었다.\n “그렇다면, 밖의 세상을 보고 싶니? 형?”\n 카스토르는 소스라치게 놀라며 멈춰섰고, 그는 폴룩스가 추구하고자 하는 것을 이해한 듯했다. 그것은 그가 한 번도 본 적이 없는, 메마른 글자 속에만 존재하고, 자신의 상상 밖에 있는 것들이었다.\n 그는 이렇게 대역죄이자 경악스러운 생각에 깊은 충격을 받았고, 그는 침묵 속에, 아마도 오랜 시간이 흘렀거나, 아니면 몇 번의 숨결이 지난 후에 두려움 없이 고개를 끄덕였다.\n 비록 그것이 온 교회에 맞서야 하고, 자신의 생명을 바쳐야 한다 할지라도.\n 그래서 한 쌍의 새가 결코 나아가지 않았던 감옥을 날아 나갔지만, 안타깝게도 그들은 자유의 대가가 이렇게 감당할 수 없는 무게가 될 것이라는 생각을 전혀 하지 못했다.\n 사냥꾼의 총소리가 울리고, 새는 공중에서 떨어졌다.\n 카스토르는 겨우 자유의 맛을 느끼기도 전에 동생의 자유를 향한 날개가 뽑히는 것을 눈앞에서 지켜보았다.\n 유리에트의 무서운 분노에 직면한, 얼굴이 창백하고 떨리는 동생은 인파를 등에 지고 자신에게 결코 굴복하지 않는 미소를 지어 보였다.\n “버텨, 자유를 위해서.”\n 카스토르는 폴룩스의 그 무언의 입모양을 계속 떠올리며, 그가 흐릿한 고통 속에서 그 두 신념 같은 글자를 새기고 나서야 다시 폴룩스와 만났다. 그리고 그때 그는 놀랍게도, 항상 자신을 이끌어 주던 사람이 이미 이 두 글자를 무정하게 던져버렸다는 것을 깨달았다."
  },
  Item_77862_Name = {Text = "샨타크"},
  Item_77863_Name = {Text = "픽맨"},
  Item_77865_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n피크맨을 중복으로 획득할 때 전환하여 획득하며, 피크맨의 기령을 활성화하는 데 사용됩니다."
  },
