  Item_77867_Name = {Text = "벌처"},
  Item_77868_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 독수리를 획득할 때 전환하여 독수리의 기령을 활성화합니다."
