  Item_77875_Name = {
    Text = "카스토르"
  },
  Item_77876_Name = {
    Text = "클레멘타인"
  },
  Item_77877_Desc = {
    Text = "소지자가 주는 광기와 힘을 증폭시킬 수 있으며, 광기 폭발을 방출한 후 다른 웨이크업 바디의 다음 광기 폭발 효과를 증폭시키고, 혈육 경계역의 웨이크업 바디가 흡수 효과를 발동할 때 대량의 광기를 회복합니다!"
  },
  Item_77877_Name = {
    Text = "사실타래주의 패뮤"
  },
  Item_77877_StoryDesc = {
    Text = "그는 교회의 첨탑이 양초처럼 녹아내려 사제의 하얀 날개 위에 떨어지는 것을 보았다. 스테인드글라스의 성인상이 극도로 빠른 속도로 썩어 해골로 변하고, 또 순간적으로 아기로 되돌아간다. 날카롭고 부드러운 기하학적 도형이 신도의 입에서 읊어지며, 홀을 가득 채운다.\n그는 기차역의 공간이 반복적으로 비유클리드 공간으로 접히는 것을 보았고, 멀리 있는 플랫폼이 손이 닿을 듯 가까워지고, 가까운 매표소는 도달할 수 없는 곳이 된다. 홀의 시계는 반시계 방향으로 회전하고, 마치 고목 같은 인파가 보이지 않는 선에 의해 끌려 후퇴하며 걷고, 진한 보라색 연기 같은 안개가 구름에서 기차의 연통으로 흘러들어간다.\n그는 숲 속의 “공간”이 실타래체로 응집되는 것을 보았다. 나무, 바위, 덩굴은 단지 “공간”의 경계를 그린 반투명한 윤곽선이다. 백조의 깃털은 끊임없이 변하는 모자이크 색조로, 그들이 지나간 곳의 호수는 반투명한 색유리로 응고된다. 연인들이 기대고 있는 긴 의자 아래, 선명한 오렌지색 그림자가 주인의 발목을 갉아먹으려 하고 있다.\n그는 오페라 하우스의 음표가 빗방울처럼 관객석에 떨어지는 것을 보았고, 그는 묘지가 미세하게 울렁거리는 것을 보았다. 마치 숨 쉬는 거대한 괴물의 피부처럼……\n그는 많은 것을 보았다, 정말 많은 것을. 그는 자신이 본 것을 어머니, 선생님, 친구들에게 이야기했으며, 그가 본 것을 그림으로 담았다. 그는 자신의 눈에 비친 세계를 사람들 앞에 가져가고 싶었지만, 그의 곁에 있는 사람들은 점점 줄어들고, 하나의 세계가 그에게서 점점 멀어져 갔다.\n하지만 왜 그럴까? 그는 단지 자신이 본 것을 기록했을 뿐이다. 픽맨은 아무리 생각해도 이해할 수 없었다.\n슬픈 픽맨은 거울 앞에 서 있었다. 그는 식인귀가 그에게 날카로운 이빨이 가득한 입을 벌리고 있는 것을 보았다.\n“진실타래을 목격하는 것보다 더 중요한 것은 없다. 광란, 혼돈, 욕심……보러 갈래, 픽맨?”\n계시의 픽맨이 그에게 미소 지으며 그 거울 속으로 걸어 들어갔다.\n그는 그 극한의 광란의 진실타래을 직접 목격하고, 그것들을 자신의 캔버스 위에 충실타래히 그려내고 싶었다.\n그는 인간도 아니고, 식인귀도 아니다.\n그는 단지 사실타래주의 화가 픽맨일 뿐이다."
  },
  Item_77879_Name = {Text = "폴룩스"},
  Item_77880_Name = {Text = "카라부"},
  Item_77882_Desc = {
    Text = "광기 폭발은 더 많은 방패를 생성하는 동시에 팀의 크리티컬 데미지를 증가시키며, 더 많은 촉수가 있는 팀에서 더 눈에 띄는 성과를 보입니다."
  },
  Item_77882_Name = {
    Text = "성화 속 길잡이"
  },
  Item_77882_StoryDesc = {
    Text = "“우리는 세속의 동과 철로 별들의 궤적을 측정하지만, 무한한 심연은 그 자체의 알고리즘을 가지고 있으며, 변덕스럽다.”\n점점 가라앉는 유람선 안에서, 크퍼산트는 “항해자의 비가”를 읊조렸다.\n그녀는 이미 자신의 운명을 알고 있었고, 자신의 운명을 선택했기에 죽음 앞에서도 두려움이 없었고, 오직 평온함만이 있었다—— 평온하게 타오르고, 평온하게 마지막 항로를 완수했다.\n하지만 타오르는 불빛이 너무 뜨거워서 그녀는 앞길을 볼 수 없었고, 목소리를 낼 수도 없었으며, 깃발을 흔들 수도 없었다. 이렇게 불완전한 안내로 배가 제대로 항해할 수 있을까?\n그녀는 알지 못했고, 그래서 두려움과 걱정이 생겼다.\n이때 “항해자의 비가”는 안내를 주었다: “젊은 항해자여, 너는 언젠가 염수에 품에 안기고, 길잡이가 되는 인지의 불꽃으로 변할 것이다.”\n길잡이의 인지의 불꽃? 크퍼산트는 침묵했다. 그녀는 분명 수레주인들 사이에서 전해지는 성 앨르모의 불 이야기를 들은 적이 있었다. 그러나 평범한 인간의 몸이 어떻게 인간세상을 비추는 성스러운 불꽃으로 변할 수 있을까?\n하지만 희망이 희박하더라도, 크퍼산트는 마음속으로 끊임없이 기도했다: 자신의 의무를 다하고 마지막 안내 작업을 완료할 수 있기를.\n크퍼산트 자신 외에는 이 기도를 들을 수 있는 사람이 없었지만, 그것으로 충분했다——\n어둠 속에서, 은심은 융식점액을 양분으로 삼아 강렬한 빛을 발산하며 그녀의 마지막 소원을 이루었다.\n“조수의 검은 책이 너의 이름을 기록하고, 포효하는 몰아치는 파도가 너를 위해 영원한 진혼곡을 연주할 것이다.”\n그녀는 결국 “항해자의 비가”가 말한 대로, 바다에서 죽었다.\n하지만 그녀는 “항해자의 비가”를 초월했다.\n그것은 인간 항해사가 바다를 마주할 때의 오만함과 충고였지만, 이제 그녀는 성 앨르모의 불꽃이 되어 배를 영원히 인도하고 있다."
  },
  Item_77884_Name = {
    Text = "네프렌카"
  },
  Item_77885_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복 획득 시 케디구라로 전환하여 케디구라의 기령을 활성화하는 데 사용됩니다."
  },
  Item_77885_Name = {
    Text = "파편 · 카티구라"
  },
  Item_77885_StoryDesc = {
    Text = "중복 획득 시 케디구라로 전환 획득하여 케디구라의 기령을 활성화하는 데 사용됩니다。"
  },
  Item_77886_Name = {
    Text = "아라크네"
  },
  Item_77887_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n카스토르를 중복 획득할 때 전환하여 카스토르의 기령을 활성화합니다."
  },
  Item_77887_Name = {
    Text = "파편 · 카스토르"
  },
  Item_77887_StoryDesc = {
    Text = "카스토르를 중복 획득할 때 전환하여 카스토르의 기령을 활성화합니다."
  },
  Item_77888_Desc = {
    Text = "미쳐날뛰는 폭발의 기본 피해와 은열쇠 획득 능력을 대폭 증가시키며, '멸망'을 통해 개인의 광기 획득과 팀 광기의 증대 중에서 유연하게 선택할 수 있습니다."
  },
  Item_77888_Name = {
    Text = "숨겨진 고통"
  },
  Item_77888_StoryDesc = {
    Text = "클레멘타인은 강한 아이가 아니었기에, 병에 걸려 병과 점점 다가오는 죽음의 고통에 시달릴 때마다 깊은 밤에 깨어나, 소리 없이 울곤 했습니다.\n그리고 매번 울고 난 다음 날, 침대 머리맡에 항상 '선물'이 나타나곤 했습니다.\n화려하게 포장된 몇 개의 캔디, 그 시점에서 유행하는 머리 장식, 귀여운 플러시 곰...\n하지만 그녀에게 가장 인상 깊었던 것은 하나의 번데기 표본이었습니다.\n그 당시에 그녀는 병이 심각해져 침대에서 내려올 수 없었고, 그저 힘을 내어 그 표본을 높이 들어 올리며 투명 번데기 안의 생명을 크게 눈을 뜨고 응시하고 있었습니다.\n그 생명은 이미 잠들었지만, 그 생명은 영생을 얻었습니다.\n그리고 그녀는, 진정한 죽음에 직면했습니다.\n이를 생각하면서 그녀의 눈물이 소리 없이 떨어졌습니다. 그러나 한 쌍의 손이 그녀의 눈물을 닦아주었습니다.\n\"울지 마라, 클레멘타인. 언젠가 너도 이 번데기들처럼 새 생명을 얻을 거야.\"\n\"내가 너에게 새 생명을 주겠다.\"\n아빠는 절대로 거짓말을 하지 않으며, 적어도 그녀에게는 거짓말을 하지 않으므로 클레멘타인은 그 말을 전적으로 믿었습니다.\n그녀는 자신의 아빠를 신뢰하며, 그 모독의 산맥에 들어갈 때도 전혀 주저하지 않았으며, 혈육이 녹아내리는 극심한 고통을 견딜 때에도 불만을 가지지 않았습니다.\n왜냐하면 그녀는 이 모든 것이 새 생명을 얻기 위한 대가와 필수적인 과정이라는 것을 믿었기 때문입니다.\n모든 고통과 절망이 끝나면, 그녀는 병이 치유되고, '집'이라고 불리는 그 곳으로 돌아가 유일한 가족과 재회할 것입니다."
  },
  Item_77889_Desc = {
    Text = "소지자가 사용하는 명령 카드의 기본 데미지와 크리티컬 피해를 증가시키며, 주기적으로 소지자의 명령 카드가 입히는 최종 피해를 증가시킵니다. 초차원 턴에서는 두 배의 효과를 발휘할 수 있습니다!"
  },
  Item_77889_Name = {
    Text = "왜곡된 기사의 서사시"
  },
  Item_77889_StoryDesc = {
    Text = "폴룩스는 꿈을 꾸었습니다.\n 그는 은색 갑옷을 입고, 위엄 있는 왕의 손에서 달처럼 빛나는 긴 검을 받았습니다.\n 그리고 그는 거대한 백마에 올라타, 동굴로 달려갔습니다. 그가 깊은 땅속으로 들어갈수록 동굴 입구의 나무들은 속삭이는 듯한 미세한 소리를 내었습니다.\n 동굴 깊숙한 곳에는 어두운 녹색 그림자가 숨어 있었습니다. 그것은 육체처럼 거대한 몬스터였고, 괴이한 쌍눈에서는 녹색 빛이 뿜어져 나왔습니다.\n “국가에 해를 끼치는 몬스터여, 나는 너의 신성한 왕국에 대한 위협을 더 이상 허용할 수 없다. 오늘, 나는 이 정의의 검으로 너를 멸망시킬 것이다!”\n 그 괴물은 떨며, 마치 응답하는 듯한 무서운 포효를 내었습니다.\n 폴룩스는 그 언어를 이해하지 못했고, 그것의 말을 듣고 싶지도 않았습니다. 그는 보물을 높이 들고, 악의 기운을 뿜어내는 그 괴물과 싸우기 시작했습니다. 괴물의 촉수는 동굴의 어두운 경계에 퍼져 있었고, 빛나는 긴 검과 충돌하며 경쾌한 소리를 냈습니다.\n 모든 영웅 이야기의 결말처럼, 용감한 기사는 괴물의 등에 올라타, 분노의 외침과 함께 검의 끝을 괴물의 가슴에 찔러 넣었습니다.\n 괴물은 힘없이 쓰러졌고, 폴룩스는 안도감을 느끼며 숨을 고르며, 검 아래 천천히 퍼져가는 흔적을 멍하니 바라보았습니다—— 그 추하고 악한 존재의 몸에서 어찌하여 이렇게 따뜻하고 선홍빛의 피가 흐르고 있는 것일까?\n 그는 꿈에서 갑자기 깨어났고, 그 피가 손에 묻는 끈적한 감촉은 마치 사라지지 않는 듯했습니다. 그의 시선은 갑자기 카스토르가 소중히 간직한 오래된 책을 보았습니다. 그것은 침대 뒤의 틈새에 조심스럽게 숨겨져 있었습니다.\n 그는 그 책을 아무렇게나 펼쳤고, 마침내 카스토르가 자주 읽던 그 기사의 이야기가 나왔습니다. 책 페이지의 정중앙에는 이렇게 적혀 있었습니다:\n “악의 괴물이 용사에게 패배할 때, 모든 이가 하늘에서 이상한 현상을 보게 될 것이며, 태양은 어둠으로 변하고, 달은 피로 변할 것이다.”\n 폴룩스는 찡그리며, 이 오래된 책을 경시하여 원래 위치에 던졌고, 월광 아래에서 중얼거리며 기도하기 시작했습니다.\n “신의 종이 여러분에게 축복을 주기 위해 여기로 파송되었으며, 여러분의 죄를 씻어내고, 어둠에서 빛으로 돌아오게 하여, 모든 순결한 의인들과 함께 정토에 들어가게 하소서……”\n 빛나는 자는 그의 성실타래한 서번트를 비추지 않았고, 악몽이 가져온 불안은 여전히 그의 심장 깊숙이 떨리고 있었습니다. 그것은 그가 깊은 잠 중에 조용히 울고 있는 영혼이었습니다."
  },
  Item_77890_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n클레멘타인을 중복으로 획득할 때 전환하여 기령을 활성화하는 데 사용됩니다."
  },
  Item_77890_Name = {
