  Item_77893_Desc = {
    Text = "보유자가 생성하는 보호막을 증폭할 수 있으며, 주기적으로 「추격」 효과 발동 시 대량의 피해 강화 효과를 제공하고, 「차원 이동」 효과 발동 시 대량의 광기를 획득합니다."
  },
  Item_77893_Name = {
    Text = "영원한 직조의 그물"
  },
  Item_77893_StoryDesc = {
    Text = "아라크네는 자신이 필연적으로 실타래패할 일을 하고 있다는 것을 알고 있었다. \n 그녀는 가볍게 물레를 돌리며, 날마다 인간의 슬픔과 기쁨, 왕조의 흥망, 별불꽃 같은 시와 사랑을 시공을 초월한 거대한 그물에 엮어 넣었다. \n 그녀는 매우 잘하고 있었다, 정확하고, 억제하며, 부드럽게. 잘못된 것들을 배제하고, 올바른 것들을 선택했다. \n 대대손손 새 생명의 미소가 드러나고, 수많은 문명이 재 속에서 새로운 역사를 써내려갔다. 그러나 엮음에서 비롯된 기쁨과 엮음에서 생긴 피로, 모든 부드러운 감정은 영원한 고역의 마모 속에서 조용히 시들어 버렸다. 그녀는 스스로 취약함을 끊어내고, 오직 깨어 있는 의지만을 남겨두었다. 매 선택이 연약함이 아닌 책임에서 비롯되도록 하기 위해서였다. \n 그러나 가장 깊은 비극은 고역 그 자체가 아니라, 그녀가 어떻게 수선하고 엮어도, 세상은 여전히 그 조용한 공허로 나아갈 것이라는 것을 분명히 알고 있다는 것이다. 문명은 취약한 모래성처럼, 조수는 결국 찾아온다. 그녀의 노력은 관중 없는 공연, 결코 회상이 없는 지켜봄이었다. \n \"운명은 이미 우리를 영원한 고독에 유죄 판결을 내렸으니, 왜 이 잔인한 처벌을 받아들여야 하는가?\" \n \"찢고, 파괴하라… 그러면 이 고역에서 탈출할 수 있다…\" \n 그녀는 시선을 아래로 향하고, 그 불필요한 생각들을 가볍게 잘라내며, 계속해서 지루하고 집중하여 엮고, 유지하고, 울고, 견디고 있었다… \n 모든 무의미한 몸부림과 모든 해결되지 않은 운명은 이미 이 그물에 엮여 있었다. \n 그리고 그물의 중심에서, 그녀는 자신을 보았다."
  },
  Item_77894_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식이다. 미사그는 신비로운 의식을 통해 깨어남체의 영식을 깨우고, 깨우침을 받은 깨어남체는 정신 능력을 영구히 강화한다.\n반복적으로 아라크네를 얻을 때 전환하여 아라크네의 기령을 활성화하는 데 사용된다."
  },
