  },
  Item_77909_StoryDesc = {
    Text = "대부분의 경우, 죽음은 항상 조용히 찾아온다. 인간의 의식이 반응할 겨를도 없이, 죽음의 신은 조용히 다가와서 그 신선하고 연약한 생명을 빼앗아 간다.\n하지만 전해지는 바에 따르면, 알려지지 않은 어떤 사막에 호박색의 죽음의 신이 존재한다고 한다. 그녀는 선언을 한 후, 호박의 불꽃과 호박의 총으로 호박색의 죽음을 가져온다.\n남자는 달빛 아래의 모래바다에 서서 총을 쥔 손이 계속 떨리고 있다. 그는 케이티굴라의 호박색 모습에 시선을 잠금하고, 조금도 긴장을 풀지 못하고 있다.\n차가운 땀이 그의 이마에서 떨어져, 뒤에 있는 모든 사람의 마음에 떨어진다. 그는 데려온 사람이 많지만, 지금 유용한 사람은 거의 없다.\n그는 이해하지 못한다. 단지 위탁받아 이미 사람이 없는 창고를 약식할 뿐인데, 왜 전설 속의 죽음의 신을 만나게 되었는지.\n「너가 말하는 그 죽음의 신? 그건 그냥 예전의 지루한 소문일 뿐이야.」\n케이티굴라는 아무렇지 않게 말했다.\n「나는 그것들을 호박색으로 칠했어. 아마 너도 그 위에 떨어지지 않은 페인트를 찾을 수 있을 거야?」\n그녀는 당당하게 앞에 있는 사람에게 손에 쥔 두 총을 보여주었다.\n「총구에서 나오는 호박색 불꽃은 어떤 특별한 물질을 뿌린 거야.」\n그녀의 손가락이 총구에 깊숙이 들어가, 한 바퀴 돌린 후 알 수 없는 가루를 꺼내왔다.\n「소위 죽음의 신은 내가 만들어낸 하나의 형상일 뿐이야.」\n「그건 강력하고 신비로우며 무소불위야.」\n「그것은 나에게 무능한 하찮은 자들을 위협하는 데 도움을 줄 수 있어.」\n그녀는 거만하게 말했다. 눈앞의 사람이 점점 더 사나워지는 시선을 전혀 신경 쓰지 않는다.\n그녀는 마치 아무도 없는 것처럼 말하며, 위험이 이미 다가오고 있다는 것을 전혀 느끼지 못한다.\n총알이 그녀를 향해 쏟아질 때, 그녀의 눈에는 충격과 혼란이 드러났다.\n그것은 단지 잠재의식 속의 흥분과 광란을 가리기 위한 것이었다.\n…………………………\n총소리가 멈추고, 모든 것이 그녀가 생각한 대로였다.\n그녀는 전장 중앙에 서 있고, 주위는 모두 그을음 자국으로 가득하다.\n케이티굴라는 두 가지 동작만 했다—총을 들고, 발사했다.\n그녀가 긴 총을 들었을 때, 죽음의 신은 만물 뒤에서 춤추며 평등하게 죽음의 예고를 내렸다.\n그녀가 방아쇠를 당기자, 불꽃이 모든 것을 휩쓸어 세계에 호박색의 꽃바다를 바쳤다.\n「그것들은 나와 함께 많은 세월을 걸어왔고, 수많은 피와 죽음을 목격했다.」\n「그것들은 강제로 거짓의 옷을 입어, 내 약함과 무력함을 가리기 위해 사용되었다.」\n「이제, 그것들은 더 이상 소문이 아니다.」"
  },
