  },
  Item_77946_Name = {Text = "픽맨"},
  Item_78731_Desc = {
    Text = "“암조충명·한정 예약 구매”에서 획득 가능합니다. \n“이해할 수 없는 윙윙거림의 공진 속에서 현실타래은 혈육으로 구축된 소리의 그물 감옥에 휘말리고 있습니다.”"
  },
  Item_78731_Name = {
    Text = "검은 조류 속 벌레의 울음"
  },
  Item_78731_StoryDesc = {
    Text = "V2.2 버전 예약 구매 이벤트"
  },
  Item_78732_Desc = {
    Text = "구매 후, 모든 예약 구매 보상을 순차적으로 받을 수 있습니다."
  },
  Item_78732_Name = {
    Text = "검은 조수 속 벌레의 울음·한정 예약 구매"
  },
  Item_78758_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 웨이크업 바디의 기령을 깨어남시키며, 깨어남된 웨이크업 바디는 정신 능력을 영구적으로 강화시킵니다.\n본원 침수의 주인을 중복으로 획득할 때 전환하여 본원 침수의 주인의 기령을 활성화하는 데 사용됩니다."
  },
  Item_78758_Name = {
    Text = "파편 · 본원 잠자는 왕"
  },
  Item_78758_StoryDesc = {
    Text = "본원 침자다의 주인을 중복으로 획득할 때 전환하여 획득하며, 본원 침자다의 주인의 기령을 활성화하는 데 사용됩니다."
  },
  Item_78759_Name = {
    Text = "본원 잠자는 왕"
  },
  Item_78760_Desc = {
    Text = "임시 텍스트"
  },
  Item_78760_Name = {
    Text = "은열쇠의 이름으로: 본원 잠자는 왕"
  },
  Item_78760_StoryDesc = {
    Text = "본원 침수의 주인 이벤트"
  },
  Item_78761_Desc = {
    Text = "깨어남체 “본원 잠자는 왕” 획득 후 해금"
  },
  Item_78761_Name = {
    Text = "본원 잠자는 왕"
  },
  Item_78762_Name = {
    Text = "본원 잠자는 왕"
  },
  Item_78774_Desc = {
    Text = "소지자가 생성하는 은열에너지를 대폭 증가시키고, 광기 폭발로 인한 피해와 방어막을 증가시킬 수 있습니다. 촉수 자세의 전환에 따라 대량의 광기를 얻고 적이 받는 피해를 증폭시킬 수 있습니다."
  },
  Item_78774_Name = {
    Text = "어둠 속의 안식"
  },
  Item_78774_StoryDesc = {
    Text = "바람과 비가 얽힌 밤, 신의 딸은 외롭게 창문 아래에 앉아 있다. \n 차가운 달빛이 아기 띠에 비추고, 검은 끈적한 액체가 흐르는 성스러운 아기가 그 안에서 편안히 잠들고 있다. \n 신의 딸은 자장가를 부르기 시작한다. \n “자라, 자라, 바다의 작은 보물아.” \n “너의 요람은 검은 달이야.” \n “별들을 꿈속에 삼켜버려.” \n 노래는 기도이기도 하며, 심해의 물고기들이 이에 따라 모여든다. \n 온 배는 마치 거대한 제단처럼, 그녀가 성스러운 아기를 낳은 날과 같다. \n 자신의 가슴을 가르고, 핏줄이 흐르는 살과 뼈를 제거하며, 생명으로 양육의 은혜와 종족의 운명에 보답한다. \n 그녀의 희생은 갈망하던 자유를 가져오지 않았고, 죽음은 영원한 편안함이 아니라 비극의 시작일 뿐이다. \n 그 이후로, 그녀의 평화는 오직 밤에서만 온다. \n “자라, 자라, 바다의 작은 보물아.” \n 이 자장가가 끝날 무렵, 위대한 신국이 바다를 찢고, 거친 파도 속에서 솟아오를 것이다. \n 이러한 허망한 환상을 품고, 뫼르피는 조용히 눈을 감았다."
  },
  Item_78775_Desc = {
    Text = "「신탄의 제사」 활동에서 성취를 완료하면 얻습니다.\n「오? 이게 당신이 바치는 공물인가? 참으로 초라하군, 신모의 벌을 걱정하지 않나요?」"
  },
  Item_78775_Name = {
    Text = "은열쇠의 이름으로: 탄망·머피"
  },
  Item_78775_StoryDesc = {
    Text = "탄망·머피 이벤트 플레이"
  },
  Item_78871_Desc = {
    Text = "피해 증폭 속성의 명륜입니다."
  },
  Item_78871_Name = {
    Text = "고독한 깃털"
  },
  Item_78871_StoryDesc = {
    Text = "태어날 때부터, 쌍둥이는 마음대로 날개를 사용해 날아다닐 수 없었습니다. 그들의 등에는 두 번째 팔이 자라났지만, 그것은 성자의 위엄을 드러내는 두 쌍의 의식 도구처럼, 항상 정해진 자세를 지켜야 했습니다.\n어릴 적, 폴룩스는 두 사람 중 가장 그 날개를 소중히 여겼습니다. 매일 빗질하고, 에센스를 바르며, 그 깃털을 비단처럼 반짝이게 키웠습니다.\n그는 항상 짧은 무인 시간을 틈타, 몰래 그 날개가 처음 자란 날개를 퍼덕이며, 카스토르의 놀란 눈초리 속에서 흔들리며 지면을 떠서 장식이 새겨진 둥근 천장을 만지러 갔습니다.\n폴룩스가 다양한 춤과 같은 유연한 자세로 날개를 움직일 수 있는 것에 비해, 카스토르는 자신의 날개가 마치 두 개의 나무판처럼 둔탁하게 느껴졌습니다. 쌍둥이는 매일 잠자기 전 비밀의 시간 속에서, 카스토르는 이렇게 조용히 폴룩스가 어둠 속에서 뛰고, 회전하며, 좁은 새장 안에서 날아오르는 모습을 지켜보았습니다.\n“동생의 날개는 정말 아름다워, 하지만 나는 아마 평생 날아오르는 법을 배우지 못할 거야.” 카스토르는 생각했습니다.\n그리고 나중에 그들이 탈출한 그 밤, 카스토르는 처음으로 저녁 바람이 날개를 받쳐주는 시원함과 편안함을 느꼈습니다. 더욱 능숙한 폴룩스는 비틀거리며 날아가는 형을 단단히 붙잡고, 고공에서 크게 웃으며, 곤두박질치고 회전하는 곡선을 그리며, 마치 진짜 하늘에 속한 새처럼 날았습니다.\n카스토르는 고개를 돌려 월광이 폴룩스의 길고 힘찬 날개에 비치는 모습을 보았습니다. 깃털 사이에서 눈부신 청록색 빛이 반사되었습니다.\n“그것은 분명 세상에서 가장 아름다운 것일 거야. 어떤 상황에서도, 나는 반드시 폴룩스를 지키고, 그 날개를 보호할 거야.”\n곧, 힘든 야외 생활로 인해 폴룩스의 날개가 야수에게 상처를 입었습니다. 카스토르는 아픔을 느끼며 폴룩스가 떨어뜨린 날개 깃을 주워 그의 품에 간직하며, 이런 일이 두 번 다시 일어나지 않겠다고 조용히 맹세했습니다. 하지만 그가 모르고 있는 것은, 나중에 이 외로운 깃털이 그가 가장 소중히 여기는 것이 되고, 그 날개에 대한 유품으로 남게 될 것이라는 사실타래입니다."
  },
  Item_78872_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
