  Item_78884_Name = {
    Text = "성자의 존안"
  },
  Item_78884_StoryDesc = {
    Text = "「성자는 등불을 든 자가 주시하는 사람이며, 태어나면서부터 그분의 은총을 받는다.」\n「성자는 그분의 뜻을 전파하고, 경건한 의인에게 빛을 내려야 한다.」\n「성자는 영혼의 청결을 유지해야 한다.」\n「성자는 속된 욕망을 끊고 경건히 수행하며, 온 마음으로 빛을 섬겨야 한다.」\n「성자는 말을 많이 해서는 안 되며, 망언을 해서는 안 된다.」\n「성자는 죄악에서 멀리하고, 죄 있는 자에게서 멀리하며, 더러운 영혼에 오염되어서는 안 된다.」\n「성자는……」\n그에게 기억이 있는 때부터, 하나 또 하나의 계율이 쇠사슬처럼 그를 속박하며, 그를 존숭의 높은 단상 위에 올려놓으면서도, 예의를 잃어서는 안 되고, 고개를 숙여서는 안 되고, 희노를 방종해서는 안 되게 했다.\n그는 크고 화려한 의포를 걸치고, 수많은 시종들에 둘러싸여, 요구에 따라 그 신성한 대리인을 연기하며, 경건한 신도들이 엎드려 무릎 꿇고 조심스럽게 그의 옷자락에 입 맞추는 것을 내려다보았다.\n성자는 마땅히 그래야 했고, 아무도 그 고고하고 변하지 않는 얼굴 아래에 어떤 감정과 취향이 있는지 신경 쓰지 않았다.\n마치 그가 그 고고한 미소에 익숙해져, 아무도 없을 때조차 자신이 진정으로 어떤 표정을 짓고 싶은지 알지 못하는 것처럼.\n「폴리덱스 성자님, 축복 의식에 가셔야 합니다.」고개를 숙인 시녀가 공손하게 그의 변함없는 일상을 안배했다.\n그는 몸을 돌려, 고개를 들고, 그 똑같이 변함없는 미소를 지으며, 마치 직접 신성한 가면을 쓰는 것 같았다.\n그 방황, 공허와 외로움은 모두 가면 아래에 가려져, 마치 존재한 적이 없는 것처럼."
  },
  Item_78885_Desc = {
    Text = "크리티컬 피해 속성의 명륜입니다."
  },
  Item_78885_Name = {
    Text = "임박한 태양"
  },
  Item_78885_StoryDesc = {
    Text = "태양은 매초 300자(秭) 줄 이상의 에너지를 방출하며, 그중 수십억 분의 일이 빛과 열의 형태로 147억 미터 이상의 거리를 이동하여 우주에서 지구를 향해 쏟아진다.\n이 에너지는 지구상의 모든 생물의 필요를 충족시키며, 이 복잡하고 거대하고 혼란스러운 삼역(三域) 속의 모든 종이 순조롭게 번식하고 진화할 수 있게 한다.\n\n「이것이 세계의 진리이며, 어떤 상황에서도 변하지 않는다.」\n그는 끊임없이 자신에게 이렇게 경고하며, 이로써 정신의 안정을 유지했다.\n「그런데 왜……이렇게 뜨겁고, 이렇게 밝은 것인가.」\n왜냐하면 그 147억 미터 너머의 것이 천천히 그의 눈를 점거하고 있었기 때문이다.\n빛과 열이 그의 동공에서 흘러나와, 화려한 몸의 모든 치수를 태우고 있었다.\n「이해했다, 이해했다, 빛이 왜 8분 20초가 지나서야 지구에 도달하는지 이해했다.」\n「왜냐하면 우리는 광휘를 직면하는 대가를 치를 수 없기 때문이다.」\n그가 모든 것을 받아들였을 때, 그는 크게 웃기 시작했다.\n「알고 보니 나는 이카로스보다 더 태양에 가까웠구나.」"
  },
  Item_79294_Name = {
    Text = "역전의 턴"
  },
  Item_79412_Desc = {
    Text = "극소수의 수호자만이 가질 수 있는 신분 표시입니다. \n무수히 많은 차원에서 당신은 승자의 신분을 증명했습니다. 물리적 한계를 초월한 이 승리는 무한한 평행 세계에 드러났습니다."
  },
  Item_79412_Name = {
    Text = "차원 화관"
  },
  Item_79412_StoryDesc = {
    Text = "대결 이벤트 프로필 프레임"
  },
  Item_79413_Desc = {
    Text = "극소수의 수호자만이 가질 수 있는 신분 표시입니다.\n밤은 당신의 화판, 핏빛 달이 물감이 되고, 심연은 당신의 손에서 탄생합니다——자랑스럽게 생각하세요, 당신이 창조한 것은 공포 그 자체입니다."
  },
  Item_79413_Name = {
    Text = "심연 모사"
  },
  Item_79413_StoryDesc = {
    Text = "창작 이벤트 프로필 프레임"
  },
  Item_79414_Desc = {
    Text = "극소수의 수호자만이 가질 수 있는 신분 표식입니다. \n무한한 우주에서 당신은 별들의 나침반입니다. 별들이 제자리를 찾아요, 카오스가 상승하고 이해할 수 없는 옛 존재가 반드시 깨어남합니다."
  },
  Item_79414_Name = {
    Text = "성운 항로"
  },
  Item_79414_StoryDesc = {
    Text = "획득 이벤트 프로필 프레임"
  },
  Item_79568_Desc = {
    Text = "이름 부분이 고의적으로 지워진 진단 보고서, 환자가 겪은 다양한 문제들이 기록되어 있습니다. 클레멘타인은 이러한 기억으로 이루어진 맛있는 것을 시도할지도 모릅니다. 상점에서 물자를 교환하는 데 사용됩니다."
  },
  Item_79568_Name = {
    Text = "진단 보고서"
  },
  Item_79609_Desc = {
    Text = "이름란이 의도적으로 지워진 진단 보고서로, 환자가 겪은 각종 문제들이 기록되어 있다. 클레멘타인이 기억으로 이루어진 이 별미를 즐길지도 모른다. 상점에서 물자와 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
