  },
  Item_79638_Name = {
    Text = "진단 보고서"
  },
  Item_80189_Name = {
    Text = "초특가 패키지 빈 패키지"
  },
  Item_80191_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “특별 치료”를 선택할 수 있습니다.\n\n그녀는 수많은 환자를 치유하고 그들을 신생으로 이끌었습니다. 지금의 모든 것은 단지 심리 치료일 뿐입니다.\n유일하게 특별한 것은, 환자가 그녀 자신이라는 것입니다."
  },
  Item_80191_Name = {
    Text = "특별 치료"
  },
  Item_80191_StoryDesc = {
    Text = "그녀는 수많은 환자를 치유하고 그들을 새로운 삶으로 이끌었습니다. 지금의 모든 것은 단지 심리 치료일 뿐입니다.\n유일하게 특별한 것은, 환자가 그녀 자신이라는 것입니다."
  },
  Item_80192_Desc = {
    Text = "정신 요양원에 흩어져 있는 감정 입자들, 만질 때 누군가가 붕괴에 가까운 속삭임을 듣는 듯하다.\n비밀 지키는 사람이 사건 「탈변」에서의 공명 향상을 위해 사용된다."
  },
  Item_80192_Name = {
    Text = "인지의 심장"
  },
  Item_80285_Desc = {
    Text = "잠금 해제 후, 「요양 기록」의 모든 임무를 완료하면 추가 보상을 받을 수 있습니다"
  },
  Item_80285_Name = {
    Text = "요양 기행"
  },
  Item_81021_Desc = {
    Text = "카렌이 특별 제작한 청소 도구는 무엇이든 완벽하게 청소할 수 있습니다."
  },
  Item_81021_Name = {
    Text = "청소 도구"
  },
  Item_81069_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
  },
  Item_81069_Name = {
    Text = "조사 과정 특전·성신편Ⅱ"
  },
  Item_81250_Desc = {
    Text = "\"항해사가 이 배에 있다\"는 의미의 신호기는 아마도 클레파샨트가 수집할 것이다. 상점에서 자원을 교환하는 데 사용된다."
  },
  Item_81250_Name = {
    Text = "신호 깃발"
  },
  Item_81701_Desc = {
    Text = "「항로 개척사가 본선에 탑승 중」을 의미하는 신호기로, 코퍼산트가 수집할지도 모른다. 상점에서 물자와 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
