  Item_81754_Name = {
    Text = "신호 깃발"
  },
  Item_81756_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬:“사라지지 않는 번개”를 선택할 수 있습니다.\n\n번영, 번영, 번영.\n비록 골혈이 끓고, 비록 피부가 타들어가더라도, 몸 안의 마지막 한 방울의 피를 짜내어 빛을 발산하라.\n이 다크 속에서, 나는 유일한 안내자다."
  },
  Item_81756_Name = {
    Text = "사라지지 않는 번개"
  },
  Item_81756_StoryDesc = {
    Text = "타오르라, 타오르라, 타오르라.\n비록 골혈이 끓고, 비록 피부가 타들어가더라도, 몸 안의 마지막 한 방울의 혈액을 짜내어 빛을 발산하라.\n이 어둠 속에서, 나는 유일한 안내자다."
  },
  Item_84131_Desc = {
    Text = "의심의 여지 없이, 주인님이야말로 미사그에서 가장 뛰어난 청소의 대가랍니다! —익명의 하녀"
  },
  Item_84131_Name = {
    Text = "청소의 대가"
  },
  Item_84131_StoryDesc = {
    Text = "청소 기행"
  },
  Item_84249_Desc = {
    Text = "이 단편 거울은 다른 세계의 장면을 엿볼 수 있고, 동시에 엿보았던 특수 물체를 기록할 수 있다."
  },
  Item_84249_Name = {
    Text = "환상 단안경"
  },
  Item_84259_Desc = {
    Text = "해제 후, 「복율기행」의 모든 임무를 완료하면 추가 보상을 받을 수 있습니다"
  },
  Item_84259_Name = {
    Text = "복률 기행"
  },
  Item_84260_Desc = {
    Text = "해제 후, 「시질기행」의 모든 임무를 완료하면 추가 보상을 받을 수 있습니다"
  },
  Item_84260_Name = {
