  },
  Item_84321_Desc = {
    Text = "좋아! 너, 녀석!"
  },
  Item_84321_EmojiName = {
    Text = "괜찮아요"
  },
  Item_84321_Name = {
    Text = "로탄·좀 하네"
  },
  Item_84321_StoryDesc = {
    Text = "제17차 페이즈 체스"
  },
  Item_84322_Desc = {
    Text = "말하길 공연 중 이렇게 자세를 취하면 관객이 매우 흥분한다고 들었다?"
  },
  Item_84322_EmojiName = {Text = "미야우"},
  Item_84322_Name = {
    Text = "카시아·냥"
  },
  Item_84322_StoryDesc = {
    Text = "제17차 페이즈 체스"
  },
  Item_84468_Desc = {
    Text = "【임시 텍스트】카시아의 복장, 주로 테스트용입니다"
  },
  Item_84468_Name = {
    Text = "【임시 텍스트】흑백 카시아"
  },
  Item_88804_Desc = {
    Text = "생활 상식을 총망라한 교양서, 매우 지혜로운 자에게 매료되었다. 「지식의 욕구」로 자원을 교환하는 데 사용된다."
  },
  Item_88804_Name = {Text = "상식 책"},
  Item_88805_Desc = {
    Text = "심오한 수리 개론을 해설한 과학 도서로, 배움을 좋아하는 어느 무지한 자의 흥미를 끈다. 「지식을 향한 소망」에서 교환하는 데 사용하는 아이템.\n\n최소 {s1}개 드롭"
  },
  Item_88805_Name = {Text = "수리 책"},
  Item_88806_Desc = {
    Text = "명작 고전 소설을 수록한 문학 책으로, 배움을 좋아하는 어느 무지한 자의 흥미를 끈다. 「지식을 향한 소망」에서 교환하는 데 사용하는 아이템.\n\n최소 {s1}개 드롭"
  },
  Item_88806_Name = {Text = "문학 책"},
  Item_88808_Desc = {
    Text = "다양한 생활 상식을 정리한 교양 도서로, 배움을 좋아하는 어느 무지한 자의 흥미를 끈다. 「지식을 향한 소망」에서 교환하는 데 사용하는 아이템.\n\n최소 {s1}개 드롭"
  },
  Item_88808_Name = {Text = "상식 책"},
  Item_88809_Desc = {
    Text = "유명 작가의 고전 소설이 수록된 문학서. 무지한 어떤 탐구적인 사람에게 매우 매력적이다. 「지식의 욕망」을 통해 자원을 교환하는 데 사용된다."
