    Text = "심오한 수리 개론을 해설한 과학 도서로, 배움을 좋아하는 어느 무지한 자의 흥미를 끈다. 「지식을 향한 소망」에서 교환하는 데 사용하는 아이템.\n\n최소 {s1}개 드롭"
  },
  Item_88872_Name = {Text = "수리 책"},
  Item_88873_Desc = {
    Text = "이 열쇠를 기록한 후, 배치 시 열쇠 능력: “운명의 어긋남”을 선택할 수 있습니다.\n그들은 항상 잘못된 시간에 한 순간의 희망과 스치고 지나갑니다.\n한때 그 어린 손이 그를 이끌며 함께 자유의 빛으로 달려갔습니다.\n그가 필사적으로 날개를 휘저을 때, 다시 한 번 운명의 감옥을 뚫고 나가려 했지만, 왜 그 익숙한 손이 지금 그의 가슴을 꿰뚫고 있나요?"
  },
  Item_88873_Name = {
    Text = "어긋난 운명"
  },
  Item_88873_StoryDesc = {
    Text = "그들은 항상 잘못된 시간에 한순간의 희망과 스쳐 지나간다.\n한때 그 유년의 손이 그를 이끌며, 함께 자유의 빛으로 달려갔다.\n그가 필사적으로 날개를 휘두르며 운명의 감옥을 다시 한 번 뚫고 나가려 하지만, 왜 그 익숙한 손이 지금 그의 가슴을 관통했을까?"
  },
  Item_88874_Desc = {
    Text = "다양한 생활 상식을 정리한 교양 도서로, 배움을 좋아하는 어느 무지한 자의 흥미를 끈다. 「지식을 향한 소망」에서 교환하는 데 사용하는 아이템.\n\n최소 {s1}개 드롭"
