  },
  Item_88994_Name = {Text = "수리 책"},
  Item_89573_Desc = {
    Text = "광기 충전 레벨 속성의 명륜이다."
  },
  Item_89573_Name = {
    Text = "폐허로부터의 부활"
  },
  Item_89573_StoryDesc = {
    Text = "당신은 인적이 드문 황야에 발을 내딛는다. \n 인류 활동의 흔적은 오래 전에 사라졌고, 영혼이 고갈된 생명체가 재와 먼지 속에서 힘겹게 나아간다. \n 여기서의 생존은 부러워할 만한 것이 아니며, 여행의 끝은 아무도 알지 못하고, 끝없는 순환의 광경 속에서 맴돌고, 맴돌고, 맴돈다. \n 그들의 발걸음이 둔해지고, 무겁게 땅에 넘어져 하늘을 바라보며 호출의 손을 뻗을 때까지—— \n\n 나의 여정이 끝난 후, \n 시체를 비옥한 땅으로, 양분으로, 원천으로 삼아, 연약한 새싹이 다시 파토를 뚫고 나오기를."
  },
  Item_89651_Desc = {
    Text = "탐색 과정에서 폭발적으로 광기를 획득하는 명륜입니다."
  },
  Item_89651_Name = {Text = "개강일"},
  Item_89651_StoryDesc = {
    Text = "이것은 당신이 미사그에 온 지 1년 후입니다. 당신은 여전히 그 대폭발에서 깨어난 후 처음으로 이 학교에 발을 들였던 날을 기억합니다. 당신은 잘 맞고 정돈된 교복을 지급받았고, 자신만의 기숙사를 가지게 되었으며, 처음으로 식당을 방문해 두 개의 접시를 깨끗이 비웠습니다. 모든 편안한 순간이 그 날에 멈추었고, 순식간에 당신은 너무 부족한 지식과 아기 같은 매끄러운 두뇌 회로로 인해 1년간의 예비 과정에 다니라는 명령을 받았습니다. 언어 학습, 체력 훈련, 은심 능력 테스트, 특수 생물 상식 보충… 고통받은 끝에, 당신의 성적은 좋지 않은 편이었고, 불합격한 레오 통용어 성적과 한 번에 세 개의 깨어남체와 연결된 업적 덕분에 캠퍼스에서 명성을 얻었습니다. 다행히도, 당신의 특별한 능력과 뛰어난 재능 덕분에 당신은 빠르게 조사원의 능력 기준에 도달하여 예비 과정의 기간을 연장할 필요가 없었습니다. 당신의 고르지 않은 단점들은 점차 호흡을 맞추는 동료들이 보완해 주었습니다. 아, 이곳은 비록 악마들이 많지만, 그들도 믿음직하고 부드러운 악마들입니다. 이곳은 자주 흐리고, 비가 오며, 맑은 날은 드물고, 수많은 잊힌 사람들과 잊힐 사람들은 항상 지키고, 희생하며, 끊임없이 전진합니다. 이렇게 일상적으로 모든 일이 진행 중인 하루, 미사그는 또 다른 신학기를 맞이했습니다. 당신은 거울 앞에서 교복의 칼라를 정리하고, 주름을 펴고, 기숙사 건물의 대문을 열었습니다. “하품, 드디어 왔구나, 나 거의 잠들 뻔했어.” “너는 기숙사에서 공부하며 웅크리고 있었니? 신생.” 당신은 로탄에게 쑥스러운 미소를 지으며, 당신의 생리적 공포를 유발할 만큼 충분한 분홍색 그림자에게 목을 움츠리며, 옆에서 웃고 있는 라모나와 오지에 뒤로 숨었습니다. 다섯 개의 그림자가 아침의 캠퍼스에서 흔들리며 길어졌습니다. “가자, 파트너.” “오늘부터 너는 공식적으로 미사그의 일원이야.”"
  },
  Item_89652_Desc = {
    Text = "열쇠 지령을 발동한 후 장착자의 임시 치명타율을 높이는 명륜이다."
  },
  Item_89652_Name = {
    Text = "파트너 특훈"
  },
  Item_89652_StoryDesc = {
    Text = "아무리 앞부분의 인생 기억이 없더라도, 당신의 발달되지 않은 근육에서 알 수 있듯이, 당신은 이전에 운동이나 폭력을 좋아하는 부류의 사람이 아니었음이 분명하다.\n당신은 미사그가 조사원에게 정한 전투 기준이 왜 이렇게 높고 포괄적인지 도무지 이해할 수 없다.\n도대체 조사원의 중점은 조사라는 두 글자에 있지 않은가, 지혜로운 머리, 치밀한 논리와 적당한 행운에 있지 않은가?\n매번 라몬나에게 기숙사의 이불 속에서 제시간에 끌려 나와, 텅 빈 운동장에서 연속적인 공격에 맞서게 될 때, 당신은 도르 교수의 풍자로 가득한 논리학 수업이 그리워진다. 산더미 같은 과제와 가장 탈모를 유발하는 시험지조차 전투 훈련 중 계속해서 맞고 넘어지는 고통보다 훨씬 부드럽다.\n19번째, 당신은 모든 행동 경로를 차단한 찌르는 검에 의해 균형을 잃고 뒤로 넘어져 땅에 주저앉으며 온몸의 뼈가 부서질 듯한 느낌을 받는다.\n헐떡이며 당신은 지쳐서 이마의 땀을 닦아내며 어떤 이유로도 다시 일어나지 않겠다고 결심한다.\n라몬나는 전혀 놀라운 표정을 짓지 않고, 멋진 검꽃을 그리며 검을 수납하며, 굽 높은 신발이 경쾌하게 발소리를 내며 당신에게 다가온다. 당신은 두 눈을 감고 모든 비난과 비판을 감수하기로 결심한다.\n의외로, 어떤 타격이나 욕설도 오지 않았고, 3초 후 당신은 눈을 뜨니, 한 장의 부드러운 미소가 당신의 앞에 다가와 있었다.\n라몬나는 살짝 허리를 굽혀, 깨끗한 장갑으로 감싼 손바닥을 당신에게 내민다.\n「사실타래 당신은 이미 많이 노력했어요, 알고 있어요. 하지만 우리가 마주해야 할 것은 항상 미지의 두려움과 위험이며, 나조차도 배려하지 못하는 예기치 않은 순간이 있을 거예요.」\n「그냥 내가 조금 안심할 수 있도록, 다시 한 번 해보자, 파트너.」"
  },
  Item_89842_Desc = {
    Text = "언제 나타났는지 모를 종이 쪼가리, 만졌을 때 앞에 신비로운 환영이 떠오릅니다. 「환영 의상 주문」에서 1기 간단한 환영 의상으로 교환할 수 있습니다."
  },
  Item_89842_Name = {
    Text = "일반 의상 티켓 (1기)"
  },
  Item_89873_Desc = {
    Text = "일일 상시 보조금"
  },
  Item_89873_Name = {
    Text = "일일 상시 보조금"
  },
  Item_89952_Desc = {
    Text = "조용한 방 안에서, 스물네 명의 손님들이 차회를 시작했다. \n\n “젠킨은 오늘 어떻게 지냈을까?” \n 느릿느릿한 24는 걱정스러운 눈빛으로 창밖을 바라보았다. \n “우리가 탈출한 날을 축하하는 날이야, 우리는 이 날에 자신들만을 위해 있다고 약속했어. 좀 더 기쁘게, 24들! 오늘은 파티야!” 열정적인 24가 두 손을 흔들었다. \n “우리가 조용하고 깊이 있는 방식으로 생각해볼 수도 있어...” 학자 24의 말을 듣는 사람은 아마 아무도 없었다. \n “춤을 추고 싶으신가요? 제가 여러분을 위해 음악을 연주할 수 있어요!” 광대 24가 나팔을 불었다. \n “자, 오늘의 차회는 여러분을 위해 준비된 거예요.” 주인격 24가 두 사람의 손을 잡아끌며 무대로 데려갔다. 그녀는 이 방의 여주인 역할에 이미 익숙해져 있었다. “우리의 고통은 여러분의 몸에 짊어져져 있어요… 여러분을 괴롭히는 것들을 잊어버리세요, 적어도 오늘만은.” \n “야옹~” 그림자 24의 쓰다듬에 고양이 24가 기대에 찬 듯 꼬리를 흔들었다. \n 우울한 24와 조증 24가 서로를 바라보았다. 그녀들은 이 방 안의 모든 고통과 혼란을 함께 짊어지고 있었다. 그녀들은 함께하는 친구였고, 이 생의 변치 않는 적이었다. 그녀들은 서로의 손을 잡고 방 중앙의 빈터로 나아갔다. 모든 불안과 슬픔이 가라앉고, 그녀들은 웃고, 얽히고, 함께 노래하며, 점프하고, 회전했다. 피와 눈물이 옷과 바닥을 적셨고, 음악과 춤의 발걸음이 같은 머릿속에서 울려 퍼졌다. \n\n 조용한 방 안에서, 스물네 명의 손님들이 숨을 죽였다. \n 그녀들은 이 순간의 평화를 누리고 있었고, 오직 자신들만을 위해서였다."
  },
  Item_89952_Name = {
    Text = "두 모습의 화음"
  },
  Item_89953_Desc = {
    Text = "딩동, 딩동. 그것은 녹슨 오르골이 노래하는 소리로, 음조가 바뀐 천운의 애가를 부르고 있습니다. \n 슬픈 인형이 오르골 안에서 끊임없이 회전하고, 날아오르는 뜨거운 눈물이 청록색 불꽃에 떨어져 맑고 투명한 보석 비로 응결됩니다. \n\n 수많은 왜곡된 얼굴이 불꽃 속에서 나타나, 탐욕스럽게 그 눈물방울을 삼키고, 고통스럽게 그녀의 치마를 잡아당깁니다. \n \"춤춰! 계속 춤춰! 절대 멈추지 마!\" \n \"너는 뭘로 춤출 수 있다는 거지? 너에게 어떤 자격이 있어! 살인자! 살인광!\" \n\n 그것은 리즈가 매일 밤 반복되는 악몽으로, 수많은 영혼이 그녀의 원형 시야 안에서 입을 벌리고, 비명과 노래를 부릅니다. 그리고 그녀의 발끝은 뻗어 있고, 팔은 굳어 있으며, 몸은 가장 표준적인 춤 자세로 잠금되어 있습니다 — 톱니바퀴의 회전과 함께 끊임없이 회전하고, 회전합니다. \n\n 만약 당신이 꿈에서 깨어날 때 그녀를 만난다면, 그녀에게 왜 다시 춤추고 싶지 않은지 묻지 마세요. 그녀는 모든 사랑, 증오와 눈물을 꿈속의 불꽃에 쏟아버렸습니다. \n\n 그녀는 사랑을 그 불꽃 속에 던졌고, 그래서 평생 사랑하던 것을 내려놓았습니다. \n 그녀는 증오를 그 불꽃 속에 던졌고, 그래서 더는 더럽고 죄악에 대해 언급하지 않았습니다. \n 그녀의 사랑과 증오가 얽혀서 불타올라, 그녀의 영혼을 끝없는 청색의 슬픔으로 물들였습니다."
  },
  Item_89953_Name = {
    Text = "회전하는 인형"
  },
  Item_89954_Desc = {
    Text = "사랑스러운 방, 정교한 가구, 푹신한 담요, 화려한 치마자락, 단정한 예절. 숙녀 머피는 남들이 부러워할 만한 지위와 탐내는 보물을 관대하게 부여받았지만, 항상 좀비처럼 살아갔다. \n\n 어느 누구도 모르는 밤, 그녀는 조용히 버려진 옷장에 숨었고, 해양도약자들의 어인들에 의해 흔들리며 교회에서 끌려 나와 인적이 드문 황야에 버려졌다. \n\n 그녀는 옷장을 밀치고, 광활한 별빛 아래로 나왔다. \n 그녀는 잡동사니 더미를 넘고, 산기슭에서 작은 공 하나를 주웠다. \n\n 골리아가 놀란 어인들 팀과 함께 잃어버린 성녀를 찾았을 때, 그녀는 여전히 옷장에서 멀지 않은 곳에 앉아 손에 든 작은 공을 높이 던졌다. 공이 굴러떨어지길 기다렸다가 다시 한 번 높이 던졌다—\n 골리아는 한마디도 묻지 않고 성녀를 다시 봉헌이라는 이름의 감옥으로 끌고 갔다. \n 그래서 그녀의 행동의 목적은 항상 말하지 않고, 칼이 가슴에 박힐 때까지 마음속에 묻혀 있었다. \n\n — 그녀는 공을 크고 둥근 달에 던지고 싶어 했다. \n — 그렇게 된다면, 그것은 다시는 떨어지지 않을 것이다."
  },
  Item_89954_Name = {
    Text = "숙녀의 작은 취미"
  },
  Item_89955_Desc = {
    Text = "창조의 아버지가 별빛에서 내려와, 피로 생명을 잉태하고, 뼈로 규칙을 새겼다.\n만물은 본래 아버지 신의 규범에 따라 행동하고, 아버지 신의 뜻에 따라 생명을 이어야 했다.\n그러나, 세월이 흐르고, 신언이 깨지며, 아버지 신의 규범을 시행하기 어려워지고, 아버지 신의 뜻이 실타래현되기 어려워졌다.\n만물이 고통받고, 재앙이 끊이지 않는다.\n\n창백한 주인이여, 나는 구세의 신언을 새롭게 시작하여, 중생을 이끌어 고통을 없애리라.\n나는 만물의 고통, 만물의 죄, 만물의 슬픔을 없애고, 나의 뼈와 피가 다할 때까지, 영혼이 하늘로 돌아갈 때까지 이를 계속하겠다.\n\n첫 번째 신언이 울려 퍼지며, 육체의 욕망은 초월을 맞이할 것이다. \n이로써, 색욕이 소멸한다.\n\n두 번째 신언이 울려 퍼지며, 생명은 더 이상 환희에 중독되지 않을 것이다. \n이로써, 폭식이 소멸한다.\n\n세 번째 신언이 울려 퍼지며, 탐욕의 마귀는 입을 다물게 된다. \n이로써, 탐욕이 소멸한다.\n\n네 번째 신언이 울려 퍼지며, 세상에 더 이상 소극적으로 살아가는 자가 없을 것이다. \n이로써, 게으름이 소멸한다.\n\n다섯 번째 신언이 울려 퍼지며, 세상 사람들은 더 이상 이치에 맞지 않는 행동을 하지 않을 것이다. \n이로써, 분노가 소멸한다.\n\n여섯 번째 신언이 울려 퍼지며, 더 이상 억울하게 죽은 자가 없을 것이다. \n이로써, 질투가 소멸한다.\n\n일곱 번째 신언이 울려 퍼지며, 중생은 만물을 경외하고 존중할 것이다. \n이로써, 오만이 소멸한다.\n\n나는 아버지 신의 뼈로 아버지 신의 권위를 대신한다.\n아버지 신의 빛이 만물을 비추기를 바라며.\n구세의 말씀이…… 영원히 세상에 남아 있기를……"
  },
  Item_89955_Name = {
    Text = "구세의 신언"
  },
  Item_89964_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 능력: “머릿속의 목소리”를 선택할 수 있습니다.\n\n두 손이 맞잡는 순간, 당신들은 서로의 눈에서 혼란과 궁금증을 보았다.\n불완전한 음부가 여기서 교차하며, 당신들이 이미 과거를 잃어버렸기 때문이다.\n침묵의 악장이 곧 작곡될 것이며, 당신들이 미래로 떨어지기로 결심했기 때문이다."
  },
  Item_89964_Name = {
    Text = "봉인된 과거의 기억"
  },
  Item_89964_StoryDesc = {
    Text = "두 손이 맞잡는 순간, 당신들은 서로의 눈에서 혼란과 당혹감을 보았다.\n부족한 음부가 여기서 교차하며, 당신들이 이미 과거를 잃어버렸기 때문이다.\n침묵의 악장이 곧 작곡될 것이며, 당신들이 미래로 떨어지기로 결심했기 때문이다."
  },
  Item_89988_Desc = {
    Text = "의상 「회전하는 인형」 획득 시 개방됩니다. \n「이 춤을 더럽히지 마세요.」"
  },
  Item_89988_Name = {
    Text = "리즈·회전하는 인형"
  },
  Item_89989_Desc = {
    Text = "의상 「두 모습의 화음」 획득 시 개방됩니다. \n「나, 나, 나와 함께 다과회를 열자!」"
  },
  Item_89989_Name = {
    Text = "「24」·두 모습의 화음"
  },
  Item_89990_Desc = {
    Text = "의상 「숙녀의 작은 취미」 획득 시 개방됩니다. \n「숙녀의 취미를 두고 수군거리지 마!」"
  },
  Item_89990_Name = {
    Text = "머피·숙녀의 작은 취미"
  },
  Item_89991_Desc = {
    Text = "의상 「구세의 신언」 획득 시 개방됩니다. \n 「아버지 신께서 신언을 내리시어, 너와 나를 인도하리라.」"
  },
  Item_89991_Name = {
    Text = "살바도르·구세의 신언"
  },
  Item_90040_Desc = {
    Text = "두꺼운 하드커버로 포장된 도서 세트는 내용이 고전적이고 편집이 뛰어나, 책을 사랑하는 자가 책장을 꾸미기에 좋은 아이템이다."
  },
  Item_90040_Name = {
    Text = "제본 도서 세트"
  },
  Item_90041_Desc = {
    Text = "특별한 경로를 통해서만 얻을 수 있는 고서적은 많은 사람들에게 알려지지 않은 고대 지혜를 기록하고 있으며, 지식을 얻는 것에 대해 열정적으로 추구하는 연구자들만이 진정으로 갈망할 수 있습니다."
  },
  Item_90041_Name = {
    Text = "고본 도서 세트"
  },
  Item_90042_Desc = {
    Text = "부식된 인형의 부품을 어떻게 부식해야 할지 모르겠는데, 녹슬어 보이는 금속 상처에서 검은색 농혈이 흘러나옵니다. \n“반보 차이” 기간 동안 한정 제공됩니다."
  },
  Item_90042_Name = {
    Text = "녹슨 인형 부품"
  },
  Item_90043_Desc = {
    Text = "정교하고 세밀한 인형 부품, 기술과 광기의 반짝임이 돋보입니다. \n“반보 차이” 기간 동안 한정 공급됩니다."
  },
  Item_90043_Name = {
    Text = "정제된 인형 부품"
  },
  Item_90044_Desc = {
    Text = "서점에서 세트로 판매되는 정품 책들은 정돈된 인쇄물과 정교한 일러스트를 자랑하며, 독서하는 사람들에게 최고의 가성비 선택입니다."
  },
  Item_90044_Name = {
    Text = "할인 도서 세트"
  },
  Item_90045_Desc = {
    Text = "분명 인형 위에 있지 않지만 스스로 회전하는 기어 세트는 가까워지면 속삭임 같은 미세한 마찰 소리를 낸다. \n“반보 차이” 기간 동안 한정 판매됩니다."
  },
  Item_90045_Name = {
    Text = "이중나선 인형 부품"
  },
  Item_90067_Desc = {
    Text = "「더 꼬집으면... 더 꼬집으면 오레타가 너를 찌를 거야!」"
  },
  Item_90067_EmojiName = {
    Text = "얼굴 꼬집기"
  },
  Item_90067_Name = {
    Text = "오리타·얼굴 조정"
  },
  Item_90067_StoryDesc = {
    Text = "제18기 과제 기록"
  },
  Item_90554_Desc = {
    Text = "시체 도시에서 퍼지는 감정의 입자들이 닿을 때, 마치 식인귀의 욕망이 가득한 숨소리를 들을 수 있다.\n비밀 지키는 사람의 사건「만족」 조사에서의 공명을 증진시키기 위해 사용됩니다."
  },
  Item_90554_Name = {
    Text = "폭식의 심장"
  },
  Item_90856_Desc = {
    Text = "「두개골 속 노래·한정 사건」에서 획득 가능.\n「그는 굶주린 듯 기다리고 있어——연회가 시작되고, '너'가 식탁에 오르는 순간을.」"
  },
  Item_90856_Name = {
    Text = "영원한 밤의 굶주린 응시"
  },
  Item_90856_StoryDesc = {
    Text = "V2.3 버전 예약 구매 이벤트"
  },
  Item_90857_Desc = {
    Text = "\"켤레 운명\"에서 얻을 수 있습니다.\n\"사람들은 항상 자신이 내린 선택이 자신의 의지와 갈망에서 비롯된다고 생각한다.\n하지만 영원한 그물의 직조자는 이미 오래전에 모든 이의 미래를 써 내려, '운명'이라는 이름의 그물로 엮어 놓았다.\""
  },
  Item_90857_Name = {
    Text = "운명의 직조자"
  },
  Item_90857_StoryDesc = {
    Text = "V2.5 버전 예약 구매 이벤트"
  },
  Item_90858_Desc = {
    Text = "“임시 텍스트”에서 얻을 수 있습니다.\n“임시 텍스트”"
  },
  Item_90858_Name = {
    Text = "임시 텍스트"
  },
  Item_90858_StoryDesc = {
    Text = "V2.7 버전 예약 구매 이벤트"
  },
  Item_90859_Desc = {
    Text = "「연해태동·한정 기행」에서 얻을 수 있습니다.\n「흉강 속의 영광이 세계를 향해 쏟아질 때, 제단 위의 신모는 인간으로서의 마지막 한 방울의 눈물을 흘렸다.」"
  },
  Item_90859_Name = {
    Text = "심해의 애가"
  },
  Item_90859_StoryDesc = {
    Text = "V2.4 버전 예약 구매 이벤트"
  },
  Item_90860_Desc = {
    Text = "「만원의 의지」에서 획득할 수 있다.\n「세계가 여전히 나아가는 한, 계략은 결코 멈추지 않는다.」"
  },
  Item_90860_Name = {
    Text = "모략 진행 중"
  },
  Item_90860_StoryDesc = {
    Text = "V2.6 버전 예약 구매 이벤트"
  },
  Item_90911_Desc = {
    Text = "구매 후, 모든 보상을 순차적으로 받을 수 있습니다."
