    Text = "자, 소스와 향신료가 가득한 황금빛 스테이크를 올려라. 자비로운 노예주가 식사를 마치면, 혹시 남은 뼈다귀를 당신에게 하사할지도 모른다. 「공물 헌납」에서 물자와 교환하는 데 사용한다.\n\n최소 {s1}개 드롭"
  },
  Item_90984_Name = {
    Text = "맛있는 레오 숯불구이"
  },
  Item_91121_Desc = {
    Text = "그녀의 과거의 결단과 용기를 존경하는 사람이 얼마나 많은지, 그렇게 재생된 행운을 부러워하는 사람도 그만큼 많다.\n활발한 두뇌 아래에는 교체 가능한 수많은, 칼과 총을 두려워하지 않으며, 결코 늙지 않는 육체가 있다. 영생의 유혹은 영원한 금단의 열매와 밝은 촛불처럼, 부와 권력을 쥔 사람들을 끌어당긴다.\n한때 미사그가 거부할 수 없는 대인물이 극히 풍부한 거래를 제안하며, 돌에게 그를 위한 동일한 뇌 이식 수술과 깨어남 과정을 요청했다.\n돌은 거절하지 않았고, 그의 무지를 비웃지도 않았다. 단지 바쁜 실타래험 중에서 잠깐의 만남 시간을 빼내어 그 대인물을 세밀하게 검사해주었다. 그리고는 그의 분노를 불러일으킬 결론을 차분하게 발표했다—— 그의 두뇌는 재생의 조건을 갖추고 있지 않다.\n미사그의 여러 가지 조정 아래, 중병에 걸린 대인물은 일련의 면책 계약에 서명하고, 그 희박한 희망에 배팅하기를 고집했다.\n돌은 직접 그에게 수술을 시행했으나, 안타깝게도 희망은 존재하지 않았다. 돌이 부정적인 판결을 내릴 때, 개발 수준이 부족한 그 두뇌는 원래의 영성을 회복할 수 없었다.\n하지만 그 성의 가득한 보상 덕분에, 돌은 여전히 애프터 서비스를 친절하게 마무리했다: 활성을 유지한 그 두뇌는 뇌 통에 넣어졌고, 그 성능에 맞는 장치 시스템이 장착되었다.\n그래서 돌의 실타래험실타래에는 점차 비행하는 진균 미학에 맞는 작은 조수들이 늘어났고, 그 짧게 날 수 있는 작은 것들은 유연한 집게발을 휘두르며 가장 간단한 작업을 수행하고, 과학의 연구와 발전에 기여하고 있다.\n「I03, 새로운 증류수를 가져와.」\n「I05, 지난 주의 배양 배지를 교체해.」\n「I01, 나를 위해 커피 한 잔 우려줘.」\n무지한 두뇌도 전혀 쓸모가 없는 것은 아닌 것 같다. 커피의 김이 모락모락 피어오르는 가운데, 돌은 미소를 지으며 생각했다."
  },
  Item_91121_Name = {
    Text = "영성의 재탄생"
  },
  Item_91157_Desc = {
    Text = "가슴 앞의 은 열쇠가 갑자기 빛나며, 이 우주 너머의 어딘가와 멀리서 공명하는 듯했습니다. 당신은 이것이 두 영혼이 공명하는 증거임을 알았습니다."
  },
  Item_91157_Name = {
    Text = "은열쇠의 광휘"
  },
  Item_91237_Desc = {
    Text = "어디선가 나타난 종이 쿠폰, 터치할 때 신비로운 환영이 눈앞에 떠오릅니다. ‘환의 주문’에서 2기 간단 환의를 교환하는 데 사용할 수 있습니다."
  },
  Item_91237_Name = {
    Text = "일반 의상 티켓 (2기)"
  },
  Item_91353_Desc = {
    Text = "물자 지원부는 「조사 작전」을 완료한 수호자에게 특별 허가를 발급했다. 조사작전을 완료할 때마다 수호자는 다음 출발을 위해 특별하고 귀중한 은심 제품을 구매할 수 있다.수량은 한정되어 있다. 은열쇠가 우리를 인도하길."
  },
  Item_91353_Name = {
    Text = "조사 과정 특전·성신편 III"
  },
  Item_91354_Desc = {
    Text = "잠금 해제 후, 「망리행」의 모든 임무를 완료하면 추가 보상으로 다음을 받을 수 있다"
  },
  Item_91354_Name = {
    Text = "망자의 성 기행"
  },
  Item_91397_Desc = {
    Text = "「진실타래은 언제나 하나.」"
  },
  Item_91397_EmojiName = {Text = "탐정"},
  Item_91397_Name = {
    Text = "라이커·탐정"
  },
  Item_91397_StoryDesc = {
    Text = "제19기 과제 기록"
  },
  Item_91435_Desc = {
    Text = "「조용히 잠든 마음을 깨우세요…」"
  },
  Item_91435_EmojiName = {
    Text = "두드리기"
  },
  Item_91435_Name = {Text = "산: BONK"},
  Item_91435_StoryDesc = {
    Text = "제19기 페이즈 체스"
  },
  Item_91730_Desc = {
    Text = "미사그 레스토랑에서 제공하는 일상적인 고기 세트 중 하나, 양이 작고, 껍질은 바삭하고, 속은 부드러운, 절대 실타래수할 수 없는 선택.\n「위대한 정복」 동안 한정 제공된다."
  },
  Item_91730_Name = {
    Text = "향신료 치킨 세트"
  },
  Item_91731_Desc = {
    Text = "미사그 레스토랑에서 가끔 제공하는 고기 세트 중 하나로, 신선한 양고기를 저온에서 구워내어, 향긋하고 육즙이 풍부하여 학생들에게 인기가 있으며, 곧 사라질 것이다.\n「위대한 정복」 기간 한정 제공된다."
  },
  Item_91731_Name = {
    Text = "연한 양고기 세트"
  },
  Item_91732_Desc = {
    Text = "미사그 레스토랑의 축제 특별 고기 세트, 호화로운 양과 매혹적인 꿀향 소금색과 기름진 육즙이 가득하여, 축제의 분위기를 잘 살려주며, 사람들에게 만끽하는 행복감을 준다.\n「위대한 정복」 기간 한정 제공된다."
  },
  Item_91732_Name = {
    Text = "화산 스테이크 세트"
  },
  Item_91764_Desc = {
    Text = "의상 「피로 담금질된 영관」 획득 시 개방됩니다. \n「왔노라, 보았노라, 학살했노라.」"
  },
  Item_91764_Name = {
    Text = "유우하시·피로 담금질된 영관"
  },
  Item_91765_Desc = {
    Text = "그가 얼마나 오랜 세월을 겪었든, 그는 그 시대, 격투사들이 누리던 영광의 시대를 잊지 않을 것이다.\n“유우하시……”\n처음에, 그를 사들인 주인은 사람들에게 그의 이름을 발표해야 했지만, 그가 모든 상대를 죽이고, 맨손으로 적의 내장을 꺼내고, 그들의 피를 다 빨아먹은 후, 전체 격투장은 그를 위해 끓어올랐다.\n“갈증자”, “악마”, “투기장의 폭군”……\n사람들은 그의 호칭이 끊임없이 변했으며, 동시에 그의 상대도 끊임없이 강해졌다.\n아이들, 노인들, 여자들, 남자들, 심지어 호랑이와 사자까지도 그의 상대가 되었고, 그들은 모두 그에게 패배했다.\n그는 패자들의 비명에 관심이 없었고, “너는 왜 싸우고 있는가”라는 따분한 임종의 말도 기억할 수 없었다.\n그는 단순히 한 가지 일을 반복했다: 살육.\n그가 살아 있고, 투기장에 서 있는 한, 그는 여기서의 무관왕이다.\n그리고 이렇게 간단한 일은 그에게 모든 것을 가져다주었다.\n사람들은 그의 이름을 호출하며, 일어나는 파도가 로마에서 가장 큰 격투장을 흔들 만큼 컸다. 그러나 그는 비웃었다.\n사람들은 그를 위해 천금을 쏟아내며, 뿌려진 금화는 격투장에 가득한 모래와 피의 바닥을 평평하게 만들 수 있었다. 그러나 그는 개의치 않았다.\n그에게는 그 소리들, 그 재물들, 그 애정과 숭배가 모두 역겹고 불쾌한 것처럼 보였고, 오직 따뜻한 피만이 만질 수 있는 것이었으며, 오직 살육만이 진실타래이었다.\n그가 갈망하는 것은 언제나 단순한 일이었다: \n나는 오고, 나는 보고, 나는 살육한다."
  },
  Item_91765_Name = {
    Text = "피로 담금질된 영관"
  },
  Item_91766_Desc = {
    Text = "어둡고 끝없는 미로에서 드디어 또 다른 신인이 나타났고, 항상 불만을 품고 있는 창백한 주인은 오랜만에 미소를 지었습니다. \n「선택해라, 나와 계약을 체결하고 내 자식이 될 것인가, 아니면 미로에서 굶어 죽고 내 자식이 될 것인가.」 \n미로에 잘못 들어온 신인은 눈을 크게 뜨고, 표정이 혼란과 혼돈, 공포 속에서 빠르게 변하다가, 결국 도망치기 시작했습니다. 수많은 '선배들'과 마찬가지로. \n「아, 도망가기를 선택했구나~ 하하, 뛰어라 뛰어라, 최선을 다해 달려라—— 어차피 너는 내 미로에서 결코 도망칠 수 없으니까.」 \n그 후, 아그리파에게는 여전히 재미있는 과정이 반복됩니다: 달리고, 힘이 빠지고, 넘어지고, 다크와 공포에 휩싸인 사람이 구해달라고 외치고, 절망하며, 결국 정신과 육체가 완전히 부서지는 것입니다. \n이 불쌍한 인간들의 뇌가 절망 속에서 걸쭉해질 때, 그녀라는 미로의 주인이 등장하는 순간입니다. 그녀가 많이 말할 필요 없이, 불쌍하고 가련한 사람들은 그녀에게 구원의 손을 내밉니다. \n「구해주세요…… 누구든 좋으니, 구해주세요……」 \n아그리파는 연민과 잔인함이 섞인 시선으로 상대를 바라보며 미소를 지었습니다. \n「나는 물론 너를 구해줄 것이다. 너의 선배들처럼…… 내 자식이 되어라.」 \n「네, 계약을 체결하기만 하면 모든 고난과 고통이 끝나게 된다.」 \n이성을 잃은 불쌍하고 가련한 사람은 본능적으로 고개를 끄덕였고, 그래서 어둡고 끝없는 미로에서 창백한 주인은 다시 한번 미소를 지었습니다. \n계약이 완료되었고, 이제 해야 할 것은 대기하는 것—— 자식의 성장과 탄생을 기다리는 것입니다."
  },
  Item_91766_Name = {
    Text = "창백한 계약"
  },
  Item_91767_Desc = {
    Text = "의상 「창백한 계약」 획득 시 개방됩니다. \n「계약을 맺고, 내 자손이 되어라~」"
  },
  Item_91767_Name = {
    Text = "아그리파·창백한 계약"
  },
  Item_94417_Desc = {
    Text = "그가 얼마나 오랜 세월을 경험했든, 그는 그 시대를 잊지 않을 것이며, 격투사의 영광의 시대를 잊지 않을 것이다. \n“유우하시……” \n처음에 그를 사들인 주인은 사람들에게 그의 이름을 발표해야 했지만, 그가 모든 상대를 죽이고 맨손으로 적의 내장을 꺼내어 피를 빨아먹은 후, 전체 투기장이 그를 위해 끓어올랐다. \n“갈증자”, “악마”, “투기장의 폭군”…… \n사람들은 그의 호칭을 끊임없이 바꾸었고, 동시에 그의 상대도 계속 강해졌다. \n아이, 노인, 여자, 남자, 심지어 호랑이와 사자까지도 그의 상대가 되었고, 모두 그에게 패배했다. \n그는 패자의 비명에 관심이 없었고, “너는 왜 싸우고 있느냐”는 지루한 임종의 말을 기억할 가능성도 없었다. \n그는 단순히 한 가지 일을 반복하고 있었다: 살육. \n그가 살아있고, 투기장에서 서 있는 한, 그는 여기서의 무관왕이다. \n그렇게 간단한 일이 그에게 모든 것을 가져다주었다. \n사람들은 그의 이름을 호출하며, 일어나는 파도가 로마에서 가장 큰 투기장을 흔들 수 있을 정도였다. 그러나 그는 비웃었다. \n사람들은 그를 위해 천금을 쏟아부었고, 쏟아진 금화는 투기장에 가득한 모래와 피의 바닥을 덮기에 충분했다. 그러나 그는 아랑곳하지 않았다. \n그의 눈에는 그 소리, 그 재산, 그 좋아하고 숭배하는 것들이 모두 역겨운 것들로 보였고, 오직 따뜻한 피만이 만질 수 있는 것이었고, 오직 살육만이 진실타래이었다. \n그가 갈망하는 것은 영원히 단순한 일이었다: \n나는 오고, 나는 보고, 나는 살육한다."
  },
  Item_94417_Name = {
    Text = "피로 담금질된 영관"
  },
  Item_94418_Desc = {
    Text = "어둡고 끝이 없는 미궁에 드디어 새로운 방문자가 등장했다. 항상 성마르고 불만족스러웠던 창백한 주인은 오랜만에 미소를 지었다. \n「선택해라. 나와 계약을 하고 내 자식이 되든지, 아니면 미궁에서 굶어 죽어 내 자식이 되든지.」 \n실타래수로 미궁에 들어온 신입은 눈을 크게 뜨고 망설임, 혼란, 공포가 뒤섞인 표정을 지으며 곧바로 달아나기 시작했다. 이전의 수많은 「선배」들과 똑같이 말이다. \n「아, 도망치는 것을 선택했군~ 하하, 도망쳐라 도망쳐! 온 힘을 다해 뛰어라——결국 네가 이 미궁을 벗어날 수는 없을 테지만.」 \n그 다음은 수천 번도 넘게 반복되었지만 아그리파에게 여전히 즐거움을 주는 과정이었다. 달리기, 기진맥진, 넘어짐, 어둠과 공포에 짓눌린 자들의 구조 요청, 외침, 절망, 그리고 정신과 육체가 완전히 망가지는 그 순간까지. \n이 가엾은 인간들의 두뇌가 절망으로 완전히 짓이겨질 때, 바로 이 미궁의 주인이자 그녀인 아그리파가 등장할 순간이었다. 그녀는 많은 말을 할 필요 없이 가엾고 비참한 인간들이 자동적으로 그녀에게 도움을 요청하기 마련이었다. \n「살려줘…… 누구든 좋으니, 제발 나를 구해줘……」 \n아그리파는 애처로우면서도 잔혹하게 그들을 바라보며 미소지었다. \n「물론 구해줄게. 너의 선배들과 마찬가지로…… 내 자식이 되어라.」 \n「그래, 계약만 하면 모든 고통과 몸부림은 끝이 날 거야.」 \n이성을 잃고 비참하고 가련한 이들은 본능적으로 고개를 끄덕였고, 그리하여 어둡고 끝없는 미궁에서 창백한 주인은 다시 미소를 지었다. \n계약은 이미 완성되었고, 이제 그녀가 할 일은 기다리는 것 뿐이었다——자식의 성장과 탄생을 말이다."
  },
  Item_94418_Name = {
    Text = "창백한 계약"
  },
  Item_94440_Desc = {
    Text = "깨어남체 「무셰트」 획득 후 해제"
  },
  Item_94440_Name = {Text = "무셰트"},
  Item_94441_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n모카를 반복적으로 획득할 때 변환하여 모카의 기령을 활성화하는 데 사용됩니다."
  },
  Item_94441_Name = {
    Text = "파편 · 무셰트"
  },
  Item_94441_StoryDesc = {
    Text = "반복적으로 무셰트를 획득할 때 변환하여 무셰트의 활성화를 위해 사용합니다."
  },
  Item_94442_Desc = {
    Text = "깨어남체 “본원 오지에” 획득 후 해금"
  },
  Item_94442_Name = {
    Text = "본원 오지에"
  },
  Item_94443_Desc = {
    Text = "죽음 저항 속성의 명륜입니다."
  },
  Item_94443_Name = {
    Text = "이성의 등불"
  },
  Item_94443_StoryDesc = {
    Text = "「이성을 등불로 삼으면, 인생의 안개를 걷어낼 수 있다.」\n언젠가, 모샤는 이런 말을 들은 적이 있었다.\n어쩌면 소로 컴퍼니의 기술자가 구무등을 조정하면서 무심코 내뱉은 감상이었을까? 아니면 필린겐 레스토랑에 갔을 때 어떤 행인이 던진 농담이었을까?\n모샤는 이미 잊어버렸다. 그녀가 선명하게 기억할 수 있는 것은, 그 말을 들었을 때 자신의 얼굴에 떠올랐던 습관적인 사교적 미소와, 그 미소 뒤에 감춰진 조소뿐이었다.\n「등불? 하, 무슨 구닥다리 골동품이야, 요즘 사람들은 손전등을 쓴다고.」\n그녀는 그것이 비유에 불과하다는 걸 모르는 게 아니었다. 다만 이해할 가치가 없다고 여겼을 뿐.\n어차피 언젠가 그녀는 죽을 것이다. 그리고 죽음 이후에는, 무슨 이성이니 안개니 하는 것들은 더 이상 존재하지 않는다——그녀는 이 세계에서 완전히 해방될 것이다.\n이것은 합리적이고 필연적인 추론이었다. 그녀가 해야 할 일은, 그 「필연」이 도래하기 전의 과정을 즐기는 것뿐.\n하지만 아무도 그녀에게 말해 준 적이 없었다. 「필연」도 「우연」과 마주칠 수 있다는 것을.\n비슷한 안개, 비슷한 곤경, 하지만 여기에는 구무등도, 조사단도, 그녀에게 익숙한 그 어떤 것도 없었다. 그녀의 도끼는 세상의 괴물을 베어낼 수 있었지만, 자신의 고독과 혼란이 피어낸 안개는 베어낼 수 없었다.\n돌아갈 수 있을까? 돌아가게 될까? 도대체 언제 돌아갈 수 있는 걸까……\n하나 또 하나의 질문이 마음속에서 떠올랐고, 보이지 않는 깊은 물처럼 천천히 그녀의 마음을 삼켜 갔다. 이 순간, 그녀의 마음속 유일한, 전부인 생각은——\n이성을 유지해라.\n미치지 마! 미치지 마! 미치지 마!\n저 세계의 안개든, 이 세계의 안개든, 자기 내면의 안개든.\n다시, 돌아가기 위해."
  },
  Item_94444_Name = {Text = "무셰트"},
  Item_94445_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 웨이크업 바디의 기령을 깨어남시키며, 깨어남된 웨이크업 바디는 정신 능력을 영구적으로 강화시킵니다.\n본원 오지에를 반복적으로 획득할 때 변환하여 본원 오지에의 기령을 활성화하는 데 사용됩니다."
  },
  Item_94445_Name = {
    Text = "파편 · 본원 오지에"
  },
  Item_94445_StoryDesc = {
    Text = "반복적으로 본원 오지에를 획득할 때 변환하여 본원 오지에을 활성화하는데 사용합니다."
  },
  Item_94446_Name = {
    Text = "서약을 저버린·오지에"
  },
  Item_94447_Desc = {
    Text = "크리티컬 확률 속성의 명륜입니다."
  },
  Item_94447_Name = {
    Text = "지난 날은 그림자처럼 따라온다"
  },
  Item_94447_StoryDesc = {
    Text = "이름 모를 역병이 도시와 마을을 삼키고, 전쟁을 탐하는 자들이 혼란 속에서 마음껏 살육하며, 철과 피의 교향이 끓어오르며 광란했다.\n공포로 인해, 혹은 공포를 이용하여.\n공포는 보이지 않는 적, 오래된 적, 치명적인 적이었다.\n그는 자격 없는 기사였으며, 공포에 패배했다.\n\n그러나 일찍이 엄숙히 맹세한 서약은 여전히 귓가에 울려 퍼졌고, 해를 거듭하며, 이미 허무해진 고향을 가로질렀다.\n「나는 약자를 자비롭게 대할 것이며, 나는 강적에 용감하게 맞설 것이다.」\n어둠이 범행자의 발자국을 숨기고, 비명과 울음의 홍수가 거리를 뒤덮으며, 군중은 공황에 빠진 양 떼와 같았다.\n「나는 악인에게 조금도 물러섬 없이 맞설 것이며, 나는 싸울 수 없는 자들을 위해 싸울 것이다.」\n창끝에 피가 물들고, 은빛 방패는 녹슬었으며, 그림자는 만족스럽게 미소 짓고, 까마귀 떼가 하늘 위를 선회하며, 눈동자 속에 악마의 섬광이 번쩍였다.\n「나는 나의 도움을 필요로 하는 자들을 도울 것이다.」\n「저 사람이야, 그가 왔어.」 사람들이 낮게 중얼거렸고, 공포가 그들의 얼굴을 일그러뜨렸다. 「속이 빈 괴물, 복수의 망령, 죽음의 깊은 연못에서 돌아와 자신의 적들을 원한의 검은 늪으로 끌어들이려 한다.」\n그가 맞다. 그는 잊지 않았으며, 결코 잊은 적이 없었다.\n\n왜 계속해야 하는가? 만약 모든 것이 결국 소멸한다면, 영광과 신념조차도.\n왜 물러서야 하는가? 어차피 운명이 어떻게 조롱하든, 인간은 오직 무릎을 꿇고 순종할 수밖에 없는데.\n설마 충성에 충성하고, 헌신에 헌신하기 위해서인가?\n공국 최후의 기사는 헛되이 물었고, 영혼은 잔해와 마찬가지로 황폐했으며, 공포의 잔재가 제멋대로 흘러 파멸의 바다를 이루었다.\n하지만 텅 빈 가슴속은 여전히 침묵을 지켰고, 잃어버린 답은 아직 행방을 알 수 없었다."
  },
  Item_94448_Desc = {
    Text = "장착자의 「광기 폭발」과 「추격」이 주는 기본 피해를 증가시키고, 타격 카드를 사용할 때마다 장착자의 타격으로 인한 피해를 지속적으로 증가시킵니다."
  },
  Item_94448_Name = {
    Text = "광란의 세계 끝에서"
  },
  Item_94448_StoryDesc = {
    Text = "「세상이 종말로 향할 때, 어떤 재미난 것이 일어날까?」\n무셰트는 그것에 대해 알지는 못했지만, 기대에 가득찼다.\n이런 기대는 이전의 것과는 사뭇 다르다. 이번에는 고대 유물 몇 개를 파는 조그마한 재미가 아니라, 하나의 세계를 기준으로 한 연구와 조사이기 때문이다. 그리고 이 연구와 조사에서 가장 중요하고 핵심적인 것은 단 한 사람——\n바로 미사그의 수호자이다.\n「난 이 세계를 구원할 거야……」\n「이 세계를 결코 붕괴할 운명으로 향하게 만들지 않을 테니까……」\n하나의 세계의 흥망성쇠를 짊어진 사람이 이렇게 이상에 가득찬 마음으로 약속하는 것에 대해 무셰트는 감동한 표정을 지어야 한다는 걸 알고 있었다. 이건 인류 사회의 관습적인 사회적 예의이니까.\n하지만, 그녀는 더 이상 위장하고 싶지 않았다. 아니, 수호자가 @4를 정면으로 대면하고, 자신의 대가로 하나의 세계가 구원되는 것을 보며 우주적인 공포를 겪은 사람에게는 결코 위장할 필요가 없다고 느꼈기 때문이다.\n「위장」은 인류 사회의 게임 규칙으로, 격식은 있나 지루하다. 반면 우주는…… 우주는 진실타래하고 직설적이다——\n살거나, 파괴되거나. 둘 중에 하나.\n그래서 그녀는 수호자에게 한 대답도 진실타래하고 직설적으로 전했다.\n「나는 이 세계가 구원받을지, 아니면 파괴될지 솔직히 상관없어…… 그보다 나는 네가 더 궁금해.」\n나는 네가 이상을 실타래현할 수 있을지, 아니면 이상을 추구하는 길에서 무너질 것인지 궁금하다.\n또한 이 세계가 당신의 소원에 응답할지, 아니면 피할 수 없는 파괴로 향할지도 궁금하다.\n어느 쪽이든, 그건 성대하고 흔치 않은 재미가 될 것이기 때문이다.\n나는 그때를 항상 고대하고 있다……\n내 눈으로, 내 도끼로, 기다리고 있을 것이니."
  },
  Item_94449_Desc = {
    Text = "장착자의 「광기 폭발」이 부여하는 방어막과 힘을 증폭시키며, 「방어」 사용 시 더 많은 방어막과 힘을 제공합니다."
  },
  Item_94449_Name = {
    Text = "그래도 데이지는 만발한다"
  },
  Item_94449_StoryDesc = {
    Text = "「화환을 잘 써요, 이게 당신의 서훈식이에요, 사랑하는 어린 기사님.」\n데이지가 들판에 만개할 때면, 언제나 나태한 병사가 호위라는 명목으로 소년을 이끌고 이곳을 거닐곤 했다.\n아키탄 공국에서 가장 흔히 볼 수 있는 꽃으로 엮은 장식품이, 금빛 머리카락 위에 살며시 얹혔다.\n「각하, 어쩌면……저희 훈련을 해야 하지 않을까요?」\n소년은 그렇게 말하면서도, 순순히 새하얀 화환을 바로 썼다.\n이 작은 식물은 언제나 빛 속에 잠겨 있었고, 소년의 나라에서도 희망의 상징이었다.\n\n다시 눈을 떴을 때, 그 밝고 아름다운 장면들은 이미 사라지고 없었다.\n전마가 울부짖고, 적들이 경멸하듯 우르르 몰려들었으며, 수많은 군마 속에 그는 홀로였다.\n그리고 귀를 찌르는 소란이 갑자기 멈추었다——\n검은 조류가 그의 영혼 속으로 밀려들었다.\n뒤이어 울려 퍼진 것은 긴 창이 살을 꿰뚫는 찢어지는 소리, 피의 요동침 소리, 적들의 울부짖음이었다.\n그 얼굴들 위의 경멸은 흔적도 없이 사라지고, 그 자리를 가득 메운 것은 압도적인 공포와 후퇴였다.\n소년은 그저 기계적으로 손을 들어 찌르고, 뽑고, 다시 들어 올렸다.\n마지막 병사가 쓰러질 때까지.\n먼지와 연기가 수많은 얼굴을 삼키고, 정복자와 피정복자의 잔해가 땅 위에 쌓여, 더 이상 구별이 없었다.\n\n그림자가 그의 등에 달라붙어 비웃으며 말했다: 「계속해. 창을 내려뜨려, 한 번 더.」\n「수호자와 파괴자 사이에는, 원래 한 끗 차이밖에 없어. 이제 너는 이미 선택을 했어.」\n\n어둠이 하늘을 가리고, 피가 대지를 적셨다.\n그는 멀리 교외의 들판을 바라보았다——단 하룻밤 사이에, 그곳은 영원히 예전의 빛깔을 잃어버렸다.\n바람이 소년의 옷자락을 들어 올리고, 요행히 남아 있는 그 풀밭도 스쳐 지나갔다.\n소리 없는 밤 속에서, 악마조차 모르는 구석에서, 알아채기 어려운 순백의 빛이 여전히 그의 눈 속에 남아 있었다.\n그것은 이 나라의 마지막 데이지였으며, 아무도 신경 쓰지 않는 곳에서 조용히 자라고 있었다.\n비록 붉은빛에 물들고 꽃줄기가 꺾였지만, 여전히 쓰러지지 않았다."
  },
  Item_94559_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬: “포식자의 결의”를 선택할 수 있습니다.\n\n여기는 미사그가 전사들에게 약속한 약속의 땅입니다. 그 항아리에는 꿀이 담겨 있고, 그 서랍에는 고기가 숨겨져 있습니다.\n용감한 전사를 막을 수 있는 것은 없습니다. 그들은 결국 자신이 마땅히 가져야 할 것을 되찾을 것입니다."
  },
  Item_94559_Name = {
    Text = "사냥의 결의"
  },
  Item_94559_StoryDesc = {
    Text = "여기는 미사그가 전사들에게 약속한 약속의 땅입니다. 그 항아리에는 꿀이 담겨 있고, 그 찬장에는 고기가 숨겨져 있습니다.\n 용감한 전사들은 무엇도 막을 수 없으며, 그들은 결국 자신이 가져야 할 것을 되찾을 것입니다."
  },
  Item_94660_Desc = {
    Text = "의상 「영성의 재탄생」 획득 시 개방됩니다. \n「모든 뇌가 같은 지혜와 행운을 가진 건 아니야.」"
  },
  Item_94660_Name = {
    Text = "돌·영성의 재탄생"
  },
  Item_94733_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다.\n「절대 비밀문서의 표지 사진, 촬영자는 카메라를 직접 바라보는 것이 부끄러운 건지 미소가 매우 어색하게 보인다.」"
  },
  Item_94733_Name = {
