    Text = "황금빛으로 빛나는 총알로, 재물과 관련된 의뢰를 표시하는 데 자주 쓰인다. 카티구라에게 건네면 보상을 받을 수 있다.\n\n최소 {s1}개 드롭"
  },
  Item_95168_Name = {
    Text = "재물의 「인장」"
  },
  Item_95169_Desc = {
    Text = "케이티굴라를 대표하는 호박색 탄환은 격렬한 화염과 함께 발사되어 전장에 떨어지게 된다. 그것을 케이티굴라에게 건네면 보상을 받을 수 있다."
  },
  Item_95169_Name = {
    Text = "전쟁의 「인장」"
  },
  Item_9516_Desc = {
    Text = "크리티컬 피해 속성의 명륜입니다."
  },
  Item_9516_Name = {
    Text = "별하늘의 짐승"
  },
  Item_9516_StoryDesc = {
    Text = "시간이 흘러, 행성이 막 태어나려던 시절 속 기억은 로탄의 기억 속에서 대부분 사라져 버린 듯했다.\n\n허나, 그녀가 기억하는 것은 단 하나. 자신이 선택받은 생명체였다는 것뿐이었다.\n\n그것은 모든 개념이 꽃피워지기 전의 이야기다.\n\n「생명」은 아직 뿌리를 내리지 못했고, 「신」 또한 아득한 저편에 머물러 있었다.\n\n이 무질서한 성운 속에서 혼돈과 혼돈이 충돌하며, 물질은 충격과 뒤섞임 속에 차츰 형제를 갖추어 갔다.\n\n별의 자녀는 먼지는 움켜쥐었고, 암석은 융기하여 산의 형상을 이루었으며, 대기는 가라앉아 넓은 물길을 이뤄갔다.\n\n그리고, 이곳은 마침내 「행성」으로 선포되었다.\n\n혼돈의 영혼은 시간의 감옥에 갇힌 채, 갓 태어난 흙을 들이받았다.\n\n포학한 본성을 제어하지 못한 채, 파괴의 본능에 삼켜진 그 존재는 수많은 산맥을 무너뜨리고, 수많은 하천을 메워버렸다.\n\n그리고―― 「신」이 먼 별을 건너, 이 황량한 행성에 강림했다.\n\n「신」은 문명의 씨앗을 가져왔고, 혼돈의 영혼을 「질서」의 육체 속에 가둬버렸다.\n\n「나와…… 약속을 하나 하자꾸나.」\n\n포효하는 혼돈의 영혼을 마주하며, 흰 베일에 싸인 「신」이 귓가에 조용히 속삭였다.\n\n「위대한 문명이 이 자리에 싹 틔울 거란다.」\n\n「너는 무위(無為)의 지혜자를 만나고, 방황하는 칼날과 맞서게 될 게다…… 그러고는 머지않아 더 이상 넌, 파괴와 멸망에 휘둘리지 않게 될 거란다.」\n\n「그날이 오기 전까지…… 즉, 우리가 재회하기 전까지, 이곳을 지켜주길 부탁하마.」"
  },
  Item_95170_Desc = {
    Text = "황금빛으로 빛나는 총알로, 재물과 관련된 의뢰를 표시하는 데 자주 쓰인다. 카티구라에게 건네면 보상을 받을 수 있다.\n\n최소 {s1}개 드롭"
  },
  Item_95170_Name = {
    Text = "재물의 「인장」"
  },
  Item_95171_Desc = {
    Text = "회색 그림자가 이 탄약을 단단히 감싸고 있으며, 그 출현은 피할 수 없는 피와 죽음을 상징한다. 카티구라에게 건네면 보상을 받을 수 있다.\n\n최소 {s1}개 드롭"
  },
