  },
  Item_9517_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_9517_Name = {
    Text = "유기 형태 Ⅱ"
  },
  Item_9517_StoryDesc = {
    Text = "나비는 외로움, 사랑, 그리고 절망으로 인해 죽어가고 있었다."
  },
  Item_9518_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “주사수호”를 선택할 수 있습니다. \n\n그녀는 “아프지 않다”… 하지만 분명히 거짓말일 거야, 그녀는 가장 아픔을 무서워하는 아이였으니까."
  },
  Item_9518_Name = {
    Text = "주사 수호"
  },
  Item_9518_StoryDesc = {
    Text = "그녀는 “아프지 않아”라고 했지만, 분명 거짓말이었을 거야. 그녀는 분명히 아픔을 가장 무서워하는 아이였어."
  },
  Item_9519_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9519_Name = {
    Text = "핏빛의 포옹 Ⅵ"
  },
  Item_9519_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 그가 빚어낸 존재를 두 손으로 끊어냈다."
  },
  Item_9520_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9520_Name = {
    Text = "4월의 찬가 Ⅲ"
  },
  Item_9520_StoryDesc = {
    Text = "그는 @2년 봄에 땅에 묻혔다."
  },
  Item_9521_Desc = {
    Text = "기어가고, 왜곡되고, 우리는 어두운 곳을 기어다닙니다……스……스……\n감염당한 번데기. 혈육 경계역의 깨어남체 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_9521_Name = {
    Text = "원생 번데기"
  },
  Item_9522_Desc = {
    Text = "비밀계약 전사에 사용할 시 두 개의 부속성을 잠글 수 있으며, 재료 교환에서 비밀계약 잔본으로 교환할 수 있습니다.\n오늘날까지도 펜은 그가 지나왔던 궤적을 그리워하고 있다."
  },
  Item_9522_Name = {
    Text = "추억의 깃펜"
  },
  Item_9523_Desc = {
    Text = "기획팀 테스트용 SR 무기"
  },
  Item_9523_Name = {
    Text = "시작용 장검(`경계`) 개발용"
  },
  Item_9523_StoryDesc = {Text = "미완성"},
  Item_9524_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_9524_Name = {
    Text = "황야의 늑대 Ⅱ"
  },
  Item_9524_StoryDesc = {
    Text = "아우우우, 아우우우."
  },
  Item_9525_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9525_Name = {
    Text = "약재의 꿈 Ⅲ"
  },
  Item_9525_StoryDesc = {
    Text = "천 년 전, 5분은 40온스의 고운 모래와 같았다."
  },
  Item_9526_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9526_Name = {
    Text = "광합성 제례 Ⅲ"
  },
  Item_9526_StoryDesc = {
    Text = "과학은 분광 분석이고, 예술은 광합성이다."
  },
  Item_9527_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다. 당신의 본능, 당신의 이성, 심지어 당신의 영혼까지... 결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9527_Name = {
    Text = "연마된 본능"
  },
  Item_9528_Name = {Text = "자물쇠"},
  Item_9529_Desc = {
    Text = "보유자가 가하는 보호막과 치유 효과를 높이고, 보유자의 반격 획득 능력을 강화하는 명륜입니다."
  },
  Item_9529_Name = {
    Text = "상처받은 지느러미"
  },
  Item_9529_StoryDesc = {
    Text = "(다음 답변은 클레멘타인의 진료 수첩에서 발췌한 것으로 참고용입니다)\n\n1. 카이커스.\n2. 16, 17…? 하늘이 알지.\n사람이 죽고 나서 이런 쓸모없는 것들을 왜 신경 쓰겠어?\n3. 한 구멍가게 어촌, 어떤 지도에서도 그 이름을 찾을 수 없어.\n4. 말하고 싶지 않아.\n5. 괴물. 추녀. 멍청한 돼지. 바보@1……이런 것들이 좀 더 흔해.\n6. 반짝이는 황금 메기 얼굴, 줄여서 메기 얼굴.\n7. 비 오는 날.\n8. 모르겠어. 비가 올 때, 나는 해변을 왔다 갔다 해……\n몇 년이 지났을까, 멀리 바라보며, 아무것도 하지 않아.\n9. 내가 말했다, 내가#¥% 모르겠다고@1 꺼져!!\n-------\n14. 음…… 아마도 오른 아저씨가 비 오는 날, 큰 범선으로 나를 데리러 온다고 말했었지「집」으로……\n15. 맞아, 그는 자신의 약속을 지켰어……\n나는 바닷속에서 며칠 동안 떠다녔고, 목마르고 배고프고, 온몸이 아팠어……\n그리고 오른 아저씨와 그의 하얀 범선을 보았어.\n그의 몸은, 오 아니, 정확히 말하자면 그의 뼈가 범선의 돛대에 걸려 있었어——그도 변화에 실타래패했어.\n그때 나는 마지막 힘을 다해 그곳으로 떠가, 돛대에 앉아 그와 함께 있었어.\n16. 우리는 함께 집에 가기로 했어."
  },
  Item_9530_Desc = {
    Text = "소지자의 생명 회복 능력을 높이고, 광기 폭발을 해제하면 일정 지연 치료를 얻을 수 있습니다."
  },
  Item_9530_Name = {
    Text = "인도하는 돛"
  },
  Item_9530_StoryDesc = {
    Text = "카수리아 민간에 전해지는 침몰 문명의 전설. \n\n 전해지길, 역사 기록 이전 먼 옛날, 별들의 이상한 이동으로 인해 한 선사 문명이 바다 속으로 가라앉았고, 카수리아인들은 그 문명의 후손이라고 한다. \n 상업과 어업 외에도 카수리아인들이 바다에 나가는 주요 목적 중 하나는 잃어버린 조상 문명을 찾는 것이다. \n 그들은 특정 별자리에서 태어난 여자아이들이 조상 문명과 감응할 수 있으며, 그녀들이 침몰 문명의 방향을 가리킬 수 있고, 폭풍 속에서 선대들을 보호할 수 있다고 믿는다. \n\n 셀레스트가 바로 그렇게 선택된 존재다. \n 그녀는 높이 걸린 흰 돛의 돛대에 묶여 아래에서 바쁘게 움직이는 인간들을 바라보고 있다. \n 그녀는 관심도 없고, 호기심도 없다. \n\n 셀레스트는 바람과 바다 새의 움직임으로 바다의 날씨를 감지할 수 있으며, 가끔 먼 잠자는 땅에서 오는 기운을 느낄 수 있다. \n 그녀는 본래 바다에, 배에 속하는 존재인 것 같다——셀레스트는 종종 이렇게 생각하며, 억제된 사실타래은 그녀의 마음속에 아무런 파장을 일으키지 않는 듯하다. \n 가끔 그녀는 돛대에서 벗어나 하늘을 나는 흰 새를 쫓아가고, 그때 배는 그녀를 놓치지 않으려 애쓴다. \n 사람들은 소녀가 항해의 순조로움의 상징이라고 믿으며, 축복받은 배는 무사히 귀항하여 막대한 재산과 진보된 문명을 가져온다고 믿는다. \n 그러나 그녀는 이에 대해 전혀 알지 못한다."
  },
  Item_9531_Desc = {
    Text = "크리티컬 피해 속성의 명륜입니다."
  },
  Item_9531_Name = {Text = "흡입"},
  Item_9531_StoryDesc = {
    Text = "깊게 심호흡해, 도미니크."
  },
  Item_9532_Name = {
    Text = "의식용 단검"
  },
  Item_9533_Name = {Text = "은열쇠"},
  Item_9534_Desc = {
    Text = "이제는 아무도 이걸로 길흉을 점치지 못할 거야. \n융해진흙으로 덮인 보라색 수정, 초월계역의 깨어남체 스킬 레벨을 올리는데 사용됩니다."
  },
  Item_9534_Name = {
    Text = "부서진 광석"
  },
  Item_9535_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_9535_Name = {
    Text = "생명력 착취 Ⅱ"
  },
  Item_9535_StoryDesc = {
    Text = "탯줄은 끝없는 미래와 연결되어 있다."
  },
  Item_9536_Desc = {
    Text = "융식액에서 추출한 고순도 원액으로, 매우 귀중하다. 정제와 붕괴를 거쳐 은심으로 변환할 수 있다.\n\n「원액」 소모 시, 증정된 「원액」이 우선 차감됩니다.\n추출: {s1}\n증정: {s2}"
  },
  Item_9536_Name = {Text = "원액"},
  Item_9537_Desc = {
    Text = "기획팀 테스트용 SR 무기"
  },
  Item_9537_Name = {
    Text = "시작용 장검 (치명타) 개발용"
  },
  Item_9537_StoryDesc = {Text = "미완성"},
  Item_9538_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n법로스를 반복 획득할 때 전환하여 법로스의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9538_Name = {
    Text = "파편 · 파로스"
  },
  Item_9538_StoryDesc = {
    Text = "중복으로 팔로스를 획득하면 전환되어, 팔로스의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9539_Desc = {
    Text = "윙클 양이 모성에서 가져온 신비로운 기술로 제작된 특별 허가증입니다. 시간을 압축하고 흐름 속으로를 가속화하여 수호자가 신속하게 시험을 완료할 수 있도록 돕습니다.\n“융식의 폐허”와 “금지된 기록”의 관문이 삼성에 도달하면 이 아이템을 소모하여 재현할 수 있습니다."
  },
  Item_9539_Name = {
    Text = "시간 압축 허가 (이미 폐기됨)"
  },
  Item_9540_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 리즈를 획득할 때 전환하여 리즈의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9540_Name = {
    Text = "파편 · 리즈"
  },
  Item_9540_StoryDesc = {
    Text = "리즈를 다시 획득할 때 전환하여 획득하며, 리즈의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9541_Desc = {
    Text = "이것은 공예품이 아니라, 연금술사와 마주한 나비의 비극적인 최후다. \n단순한 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9541_Name = {
    Text = "희미한 결정 나비"
  },
  Item_9542_Desc = {
    Text = "재앙에서 빚어진 기적.\n주간 시련에서 얻을 수 있는 희귀한 융식 결정체로, 달빛처럼 빛난다. 교환 상점에서 상품을 교환할 때 사용할 수 있다."
  },
  Item_9542_Name = {
    Text = "융식의 구슬"
  },
  Item_9543_Desc = {
    Text = "수많은 전쟁이 그것 때문에 일어났다. \n “제5원소”라고 불리는 붉은 결정체는 그 제조 방법이 이미 실타래전되었다. \n 일반적으로 깨어남체 스킬 향상 재료로 사용된다."
  },
  Item_9543_Name = {
    Text = "현자의 돌"
  },
  Item_9544_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 페이지로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9544_Name = {
    Text = "순백의 조각"
  },
  Item_9545_Desc = {
    Text = "「나는 다시 일어날 수 있을 줄 몰랐습니다. 정의를 위해 다시 싸울 수 있는 기회가 제게 주어진 것은 영광입니다.」\n·팀의 부정 효과 해제\n·폭발적인 방어 능력"
  },
  Item_9545_Name = {Text = "엘바"},
  Item_9546_Desc = {
    Text = "그녀는 남에게 직시되는 것을 좋아하지 않아, 그럴 경우 그녀의 내면의 약점이 드러나기 때문입니다. \n·보호막을 생성하여 공격을 방어합니다. \n·적절한 시기에 독을 주입하여 적을 무너뜨립니다."
  },
  Item_9546_Name = {
    Text = "아그리파"
  },
  Item_9547_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 회복, 검은 인장 드롭율, 은열쇠 충전 중 무작위 1개를 획득합니다."
  },
  Item_9547_Name = {
    Text = "표준 밀체 SSR"
  },
  Item_9549_Desc = {
    Text = "바람이 새는 집. 그래도 없는 것보다는 낫다.\n버려진 번데기 껍질. 혈육 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9549_Name = {
    Text = "마른 번데기"
  },
  Item_9550_Desc = {
    Text = "크리티컬 피해 속성의 명륜입니다."
  },
  Item_9550_Name = {Text = "숙성"},
  Item_9550_StoryDesc = {
    Text = "우리는 공허한 인간, 우리는 허수아비."
  },
  Item_95510_Desc = {
    Text = "깊은 바다에 전해 내려오는 고대의 비밀을 기록한 신비한 고서.\n 무료로 「망각편」의 「심해」 영역 한정 명륜을 1개 선택하여 획득할 수 있습니다."
  },
  Item_95510_Name = {
    Text = "심해의 비전·망각편"
  },
  Item_95511_Desc = {
    Text = "익숙한 세계를 기준으로, 혼돈 영역으로 방향을 맞추어 원질을 포획하고 깨어남시키는 기술.\n 무료로 「망각편」의 「혼돈」 영역 한정 깨어남체 1명을 획득할 수 있습니다."
  },
  Item_95511_Name = {
    Text = "혼돈의 메아리·망각편"
  },
  Item_95512_Desc = {
    Text = "익숙한 세계를 기준으로, 혈육 영역으로 방향을 맞추어 원질을 포획하고 깨어남시키는 기술.\n 무료로 「망각편」의 「혈육」 영역 한정 깨어남체 1명을 획득할 수 있습니다."
  },
  Item_95512_Name = {
    Text = "혈육의 탄생·망각편"
  },
  Item_95513_Desc = {
    Text = "정신 차원에 잠금된 앵커 위치에서 깨어남 장치를 제거하고, 정신 연결 장치만을 통해 원질을 포획하는 것으로, 순간적으로 미지의 공명이 발생한다.\n 무료로 「망각편」 한정 깨어남체 1명을 무작위로 획득할 수 있습니다."
  },
  Item_95513_Name = {
    Text = "원질 포획·망각편"
  },
  Item_95514_Desc = {
    Text = "이상한 차원에서 온 예언을 기록한 신비한 고서.\n 무료로 「망각편」의 「초차원」 영역 한정 명륜을 1개 선택하여 획득할 수 있습니다."
  },
  Item_95514_Name = {
    Text = "초차원 예언·망각편"
  },
  Item_95515_Desc = {
    Text = "익숙한 세계를 기준으로, 초차원 영역으로 방향을 맞추어 원질을 포획하고 깨어남시키는 기술.\n 무료로 「망각편」의 「초차원」 영역 한정 깨어남체 1명을 획득할 수 있습니다."
  },
  Item_95515_Name = {
    Text = "초차원 투영·망각편"
  },
  Item_95516_Desc = {
    Text = "혼돈 공간에서 진행된 극비 실타래험을 기록한 신비한 고서.\n 무료로 「망각편」의 「혼돈」 영역 한정 명륜을 1개 선택하여 획득할 수 있습니다."
  },
  Item_95516_Name = {
    Text = "혼돈의 실타래험·망각편"
  },
  Item_95517_Desc = {
    Text = "우주의 수많은 운명의 축소판을 기록한 신비한 고서.\n 무료로 「망각편」 한정 명륜 1개를 무작위로 획득할 수 있습니다."
  },
  Item_95517_Name = {
    Text = "운명 잠금·망각편"
  },
  Item_95518_Desc = {
    Text = "피부에 기록된 피와 육체의 비밀을 담은 신비한 고서.\n 무료로 「망각편」의 「혈육」 영역 한정 명륜을 1개 선택하여 획득할 수 있습니다."
  },
  Item_95518_Name = {
    Text = "혈육의 속삭임·망각편"
  },
  Item_95519_Desc = {
    Text = "익숙한 세계를 기준으로, 심해 영역으로 방향을 맞추어 원질을 포획하고 깨어남시키는 기술.\n 무료로 「망각편」의 「심해」 영역 한정 깨어남체 1명을 획득할 수 있습니다."
  },
  Item_95519_Name = {
    Text = "심해의 몽환·망각편"
  },
  Item_9551_Desc = {
    Text = "날개는 단지 아름다움을 더할 뿐이며, 5펜시의 값어치가 있다. \n빛나는 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9551_Name = {
    Text = "빛나는 결정 나비"
  },
  Item_9552_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_9552_Name = {
    Text = "표준 밀체 SSR"
  },
  Item_9553_Desc = {
    Text = "「회귀·라모나」를 호출하기 위한 도구로, 사용 후 「라몬나」의 본원 형태를 해금할 수 있습니다.\n\n당신은 그녀의 새로운 악몽이 되지 않을 것입니다, 단지 당신이 그녀 곁을 떠나지 않을 것이기에."
  },
  Item_9553_Name = {
    Text = "잃어버린 진동"
  },
  Item_95548_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬: “지금 태양”을 선택할 수 있습니다.\n\n허위의 검은 태양이 하늘을 가리고 있지만, 진정한 태양은 결코 꺼지지 않을 것입니다.\n지금의 짧은 일몰은 더 뜨거운 태양을 폭발시키기 위함입니다.\n현재, 호박색 불꽃을 지닌 태양이 두 번째로 떠오르며 다시는 지지 않을 것입니다."
  },
  Item_95548_Name = {
    Text = "꺼지지 않는 태양"
  },
  Item_95548_StoryDesc = {
    Text = "거짓의 검은 태양이 하늘을 가렸더라도, 진정한 태양은 결코 꺼지지 않을 것이다.\n이 순간의 짧은 일몰은 더욱 뜨거운 태양이 터져 나오기 위함이다.\n지금, 호박색 불꽃을 타고 있는 태양이 두 번째로 떠오르며, 다시는 지지 않을 것이다."
  },
  Item_9554_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 충전 레벨, 검은 인장 드롭율과 은열쇠 충전 중 랜덤으로 1개를 획득한다."
  },
  Item_9554_Name = {
    Text = "진홍빛 심동 Ⅳ"
  },
  Item_9554_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 자신의 혈액으로 골렘을 길러냈다."
  },
  Item_9555_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다. 당신의 본능, 당신의 이성, 심지어 당신의 영혼까지... 결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9555_Name = {
    Text = "연마된 영혼"
  },
  Item_9556_Desc = {
    Text = "경험치가 일정 수준에 도달할 시 수호자 조사 등급이 상승합니다. 조사 작전, 막간 훈련 등의 스테이지에서 린피테이프를 소모할 시 획득할 수 있습니다."
  },
  Item_9556_Name = {Text = "경험치"},
  Item_9557_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n아그리파를 반복 획득할 때 전환하여 기령을 활성화하는 데 사용됩니다."
  },
  Item_9557_Name = {
    Text = "파편 · 아그리파"
  },
  Item_9557_StoryDesc = {
    Text = "아그리파를 중복으로 획득하면 이를 전환하여 기령을 활성화하는 데 사용할 수 있습니다."
  },
  Item_9558_Desc = {
    Text = "끝없는 바다에 산일된 감정 입자로, 접촉하면 \"저에게 맡겨요\"라는 결별의 말이 들리는 듯합니다.\n수호자가 조사 이벤트 「뒤틀린 별무리」에서의 공명을 높이는 데 사용됩니다.\n「뒤틀린 별무리」 관문 첫 클리어 보상에서 획득할 수 있습니다."
  },
  Item_9558_Name = {
    Text = "갈망의 심장"
  },
  Item_95592_Desc = {
    Text = "많은 희귀 결정체로 가득 찬 상자, 연구원의 얼마나 많은 머리카락이 소모되었는지 알 수 없으며, 무질서한 세포는 혼란과 풍부한 아름다움으로 가득 차 있어 깨어남체가 자신의 힘을 신속하게 발전시킬 수 있습니다.\n“죽은 자의 미학” 기간 한정으로 공급됩니다."
  },
  Item_95592_Name = {
    Text = "모방 지원 상자"
  },
  Item_95593_Desc = {
    Text = "모든 힘의 비밀이 이 빨간 결정들 속에 응축되어 있다. 이 상자를 여는 순간, 당신은 미사그가 당신에게 쏟은 신뢰와 결단을 느낄 수 있을 것이다. 학교 측은 모든 자원을 쏟아부으면 반드시 훌륭한 수호자를 양성할 수 있다고 믿고 있다. \n“죽음의 미학” 기간 한정으로 공급된다."
  },
  Item_95593_Name = {
    Text = "현석 지원 상자"
  },
  Item_95594_Desc = {
    Text = "미사그가 특히 의욕이 넘치는 조사원을 위해 준비한 훈련 지원 물자와 함께 대량의 고된 연습이 이루어져, 강력한 깨어남체 팀을 신속히 육성할 수 있었다.\n「죽음의 미학」 기간 한정으로 공급된다."
  },
  Item_95594_Name = {
    Text = "특훈 지원 상자"
  },
  Item_9559_Desc = {
    Text = "인류의 존속을 위해.\n\n\n\n액자에 보관된 기억. 혈육 영역 깨어남체의 승급 재료."
  },
  Item_9559_Name = {
    Text = "기억 복사본"
  },
  Item_9560_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 문서로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9560_Name = {
    Text = "순백의 서류"
  },
  Item_9561_Desc = {
    Text = "기획팀 테스트용 SR 무기"
  },
  Item_9561_Name = {
    Text = "시작용 장검 (행운) 개발용"
  },
  Item_9561_StoryDesc = {Text = "미완성"},
  Item_9562_Desc = {
    Text = "구매 후 랜덤 부위의 SSR 품질 미스터리: 먼 곳의 잔치"
  },
  Item_9562_Name = {
    Text = "계약 상자: 먼 곳의 장치"
  },
  Item_9563_Desc = {
    Text = "우리에게 미지의 영지를 부여한다.\n필린 시사의 특수 필름으로, 인간의 영지를 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9563_Name = {
    Text = "영지 템플릿"
  },
  Item_9564_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9564_Name = {
    Text = "환형의 시편 Ⅵ"
  },
  Item_9564_StoryDesc = {
    Text = "환형 시간의 틈새를 떠다니는 것."
  },
  Item_9565_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
