  },
  Item_95674_Desc = {
    Text = "크리티컬 피해 속성의 명륜입니다."
  },
  Item_95674_Name = {Text = "진미"},
  Item_95674_StoryDesc = {
    Text = "소리 없이 조용히 죽어가는 영혼만이 섬세히 음미할 가치가 있다. 살아 있는 자들의 몸부림은 단지 맛을 어지럽히고 혼란스럽게 할 뿐이다. \n원형 접시가 올려졌을 때도 여전히 온기가 남아 있었고, 한쪽에는 심장이 온전히 놓여 있었으며, 표면이 살짝 부풀어 방금 마지막 박동을 마친 것처럼 보였다. 두 개의 안구는 옆에서 장식해주고 있었는데, 동공에는 죽기 전 마지막 순간의 놀라움이 그대로 담겨 있었으며, 부드럽고 순순히 우윳빛으로 조리되어 있었다. \n그가 칼을 들어 천천히 심장 끝을 가르려던 그 순간 멈춰 섰다. \n영혼은 여전히 쉰 소리로 비명을 질렀고, 집착의 자취는 혈관 속에 남아 있으며 완전히 사라지지 않았다. 그는 칼을 내려놓고 두 손을 모아 망자의 목소리를 조용히 들었다. \n이 심장은 생전에 병과 고통에 시달렸던 한 시인에게서 온 것으로, 죽음 속에서 오랜 실타래의에서 해방되었으나 여전히 삶에 대한 아쉬움이 남아 있었다. 그는 이 심장을 진정으로 \"맛이 배어들게\" 하기 위해, 음식을 충분히 존중하는 것이 필요하다는 것을 알고 있었다. 방법은 단 하나, 기다리는 것이다— \n육체에 얽혀 있는 집착이 죽음 속에서 완전히 부서질 때까지 기다리고, 망자의 기억의 마지막 메아리가 침향으로 변해 혈관 벽에서 조용히 스며 나올 때까지 기다리는 것이다. \n그는 두 손을 우아하게 교차시켜 무릎 위에 얹고 눈을 감고 깊이 숨을 들이켰다. \n향기가 공기 중에 천천히 퍼졌다. 그것은 복잡하지만 부드러운 향내였다. 연인의 떨림, 이별의 씁쓸함, 먹물 향과 약초 냄새, 그리고 아침 이슬 같은 조심스러움이 섞여 있었다. \n그는 생명의 잎이 울창한 나무 아래에 조용히 앉아 있었고, 잘 익은 과실타래이 제때 떨어지기를 기다렸다."
  },
  Item_95675_Desc = {
    Text = "깨어남체 「도어세인」 획득 후 해제"
  },
  Item_95675_Name = {
