  },
  Item_9568_Desc = {
    Text = "그녀는 순수한 아름다움을 추구하며, 찰나의 순간을 영원으로 만듭니다. \n·지연 방어막을 부여하고 동시에 데미지를 입힙니다. \n·방어막을 부여하고 터치 월을 획득합니다"
  },
  Item_9568_Name = {Text = "산"},
  Item_95690_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n두레인을 반복 획득 시 전환하여, 두레인의 기령을 활성화하는 데 사용됩니다."
  },
  Item_95690_Name = {
    Text = "파편 · 도어세인"
  },
  Item_95690_StoryDesc = {
    Text = "두르세인을 반복적으로 얻을 때 변환하여, 두르세인의 깨어남을 활성화하는 데 사용합니다."
  },
  Item_95691_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬:“잔혹한 인사”을 선택할 수 있습니다.\n\n보름달이 중천에 떠올라서, 구울의 왕이 당신에게 인사를 합니다.\n오늘 밤, 우리는 적의 머리로 원한을 마십니다.\n오늘 밤, 우리는 사랑하는 이의 갈비뼈로 영원을 측정합니다."
  },
  Item_95691_Name = {
    Text = "잔혹한 인사"
  },
  Item_95691_StoryDesc = {
    Text = "보름달이 중천에 떠올라서, 구울왕이 당신에게 인사를 합니다.\n오늘 밤, 우리는 적의 머리로 원한을 마십니다.\n오늘 밤, 우리는 사랑하는 이의 갈비뼈로 영원을 측정합니다."
