  Item_95698_Name = {
    Text = "부패한 손뼈"
  },
  Item_95699_Desc = {
    Text = "장착자가 입히는 기본 피해를 증가시키고, 탐험 진행에 따라 장착자의 광기 폭발 피해와 치명타 확률을 지속적으로 증가시키며 배아를 소비할 때 주기적으로 추가 광기를 획득합니다."
  },
  Item_95699_Name = {
    Text = "안식의 입맞춤"
  },
  Item_95699_StoryDesc = {
    Text = "죽음을 두려워하지 마세요. 그것은 단지 육체가 영혼을 밤의 어둠에 돌려보내는 과정일 뿐입니다. 마치 밀물이 빠져나가 깊고 고요한 안식에 이르는 것과 같습니다. 완전히 사라져 부식되고, 아무도 알지 못하는, 무의미한 존재로 전락하는 것이야말로 진정한 공포입니다. \n그녀는 평온하게 죽지 않았습니다. \n말라붙은 몸은 이미 차갑게 굳어 있었고, 피와 부식액이 섞여 어두운 붉은색 유리처럼 굳어 있었습니다. 하지만 그녀의 젊은 영혼은 여전히 목구멍 깊숙이에서 떨리고 있었습니다. 사라지지 않은 의식 한 조각이 뼈 사이에 연기처럼 머물러 있었습니다. 마치 나약하게 부러진 날개를 가진 아름다운 나비처럼요. \n둘르세인이 조용히 방 안으로 들어왔습니다. 그의 발걸음은 먼지조차 흩트리지 않았습니다. 그는 그녀 곁에 무릎을 꿇고, 그녀의 단단히 닫힌 눈, 펼쳐지지 않은 손가락 마디, 그리고 불안에 떨리는 영혼을 부드러운 시선으로 스쳤습니다. \n“내가 아직 살아있나요?” \n“이 어둠이 나를 삼킬 건가요?” \n그는 말없이 손을 내밀어 그녀의 거칠어진 손가락을 하나하나 펴주었습니다. 마치 떨리는 꽃잎의 주름을 펴주듯 부드럽게요. 연민도, 비난도 없이, 오직 평화롭고 고요한 인내심으로, 마치 세상에서 가장 공정하고 위엄있는 신처럼 그녀에게 평온의 권리를 부여했습니다. 그 순간, 그녀는 마치 영원의 고요에 이른 듯했습니다. \n그래서 순수한 향기가 그들의 맞잡은 손에서 퍼져 나왔습니다. 그는 몸을 굽혀 그녀의 손등에 만족스럽고 엄숙하게 입을 맞췄습니다. 입맞춤이 이루어진 순간, 죽음의 마지막 메아리가 점차 길어지다가 공중에 떠도는 맑은 바람처럼 하나가 되었고, 폭풍 후의 호수처럼 완전히 고요해졌습니다. 의문도, 원망도, 두려움도 없었습니다. 그녀는 마침내 죽음 자체에 안착한 것입니다. \n“내가 당신을 기억할 겁니다.” \n그는 몸을 일으켜 이제 완전히 고요에 이른 그녀의 모습을 응시했습니다. 아득한 순간, 그의 송곳니가 피부에 닿고, 그는 셀리네의 목소리를 들었습니다. \n“당신을 믿어요, 오라버니.” \n그녀는 행운이었습니다. 둘르세인의 기억 속에서 그녀는 영원의 안식을 얻게 될 것입니다. ."
  },
  Item_9569_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 회복, 검은 인장 드롭율, 은열쇠 충전 중 무작위 1개를 획득합니다."
  },
