  Item_95704_Desc = {
    Text = "장해성의 주인은 망자가 모독당하는 것을 좋아하지 않는다. 이 남은 사지도 예외는 아니다. 식당에서 괜찮은 선물과 교환하는 데 쓸 수 있을지도 모른다.\n\n최소 {s1}개 드롭"
  },
  Item_95704_Name = {
    Text = "부패한 손뼈"
  },
  Item_9570_Desc = {
    Text = "장착자의 명령 카드 효과를 전면적 및 종합적으로 향상시켜, 「소멸」을 통해 더 많은 은열쇠 에너지를 획득하는 것과 단일 열쇠 지령 효과 상승 중 유연하게 선택하도록 합니다."
  },
  Item_9570_Name = {
    Text = "시첩의 끝구절"
  },
  Item_9570_StoryDesc = {
    Text = "그녀가 꽃집에서 눈을 뜨자, 대화재가 정원 전체를 휩쓸어 그녀 앞에 다가왔다. \n 꽃집의 문 잠금장치는 밖에서 잠겨 있었고, 공기 중에는 짙은 알코올과 기름의 냄새가 가득했다. 그녀는 크게 코레트의 이름을 부르며, 목소리가 연기에 쩔어 시끄러워지기 전까지 계속했다. 응답하는 것은 불꽃의 울부짖음뿐이었다. \n 그녀는 다행스러움을 느꼈다. 코레트가 밖에 나갔으니, 이렇게 큰 불이라면 자신도 위험했을 것이다. \n 그녀는 슬퍼졌다. 인생의 마지막 순간에, 그녀는 소중한 친구의 마지막 모습을 보지 못했다. 코레트가 돌아와서 불타버린 정원과 자신을 보게 된다면, 분명 매우 슬플 것이다. \n 그녀는 아쉬움을 느꼈다. 그들의 삶은 점점 좋아지고 있었는데, 이 불꽃이 그들에게 마침표를 찍을 것이다. \n 타오르다. 집이 타고 있다. 하늘이 타고 있다. 나뭇잎이 타고 있다. 꽃잎이 타고 있다. 정원에서 겪었던 장면들이 그녀 앞에서 연기되어 흘러간다: 그녀는 그녀를 정원으로 데려오고, 장미를 건네주며, 하루의 노동으로 그녀에게 부드러운 빵을 가져다 주었다. 그들은 장난치고, 쫓고, 고요한 햇빛 아래 누워 백작부인 방에 들어가는 날을 꿈꿨다. \n 타오르다. 과거가 타고 있다. 미래가 타고 있다. 정원은 모든 이야기와 모든 감정을 담고, 미친 듯이 타오르고 있다. \n 눈물이 그녀의 얼굴에서 흘러내리며, 불꽃의 뜨거움 속에서 곧 사라졌다. \n 그녀는 아름다움을 느꼈다. 시에서, 고통과 아쉬움은 아름다움이다. 그녀는 주위를 돌아다니며, 불꽃에 의해 침식된 종이와 펜을 찾았다. \n 감사, 그리움, 아쉬움, 축복, 아름다움. 그녀는 이 가장 아름다운 모든 것을 코레트에게 남기고 싶었다. \n “……코레트에게. 오를라, 불 속에서.” \n 시편의 마지막에, 그녀는 마지막 서명을 남겼다. \n 백 미터 떨어진, 정원 맞은편 도로에서, 코레트는 무언가를 감지한 듯 보였다. 그녀는 고개를 들었고, 강렬한 불빛이 그녀의 얼굴을 비추었다. \n 눈물이 그녀의 얼굴에서 흘러내리며, 불꽃의 뜨거움 속에서 곧 사라졌다."
  },
  Item_9571_Desc = {
    Text = "신비로운 보라색 휘광을 반짝이며, 캄브리안 계곡에 운석이 추락할 때 남은 파편이라고 전해집니다. \n 초원차원 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_9571_Name = {
    Text = "유성의 파편"
  },
  Item_9573_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9573_Name = {
    Text = "약재의 꿈 Ⅴ"
  },
  Item_9573_StoryDesc = {
    Text = "천 년 전, 5분은 40온스의 고운 모래와 같았다."
  },
  Item_9574_Desc = {
    Text = "“플라스크는 새 것처럼 세척해야 하고, 테이블은 반사될 정도로 광을 내야 하며, 저울은 3일마다 다시 교정해야 한다.”\n- 팀에 광기를 제공\n- 팀의 생명을 대량으로 회복"
  },
  Item_9574_Name = {Text = "돌"},
  Item_9575_Desc = {
    Text = "이제는 아무도 이걸로 길흉을 점치지 못할 거야. \n융해진흙으로 덮인 보라색 수정, 초월계역의 깨어남체 스킬 레벨을 올리는데 사용됩니다."
  },
  Item_9575_Name = {
    Text = "부서진 광석"
  },
  Item_9576_Desc = {
    Text = "주 속성으로 치명타 확률, 치명타 피해, 은열쇠 충전 레벨과 광기 충전 레벨 중 랜덤으로 1개를 획득한다."
  },
  Item_9576_Name = {
    Text = "뒤틀린 쌍둥이·백 Ⅰ"
  },
  Item_9576_StoryDesc = {
    Text = "하얀 안개의 축복."
  },
  Item_9577_Desc = {
    Text = "적 처치와 함께 영구적으로 많은 치명타 피해를 증가시키고, 점프 효과를 발동한 후 이번 턴의 피해 능력을 더욱 높일 수 있다."
  },
  Item_9577_Name = {
    Text = "가장 소중한 수집품"
  },
  Item_9577_StoryDesc = {
    Text = "너가 처음 살아있는 골렘을 만난 것은 여학자의 집에서였다.\n「지금까지 그녀는 여전히 나를 놀라게 한다. 나에게 그녀는 우주 자체이다.」\n골렘은 너에게 기계적인 미소를 지으며, 모호한 꿈결의 속삭임을 내뱉었다.\n너는 그녀의 회색 눈를 바라보며, 마치 거센 회색 바다에 서 있는 듯한 기분이 들었다. 반짝이는 파도가 한 지평선을 넘어 다른 지평선으로 기어가고 있었다.\n\n떠나기 전에, 여학자는 너에게 낡은 작은 책자를 건넸다. 그 안에는 골렘을 만드는 비법이 적혀 있었다.\n그날 밤, 너는 그것을 펼쳐서 엉성한 공식과 주문을 읽었지만, 머릿속에는 골렘의 잡히지 않는 미소만 가득했다.\n너는 그녀를 잊을 수 없었다.\n\n며칠 후, 너는 다시 방문할 핑계를 찾았다.\n너는 쌓여 있는 책, 도구, 골격을 넘어, 두꺼운 커튼과 얽힌 거미줄을 헤치고, 결국 골렘 앞에 무릎을 꿇었다.\n여학자는 구석에 웅크리고 있었다. 며칠 사이에 그녀는 수척해져, 눈에서는 빛을 잃었다.\n「너는 다시 왔구나…… 그들과 같아.」\n여학자는 허약하게 기침을 했다.\n「그래…… 나왔어.」\n너는 골렘의 손을 잡고 계속해서 입맞춤을 했다.\n차가운 손가락이 너의 목에 부드럽게 스치고, 미세한 고통이 느껴지며, 너는 눈을 감았다.\n\n깨어났을 때, 너는 따뜻한 흰 햇빛 아래에서, 몸이 부드러운 파도에 따라 오르락내리락하고 있었다.\n너는 전례 없는 가벼움을 느끼며, 마치 영혼이 육체를 버린 듯한 기분이었다.\n너는 고개를 돌려, 회색과 검은색의 머리들이 보였다.\n그들은 울부짖고, 왜곡되어, 마치 검은 야생화처럼, 회색 원질의 바다에 별처럼 흩어져 있었다.\n「안 돼——」\n목에서 검은 점액이 쏟아져 나오고, 너는 더 이상 움직일 수 없었다.\n결국 너도 그 머리들 중 하나가 되어버린 것이었다.\n\n「@2년 6월, 유명한 연금술사 로마린·루드비히가 자택 서재에서 기이하게 사망한 채 발견되었고, 그의 머리는 사라졌으며, 함께 실타래종된 것은 그 신비로운 연금술 수첩이었다……」\n\n(위 내용은 미사그 도서관 《연금술 일화》 제2권에 기록되어 있다.)"
  },
  Item_9578_Desc = {
    Text = "윙클 양이 개발한 신비한 약재로, 조사원이 미경에서 이성을 유지할 수 있도록 돕는 역할을 한다. 부작용은 아직 미지수이므로 사용에 주의할 것.\n현재 수량이 300 미만일 경우 5분마다 1개씩 자동으로 보충되며, 300을 초과할 경우 15분마다 1개씩 보충됩니다.\n최대 3000까지 보유할 수 있습니다."
  },
  Item_9578_Name = {
    Text = "린피테이프"
  },
  Item_9579_Desc = {
    Text = "미스터리의 본질은 금기의, 인식하기 어려운 지식이다. 타블렛을 사용하여 다시 묘사하면 미스터리의 힘이 더욱 강화된다."
  },
  Item_9579_Name = {
    Text = "밀키트 작성(이미 폐기됨)"
  },
  Item_9580_Name = {
    Text = "도해자 로고 흐린 버전"
  },
  Item_9581_Desc = {
    Text = "팀에 더 강력한 방패를 제공하는 동시에 폭발 피해를 증가시키고 더 많은 열쇠 에너지를 얻으며, 촉수의 타격에 의해 자신의 광기 순환을 가속화합니다."
  },
  Item_9581_Name = {
    Text = "은밀한 탄생"
  },
  Item_9581_StoryDesc = {
    Text = "어머니. 어머니. \n머피는 이미 관련된 대부분의 기억을 잃어버렸다. \n누군가는 죽어가는 어머니가 그녀를 보호하고, 피가 그녀의 목구멍으로 넘어갔다고 말했다. \n그러자 사람들은 앞다투어 나와 그녀들을 무례하게 분리했다. \n그 순간, 머피는 어머니의 얼굴을 보았다. 그 얼굴은 광란의 표정을 지었지만, 매우 아름다웠다. \n기억이 시작된 이후, 그녀는 새로운 “어머니”를 갖게 되었다. \n온화하고 신중한 그녀는 머피의 모든 불합리한 요구를 충족시켜 주었지만, 적당한 거리를 유지했다. \n머피는 그들의 관계가 이렇게 계속될 것이라고 생각했다. 마치 미리암의 표정이 영원히 변하지 않을 것처럼 말이다. 그러던 중 그녀는 높은 곳에서 칠흑 같은 왕좌에 들어 올려졌고, 꿈속에서 발광하는 “알”을 보았다. \n그것은 어둠 속에서 반짝이며, 눈 같기도 하고, 별 같기도 했다. 몽환적인 노래가 성소 주위를 감싸고 있었다: \n<Italic:그녀의 딸인 @1으로부터, @1의 신이 강림했다@1……>\n그녀는 자신과 관련이 있으면서도 없는 위대한 사명을 부여받았다: 신을 부활시키는 어머니가 되는 것. \n참 신기하구나. 그녀는 어머니가 무엇인지, 딸이 무엇인지 아직도 이해하지 못하는데, “어머니”가 되는 법을 배우기 시작해야 한다. \n머피는 그 광란의 아름다운 얼굴을 떠올렸고, 혀끝에 달콤하면서도 쓴 맛을 기억했다. \n그 아름다운 사람은 내가 이렇게 무덤으로 떨어지는 것을 원하지 않았던 것이지, 그렇지?"
  },
  Item_9582_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 충전 레벨, 검은 인장 드롭율, 은열쇠 충전 중 랜덤으로 1개를 획득한다."
  },
  Item_9582_Name = {
    Text = "저주받은 토끼 Ⅳ"
  },
  Item_9582_StoryDesc = {
    Text = "하얀 털 토끼를 싫어하는 사람은 없을 거에요."
  },
  Item_9583_Desc = {
    Text = "“하늘은 폭력으로 부서진 분수를 보호하라!”\n, 검은 인장을 잘 수집함\n, 적의 방어막을 제거할 수 있음"
  },
  Item_9583_Name = {Text = "라이커"},
  Item_9584_Desc = {
    Text = "세트: \n뒤틀린 쌍둥이·백Ⅰ\n뒤틀린 쌍둥이·백Ⅱ\n뒤틀린 쌍둥이·백Ⅲ\n뒤틀린 쌍둥이·백Ⅳ\n뒤틀린 쌍둥이·백Ⅴ\n뒤틀린 쌍둥이·백Ⅵ"
  },
  Item_9584_Name = {
    Text = "뒤틀린 쌍둥이·백"
  },
  Item_9585_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 충전 레벨, 검은 인장 드롭율, 은열쇠 충전 중 랜덤으로 1개를 획득한다."
  },
  Item_9585_Name = {
    Text = "황야의 늑대 Ⅳ"
  },
  Item_9585_StoryDesc = {
    Text = "아우우우, 아우우우."
  },
  Item_9586_Desc = {
    Text = "바람이 새는 집. 그래도 없는 것보다는 낫다.\n유적에 남겨진 번데기 껍질. 혈육 경계역 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다。"
  },
  Item_9586_Name = {
    Text = "마른 번데기"
  },
  Item_9587_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9587_Name = {
    Text = "바다에서 돌아오는 길 Ⅴ"
  },
  Item_9587_StoryDesc = {
    Text = "돌아오라, 잊혀진 그 도시가 재현될 것이다."
  },
  Item_9588_Desc = {
    Text = "광기 폭발이 가하는 기본 피해를 대폭 증가시키는 동시에, 거대한 광기 획득과 영구적인 피해 성장 사이에서 유연하게 선택할 수 있습니다."
  },
  Item_9588_Name = {
    Text = "이형체의 포식"
  },
  Item_9588_StoryDesc = {
    Text = "@1년 6월 5일\n알비노는 융식 균열에서 몇 가지 희귀한 은심을 가져왔다. 정말 대단하다.\n정제 방법을 조금 개선했다.\n이번에는 충분한 이산화탄소와 염소가 주입되었고, 저온 증발과 결정화……\n일부 기계적 단계, 기록할 것이 별로 없다.\n\n@1년 6월 6일\n실타래험체 024의 내장과 사지를 절제했다.\n이것은 알비노가 클리닉에서 가져온 소재로, 이미 13개의 융식 구멍이 생성되었으며, 최대 직경은 8mm이다.\nOS-106번 융식 괴물의 기생 생물 절단.\n각종 테스트 데이터 비교 결과, 그것과 024 사이의 공명이 가장 높은 상성이다.\n유일한 문제는…… 그 촉수가 좀 너무 「활발」하다는 것이다.\n나는 오랫동안 문어를 다시는 먹고 싶지 않을 것 같다.\n최종 결과가 나를 실타래망시키지 않기를 바란다.\n\n@1년 6월 6일\n접목 실타래험 성공, 실타래험체의 모든 생명 징후가 사라졌다.\n이는 흔한 상황으로, 접목 부위에 감염이 확산되지 않도록 확인하면 된다.\n관찰실타래에 일주일간 보내고, 다음은 내 일이 아니다.\n오늘 「내부 저널」에서 살아있는 깨어남체 실타래험을 비난하는 두 편의 글을 읽었다.\n말할 필요도 없이, 서명을 보니 미사그의 오래된 친구들이었다.\n정말 웃기다, 이 구식들이 조금만 그들의 뚱뚱한 엉덩이를 움직여서 실타래험실타래을 돌아다녔다면, 내 결론이 흔들림 없는 것임을 알았을 것이다.\n024의 실타래험은 훌륭한 반격이 될 것이다.\n\n@1년 6월 22일\n2주가 지났고, 024의 각종 생체 징후는 여전히 불안정하다—— 아니면 이렇게 말하겠다, 그녀의 체내 인격이 세포 유사 분열 속도로 미친 듯이 증식하고 있다.\n실타래험은 상상할 수 없는 방식으로 실타래패를 선언했다.\n024를 왁스상관으로 보내자, 나는 매일 나를 지키고 있도록 할 필요가 없다, 그렇게 해서 내 어리석음과 경솔함을 항상 떠올리게 할 필요가 없다."
  },
  Item_9589_Desc = {
    Text = "장착자가 부여하는 중독 수치를 증가시키며, 은열쇠 발동 시 추가로 광기를 획득합니다."
  },
  Item_9589_Name = {
    Text = "부패의 선물"
  },
  Item_9589_StoryDesc = {
    Text = "「사람들은 밀물이 올 때 태어나고, 썰물이 갈 때 죽는다」\n이는 닌피야의 고향에서 오랜 세월 동안 전해져 내려온 전설입니다.\n\n세와다 주민들은 죽음을 두려워하지 않습니다. 그들에게 생명의 싹트임과 시듦은 밀물과 썰물처럼 자연의 일부일 뿐입니다.\n그들은 푸른 하늘, 바다, 무리를 지어 날아다니는 갈매기, 그리고 아침 해를 맞으며 피어나는 스파티필룸을 사랑합니다.\n반대로 그들은 증기, 철도 같은 인공적인 흔적이 지나치게 심한 사물—생명에 대한 간섭을 포함하여—를 혐오합니다.\n자신의 생명을 인위적으로 끊는 것은 세와다 사람들이 용납하지 못하는 행동입니다.\n\n닌피야는 전형적인 세와다 주민은 아닙니다.\n예를 들어, 그녀는 침몰한 배의 분위기에 항상 매료되곤 했습니다.\n죽은 배 한 척은 무수한 생명들의 보금자리입니다: 물고기, 수초, 여러 가지 조개류...\n그곳에서는 삶과 죽음이 묘하고 신성한 방식으로 얽히게 됩니다.\n닌피야는 차분한 마음으로 침몰한 배로 다가가는데, 마치 웅장한 대성당에 들어서는 것처럼 느껴졌습니다.\n\n아버지가 그녀를 데리고 여행을 다니던 시절, 닌피야는 한 5막극을 보았습니다.\n그 연극의 내용은 이미 그녀의 기억 속에서 흐려져, 고대 제왕의 생애를 다룬 것으로만 남아 있습니다.\n그는 생전에 말을 달리며 남북을 정복했지만, 비열한 음모로 인해 죽음을 맞이합니다.\n닌피야는 극 중에서 나온 한 구절을 기억합니다:\n<Italic:비겁자는 죽기 전에 이미 여러 번 죽는다; 용사는 평생 단 한 번 죽을 뿐이다.>\n\n여러 해가 지나고, 차가운 바닷물 속으로 나아가던 닌피야는 삶에 대한 애착으로 인해 견딜 수 없을 만큼 고통스러웠을 때, 그 구절이 그녀의 머릿속을 스쳐갔습니다:\n「용사는 평생 단 한 번 죽을 뿐이다...」\n그녀는 눈물을 닦고 마지막으로 부모님께 작별 인사를 고한 뒤, 마음속 침몰한 배로 조용히 나아갔습니다.\n그녀는 스스로의 용사가 되기로 결심했습니다."
  },
  Item_9590_Name = {
    Text = "프랜시스의 노트"
  },
  Item_9591_Desc = {
    Text = "기획자 테스트용 SSR 무기"
  },
  Item_9591_Name = {
    Text = "시작 레이저 포(치명타) 개발용"
  },
  Item_9591_StoryDesc = {Text = "미완성"},
  Item_9592_Desc = {
    Text = "인류의 존속을 위해. \n액자에 보관된 감정. 혈육 영역 깨어남체의 승급에 사용되는 재료입니다."
