  Item_9592_Name = {
    Text = "감정 복사본"
  },
  Item_9593_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 문서로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9593_Name = {
    Text = "순백의 서류"
  },
  Item_9594_Desc = {
    Text = "기호, 문자, 기억…… 그것은 모든 것을 변조할 것입니다. \n미스터리 전사에 사용됩니다. 전사 후 미스터리는 새로운 부속성을 무작위로 생성합니다."
  },
  Item_9594_Name = {
    Text = "천면인장"
  },
  Item_9595_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n틴커트를 반복 획득 시 전환하여 기령을 얻습니다."
  },
  Item_9595_Name = {
    Text = "파편 · 틴커트"
  },
  Item_9595_StoryDesc = {
    Text = "틴커트를 변환하여 획득한 후, 이를 기령 활성화에 사용할 수 있습니다."
  },
  Item_9596_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9596_Name = {
    Text = "무구의 계시록 Ⅲ"
  },
  Item_9596_StoryDesc = {
    Text = "그것은 영원하고 무구한 진실타래의 한 순간이다."
  },
  Item_9597_Desc = {
    Text = "손으로 만지지 말 것.\n특제 배양 용기에 밀봉된 희귀한 영식. 해금된 SSR 캐릭터의 깨어남체 파편 중 1개를 선택할 수 있습니다."
  },
  Item_9597_Name = {
