  },
  Item_9598_Desc = {
    Text = "세트: \n핏빛의 포옹Ⅰ\n핏빛의 포옹Ⅱ\n핏빛의 포옹Ⅲ\n핏빛의 포옹Ⅳ\n핏빛의 포옹Ⅴ\n핏빛의 포옹Ⅵ"
  },
  Item_9598_Name = {
    Text = "핏빛의 포옹"
  },
  Item_9599_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_9599_Name = {
    Text = "광합성 제례 Ⅱ"
  },
  Item_9599_StoryDesc = {
    Text = "과학은 분광 분석이고, 예술은 광합성이다."
  },
  Item_9600_Desc = {
    Text = "세트: \n기계장치의 신Ⅰ\n기계장치의 신Ⅱ\n기계장치의 신Ⅲ\n기계장치의 신Ⅳ\n기계장치의 신 Ⅴ\n기계장치의 신 Ⅵ"
  },
  Item_9600_Name = {
    Text = "기계장치의 신"
  },
  Item_9601_Desc = {
    Text = "꿈틀대고, 몸을 비틀며, 우리는 어둠 속을 기어다닌다...쉬...쉬......\n감염된 번데기. 혈육 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9601_Name = {
