  },
  Item_9602_Name = {Text = "신문"},
  Item_9603_Desc = {
    Text = "세계는 그녀의 이름을 잊어버렸고, 그렇게 백합처럼 피어난 하얀 실타래루엣은 서둘러 “Lily”라는 이름으로 불리게 되었다. \n·생명을 대가로 높은 방어막을 부여\n·상처받음이 깊을수록 데미지가 증가"
  },
  Item_9603_Name = {Text = "릴리"},
  Item_9604_Desc = {
    Text = "우리에게 미지의 정신을 부여한다.\n필린 시사의 특수 필름으로, 인간의 정신을 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9604_Name = {
    Text = "정신 템플릿"
  },
  Item_9605_Name = {
    Text = "프랜시스의 일기장"
  },
  Item_9606_Desc = {
    Text = "세트: \n먼 곳의 잔치Ⅰ\n먼 곳의 잔치Ⅱ\n먼 곳의 잔치Ⅲ\n먼 곳의 잔치Ⅳ\n먼 곳의 잔치Ⅴ\n먼 곳의 잔치Ⅵ"
  },
  Item_9606_Name = {
    Text = "먼 곳의 잔치"
  },
  Item_9607_Desc = {
    Text = "번거롭지만 반드시 해야만 하는 일과.\n지시 보고서에 사용되는 붉은 도장은 학기 과제의 진도를 높여주며, 당신이 결코 게으르지 않은 모범생임을 증명한다."
  },
  Item_9607_Name = {
    Text = "과제 증명"
  },
  Item_9608_Desc = {
    Text = "기획자 실타래험용 R 등급 무기"
  },
  Item_9608_Name = {
    Text = "시작용 칼 (광기) 개발용"
  },
  Item_9608_StoryDesc = {Text = "미완성"},
  Item_9609_Desc = {
    Text = "그가 호수의 바닥으로 몸을 던지자, 끓어오르는 기포들이 부드럽게 그를 감쌌다. \n·방어막 적용, 반격 획득 \n·생명 회복, 터치 월의 힘 강화"
  },
  Item_9609_Name = {
    Text = "카이커스"
  },
  Item_9610_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_9610_Name = {
    Text = "모임의 순간"
  },
  Item_9610_StoryDesc = {
    Text = "워드 필립스 선생님에게 수용된 이후, 알리스타르는 그와 함께 여러 차례 미사그의 고위 회의에 참석했다.\n\n고위라고는 하지만, 실타래제로는 매달 한 번 열리는 토론회에 더 가깝다:\n필립스 선생님은 온화한 어조로 순차적으로 유도하고;\n클라르크스는 신랄한 발언으로 한 발짝도 물러서지 않는다.\n그들은 차례로 찬성 또는 반대 입장을 맡아 미사그의 미래나 다음 달 깨어남학과의 자원 배급을 두고 끝없이 다투었다.\n타비 양은 조용한 관찰자로서 쉽게 자신의 의견을 내지 않는다.\n자신은 정직한 점수 기록자가 되기 위해 노력하며, 가끔 심판 역할도 맡고, 심지어 한 번은 격투 기술을 써야 할 정도로 작은 회의 테이블이 위험에 처한 적도 있다.\n\n현재 회의 구성원은 두 명만 남았다. 한 명은 영원히 블랙풀을 떠날 수 없고, 다른 한 명은 그 가능성 있는 “미래”를 위해 더 이상 지하에서 나올 수 없다.\n그 테이블은 그 사건 이후로 다시는 찾을 수 없게 되었다."
  },
  Item_9611_Desc = {
    Text = "코르트 학장 대행 특별 승인의 풍부한 보급품입니다.\n귀중한 소재가 들어 있는 나무 상자로, 밀경과실타래의 일일 시험 훈련과 주간 훈련 임무를 수행하는 수호자에게 도움을 제공합니다.\n다음의 모든 소재를 얻을 수 있습니다:\n빛나는 결정 나비*9\n긴줄기 바다나리*9\n원생 번데기*9\n유성 파편*9"
  },
  Item_9611_Name = {
    Text = "Ⅰ급 전역 보급"
  },
  Item_9612_Desc = {
    Text = "세트: \n달콤한 달팽이Ⅰ\n달콤한 달팽이Ⅱ\n달콤한 달팽이Ⅲ\n달콤한 달팽이Ⅳ\n달콤한 달팽이Ⅴ\n달콤한 달팽이Ⅵ"
  },
  Item_9612_Name = {
    Text = "달콤한 달팽이"
  },
  Item_9613_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 페이지로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9613_Name = {
    Text = "순백의 조각"
  },
  Item_9614_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 완다를 획득할 때 전환하여 완다의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9614_Name = {
    Text = "파편 · 완다"
  },
  Item_9614_StoryDesc = {
    Text = "중복으로 완다를 획득할 때 전환하여 획득하고, 완다의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9615_Desc = {
    Text = "알 수 없는 침전물.\n근원의 거품을 탈수해 얻은 침전물이다. 잘 보관하라, 이는 미사그 상점의 화폐다."
  },
  Item_9615_Name = {
    Text = "근원 침전물"
  },
  Item_9616_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_9616_Name = {
    Text = "노심융해"
  },
  Item_9616_StoryDesc = {
    Text = "A. F.@1년@1월@1일\n\n08:00\n\n번호 107에서 133까지의 부품 조립을 진행합니다.\n\nC형 부품은 이제 이 부분만 남았으며, 완료 후 자동인형 「틱택맨」의 에너지 코어로 사용될 예정입니다.\n\n저는 직접 조립하고 싶었지만, @2가 책임자는 자신의 작업 파트너를 신뢰하는 법을 배워야 한다고 말했습니다.\n\n정말 뻔뻔하게 말하네요, 분명히 그녀가 부품 점검을 자정까지 한 사람이거든요.\n\n-------\n\nA. F.@1년@1월@1일\n\n00:21\n\n모터 MF311000 조립 완료, 기어 맞춤, 배관 원활, 현재 모든 기술 정상입니다. 곧 마지막 수정이 진행될 예정입니다.\n\n13:07\n\n특수 에너지 S를 접속하였고, 모터 MF311000이 잘 작동하며 EA307850번 인공 몸체와 잘 맞습니다. 인공 몸체는 정상적으로 작동하고 있습니다.\n\n@2는 매우 낙관적입니다. 그녀는 우리가 이번에 이전보다 더 멀리 나갈 수 있다고 생각합니다. 저는 그녀에게 다섯 번째 깨어남 시도 때 무슨 일이 일어났는지 잊지 말라고 상기시켰더니, 그녀는 귀를 막고 듣지 못한다고 했습니다. 그때 제가 반응이 빨랐더라면 에너지 코어가 자가 발화하여 그녀의 머리카락이 모두 타버릴 뻔했습니다.\n\n정말 그녀에게 대머리의 맛을 보여줘야 할 것 같아요, 그러면 그녀도 조심하는 법을 배울 수 있을지도 모릅니다.\n\n-------\n\nA. F.@1년@1월@1일\n\n14:55\n\n최종 준비 완료, 에너지 준비 완료, 속박 장치가 활성화되었으며, 속박 상태: 양호. 몸체는 깨어남이 완료된 후 설치될 예정입니다.\n\n15:00\n\n「틱택맨」 제13차 시동 시도를 시작합니다.\n\n15:05\n\n몸체 EA307853이 정상적으로 작동하며, 모터 MF311000이 정상적으로 작동합니다. 「틱택맨」 목 관절이 정상적으로 작동하고, 「틱택맨」 머리 부품이 정상적으로 작동합니다.\n\n15:15\n\n「틱택맨」이 성공적으로 눈 깜빡임, 시선 추적, 입 벌리기 명령을 수행했습니다. 모터에서 발열 현상이 있지만 여전히 허용 범위 내입니다.\n\n이제 사지 부품 설치를 진행합니다. 하늘이여, 이번에는 순조롭게 진행되기를 바랍니다.\n\n18:07\n\n걷기 명령을 실타래행할 때, 모터의 핵이 융해되고 회로가 타버렸습니다. 특수 에너지 S는 손상되지 않았습니다.\n\n@2는 이 특수 에너지를 매우 소중히 여기며, 저조차도 만지지 못하게 합니다. 이해할 수 있을 것 같아요, 정말 신비로운 물체입니다. 보기에는 평범한 금속 은처럼 보이지만 에너지를 저장할 능력이 없어 보이는데, 진짜로 자동인형에 전원을 공급할 수 있고, 그런 높은 온도에서도 손상되지 않았다니 정말 믿기 어렵습니다.\n\n이 물체가 대량 생산되거나 대량 채굴이 가능하다면……\n\n어쩌면 하루를 정해서 다시 그녀에게 물어봐야 할 것 같습니다. 그녀가 이 인형에 얼마나 더 많은 시간을 쏟을지 모르겠네요. 언젠가 그녀가 스스로 인형이 된다면 저는 전혀 놀라지 않을 것 같습니다."
  },
  Item_9617_Desc = {
    Text = "유령선에 산일된 감정 입자로, 접촉하면 \"어쩔 수 없어요\"라는 탄식이 들리는 듯합니다.\n수호자가 조사 이벤트 「폭풍의 눈」에서의 공명을 높이는 데 사용됩니다.\n「폭풍의 눈」 관문 첫 클리어 보상에서 획득할 수 있습니다."
  },
  Item_9617_Name = {
    Text = "절망의 심장"
  },
  Item_9619_Desc = {
    Text = "기호, 문자, 기억…… 그것은 모든 것을 변조할 것입니다. \n비밀 계약 업그레이드와 미스틱 전사에 사용되며, 비밀 계약 업그레이드는 비밀 계약의 주 속성을 향상시키고, 미스틱 전사는 비밀 계약이 부속성을 무작위로 획득하게 합니다."
  },
  Item_9619_Name = {
    Text = "천면인장"
  },
  Item_9620_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 회복, 검은 인장 드롭율, 은열쇠 충전 중 무작위 1개를 획득합니다."
  },
  Item_9620_Name = {
    Text = "달콤한 달팽이 Ⅳ"
  },
  Item_9620_StoryDesc = {
    Text = "달콤하고, 끈적거린다."
  },
  Item_9621_Desc = {
    Text = "날개는 단지 아름다움을 더할 뿐이며, 5펜시의 값어치가 있다. \n빛나는 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9621_Name = {
    Text = "빛나는 결정 나비"
  },
  Item_9622_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다. 당신의 본능, 당신의 이성, 심지어 당신의 영혼까지... 결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9622_Name = {
    Text = "연마된 이성"
  },
  Item_9623_Desc = {
    Text = "소지자가 매회 가하는 피해량을 증가시키며, 초차원 턴이 끝난 후 추가로 적의 중독을 유발할 수 있습니다."
  },
  Item_9623_Name = {
    Text = "돌고 도는 춤사위"
  },
  Item_9623_StoryDesc = {
    Text = "거대한 무대 위에서 한 소녀가 춤추고 있습니다.\n 그녀의 머리는 단단하게 올려져 있으며, 깨끗한 흰색 깃털과 작고 귀여운 왕관으로 장식되어 있습니다. 순백의 무용복이 그녀의 동작에 따라 펼쳐지며, 슬픈 바이올린 선율에 맞춰 한 바퀴, 또 한 바퀴 돌고 있습니다.\n 팔을 펼치고 발끝으로 땅을 찍으며, 백조는 긴 목을 낮추고 왕자에게 자신의 슬픔과 애수를 이야기합니다.\n 어린 리즈는 입을 살짝 벌리고 무대 위에서 가볍고 우아한 소녀를 바라보고 있습니다. 그 소녀는 그녀의 사촌으로, 리즈가 태어나기 전부터 그녀의 집에 와서 할머니에게서 엄격한 훈련을 받았습니다. 평소에는 항상 소박하고 조용한 사촌이 오늘처럼 생동감 넘치는 적은 없었습니다. 그녀는 마치 날개를 퍼덕일 준비가 된 백조처럼 보였고, 그녀, 그리고 극장 안의 모든 사람들은 그녀의 그림자 아래에 매료되었습니다.\n 그녀의 심장은 점점 더 빨리 뛰고, 점점 더 빨리 뛰고 있습니다—— 얼마나 부럽습니까! 그녀도 그 백조가 되고 싶습니다. 영원한 무대 위에 자신만의 그림자를 오래 남기고 싶습니다. 그녀는 자신이 할 수 있다는 것을 알고 있습니다. 할머니가 자신이 모르는 사이에 다리가 길고 곧다고 칭찬하지 않았나요? 그녀가 오랫동안 수석을 맡았던 사촌이 그녀에게 춤에 대한 재능이 뛰어나다고 말하지 않았나요? 맞습니다. 그녀가 시작하기만 하면, 발끝 신발을 신기만 하면, 사람들은 먼 도시에서 공연을 보러 올 것입니다. 그녀는 이번 세기의 가장 위대한 무용가가 될 것이며, 발레 예술의 찬란한 스타가 될 것입니다!\n 그때의 그녀는 자신의 앞에 기다리고 있는 것이 오직 뜨거운 불꽃뿐이라는 것을 알지 못했습니다."
  },
  Item_9624_Desc = {
    Text = "고집스럽고, 이기적이고, 자기 중심적…… 그녀와 접촉해 본 많은 사람들이 그녀의 성격에 대해 이런 평가를 내린다. \n·생명 상한을 희생하고 방어막과 산출력을 획득한다. \n·방어막을 부여하고, 터치 월의 힘을 강화한다."
  },
  Item_9624_Name = {Text = "머피"},
  Item_9625_Desc = {
    Text = "지속적이고 안정적인 광기와 은열쇠 획득, 광기 폭발에 의존하는 은열쇠 캐릭터에게 적합하다."
  },
  Item_9625_Name = {
    Text = "아쿠트의 봄"
  },
  Item_9625_StoryDesc = {
    Text = "재앙이 허공에서 사라지고, 위기가 일시적으로 해제된 후, 미사그 특별 작전대는「의외의 수확」을 가지고 아쿠트를 떠났습니다.\n덕스터씨는 마지막으로 폭발 중심의 거대한 구덩이를 한 번 돌아보았고, 알 수 없는 식물의 연한 싹이 언제 자랐는지 조용히 땅을 뚫고 나왔습니다.\n그녀는 안도의 한숨을 쉬며 기분이 좋았습니다.\n아쿠트 린지는 자신의 봄을 맞이할 것입니다.\n버드나무는 다음 봄이 올 때 가지를 뻗고, 은방울꽃은 다음 우기가 지나면 조용히 피어날 것이며, 모든 생명은 신생을 맞이할 것입니다.\n그리고 그들은 미지를 향한 여정을 새롭게 시작할 것입니다.\n"
  },
  Item_9626_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9626_Name = {
    Text = "유기 형태 Ⅵ"
  },
  Item_9626_StoryDesc = {
    Text = "나비는 외로움, 사랑, 그리고 절망으로 인해 죽어가고 있었다."
  },
  Item_9627_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9627_Name = {
    Text = "진홍빛 심동 Ⅵ"
  },
  Item_9627_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 자신의 혈액으로 골렘을 길러냈다."
  },
  Item_9628_Desc = {
    Text = "주 속성으로 광기 충전 레벨, 죽음 저항, 은열쇠 충전 레벨과 피해 증폭 효과 중 랜덤으로 1개를 획득한다."
  },
  Item_9628_Name = {
    Text = "황야의 늑대 Ⅴ"
  },
  Item_9628_StoryDesc = {
    Text = "아우우우, 아우우우."
  },
  Item_9629_Desc = {
    Text = "수억 년 전, 그들은 따뜻한 바다에서 군림했다.\n높은줄기 바다백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9629_Name = {
    Text = "높은줄기 바다백합"
  },
  Item_9630_Desc = {
    Text = "「타격」을 사용할 때 추가 행동력을 획득하고, 촉수로 적을 공격할 수 있다."
  },
  Item_9630_Name = {
    Text = "폭우 속에서"
  },
  Item_9630_StoryDesc = {
    Text = "내 배는 무언가에 단단히 포박되어 있고, 프로펠러는 힘겹게 몸부림치며 무서운 소리를 내고 있다.\n적란운이 우리 머리 위에 모여들고, 검은 구름 속에서 번개가 요동친다.\n천둥이 마스트에 부딪히는 순간, 프로펠러는 속박에서 벗어나 다시 회전하기 시작했다.\n나는 안도의 한숨을 쉬었지만, 기관장은 비명을 지르기 시작했다.\n\n바닷물 속에 끈적한 액체가 섞여 들어갔고, 폭풍우의 야외에서 그 냄새가 바람을 타고 멀리 퍼져 나갔다. 내 코는 오직 죽음의 냄새만을 맡을 수 있었다.\n하지만 나는 그 반짝이는 형광 액체가 어떤 혈액임을 깨달았다.\n내 가장 소중한 동료, 내가 가장 신뢰하는 배는 침몰하기 전 최선을 다했다——그녀가 본래 바닷물을 가르며 나가야 할 날개가 몬스터의 촉수를 강하게 베어냈다.\n\n이것은 행운의 징조다! 우리는 곧 폭풍우를 벗어날 수 있을 것이다!\n나는 이로써 내 선원들을 달래고 싶었지만, 고개를 들자마자 어둠의 바다 중앙에 빛이 나타났다.\n그것은 등대인가? 어떻게 그럴 수 있지? 아니, 불가능하다.\n여기는 대양 중앙이고, 가장 가까운 육지는 수백 해리 밖에 있다. 어떻게 사람이 있을 수 있고, 어떻게 여기서 등대를 세울 수 있겠는가?\n\n내 수레주인들은 울기 시작하고, 기도를 올리기 시작하며, 고향의 노래를 함께 부르기 시작했다.\n그러나 그 등대는 갑자기 꺼졌다.\n모든 빛이 사라지고, 포효하는 폭풍도 이슬비처럼甲板에 떨어졌다.\n선원들은 자비로운 주를 찬양하며, 재난에서 살아남은 기쁨에 젖어 있었다.\n하지만 나는 분명히 보았다.\n\n그 빛 속에서 사라진 것은 분명히 우아한 몸매의 여자였다."
  },
  Item_9631_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9631_Name = {
    Text = "핏빛의 포옹 Ⅲ"
  },
  Item_9631_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 그가 빚어낸 존재를 두 손으로 끊어냈다."
  },
  Item_9632_Desc = {
    Text = "우리에게 미지의 정신을 부여한다.\n필린 시사의 특수 필름으로, 인간의 정신을 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9632_Name = {
    Text = "정신 템플릿"
  },
  Item_96331_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매하면 얻을 수 있습니다.\n「언제 블랙풀에 가더라도 그녀의 얼굴에는 그 기괴한 미소가 가득합니다. 당신은 종종 융식이 그녀의 뇌 운동 피질을 파괴했는지, 아니면 편도체가 감정을 표현하는 부분이 이 잠금된 하나만 남았는지 의심하게 됩니다.」"
  },
  Item_96331_Name = {
    Text = "결코 바래지 않는 어제: 융해·돌"
  },
  Item_96331_StoryDesc = {
    Text = "제20기 과제 기록"
  },
  Item_96332_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매하면 얻을 수 있습니다.\n「36시간 동안의 실타래험실타래 작업으로 인해 그 천재 두뇌의 피로가 인형의 몸을 통해 발산되고, 당신은 무기질의 얼굴에 환상적인 다크서클이 나타나는 것을 보는 듯합니다. 생명을 지키기 위한 상식: 이럴 때 그녀의 이성을 절대 도전하지 마세요, 절대.」"
  },
  Item_96332_Name = {
    Text = "결코 바래지 않는 어제: 돌"
  },
  Item_96332_StoryDesc = {
    Text = "제20기 과제 기록"
  },
  Item_9633_Desc = {
    Text = "이것은 공예품이 아니라, 연금술사와 마주한 나비의 비극적인 최후다. \n단순한 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9633_Name = {
    Text = "희미한 결정 나비"
  },
  Item_9634_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_9634_Name = {
    Text = "유기 형태 Ⅰ"
  },
  Item_9634_StoryDesc = {
    Text = "나비는 외로움, 사랑, 그리고 절망으로 인해 죽어가고 있었다."
  },
  Item_9635_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9635_Name = {
    Text = "생명력 착취 Ⅴ"
  },
  Item_9635_StoryDesc = {
    Text = "탯줄은 끝없는 미래와 연결되어 있다."
  },
  Item_9636_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9636_Name = {
    Text = "무덤의 속삭임 Ⅲ"
  },
  Item_9636_StoryDesc = {
    Text = "네 무덤을 증오한다."
  },
  Item_9638_Name = {
    Text = "오래된 사진"
  },
  Item_9639_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다. 당신의 본능, 당신의 이성, 심지어 당신의 영혼까지... 결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9639_Name = {
    Text = "연마된 이성"
  },
  Item_9640_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_9640_Name = {
    Text = "바다에서 돌아오는 길 Ⅰ"
  },
  Item_9640_StoryDesc = {
    Text = "돌아오라, 잊혀진 그 도시가 재현될 것이다."
  },
  Item_9641_Desc = {
    Text = "기획자 테스트용 SSR 무기"
  },
  Item_9641_Name = {
    Text = "시작 레이저 포 (광기) 개발용"
  },
  Item_9641_StoryDesc = {Text = "미완성"},
  Item_9642_Desc = {
    Text = "카드를 사용하면서 추가 방패를 얻고, 촉수가 많은 팀에서 더 좋은 성능을 발휘한다."
  },
  Item_9642_Name = {
    Text = "산호 여인의 죽음"
  },
  Item_9642_StoryDesc = {
    Text = "그녀는 결코 꿈을 꾸지 않는다.\n\n젊은 조각가 수습생은 절대적인 이성과 질서를 신념으로 삼고 있으며, 그녀의 차가운 작품과도 같다.\n그것을 처음 본 순간부터 그녀는 매료되었다.\n부드럽고 순수한—그것은 완벽한 채색 재료이다.\n그녀는 달빛 아래에서 바쁘게 움직이며, 검은 점액을 난장터에서 작업실타래로 가져온다.\n\n일주일 후, <@2>라는 이름의 조각상이 박람회에 전시된다.\n그날 밤, 그녀는 먼 곳에서 들려오는 파도 소리를 듣는다.\n그녀는 처음으로 꿈을 꾸었다.\n조용한 아침 빛 아래, 먼지로 덮인 해저 궁전은 깊은 잠에 빠져 있다.\n그녀는 하얀 산호 군락 속을 지나며, 호흡 속에는 고독과 잊혀짐의 향기가 가득하다.\n\n깨어나고 나서, 그녀의 손가락은 움츠러들고 검게 변해, 결국 하얀 산호가 돋아났다.\n그녀는 여러 번 냄새를 맡으며, 그 안에 있는 고대의 수많은 생물들의 저어 저어 소리를 느낀다.\n그것은 진정한 부드러운 화석이다.\n그녀는 신경질적으로 웃음을 터뜨렸다—이것이 꿈꾸는 것이구나.\n그녀는 작업실타래에 자신을 가두고, 잊고 있는 듯한 창작을 시작한다.\n주형, 점토 조각, 채색……\n혼란의, 질서의. 무기물의, 유기물의.\n\n그녀는 영원히 꿈을 꾸게 될 것이다."
  },
  Item_9643_Desc = {
    Text = "노련한 수호자들의 활성화된 정신력으로 변환된 입방체. 다프다일의 작은 상점에서 귀중한 소재로 교환할 수 있습니다."
  },
  Item_9643_Name = {
    Text = "염석(이미 폐기됨)"
  },
  Item_9644_Desc = {
    Text = "전투 초반 폭발적으로 많은 광기를 제공하고 지속적으로 광기 순환을 가속화하여, 광기에 의존하는 폭발형 캐릭터에게 적합하다."
  },
  Item_9644_Name = {
    Text = "신왕의 찬송가"
  },
  Item_9644_StoryDesc = {
    Text = "그는 만사를 알고 있는 왕이며, 리모리아의 지고의 존재입니다.\n청금석은 그의 왕좌이고, 골드는 그의 관입니다. 영혼은 그의 권위이며, 그는 최고 위치에서 잠들어 있습니다.\n신을 섬기는 사제들도 그를 섬기며, 그의 앞에 무릎 꿇고 있습니다.\n그들은 그의 충실타래한 신하들이며, 그의 성실타래한 신도입니다.\n\n신들은 밤에 월광을 파견하여 그를 영면의 궁전으로 초대합니다.\n그곳에서, 그들은 그와 영혼의 음식을 나누고, 신의 지혜를 줍니다.\n그들은 그에게 끝없는 꿈을 주어, 만물의 시작과 시간의 끝을 보게 합니다.\n그는 이에 대해 알게 되었습니다: 만물의 시작은 혼돈이며, 신들이 그 속에서 깨어남하여 어둠에 떠 있는 궁전을 세웁니다.\n그는 이에 대해 알게 되었습니다: 시간의 끝은 어둠이며, 모든 것이 혼돈으로 돌아갑니다.\n\n왕 중의 왕이여, 신의 사랑받는 자여,\n누가 당신과 같을 수 있겠습니까?\n누가 당신처럼 꿈속에서 통솔할 수 있으며, 누가 당신의 위엄과 같을 수 있겠습니까?\n고귀한 신왕이여, 어린 주재여,\n부디 마음껏 잠들어 주십시오.\n당신의 신민과 신도는 당신이 신의 예언을 가져오기를 인내하며 기다릴 것입니다.\n존경하는 스크류 사라짐 주재여, 심연의 주인을 명령하십시오,\n부디 우리가 당신의 이름을 호출하게 해주시고, 우리에게 보호를 주십시오,\n툴루, 툴루."
  },
  Item_9645_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9645_Name = {
    Text = "4월의 찬가 Ⅴ"
  },
  Item_9645_StoryDesc = {
    Text = "그는 @2년 봄에 땅에 묻혔다."
  },
  Item_9646_Desc = {
    Text = "코레트 대리 학장 특별 승인의 풍부한 보급품입니다. \n내용물은 다음과 같습니다: \n침식된 뼈 조각*3\n파손된 광결정*3\n부패한 식물*3"
  },
  Item_9646_Name = {
    Text = "Ⅰ급 보급 (이미 폐기됨)"
  },
  Item_9647_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n윙클을 반복 획득할 때 전환하여, 윙클의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9647_Name = {
    Text = "파편 · 윙클"
  },
  Item_9647_StoryDesc = {
    Text = "벤코르를 중복으로 획득할 때 전환하여, 벤코르의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9648_Desc = {
