  },
  Item_9653_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬: “쥐의 지혜”를 선택할 수 있습니다. \n\n소년쥐와 그의 주인은 많은 공통점을 가지고 있다: \n교활하고, 용감하며, 빨리 달린다…… \n그들은 자유롭게 동쪽 지역의 어지러운 집 간격을 누비며 하늘을 이불 삼고 지붕을 자리 삼는다. \n그들은 도시의 구석에서 튼튼하게 자란다."
