  Item_9663_Desc = {
    Text = "주 속성으로 광기 충전 레벨, 죽음 저항, 은열쇠 충전 레벨과 피해 증폭 효과 중 랜덤으로 1개를 획득한다."
  },
  Item_9663_Name = {
    Text = "먼 곳의 잔치 Ⅴ"
  },
  Item_9663_StoryDesc = {
    Text = "즐겁게 잔치를 즐겨라, 노랫소리 속에서."
  },
  Item_96640_Desc = {
    Text = "메이슨은 최근에 기름종이 우산을 하나 얻었다. \n 그것은 동방 여러 나라에서 임무를 수행하고 돌아온 조사원이 가져온 기념품 중 하나이다. 가늘고 대나무로 된 우산 뼈대는 믿을 수 없을 만큼 유연하게 선명한 붉은색 우산 면을 지탱하고 있다. \n 그녀는 이렇게 손상된 수공예품이 오직 감상용으로만 쓰일 것이라고 걱정했지만, 조심스럽게 우산을 받쳐 들고 비를 맞으며 걸어 들어가자, 그 얇고 마치 손을 뻗으면 뚫어버릴 수 있을 것 같은 종이 면으로는 한 방울의 빗방울도 스며들지 않는다는 것을 발견했다. 기름의 은은한 향기 속에서, 그녀는 흐릿한 붉은 빛의 아우라 아래 서서 동방의 아름다움에 전례 없는 매료를 느꼈다. \n미사그가 가을 야외 만찬을 개최할 것이라는 통지를 받은 후, 메이슨은 즉시 그 기름종이 우산을 떠올렸다. 그녀는 그것과 어울리는 드레스를 만들고, 그 우산을 들고 캠퍼스의 보도를 걸어가고 싶어했다.\n그녀는 렌티니언 최고의 직조 여공이었으니, 비록 동방의 의상을 본 적이 없더라도, 도서관에서 빌린 책에 있는 몇 안 되는 소개를 바탕으로 상상력을 발휘하여 스탠드 조명 아래에서 세심하게 재단하고 바느질했다.\n레이스, 구슬, 드레스를 끌어내리는 치마자락, 그리고 동방 의상에서 긴 소매. 그녀는 가장 아름다운 장식을 이 드레스에 바느질했고, 이후 특별히 빨간색 치마 가장자리와 소매 안감을 추가했다.\n「이렇게 하면 그 우산과 어울리겠지.」\n메이슨은 조형대 옆에 서서 그녀가 만든 깨끗한 면사 드레스를 면밀히 살펴본 후, 갑자기 자신의 머리를 감싸 쥐었다.\n「너 같은 비천한 바보가 이렇게 순결한 드레스를 입을 자격이 있겠어?」\n「안 돼, 만지지 마… 아!」\n악의적인 인격이 갑자기 나타나 사지와 팔이 아프게 얽히고 찢어졌다—— 비명과 함께 구르고 피가 쏟아졌다.\n 「하하하, 부족해! 아직 부족해! 그 우산처럼 빨갛게 변해야 해!」\n몇 분, 아니 몇 시간이 지나 메이슨이 방 바닥에서 희미하게 깨어났을 때, 드레스의 소매와 치마 자락은 이미 자신의 피로 가득 차 있었다.\n그녀는 떨리는 손을 깨끗이 씻고, 무거운 치마자락을 문질러 보려 했지만, 피자국이 고집스럽게 더 넓은 연한 붉은색으로 번지는 것만 보았다.\n「하지만, 내일 밤 만찬이 시작되는데…」\n다시 만들 시간이 없다는 것을 깨달은 메이슨은 그 자리에서 멍하니 서 있었고, 쓸모없는 자신이 또 한 번 골치 아픈 일을 일으킨 것에 눈물을 흘렸다. \n「언니, 드레스는 다 되었어? 내가 누구를 데려왔는지 봐! 아이기스가 그녀도 너와 함께 옷 만드는 법을 배우고 싶다고 했어… 언니?」\n부끄러운 친구를 끌어당기며 신나게 문을 열었던 젠킨은 소리를 멈추고, 두 아이는 당황한 채 문 앞에 서서 급히 눈물을 닦는 메이슨을 바라보았다.\n그녀의 억지로 가벼운 설명 속에서 아이들은 침묵을 지키며 서로를 바라보았다. \n「괜찮아, 언니에게는 다른 예쁜 드레스가 있어. 이 드레스는 다음… 다음에 입을게.」\n메이슨보다 더 슬퍼 보이는 아이기스는 정성스럽게 바느질한 꽃무늬를 만지며 갑자기 얼굴이 붉어져 메이슨의 소매를 급히 잡아당겼다.\n「아이기스가 방금 젠킨과 오는 길에, 하얀 머리의 화가 오빠가 단풍나무 숲에 앉아 단풍을 그리고 있었어. 그를 초대해서 드레스에 그려달라고 할 수 있을까? 이 더러움… 이 붉은색도 분명 예쁜 단풍잎으로 변할 수 있을 거야!」\n젠킨이 눈을 크게 뜨고 「천재야!」라고 외치자, 메이슨은 코끝이 찡해지며 두 명의 가장 좋은 여동생을 꼭 껴안았다.\n다음 날 밤, 붉은 단풍이 만개하는 속에서, 붉은 우산 아래 그 흔들리는 깨끗한 드레스 위에도 선명한 붉은 단풍이 가득했다."
  },
  Item_96640_Name = {
    Text = "단풍은 피처럼"
  },
  Item_9664_Desc = {
    Text = "세트: \n뒤틀린 쌍둥이·흑Ⅰ\n뒤틀린 쌍둥이·흑Ⅱ\n뒤틀린 쌍둥이·흑Ⅲ\n뒤틀린 쌍둥이·흑Ⅳ\n뒤틀린 쌍둥이·흑Ⅴ\n뒤틀린 쌍둥이·흑Ⅵ"
  },
