  },
  Item_9666_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 회복, 검은 인장 드롭율, 은열쇠 충전 중 무작위 1개를 획득합니다."
  },
  Item_9666_Name = {
    Text = "광합성 제례 Ⅳ"
  },
  Item_9666_StoryDesc = {
    Text = "과학은 분광 분석이고, 예술은 광합성이다."
  },
  Item_9667_Desc = {
    Text = "죽음 저항을 촉발한 후 생존력이 폭발적으로 증가하며, 혈육 경계에서 추가로 배아 융합을 얻을 수 있습니다."
  },
  Item_9667_Name = {
    Text = "삼켜진 자장가"
  },
  Item_9667_StoryDesc = {
    Text = "그녀는 죽음과 함께 태어난 저주받은 자식, 축복받지 못한 딸로 불린다. \n 그녀와 여동생의「요람」은 막 깨져, 찬란한 빛이 틈새로 흘러나와 땅에 뿌리를 내린다. 순간, 푸른 풀은 시들고, 꽃은 쇠퇴하며, 멀리 있는 큰 나무와 호수의 물고기들까지도 그녀에게서 생기를 빨아들여 무혼의 시체가 되어버린다. \n 그녀의 부족 사람들은 경악하여 서둘러 다른 모든 요람들을 이동시킨다. 그녀는 요람을 부수려고 애쓰지만, 병아리가 알껍질을 깨듯이, 내민 손은 혐오감에 의해 피하고, 눈에 보이는 것은 혐오스러운 얼굴들뿐이다. \n 오직 그녀의 여동생만이, 그녀보다 늦게 태어나지만 더 일찍 성장한 여동생만이, 영원히 그녀를 안아줄 것이다. 그녀를 위해 영혼의 새처럼 노래를 부르며 하나하나 자장가를 불러준다. \n 자라라, 자라라, 사랑하는 언니여; \n 자라라, 자라라, 좋은 꿈이 결국 다가올 것이다. \n\n 그녀는 존재해서는 안 된다. 만약 그녀가 존재하지 않았다면, 그녀의 반짝이는 여동생은 결코 죄악의 그림자로 물들지 않았을 것이다. \n 나의 가련한 여동생아, 그녀는 항상 생각한다, 네가 감당하지 않아도 되는 생존의 대가를 네가 대신 지고 있다고. \n 나의 가련한 여동생아, 그녀는 항상 생각한다, 언니가 할 수 있다면, 반드시 너를 위해 최선을 다할 것이라고. \n 자라라, 자라라, 사랑하는 여동생아; \n 자라라, 자라라, 꿈속에서도 나는 너를 사랑해."
  },
  Item_9668_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 비밀 문서로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9668_Name = {
    Text = "순백의 비편"
  },
  Item_9669_Desc = {
    Text = "인류의 존속을 위해. \n액자에 보관된 의식. 혈육 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9669_Name = {
    Text = "의식 복사본"
  },
  Item_9670_Name = {Text = "열쇠"},
  Item_9671_Desc = {
    Text = "포자는 무슨 죄일까? 그저 집을 원했을 뿐인데.\n번데기와 그 포자 이웃들. 혈육 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9671_Name = {
    Text = "포자 중합체"
  },
  Item_9672_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 회복, 검은 인장 드롭율, 은열쇠 충전 중 무작위 1개를 획득합니다."
  },
  Item_9672_Name = {
    Text = "무덤의 속삭임 Ⅳ"
  },
  Item_9672_StoryDesc = {
    Text = "네 무덤을 증오한다."
  },
  Item_9673_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 판디아를 획득할 때 전환하여 판디아의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9673_Name = {
    Text = "파편 · 판디아"
  },
  Item_9673_StoryDesc = {
    Text = "중복으로 판디아를 획득할 때 전환 획득하며, 판디아의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9674_Desc = {
    Text = "그녀는 죄인의 공포와 갈망, 죽어가는 자의 단비와 독주, 달콤한 고통과 낭만적인 광기를 가져다줍니다. \n·적의 힘을 빼앗음 \n·적의 공세가 강렬할수록 주는 데미지 횟수가 증가"
  },
  Item_9674_Name = {Text = "판디아"},
  Item_9675_Desc = {
    Text = "수억 년 전, 그들은 따뜻한 바다에서 군림했다.\n높은줄기 바다백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9675_Name = {
    Text = "높은줄기 바다백합"
  },
  Item_9676_Desc = {
    Text = "120분의 1의 기적. \n암홍색 보석 조각으로, 현자의 돌을 합성하는 데 사용할 수 있습니다."
  },
  Item_9676_Name = {
    Text = "현자의 돌"
  },
  Item_9677_Desc = {
    Text = "소유자의 반격 쌓기 능력을 대폭 증가시키며, 소유자의 카드가 초차원 공간에 들어가면 추가로 대량의 광기를 얻을 수 있습니다."
  },
  Item_9677_Name = {
    Text = "여왕의 계율"
  },
  Item_9677_StoryDesc = {
    Text = "완다의 정확한 출처에 대해 캄브리아의 주민들은 의견이 분분하다.\n\n어떤 이는 그녀가 거대한 돌 위에 앉아 호숫가로 떨어지는 것을 직접 보았다고 한다.\n어떤 이는 그녀가 레무바시의 여왕이라고 주장하며, 자신이 미라에서 똑같은 등가시를 보았다고 한다.\n또 다른 이는 그녀가 프랑 고원 출신의 공작부인으로, 네 명의 남편을 연속으로 죽인 후 막대한 재산을 상속받았다고 말한다.\n……\n\n소문은 바람처럼 퍼져 나가고, 주민들은 계속해서 농사짓고, 직조하고, 돌을 밀고 있다.\n그 어려운 세월 속에서, 무거운 세금은 머리 위에 걸린 날카로운 칼날처럼 모든 불필요한 가지와 환상을 잘라냈다.\n다만…… 여왕이 거주하는 호수 지역을 지날 때마다, 숲속에서 들려오는 음악 소리는 모두의 마음을 쉽게 사로잡았다.\n그것은 여기서 나올 수 없는 멜로디였다.\n너무 즐겁고, 너무 느긋하여 악마의 속삭임처럼 사악하게 느껴졌다.\n\n「이제 와서 모든 것을 버리라.」\n「자비로운 왕이 호수 중앙에 앉아, 맹안의 하인을 기다린다……」\n\n그래서, 바람 없는 어느 밤, 지친 주민은 농기구를 내려놓고 도망친 호기심을 만족시키기로 결심했다.\n그는 숲을 돌아서 작은 다리를 건너고, 길 양쪽에는 꽃들이 만발한 곳을 지나쳤다. 그는 한 번도 바라보지 않았다.\n그는 초록빛 호수를 보았다.\n그것은 낮게 드리운 별빛 하늘과 연결되어 있으며, 가장자리에 고대의 성이 우뚝 서 있었다.\n\n가시덤불을 쓴 여왕은 호수 중앙에 앉아, 성스럽게 찾아오는 주민들을 기다리고 있었다.\n그녀는 손을 뻗어, 인간의 입맞춤과 경배를 즐겼다.\n먹구름이 걷히고, 맑은 보름달이 떠올랐다.\n여왕은 그의 척추에 등가시를 찔렀다.\n마비의 액체가 혈관을 따라 퍼져 나가고, 그는 무릎을 꿇고, 네 개의 사지를 잘리고, 두 눈이 파여졌다.\n\n이제 그는 대지에서 오는 무거운 중력에 더 이상 붙잡히지 않게 되었고, 그의 모든 시와 꿈은 그 여왕에게만 얽혀 있었다.\n그는 마침내 자신의 운명을 맞이하게 되었다."
  },
  Item_9679_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
