  Item_9681_StoryDesc = {Text = "미완성"},
  Item_96825_Desc = {
    Text = "픽맨이 대량으로 구입한 안료가 환상의 꿈으로 캔버스를 장식한다."
  },
  Item_96825_Name = {
    Text = "환몽의 물들임"
  },
  Item_96826_Desc = {
    Text = "픽맨이 대량으로 구입한 색소는 미친 듯이 영혼을 칠하고 있다."
  },
  Item_96826_Name = {
