  },
  Item_96827_Desc = {
    Text = "픽맨이 대량으로 구매한 도료는 색상이 본래의 모습을 되찾게 했다."
  },
  Item_96827_Name = {
    Text = "진실타래의 물들임"
  },
  Item_9682_Desc = {
    Text = "주 속성으로 치명타 확률, 치명타 피해, 은열쇠 충전 레벨과 광기 충전 레벨 중 랜덤으로 1개를 획득한다."
  },
  Item_9682_Name = {
    Text = "저주받은 토끼 Ⅰ"
  },
  Item_9682_StoryDesc = {
    Text = "하얀 털 토끼를 싫어하는 사람은 없을 거에요."
  },
  Item_9683_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_9683_Name = {
    Text = "약재의 꿈 Ⅰ"
  },
  Item_9683_StoryDesc = {
    Text = "천 년 전, 5분은 40온스의 고운 모래와 같았다."
  },
  Item_9684_Desc = {
    Text = "파인트는 희미해진, 깨기 어려운 씨앗입니다. \n·죽음으로 삶을 얻다 \n·생명을 흡수하여 방어막 생성"
  },
  Item_9684_Name = {Text = "파인트"},
  Item_9685_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키링 스킬: “순백의 첫 만남”을 선택할 수 있습니다. \n\n리리의 병력 카드가 하얀색으로 가득 차길 바랍니다. 처음 만났던 그 설원처럼."
  },
  Item_9685_Name = {
    Text = "순백의 첫 만남"
  },
  Item_9685_StoryDesc = {
    Text = "리리의 진료 기록이 하얗게 되기를 바란다. 그녀와 처음 만났던 그날의 눈 덮인 들판처럼."
  },
  Item_9686_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 카이커스를 획득할 때 전환하여 기령을 활성화하는 데 사용됩니다."
  },
  Item_9686_Name = {
    Text = "파편 · 카이커스"
  },
  Item_9686_StoryDesc = {
    Text = "중복으로 케이크스를 획득할 때 전환하여 획득하며, 케이크스의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9687_Name = {Text = "연고"},
  Item_9688_Desc = {
    Text = "세트: \n바다에서 돌아오는 길Ⅰ\n바다에서 돌아오는 길Ⅱ\n바다에서 돌아오는 길Ⅲ\n바다에서 돌아오는 길Ⅳ\n바다에서 돌아오는 길Ⅴ\n바다에서 돌아오는 길Ⅵ"
  },
  Item_9688_Name = {
    Text = "바다에서 돌아오는 길"
  },
  Item_9689_Desc = {
    Text = "장착자의 방어막 생성량과 기본 피해가 증가하고, 추가로 생성되는 타격 및 방어로 더 많은 선택지를 제공합니다."
  },
  Item_9689_Name = {
    Text = "견고한 의지"
  },
  Item_9689_StoryDesc = {
    Text = "「철수해, 철수해!」 \n「@3으로 가! 서둘러!」 \n「살려줘, 제발 날 구해줘! 날 버리지 마!」 \n「그를 놔두고 빨리 철수하자——엘르바!」 \n총검을 손에 쥔 병사가 재빠르게 달려나갔다. 그녀의 옆에서 폭탄이 터지고, 병사들의 격전 소리, 비명 소리, 긴박한 전쟁의 나팔 소리가 뒤섞였다. 피가 흙을 검게 물들였고, 화약 냄새로 덮을 수 없는 강한 비린내가 났다. 쓰러진 병사들의 눈은 텅 비었고, 어느 군복을 입었든 간에 지금 이 순간엔 모두 눈부신 붉은색이 되었다. \n\n엘르바는 이를 악물고 자신에게 닥쳐오는 적들을 하나씩 돌파하며 앞으로 나아갔다. 그녀는 볼 수 있었다. 도움을 청하던 젊은 병사, 그는 바닥에 눕혀져 있던 채로 강력히 저항하며 키 큰 적군의 칼날을 간신히 막아내고 있었다. \n\n폭발적인 총소리와 심한 고통이 동시에 찾아오고, 가까운 곳의 적군이 서서히 쓰러졌다. 엘르바는 곧바로 뒤로 몸을 돌려 칼을 휘두르며, 다리의 아픔을 참고 세차게 부딪쳤다. 적군이 균형을 잃는 순간, 그녀는 번개같이 그를 가슴 깊숙이 찌르고 방아쇠를 당겼다. \n\n총알이 몸에 박히며 피와 살점이 흩날렸다. 그녀는 대충 얼굴을 손으로 닦고, 젊은 병사의 안전을 확인하려 뒤를 돌아봤지만 이미 그가 언제 떠났는지는 알 수 없었다. \n\n그녀는 고개를 숙여봤다. 한 자루의 칼이 그녀의 왼쪽 무릎 위를 관통하고, 따뜻한 피가 쉼없이 흘러내리고 있었다. 그녀는 망토를 찢어 다리 위쪽에 감아 억지로 출혈을 막으며, 총검을 임시 목발로 사용해 절뚝이면서 부대 뒤를 따라갔다."
  },
  Item_9690_Desc = {
    Text = "누구도 눈물로 당신을 존경하지 않고, 누구도 우는 당신을 매장하지 않을 것입니다. 생전에 당신은 이미 로마에서 이름을 떨쳤습니다. \n·멈추지 않고 전투하라, 죽음까지\n·생명이 낮을수록 광기가 더욱 깊어진다"
  },
  Item_9690_Name = {
    Text = "유우하시"
  },
  Item_9691_Desc = {
    Text = "광기 충전 레벨 속성의 명륜이다."
  },
  Item_9691_Name = {
    Text = "귀족의 지팡이"
  },
  Item_9691_StoryDesc = {
    Text = "덕스터 귀족의 지팡이에 대한 미사그 캠퍼스에는 많은 추측이 돌고 있습니다. \n\n “틀림없이 귀족의 지팡이는 그의 미소처럼 비밀을 숨기고 있습니다. \n 과연 은심이 박혀 있어 깨어남체의 힘을 조종할 수 있는 것인지, 아니면 언제든지 총기로 변신할 수 있는 화약이 숨겨져 있는 것인지요? \n 덕스터 귀족이 우리에게 그 비밀을 밝혀주겠군요!” \n\n 이렇게 오프닝 멘트를 외우며 속기한 한나는 카메라를 덕스터 귀족에게 향하고, 소유자로부터의 후속 이야기를 기대했습니다. \n\n “이거요? 특별한 것은 없어요, 그냥 덕스터 가문이 맞춤 제작한 일상용 지팡이에 불과합니다. \n 제가 사용하는 보석은 심지어 제 형의 것보다 귀하지도 않아요. \n 만약 이 지팡이에 특별한 점이 있다면…… \n 그것은 한때 제 부모와 형제의 피가 묻었다는 것이죠, 이게 특별한 걸까요?”"
  },
  Item_9692_Desc = {
    Text = "영역 숙련 속성의 명륜입니다."
  },
  Item_9692_Name = {
    Text = "정보가 곧 생명"
  },
  Item_9692_StoryDesc = {
    Text = "렌티니언의 지하 세계에는 이런 이야기가 전해진다. \n\n 바쁜 항구, 외진 골목, 시끌벅적한 술집… \n 당신은 언제, 어디서 카메라를 들고 안경을 쓴 유니폼 차림의 소녀를 찾을 수 있을지 모른다. 하지만 그녀를 찾기만 하면 원하는 정보를 무엇이든 살 수 있으며, 대가는 단 하나뿐이다— \n\n 오직 당신만 아는 비밀을 제공하는 것. \n\n 어떤 이는 바닥에서 들은 술자리 진실타래로 경쟁자의 치명적인 약점을 바꿔왔다. \n 어떤 이는 자신의 약점으로 애인의 입을 막는 과거를 바꿔왔다. \n 소녀는 수많은 정보를 쥐고 있지만, 오직 하나는 어떤 비밀로도 바꿀 수 없다. \n\n “내 일에 관한 건? 미안해요, 이건 비매품이에요.”"
  },
  Item_9693_Desc = {
    Text = "광기 충전 레벨 속성의 명륜이다."
  },
  Item_9693_Name = {
    Text = "마음의 장벽"
  },
  Item_9693_StoryDesc = {
    Text = "미사그 캠퍼스에서 가장 건드려서는 안 될 사람, 돌이 스스로를 두 번째로 칭한다면, 첫 번째는 실타래비아 씨가 틀림없습니다. \n\n 미사그 유일의 심리 의사인 이 신비로운 여성은 놀란 조사원들을 달래는 임무를 담당할 뿐만 아니라 깨어남체의 불안한 감정을 조절하는 것도 그녀의 책임입니다. \n 깨어남체를 두려워하지 않을 뿐만 아니라, 정신적으로 그들과 동등하게 대립할 수 있는— 대체 어떤 강자일까요? \n\n 미지에 대한 호기심을 품고 경외심이 다소 결여된 신생들이 깊은 밤에 실타래비아 씨의 진료실타래로 몰래 들어갔습니다. \n\n 그리고 그들은 의식을 잃었습니다. \n 다음 날 아침 캠퍼스 광장에서 깨어났을 때, 그들은 머리가 쪼개질 듯 아팠지만, 마음은 전례 없는 명쾌함을 느꼈습니다. \n 누군가 그들의 주머니에서 떨어진 편지를 주워 들었습니다: \n\n “심리 상담이 필요하다면, 미리 에리카 씨에게 신청하세요— \n 실타래비아”"
  },
  Item_9694_Desc = {
    Text = "이제는 아무도 이걸로 길흉을 점치지 못할 거야. \n융해진흙으로 덮인 보라색 수정, 초월계역의 깨어남체 스킬 레벨을 올리는데 사용됩니다."
  },
  Item_9694_Name = {
    Text = "부서진 광석"
  },
  Item_9695_Desc = {
    Text = "크리티컬 확률 속성의 명륜입니다."
  },
  Item_9695_Name = {
    Text = "망각의 손"
  },
  Item_9695_StoryDesc = {
    Text = "어둠 속에서 손이 주인을 찾으려 더듬거린다.\n\n피로 얼룩진 그 밤, 손은 주인의 몸에서 잔인하게 떼어져 나왔다.\n지금 이 순간, 손을 가져간 원흉이 그 주변을 떠돌며 기묘한 윙윙거리는 소리를 낸다.\n\n「포기해라, 우리와 함께 가자. 밀랍 조형가는 너를 완전히 잊을 것이다.」\n\n손은 미동도 하지 않고, 자랑스러운 긴 손가락들을 움직이며 말했다.\n\n「주인은 나를 잊지 않을 것이다.\n나는 그의 예술을 이루는 유일한 도구다——\n너희는 내가 그에게 무엇을 의미하는지 이해하지 못한다.」\n\n「사람은 연인을 잊고, 시간을 잊어도, 자신을 잊지는 않는다.」\n\n어둠 속에서 동정 어린 웃음소리가 들려왔다.\n「그와는 정반대다. 사람이 가장 먼저 잊는 것은 항상 자기 자신이다.\n하지만 걱정하지 마——」\n\n시간이 모든 것을 설명해 줄 것이다. 손도 곧 이 진리를 깨닫게 될 것이다:\n잊혀지지 않을 것은 없다.\n그것들은 수많은 세기를 흘러왔고, 인간 세상의 이야기가 그것들 곁에서 펼쳐지다가도 다음날이면 잊혀졌다.\n하지만 그것들은 여전히 쉼 없이 흐르고 있다."
  },
  Item_9696_Desc = {
    Text = "기획자 테스트용 SSR 무기"
  },
  Item_9696_Name = {
    Text = "시작 레이저 포(폭발 피해) 개발용"
  },
  Item_9696_StoryDesc = {Text = "미완성"},
  Item_9697_Desc = {
    Text = "검은 인장 드롭율 속성의 명륜입니다."
  },
  Item_9697_Name = {
    Text = "존재하지 않는 곳"
  },
  Item_9697_StoryDesc = {
    Text = "타비는 블랙풀의 바닥에서 잠들어 있다.\n\n그곳은 연중 무음무광이며, 오직 절망적인 어둠만이 있을 뿐이다.\n여기에는 결코 손님이 찾아온 적이 없고, 결코 소리가 도달한 적이 없다.\n여기는 파멸이 닿을 수 없는 곳——\n\n왜냐하면 재앙이 이미 강림했기 때문이다.\n\n시서의 주관자로서, 그녀는 너무 많은 비통한 결말을 목격해왔다.\n규칙의 일원으로서, 그녀 또한 어둠의 강림을 막을 수 없다.\n그렇다면, 존재하지 않는 곳에 잠복하며 존재하지 않는 모습으로 '변수'라 할 수 있는 사람의 도착을 기다릴 수밖에 없다.\n\n그 사람은 결국 도착할 것이다."
  },
