  Item_97039_Name = {
    Text = "광기의 감염"
  },
  Item_9703_Desc = {
    Text = "범용 피해형으로, 깨어남체의 출력 능력을 폭넓고 종합적으로 강화합니다"
  },
  Item_9703_Name = {
    Text = "태양의 추락"
  },
  Item_9703_StoryDesc = {
    Text = "A.F. 314, 겨울 어느 깊은 밤, 폭발 소리가 아쿠트 숲을 가득 채웠습니다.\n대지가 떨리고, 숲은 낮처럼 밝아졌습니다. 생명의 날카로운 포효와 자연의 울음소리가 어우러져 마을은 평지가 되었습니다.\n「아쿠트 재앙 조사」에 참여했던 깨어남학과 예비생 덕스터에 따르면, 그 밤 하늘을 찢는 불빛 속에서 검은색과 은색이 반짝였습니다."
  },
  Item_97040_Desc = {
    Text = "픽맨이 대량으로 구입한 물감으로, 색채를 본래의 모습으로 되돌린다.\n\n최소 {s1}개 드롭"
