  },
  Item_9704_Desc = {
    Text = "영역 숙련 속성의 명륜입니다."
  },
  Item_9704_Name = {
    Text = "영혼의 탄생"
  },
  Item_9704_StoryDesc = {
    Text = "시간의 현이 하나하나 끊어지고, 흐르는 건반이 조각조각 부서진다.\n그들은 현실타래 밖에 서서 현실타래을 재료로 하여 결점을 꿰매고, 결코 막을 내리지 않는 악장이 다시금 하늘 위에서 울려 퍼지게 한다.\n그 순간 꿈에서 깨어났을 때 흘린 눈물이 어디로 흘러갔는지는 아무도 모른다."
  },
  Item_97050_Desc = {
    Text = "픽맨이 대량으로 구입한 물감으로, 환상으로 캔버스를 수놓는다.\n\n최소 {s1}개 드롭"
