  Item_97055_Name = {
    Text = "진실타래의 물들임"
  },
  Item_97056_Desc = {
    Text = "픽맨이 대량으로 구입한 물감으로, 광기로 영혼을 그려낸다.\n\n최소 {s1}개 드롭"
  },
  Item_97056_Name = {
    Text = "광기의 감염"
  },
  Item_9705_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_9705_Name = {
    Text = "이율배반 Ⅱ"
  },
  Item_9705_StoryDesc = {
    Text = "필연, 우연. 유한, 무한."
  },
  Item_9706_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9706_Name = {
    Text = "저주받은 토끼 Ⅵ"
  },
  Item_9706_StoryDesc = {
    Text = "하얀 털 토끼를 싫어하는 사람은 없을 거에요."
  },
  Item_9707_Desc = {
    Text = "우리에게 미지의 정신을 부여한다.\n필린 시사의 특수 필름으로, 인간의 정신을 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9707_Name = {
    Text = "정신 템플릿"
  },
  Item_9708_Desc = {
    Text = "세트: \n묘지의 속삭임Ⅰ\n묘지의 속삭임Ⅱ\n묘지의 속삭임Ⅲ\n묘지의 속삭임Ⅳ\n묘지의 속삭임Ⅴ\n묘지의 속삭임Ⅵ"
  },
  Item_9708_Name = {
    Text = "묘지의 속삭임"
  },
  Item_9709_Desc = {
    Text = "세트: \n먼 곳의 잔치Ⅰ\n먼 곳의 잔치Ⅱ\n먼 곳의 잔치Ⅲ\n먼 곳의 잔치Ⅳ\n먼 곳의 잔치Ⅴ\n먼 곳의 잔치Ⅵ"
  },
  Item_9709_Name = {
    Text = "먼 곳의 잔치"
  },
  Item_9710_Name = {
    Text = "빨간 리본"
  },
  Item_9711_Desc = {
    Text = "인류의 존속을 위해.\n\n\n\n액자에 보관된 기억. 혈육 영역 깨어남체의 승급 재료."
  },
  Item_9711_Name = {
    Text = "기억 복사본"
  },
  Item_9712_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복 획득 시 레아를 전환하여 레아의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9712_Name = {
    Text = "파편 · 레아"
  },
  Item_9712_StoryDesc = {
    Text = "중복 획득한 레아는 전환되어 기령을 활성화하는 데 사용됩니다."
  },
  Item_97139_Desc = {
    Text = "피크맨 화실타래 특별 제공, 초보자를 위한 전용 세트로, 기초 화구와 실타래용 도구가 포함되어 있어 당신이 쉽게 예술의 전당에 발을 들일 수 있도록 돕습니다. \n「캔버스의 어두운 면」 기간 한정 공급입니다."
  },
  Item_97139_Name = {
    Text = "초심자 출발 세트"
  },
  Item_9713_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n타이스를 반복 획득할 때 전환하여 타이스의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9713_Name = {
    Text = "파편 · 타이스"
  },
  Item_9713_StoryDesc = {
    Text = "테이스를 중복 획득하면 전환하여 사용할 수 있으며, 이를 통해 테이스의 기령을 활성화할 수 있습니다."
  },
  Item_97140_Desc = {
    Text = "피크맨 화실타래 특별 제공, 고급 화재를 선택하여 당신이 붓질로 낡은 규칙을 찢고, 색상과 선의 충돌 속에서 내면의 불안을 해방할 수 있도록 도와줍니다.\n「캔버스의 어두운 면」 기간 한정 공급."
  },
  Item_97140_Name = {
    Text = "붓 터치 승급 선물상자"
  },
  Item_97141_Desc = {
    Text = "피크맨 화실타래 특별 제공, 비교할 수 없는 피크맨 대가의 소장품. 당신의 열정과 광기가 캔버스 위에서 자유롭게 발휘되어 진정한 예술의 아름다움을 창조하도록 도와줍니다!\n「캔버스의 어두운 면」 기간 한정 공급."
  },
  Item_97141_Name = {
    Text = "광채 대장 보유"
  },
  Item_9714_Desc = {
    Text = "감금된 소녀의 영혼은 피를 갈망한다. 이는 시각 장애인이 빛을 간구하고, 방종한 자가 사랑에 빠지는 것과 같다. \n·배아 융합도 \n·생명을 힘으로 바꾸다"
  },
  Item_9714_Name = {Text = "레아"},
  Item_9715_Name = {
    Text = "혈쇄·히로"
  },
  Item_9716_Desc = {
    Text = "기획팀 테스트용 SR 무기"
  },
  Item_9716_Name = {
    Text = "시작 장검 (죽음 저항) 개발용"
  },
  Item_9716_StoryDesc = {Text = "미완성"},
