  Item_9723_StoryDesc = {
    Text = "그는 @2년 봄에 땅에 묻혔다."
  },
  Item_97242_Desc = {
    Text = "장례 도시에서는 누구도 죽음의 도래를 두려워하지 않습니다.\n죽음이 오기 전의 매일을 사람들은 생명의 마지막 날로 여기고, 노래하고, 춤추고, 연회를 즐깁니다. 이 죽음의 도시는 어떤 생자도 상상할 수 없을 만큼 더욱 떠들썩합니다.\n한 송이 보라색의 망각꽃이 창가에 조용히 떨어질 때, 이 편지를 받은 사람은 기꺼이 목욕하고, 단장하며, 가장 좋아하는 옷을 입고, 그것을 머리 옆에 꽂고, 도시의 사람들과 하나하나 작별 인사를 나눈 후, 결국 사랑하는 사람의 손을 잡습니다.\n그것은 네크로비아의 군주로부터의 축복이자 그의 약속입니다. 그는 그들이 사랑하는 사람과 함께 하나로 합쳐지기를 축복하며, 아무도 서로를 버리거나 잊지 않을 것이라고 약속합니다; 그는 이 만남의 기한이 그가 세상에서 사라지기 전까지의 영원하다고 약속합니다.\n세상에서 그 묘지 근처에서, 해탈을 찾는 사람들 사이에도 같은 전설이 전해집니다.\n당신이 불행히도 이 세상의 고통을 모두 겪고 생명의 끝에 다다를 때, 당신은 고요한 새벽에 영혼을 편안하게 하는 안개를 보게 될 것입니다.\n그 안개의 인도를 따라 황야로, 아무도 모르는 세계의 끝으로 나아가면, 수많은 묘비들 사이에서 피어나는 보라색 꽃바다를 보게 될 것입니다.\n그 안개의 끝에는 한 아름다운, 꽃처럼 변모한 청년이 서 있습니다. 그는 당신의 일생을 기다린 듯 보이며, 이제는 어떤 운명의 약속에 따라 당신을 고통 없는 고요한 꿈의 나라로 인도할 것입니다.\n그는 당신의 모든 것을 받아들이고, 당신의 모든 것을 위로하며, 마지막 구원을 가져다줄 것입니다.\n그는 그 꽃바다 가운데 서서 부드럽게 당신에게 손바닥을 내밀며 말합니다:「저와 함께 춤을 추시겠습니까?」"
  },
  Item_97242_Name = {Text = "물망초"},
  Item_9724_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
