  },
  Item_9725_StoryDesc = {Text = "미완성"},
  Item_9726_Desc = {
    Text = "이제 아무도 이것으로 길흉을 점치지 못할 것이다. \n융식액에 덮인 보라색 수정. 초차원 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9726_Name = {
    Text = "부서진 광석"
  },
  Item_9727_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n오를라를 반복 획득할 때 전환하여 오를라의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9727_Name = {
