  Item_9730_Desc = {
    Text = "세트: \n환형의 시편Ⅰ\n환형의 시편Ⅱ\n환형의 시편Ⅲ\n환형의 시편Ⅳ\n환형의 시편Ⅴ\n환형의 시편Ⅵ"
  },
  Item_9730_Name = {
    Text = "환형의 시편"
  },
  Item_97317_Desc = {
    Text = "속성이 있는 은열 충전 등급의 명륜입니다."
  },
  Item_97317_Name = {
    Text = "푸른 고리 독소"
  },
  Item_97317_StoryDesc = {
    Text = "오랜 세월이 흐른 뒤, 엎드려 기도하는 도해자들을 마주한 탄망·머피는 「어머니」가 파란고리문어 이야기를 들려주던 그 아득히 먼 오후를 떠올리곤 했다.\n유리병 속의 피조물은 부드럽고 현란했으며, 기이한 유청색 빛이 물속에서 떠다니며 어린 그녀를 저도 모르게 가까이 다가가도록 유혹했다.\n그러나 미리아무는 그녀의 머리를 쓰다듬으며, 거부할 수 없는 힘으로 어두운 선실타래 구석을 바라보게 했다——한 도해자의 시신이 축 늘어진 채 바닥에 쓰러져 있었고, 독소에 모든 것을 빨아먹힌 듯한 공허하고 창백한 빛을 띠고 있었다.\n「명심해라, 바다에서 가장 고요하고 가장 치명적인 것은, 대개 가장 아름다운 것이란다.」\n유리병의 차가운 빛이 그녀의 자비로운 옆모습을 비추었고, 탄망·머피는 아름다움에 감싸인 공포만을 느꼈다.\n\n세월은 별들의 리듬을 따라 조용히 흘러갔고, 탄망·머피는 여전히 제멋대로였지만 침묵과 관찰도 배워 나갔다.\n「리모리아, 리모리아……」\n제단 위에서, 언제나 평온하고 온화하던 그 얼굴이 점차 광기에 물들어 갈 때에야 비로소 깨달았다——자신은 미리아무를 진정으로 알았던 적이 없었다는 것을. 자신의 머리를 쓰다듬던 그 부드러운 어머니의 손이, 신국의 적에게는 가장 가혹한 징벌을 내리기도 한다는 것을.\n그때, 기억 깊숙이 봉인되어 있던 공포가 갑자기 되살아나, 마침내 차가운 인식으로 응고되었다——그녀의 자비란 위장된 촉수에 불과하며, 온화한 외모가 환화한 아름다운 파란 고리야말로 피를 보면 목숨을 앗아가는 독소 그 자체였다는 것을.\n\n오늘에 이르러, 허무의 신은 마침내 탄망·머피에게 왕관을 씌웠다. 그녀는 엎드린 도해자들을 내려다보며, 미리아무의 시선 속에 아직 사그라지지 않은, 거의 황당하기까지 한 기대와 마주했다. 마치 다시 한번 유리병 앞에서 아름다운 생물을 응시하며 전율하던, 보잘것없이 작았던 자신을 본 듯했다."
  },
  Item_9731_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_9731_Name = {
    Text = "뒤틀린 쌍둥이·백 Ⅱ"
  },
  Item_9731_StoryDesc = {
    Text = "하얀 안개의 축복."
  },
  Item_9732_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복 획득 시 셀레스트를 전환하여, 셀레스트의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9732_Name = {
    Text = "파편 · 셀레스트"
  },
  Item_9732_StoryDesc = {
    Text = "중복 획득 시 셀레스트를 전환하여 획득하며, 셀레스트의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9733_Desc = {
    Text = "기어가고, 왜곡되고, 우리는 어두운 곳을 기어다닙니다……스……스……\n감염당한 번데기. 혈육 경계역의 깨어남체 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_9733_Name = {
    Text = "원생 번데기"
  },
  Item_97349_Desc = {
    Text = "“그토록 매혹적인 냄새…… 과연 얼마나 아름다운 망자여야 이런 향기를 풍길 수 있을까?”"
  },
  Item_97349_EmojiName = {
    Text = "향기롭다"
  },
  Item_97349_Name = {
    Text = "둘레세인·향기롭다"
  },
  Item_97349_StoryDesc = {
    Text = "제27기 페이즈 대결"
  },
  Item_9734_Desc = {
    Text = "「타격」을 사용하여 지속적으로 방어막을 획득하고, 더 많은 방어막으로 아군을 보호하는 동시에 중독을 부여합니다."
  },
  Item_9734_Name = {
    Text = "고통을 넘어"
  },
  Item_9734_StoryDesc = {
    Text = "“기억이란 무엇인가요?”\n“당신이 잊어버린 것들이에요.”\n\n릴리에게는 잊기 쉬운 엄마가 있습니다.\n엄마는 릴리를 부르며 함께 저녁을 먹는 것을 잊기도 하고, 릴리에게 약을 주는 것을 잊기도 하며, 심지어 릴리의 이름조차 잊어버리곤 합니다.\n“어떻게 해야 할까요?”\n릴리는 병상에 앉아 깊은 생각을 하며 한숨을 내쉬었습니다.\n이런 엄마는 정말 걱정이 되네요.\n\n그 후, 릴리는 자신의 이름을 나무판에 적어 매일 가슴에 걸어두었습니다.\n이렇게 하면 엄마가 기억할 수 있을까요?\n처음에는 엄마가 웃으며 그녀의 행동이 쓸데없다고 말했지만, 그건 단지 장기간의 피로로 인한 합병증이라고 했습니다.\n\n점점 엄마는 혼란스러워하고, 조급해졌습니다:\n“릴리……릴리는 뭐죠?”\n호박색의 두 눈이 릴리를 바라보며 약간의 신중함을 띠고 있습니다.\n결국, 글자의 의미마저 잊혀지면, 언어에 의존해 잠시 유지되던 화합은 결국 사라지게 됩니다.\n\n릴리는 엄마를 포옹했습니다.\n모녀의 심장 박동 소리는 단 몇 인치 밖에 떨어져 있지 않았지만, 그녀는 극도의 외로움을 느꼈습니다.\n\n그날 이후, 릴리는 나무판을 치우고 더 이상 엄마에게 애교를 부리지 않았으며, 자신이 며칠째 배고프다는 것을 상기시키지도 않았습니다.\n그녀는 곧 죽을 병에 걸린 환자로, 무감각하게 죽음의 선고를 기다리고 있었습니다.\n그녀는 방관자로, 멀리서 자신이 주사를 맞고, 마취되고, 엄마가 원하는 어떤 모습으로 조작되는 것을 지켜보고 있었습니다.\n모녀 간의 즐거운 대화, 부드러운 포옹……\n그런 꿈의 거품처럼 반짝이는 즐거운 기억들은 릴리가 조심스럽게 마음속에 잠가두었습니다.\n오직 어떤 피곤한 밤에만, 그녀는 그것들을 꺼내어 부드럽게 핥아보았습니다."
  },
  Item_97350_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매하면 얻을 수 있습니다.\n「절대 비밀 문서의 표지 사진으로, 촬영 중 촬영자가 사진사를 폭력적으로 위협하고 카메라 한 대를 부숴 버렸다.」"
  },
  Item_97350_Name = {
    Text = "둔한 아카이브 사진: 혈쇄·히로"
  },
  Item_97352_Desc = {
    Text = "“또… 출근해야 하는 하루네…”"
  },
  Item_97352_EmojiName = {Text = "일어나"},
  Item_97352_Name = {
    Text = "닝피아·기상"
  },
  Item_97352_StoryDesc = {
