  },
  Item_97369_Desc = {
    Text = "빨리 단체 사진 포즈를 취하세요… 아니, 그런 식이 아니에요!!"
  },
  Item_97369_EmojiName = {
    Text = "하트 비교"
  },
  Item_97369_Name = {
    Text = "폴리덱스·비하트"
  },
  Item_97369_StoryDesc = {
    Text = "제26기 상위 대국"
  },
  Item_9736_Desc = {
    Text = "광기 폭발을 해방하면 광기를 회복하고 열쇠 능력을 얻으며, 많은 카드를 추출할 수 있는 깨어남체에 적합합니다."
  },
  Item_9736_Name = {
    Text = "환희의 마법 공연"
  },
  Item_9736_StoryDesc = {
    Text = "「내 명작인가요? 음—— 그렇게 궁금해하시다니, 좋습니다, 좋습니다, 어쨌든 VVIP의 요청이니까요. 하지만 일반적인 이야기는 마법사 대장이라는 저의 명성에 맞지 않죠. 화려한 공연으로 여러분께 보여드리겠습니다!\n자, 자, 자, 귀빈석에 앉아주세요. 돈과 배신이 가득한 서스펜스 즐거움 마법 회상 쇼가 곧 시작됩니다!」\n-------\n손가락을 튕기자, 조명이 켜지고, 카시아의 마법 모자가 공중에 떠오릅니다. 노란 입구가 열렸다 닫히면서 카시아의 목소리가 들려옵니다. \n「오래 전, 그리 멀지 않은 곳에 한 서커스가 있었어요. 서커스 안에는 토끼, 광대, 사자, 코끼리가 있었죠——」\n모자가 흔들리면서 안에서 토끼 한 마리, 광대 한 명, 사자 한 마리, 코끼리 한 마리가 떨어져 나옵니다. 반주에 맞춰 드럼 비트가 점점 빨라지고, 폭죽이 터지는 소리와 함께 화려한 의상을 입은 카시아가 모자에서 튀어나와서 모자를 뒤집어 썼습니다. \n「가장 중요한 것은, 특출난 재능과 뛰어난 재능을 가진 마법사 견습생이 있다는 거예요!」\n-------\n견습생의 성장은 박수갈채와 함께 이루어졌고, 심지어 화려한 투자자 한 명을 끌어들였습니다. 이상하게도 투자자가 그들과 함께 여행한 이후로 토끼, 광대, 사자, 코끼리…… 많은 사람과 동물들이 하나둘씩 사라졌습니다. 무대는 절반 이상 비어버렸지만, 견습생은 전혀 눈치채지 못한 듯 원래의 생활을 반복했습니다. 그러다 투자자가 그녀에게 술 한 잔을 건넸습니다. \n견습생은 술을 마시고 기절해버렸고, 무대는 어둠에 휩싸이며, 미약한 한숨이 어둠 속에서 흘러나왔습니다. \n「그때 나는 처음으로 유감이라는 것을 이해했습니다.」\n-------\n「하지만, 유감만으로는 부족해요. 나는 후원자님이 울 때의 기분이 어떤 건지, 관객들이 웃을 때의 기분이 어떤 건지 더 알고 싶어요, 더, 더 알고 싶어요. 그때——\n눈을 떴습니다.」\n종이로 만든 화환이 공중에서 터지며 조각들이 흩날리고, 카시아가 갑자기 무대 중앙에 나타났습니다. 그녀는 모자의 챙을 두드리자, 모자가 입을 벌리며 눈부신 빛을 내뿜었습니다. \n「나는 눈을 떴고, 모든 감정은 빛이라는 것을 발견했어요. 모두 내 마법 모자에 담을 수 있는 것이죠. \n이제 편안히 앉아주세요, 사랑하는 귀빈님. 다음 단계는 전혀 아프지 않을 것이고, 오히려 약간 무감각해지고, 삶이 조금 지루하게 느껴질 것입니다……」"
  },
  Item_97370_Desc = {
    Text = "「내가 사랑하는 작은 가죽 채찍을 좋아하니?」"
  },
  Item_97370_EmojiName = {
