  Item_97388_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매하면 얻을 수 있습니다.\n「절대 비밀 문서의 표지 사진, 촬영자는 측면을 촬영해도 되는지 물었지만 학교 측에서 거절했습니다.」"
