  Item_97408_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다. \n「절대 비밀 문서의 표지 사진으로, 촬영 도중 촬영자가 사진사를 끊임없이 방해하여 촬영이 한때 중단되기도 했다.」"
