  Item_97411_Name = {
    Text = "결코 바래지 않는 어제: 레이크"
  },
  Item_97412_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다. \n「절대 비밀 문서의 표지 사진, 촬영자가 표정이 충분히 엄격하지 않아 조정을 지시받았다.」"
  },
  Item_97412_Name = {
    Text = "우두커니 프로필 사진: 테이스"
  },
  Item_97412_StoryDesc = {
    Text = "제24기 과제 기록"
  },
  Item_97413_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매한 후 획득할 수 있습니다. \n「절대 비밀 문서의 표지 사진, 촬영자는 거대한 양의 레오방으로 사진사를 매수하여 꼬박 한 시간 동안 촬영했다.」"
  },
  Item_97413_Name = {
    Text = "둔한 아카이브 사진: 소렐"
  },
  Item_97413_StoryDesc = {
    Text = "제24기 과제 기록"
  },
  Item_97414_Desc = {
    Text = "「에? 이렇게 솔직하게 말해야 하나요? 저에게는 좀 민망하네요……」"
  },
  Item_97414_EmojiName = {
    Text = "하트비트·오를라"
  },
  Item_97414_Name = {
    Text = "오를라·하트"
  },
  Item_97415_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매하면 얻을 수 있습니다.\n「누군가는 엘바가 어머니를 잃은 강아지를 돌보기 위해 한 달 동안 조용히 밤을 새우고 잠을 이루지 못했다는 것을 보았습니다. 군인으로서 그녀의 충성은 집단에 속했지만, 예전의 동료들에게 잔인하게 버려졌습니다. 결국 다친 짐승은 그녀를 다시 받아줄 부족을 찾았고, 만약 당신이 운 좋게 그녀의 뒤에 배정된다면, 그녀의 단단한 외면 아래 가장 부드러운 마음이 숨겨져 있음을 발견할 것입니다.」"
  },
  Item_97415_Name = {
    Text = "바람에 지지 않는 어제: 엘바"
  },
  Item_97415_StoryDesc = {
    Text = "제21기 과제 기록"
  },
  Item_97416_Desc = {
    Text = "\"물론이죠, 저는 진심으로 당신을 감사하고 있습니다, 제 가장 충실타래한 관객이시여.\""
  },
  Item_97416_EmojiName = {
    Text = "비하트·리즈"
  },
  Item_97416_Name = {
    Text = "리즈·하트"
  },
  Item_97417_Desc = {
    Text = "“구운 생선, 정말 맛있어요.”"
  },
  Item_97417_EmojiName = {Text = "물장난"},
  Item_97417_Name = {
    Text = "시로·장난치기"
  },
  Item_97417_StoryDesc = {
    Text = "제21기 페이즈 체스"
  },
  Item_97418_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「이상하다, 내가 여기 왜 왔더라…… 아! 생각났다! 전설의 재료를 찾으러 온 거였어!」"
  },
  Item_97418_Name = {
    Text = "결코 바래지 않는 어제: 노틸라"
  },
  Item_97418_StoryDesc = {
    Text = "제24기 과제 기록"
  },
  Item_97419_Desc = {
    Text = "\"만약 이것이 혈맥을 감당하기 위한 필연적인 숙명이라면……\""
  },
  Item_97419_EmojiName = {
    Text = "숙명의 애가"
  },
  Item_97419_Name = {
    Text = "케이크스·운명의 탄식"
  },
  Item_97419_StoryDesc = {
    Text = "제25기 페이즈 체스"
  },
  Item_9741_Desc = {
    Text = "크리티컬 피해 속성의 명륜입니다."
  },
  Item_9741_Name = {Text = "임계점"},
  Item_9741_StoryDesc = {
    Text = "귀족 부인이 연민과 혐오로 손수건으로 코를 막고, 필요 없는 보석을 그녀에게 주라고 하자, 그녀는 생각했다: \n 빈민원의 아이들이 한 끼 고기를 먹을 수 있다면 얼마나 좋을까. \n\n 그녀는 자신의 식사를 아이들에게 나누어 주고, 스스로는 오랜 시간 허기으로 복도에서 기절했을 때, 그녀는 말했다: \n 괜찮아요, 의사 부르지 마세요, 진료비로 여러 개의 빵을 살 수 있어요. \n\n 친절한 예술가가 아는 의사와 함께 방문해 장기 협력 제안을 했을 때, 그녀는 생각했다: \n 반드시 그들이 먼저 내 몸에서 시험해 봐야 해, 그렇지 않으면 아이들이 그들이 하는 이 치료를 받게 할 수 없어. \n\n 사라는 무엇이든 견딜 수 있지만, 유일하게 견딜 수 없는 것은 자신이 한 모든 일이 결국 비극적인 결말로 이어지는 것이다."
  },
  Item_97420_Desc = {
    Text = "“……이렇게 대조해야 하나요?”"
  },
  Item_97420_EmojiName = {
    Text = "엄지보다"
  },
  Item_97420_Name = {
    Text = "카스토르·엄지보다"
  },
  Item_97420_StoryDesc = {
    Text = "제26기 상위 대국"
  },
  Item_97421_Desc = {
    Text = "임시 텍스트"
  },
  Item_97421_Name = {
    Text = "은열쇠의 이름으로: 성아"
  },
  Item_97421_StoryDesc = {
    Text = "성아 플레이 이벤트"
  },
  Item_97422_Desc = {
    Text = "「학기 과제」에서 「핵심 과제」를 구매하면 획득할 수 있습니다.\n「파트너…… 이렇게 부르는 거 괜찮다면, 우리가 처음 만났을 때를 기억해? 아…… 맞아, 내 말은…… 라모나와 만났을 때 말이야.」"
  },
  Item_97422_Name = {
    Text = "영원히 바래지 않는 어제: 환형·라모나"
  },
  Item_97422_StoryDesc = {
    Text = "제23기 학기 과제"
  },
  Item_9742_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_9742_Name = {
    Text = "이율배반 Ⅰ"
  },
  Item_9742_StoryDesc = {
    Text = "필연, 우연. 유한, 무한."
  },
  Item_9743_Desc = {
    Text = "아포는 또 무엇을 잘못했을까, 그들은 단지 집이 필요할 뿐이었다. \n 벌레유충과 그의 아포 이웃. 혈육 경계역 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_9743_Name = {
    Text = "포자 중합체"
  },
  Item_9744_Name = {Text = "내장"},
  Item_9745_Desc = {
    Text = "그녀는 고쳐지지 않는 오토바이 주변을 계속 맴돈다: 여기의 나사를 조이고, 저기의 파이프를 고친다…\n·강력한 방어막을 부여\n·반격으로 데미지를 입힌다"
  },
  Item_9745_Name = {Text = "노틸라"},
  Item_9746_Desc = {
    Text = "거대한 칼의 송곳니는 수많은 적과 동족의 목을 베어놓았으며, 그 자신의 목도 베어놓았다. \n·힘을 가하여 중격을 시전\n·힘에 대한 추가적인 향상"
  },
  Item_9746_Name = {Text = "골리아"},
  Item_9747_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9747_Name = {
    Text = "환형의 시편 Ⅲ"
  },
  Item_9747_StoryDesc = {
    Text = "환형 시간의 틈새를 떠다니는 것."
  },
  Item_9748_Name = {
    Text = "밀랍상 선생"
  },
  Item_9749_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9749_Name = {
    Text = "무덤의 속삭임 Ⅵ"
  },
  Item_9749_StoryDesc = {
    Text = "네 무덤을 증오한다."
  },
  Item_9750_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n에리카를 반복 획득하면 전환하여 사용할 수 있으며, 이를 통해 에리카의 기령을 활성화할 수 있습니다."
  },
  Item_9750_Name = {
    Text = "파편 · 에리카"
  },
  Item_9750_StoryDesc = {
    Text = "에리카를 중복 획득하면 전환하여 사용할 수 있으며, 이를 통해 에리카의 기령을 활성화할 수 있습니다."
  },
  Item_9752_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9752_Name = {
    Text = "이율배반 Ⅵ"
  },
  Item_9752_StoryDesc = {
    Text = "필연, 우연. 유한, 무한."
  },
  Item_97539_Desc = {
    Text = "신의 탄생은 신모에게 평온을 가져다주지 않았고, 악몽을 쫓는 향이 날마다 침궁을 감돌았으니, 잠깐의 평화로움이 주제사의 축복을 가져다줄 것이다.\n\n최소 {s1}개 드롭"
  },
  Item_97539_Name = {
    Text = "구액 향훈"
  },
  Item_9753_Desc = {
    Text = "세트: \n4월의 찬가Ⅰ\n4월의 찬가Ⅱ\n4월의 찬가Ⅲ\n4월의 찬가Ⅳ\n4월의 찬가Ⅴ\n4월의 찬가Ⅵ"
  },
  Item_9753_Name = {
    Text = "4월의 찬가"
  },
