    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9760_Name = {
    Text = "광합성 제례 Ⅵ"
  },
  Item_9760_StoryDesc = {
    Text = "과학은 분광 분석이고, 예술은 광합성이다."
  },
  Item_97610_Desc = {
    Text = "그녀는 그 꿈에서 벗어날 수 없었고, 이미 다시는 깨어나지 않기로 결심했으니, 그녀가 계속 편히 잠들게 두어라, 그녀는 네가 받아야 할 보상을 줄 것이다.\n\n최소 {s1}개 드롭"
  },
  Item_97610_Name = {
    Text = "포몽 향훈"
  },
  Item_97611_Desc = {
    Text = "태우면 마음을 안정시키는 효과가 있는 허브 다발로, 미사그의 밤에도 악몽에 깨어나는 어린 소녀가 편히 잠들 수 있게 해준다.\n\n최소 {s1}개 드롭"
  },
  Item_97611_Name = {
    Text = "안신 향훈"
  },
  Item_97612_Desc = {
    Text = "그녀는 그 꿈에서 벗어날 수 없었고, 이미 다시는 깨어나지 않기로 결심했으니, 그녀가 계속 편히 잠들게 두어라, 그녀는 네가 받아야 할 보상을 줄 것이다.\n\n최소 {s1}개 드롭"
  },
  Item_97612_Name = {
    Text = "포몽 향훈"
  },
  Item_97613_Desc = {
    Text = "그녀는 그 꿈에서 벗어날 수 없었고, 이미 다시는 깨어나지 않기로 결심했으니, 그녀가 계속 편히 잠들게 두어라, 그녀는 네가 받아야 할 보상을 줄 것이다.\n\n최소 {s1}개 드롭"
  },
  Item_97613_Name = {
    Text = "포몽 향훈"
  },
  Item_9761_Desc = {
    Text = "세트: \n유기 형태 Ⅰ\n유기 형태 Ⅱ\n유기 형태 Ⅲ\n유기 형태 Ⅳ\n유기 형태 Ⅴ\n유기 형태 Ⅵ"
  },
  Item_9761_Name = {
    Text = "유기 형태"
  },
  Item_9762_Desc = {
    Text = "미사그 대학의 설립자가 개발한 약재로, 깨어남체의 능력을 향상시킨다. \n은심과 비밀의 약을 섞어 독특한 색을 띠고 있다.\n사용 시 깨어남체의 경험치가 10000 증가한다."
  },
  Item_9762_Name = {
    Text = "영지 비약Ⅲ"
  },
  Item_9763_Name = {
    Text = "밀랍상들"
  },
  Item_9764_Desc = {
    Text = "죽음 저항 속성의 명륜입니다."
  },
  Item_9764_Name = {
    Text = "밤의 그림자 속에서"
  },
  Item_9764_StoryDesc = {
    Text = "거대한 짐승이 밤의 그림자에 숨어 있다. \n\n작은 오두막 안에서, 사랑하는 딸을 잃은 슬픔의 울음소리가 매일 자정마다 낮의 인내와 억압을 뚫고 아무런 가식 없이 격렬하게 터져 나온다. \n흐느낌에서 비통한 울음으로, 결국 거대한 짐승에게 더 이상 속하지 않는 그 이름을 이야기하며 아픈 호출 소리로 거대한 짐승의 인간과 다름없는 심장을 관통한다. \n\n집으로 돌아가렴, 리사. \n오, 나의 리사. \n거대한 짐승은 조용히, 밤의 그림자에 숨어 있다. 몸을 움츠리고, 깊은 잠에 빠진다. \n언젠가 그녀는 돌아갈 것이다, “집”이라는 이름의 곳으로."
  },
  Item_9765_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 리리 획득 시 전환하여 리리의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9765_Name = {
    Text = "파편 · 릴리"
  },
  Item_9765_StoryDesc = {
    Text = "중복으로 리리 획득 시 전환하여 획득한 것으로, 리리의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9766_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 히로 획득 시 전환하여 히로의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9766_Name = {
    Text = "파편 · 히로"
  },
  Item_9766_StoryDesc = {
    Text = "중복으로 히로 얻기 전환하여 획득하며, 히로의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9767_Desc = {
    Text = "“번식”과 “생존”이야말로 테이스의 추구하는 바——무론 이 웃기는 논조 아래에 다른 숨겨진 사정이 있든 없든. \n·팀원에게 광기 제공\n·아군 스킬 모방"
  },
  Item_9767_Name = {Text = "타이스"},
  Item_9768_Desc = {
    Text = "우리에게 미지의 영지를 부여한다.\n필린 시사의 특수 필름으로, 인간의 영지를 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9768_Name = {
    Text = "영지 템플릿"
  },
  Item_9769_Desc = {
    Text = "날갯짓은 토네이도를 일으키거나 꽃가루 알레르기를 유발할 수 있다.\n나비 결정 무리. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9769_Name = {
    Text = "혼돈의 결정 나비"
  },
  Item_9770_Desc = {
    Text = "이것은 공예품이 아니라, 연금술사와 마주한 나비의 비극적인 최후다. \n단순한 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9770_Name = {
    Text = "희미한 결정 나비"
  },
  Item_9771_Desc = {
    Text = "꽃말: 내게 멀리 떨어져. \n낮은줄기 바다백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9771_Name = {
    Text = "낮은줄기 바다백합"
  },
  Item_9772_Name = {
    Text = "특수 융식 흔적"
  },
  Item_97737_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “정지된 중하의 기념”을 선택할 수 있습니다.\n\n현실타래의 축제는 언젠가 끝나지만, 영혼에 새겨진 기억은 영원히 멈추지 않습니다.\n얼마나 많은 번을 되돌아보더라도 이 순간을 추억할 때마다 그리움은 밀물처럼 밀려옵니다."
  },
  Item_97737_Name = {
    Text = "정지된 한여름의 추억"
  },
  Item_97737_StoryDesc = {
    Text = "현실타래의 축제는 언젠가 끝나지만, 영혼에 새겨진 기억은 영원히 멈추지 않습니다. \n얼마나 많은 번을 되돌아보더라도 이 순간을 추억할 때마다 그리움은 밀물처럼 밀려옵니다."
  },
  Item_9773_Desc = {
    Text = "액체는 그것의 외관이며, 모든 것의 기반이자 구성 요소이다. \n유리병에 봉인된 특수 물질로, 운명을 간섭할 수 있는 힘을 지녔다고 전해진다. \n명륜의 등급을 올리는 데 사용할 수 있다."
  },
  Item_9773_Name = {
    Text = "혼란의 이더(이미 폐기됨)"
  },
  Item_9774_Desc = {
    Text = "주 속성으로 치명타 확률, 치명타 피해, 은열쇠 충전 레벨과 광기 충전 레벨 중 랜덤으로 1개를 획득한다."
  },
  Item_9774_Name = {
    Text = "황야의 늑대 Ⅰ"
  },
  Item_9774_StoryDesc = {
    Text = "아우우우, 아우우우."
  },
  Item_9775_Desc = {
    Text = "날개는 단지 아름다움을 더할 뿐이며, 5펜시의 값어치가 있다. \n빛나는 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9775_Name = {
    Text = "빛나는 결정 나비"
  },
  Item_9776_Desc = {
    Text = "달콤하고 단단하다. 아이들의 속삭임과 함께 오가며, 우정의 상징이자 어린 시절의 보물이 된다.\n아이들이 좋아하는 사탕. 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9776_Name = {
    Text = "행운의 사탕"
  },
  Item_97775_Desc = {
    Text = "미사격 깨어남체의 집단 잠재의식이 기억의 바다에 밀려와 환화된 해변 조개껍데기로, 하나하나가 독보적이며 환몽 속에서 부서진 아름다운 기억을 품고 있습니다.\n\n최소 1800개 드롭"
  },
