  },
  Item_97805_Name = {
    Text = "해변 특산물 조개"
  },
  Item_9780_Desc = {
    Text = "종말이 태아의 탄생 순간에 찾아온다 해도, 그녀는 그것을 단맛처럼 받아들일 것이다. \n성실타래한 마음으로 빛나는 신비한 장식품. 깨어남체 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_9780_Name = {
    Text = "성심의 경건함"
  },
  Item_9781_Desc = {
    Text = "케르베로스라 불리는 고차원 생명체에게서 떨어져 나온 결정. 현재 인류의 문명 수준으로는 그 구성 성분을 해석할 수 없다. \n신비로운 보랏빛 결정체. 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9781_Name = {
    Text = "차원 결정"
  },
  Item_9782_Desc = {
    Text = "나무의 유골로, 아란 문명이 오늘날에 남긴 잔해를 상징하는 것일지도 모른다.\n풍요의 지모수에서 꺾인 가지. 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9782_Name = {
    Text = "지모수의 유해"
  },
  Item_9783_Desc = {
    Text = "태생적으로 왕관을 착용한 자는 경쟁자의 열정을 이해하기 어렵다. \n무거운 왕관. 깨어남체 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_9783_Name = {
    Text = "성태의 면류관"
  },
  Item_9784_Desc = {
    Text = "그 무수한 원초의 시선 아래에서, 너희는 부상을 입고 목숨을 잃는다. 너희는 수호자라는 이름으로 계속해서 나아갈 것이다.\n최고의 의지가 남긴 눈는 깨어남체 스킬 레벨을 강화하는 데 사용된다."
  },
  Item_9784_Name = {
    Text = "원초의 눈"
  },
  Item_9785_Desc = {
    Text = "불길을 상징하는 꿈 포착망, 전설에 따르면 영원으로 통하는 문을 연결할 수 있다고 한다.\n등불 교회가 신의 꿈속 헛소리를 포착하기 위해 사용하는 도구로, 깨어남체 스킬 레벨을 올리기 위해 사용된다."
  },
  Item_9785_Name = {
    Text = "꿈결의 고리"
  },
  Item_9786_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_9786_Name = {
    Text = "겨울밤의 추억"
  },
  Item_9786_StoryDesc = {
    Text = "잔뜩 찌푸린 구름이 렌티니엔 상공을 뒤덮어 달빛을 가로막았다. 자정을 알리는 종소리가 이미 울렸고, 높게 솟은 굴뚝은 여전히 뜨거운 검은 연기와 습기를 뿜어내고 있었다. 바람에 실타래려 온 먼지가 눈송이에 붙어, 떨어지기도 전에 칙칙한 회색으로 물들었고, 그 눈송이는 가로등 위로 아슬아슬하게 내려앉았다. 거의 즉시, 가로등 불빛의 열기로 녹아내려, 지나가는 소녀의 몸 위로 물방울을 떨어뜨렸다.\n\n소녀는 갈색 옷을 입고, 너무 커서 어설프게 걷어올린 소매 사이로 뼈만 앙상하게 드러난 팔이 보였다. 그녀는 힘겹게 종종걸음을 치며, 가끔 옷소매를 올려가며 앞서가는 여자를 따라잡으려 애쓰고 있었다.\n\n여자가 고개를 돌려 소녀를 힐끗 보고 혀를 찼다. \n“좀 빨리 움직여라. 천천히 가면 안 가도 되는 줄 아냐?” \n\n“네, 네... 엄마.” 소녀는 급하게 여자의 옆으로 달려갔지만, 헐떡이며 말을 이었다. “죄송해요, 엄마.” \n\n“엄마라고 부르지 마!” 여자는 소녀의 팔을 휙 잡아채며 발걸음을 재촉했다. \n“남의 피를 빨아먹는 쓸모없는 놈. 네가 없었더라면 내가 이런 누추한 곳에 떨어지지도 않았을 텐데.” \n\n“죄송해요...” \n\n“닥쳐, 무가치한 놈.” 여자의 손톱이 소녀의 팔에 박히며 깊은 자국을 남겼다. \n“분명히 말할게. 오늘부터 공방이 네 집이야. 날 찾으러 오겠다는 생각은 꿈도 꾸지 말라고. 죽어도 널 보고 싶지 않아. 알겠어?” \n\n“알았습니다...” 소녀는 고개를 숙인 채 대답하며 흐르는 눈물을 닦지도 않고, 더러운 눈물방울은 신발 위로 모였다가 더러운 눈물과 함께 돌길 바닥으로 사라졌다. 저 멀리 공장의 퇴근 저녁 나팔 소리가 울려 퍼졌고, 골목길 사이에서는 야생 고양이 한 마리가 순간적으로 뛰어들어 사라졌다. 적막을 깨며 남은 건 두 사람의 발소리뿐이었다. 그녀들은 골목 모퉁이를 돌아 길가에 널어둔 젖은 빨래에서 축축한 냄새가 나는 뒷마당을 지나갔다. 그리고 금속 대문이 달린 건물 앞에서 걸음을 멈췄다.\n\n“여기서 기다리고 있어라,” 여자의 목소리는 매우 평온하며 나아가 감정이 빠진 듯 들렸다. \n“날이 밝으면 안에서 사람들이 나올 거야. 그들이 널 받아줄 거다. 따라오는 것만은 절대 하지 마. 그러면 내가 널 죽여버릴 테니까.” \n\n여자는 뒤돌아 걸어갔다. 마찬가지로 앙상하고 약간 구부정한 실타래루엣이 곧 어둠 속으로 사라졌다. 소녀는 무력하게 자신의 작은 손을 붙들며 떠나는 여자의 뒷모습을 바라보았다. 그러면서 소매로 얼굴의 눈물을 훔쳤다.\n\n희미한 등불이 그녀 뒤에서 비추며 철문과 그녀의 그림자를 길게 늘어뜨렸다. 그녀의 어깨 위로 손이 내려오자 소녀는 깜짝 놀랐다. \n\n“안쓰러운 아이구나, 왜 혼자 여기 이러고 있니?” \n젊은 여성이었다. 수녀처럼 보이는 옷을 입은 그녀가 말했다. \n“어서, 사라 언니가 데려가 줄게. 금방 안 추워질 거야.”"
  },
  Item_9787_Desc = {
    Text = "푸른 불꽃이 모든 악도들의 영혼을 태우고, 무대 위의 모든 더러움을 불살랐다. \n·그 녹화염은 초원공간에서 끊임없이 성장한다. \n·광기 폭발이 모든 녹화염을 태워버릴 것이다."
  },
  Item_9787_Name = {Text = "리즈"},
  Item_9788_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9788_Name = {
    Text = "약재의 꿈 Ⅵ"
  },
  Item_9788_StoryDesc = {
    Text = "천 년 전, 5분은 40온스의 고운 모래와 같았다."
  },
  Item_9789_Desc = {
    Text = "'타격'을 사용하는 동시에 추가 카드를 뽑을 확률이 있으며, 초차원 턴 중 폭발적으로 아이디어를 얻습니다."
  },
  Item_9789_Name = {
    Text = "속박된 노래"
  },
  Item_9789_StoryDesc = {
    Text = "인간은 노래하는 것을 좋아하는 생물이며, 황야의 별 사람들에게도 마찬가지이다. \n 멜로디는 목구멍에서 자유롭게 흘러나오고, 어떤 의도나 목적도 필요 없다. \n 그것들은 바람에 의해 흩어지는 음표로 나뉘어지고, 감정과 함께 시들어 간다. \n 전해지길, 사막에서 모든 방랑 부족은 자신의 노래를 가지고 있다고 한다. \n 하지만 황야의 별 사람들은 자신의 노래를 잃어버렸다. \n\n 노래와 함께 잃어버린 것은 이름이었다. \n 아무도 황야의 별이 원래 어떤 이름이었는지 모른다. \n 이것은 저주받은 별이다. 가뭄, 폭풍, 기근…… \n 여러 가지 재앙들이 경쟁하듯 나타나 결국 황야의 별을 완전히 무너뜨렸다. \n 화려하게 차려입은 큰 인물들은 방주를 타고 떠났고, 황야의 별은 진정한 황야의 별이 되어 축복받지 못한 하층민들만 남았다. \n 그들은 모두 버림받았다. \n\n 그 이후로 황야의 별 사람들은 결심했다. 그들은 웃음도 필요 없고, 시도 필요 없고, 노래도 필요 없다. \n 그들은 버림받은 고통과 아픔을 기억하고, 백색 사막 속에서 끝없이 기어 다니며 별이 멸망하는 그 순간까지 계속할 것이다."
  },
  Item_9790_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_9790_Name = {
    Text = "먼 곳의 잔치 Ⅱ"
  },
  Item_9790_StoryDesc = {
    Text = "즐겁게 잔치를 즐겨라, 노랫소리 속에서."
  },
  Item_9791_Desc = {
    Text = "각 명륜은 회귀, 혹은 재탄생을 갈망한다.\n 교과서에 기록된 궤적의 법칙. 명륜 돌파에 사용됩니다."
  },
  Item_9791_Name = {
    Text = "순환의 모본"
  },
  Item_9792_Desc = {
    Text = "액체는 그것의 외관이며, 모든 것의 기반이자 구성 요소이다. \n유리병에 봉인된 특수 물질로, 운명을 간섭할 수 있는 힘을 지녔다고 전해진다. \n명륜의 등급을 올리는 데 사용할 수 있다."
  },
  Item_9792_Name = {
    Text = "혼합 이더 (이미 폐기됨)"
  },
  Item_9793_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 문서로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9793_Name = {
    Text = "순백의 서류"
  },
  Item_97948_Desc = {
    Text = "이벤트「검은 양이 내리쬐는 영원한 여름」에서 획득함. \n「말해 봐, 지금 누가 진짜 최강의 배구 챔피언인지?」"
  },
  Item_97948_Name = {
    Text = "배구 '대장'"
  },
  Item_97949_Desc = {
    Text = "해제 후, 「그림 측정 기행」의 모든 임무를 완료하면 추가 보상을 받을 수 있습니다"
  },
  Item_97949_Name = {
    Text = "휴일 기행"
  },
  Item_9794_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 라모나를 획득할 때 전환하여, 라모나의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9794_Name = {
    Text = "파편·라모나"
  },
  Item_9794_StoryDesc = {
    Text = "중복으로 라모나를 획득할 때 전환하여 획득하며, 라모나의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9795_Desc = {
    Text = "이 증거에 따라 미사그 학내 훈련에 한 번 참여할 수 있습니다."
  },
  Item_9795_Name = {
    Text = "연습 증명서 (이미 폐기됨)"
  },
  Item_9796_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9796_Name = {
    Text = "달콤한 달팽이 Ⅲ"
  },
  Item_9796_StoryDesc = {
    Text = "달콤하고, 끈적거린다."
  },
  Item_9797_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9797_Name = {
    Text = "뒤틀린 쌍둥이·흑 Ⅵ"
  },
  Item_9797_StoryDesc = {
    Text = "진한 검은 피의 제물."
  },
  Item_97989_Desc = {
    Text = "「과제 기록」에서 「핵심 과제」를 구매하면 얻을 수 있습니다.\n「세상의 정상에 서서 오직 혼자만의 고독을 즐긴다. 아, 장생종의 인생은 이토록 건조하고 무미건조하구나.」"
  },
  Item_97989_Name = {
    Text = "바래지 않는 어제: 로탄"
  },
  Item_97989_StoryDesc = {
    Text = "제21기 과제 기록"
  },
  Item_9798_Desc = {
    Text = "우리에게 미지의 인식을 부여한다.\n필린 시사의 특수 필름으로, 인간의 인식을 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9798_Name = {
    Text = "인식 템플릿"
  },
  Item_97991_Desc = {
    Text = "좋은 축제는 흥청망청 즐길 이유가 되어야 한다.\n축제가 충분히 사랑받는지 판단할 때, 그 유래가 특히 중요하다. 축제가 너무 작으면, 나무를 심거나 어리석은 다람쥐를 기념하는 축제처럼 즐길 기회가 부족하다; 축제가 너무 크면, 은상제와 같은 성대한 축제는 지나치게 엄숙하고 규칙이 많다.\n온 달력을 뒤져보면, 머피가 가장 기대하는 날은 순성제라는 날이다. 이 다정한 축제는 자연스럽게 야간 파티를 동반하며, 모든 사람들이 기이한 모습으로 화려하게 차려입을 수 있다. 가장 중요한 것은, 이 날에는 무수한 디저트와 사탕이 미사그의 모든 구석을 차지한다.\n과일 젤리, 리큐르 사탕, 밀크 캔디, 민트 사탕, 태피 캔디, 각종 초콜릿…… 하! 이게 바로 숙녀를 위해 준비된 축제가 아닌가?\n머피는 신나게 뾰족한 마녀 모자를 쓰고, 부풀어 오른 호박 치마로 갈아입은 후, 가장 큰 호박 바구니를 정성스럽게 골라 문을 열고 나갔다.\n「뭐라고? 이 사탕이 어린이를 위해 준비된 거라고?」\n젠킨이 가득 담은 바구니를 들고 떠나는 뒷모습을 보며, 숙녀는 믿기지 않는다는 듯 눈썹을 치켜세우고, 치마 아래의 더듬이가 불만스럽게 흔들렸다.\n두 줄의 이가 분노에 차서 갈갱이를 갈고, 그녀는 냉소를 지으며, 쿵 하고 호박 바구니를 카운터 위에 세게 내리쳤다.\n「받지 못할 거라면, 좋아, 이제 나는 아이가 아니야, 강도야! 탈취한다! 내가 셋을 센다, 너희의 모든 사탕을 빨리 포장해! 서둘러!」\n땀을 뻘뻘 흘리는 레스토랑 종업원은 어쩔 수 없이 사탕대를 비우고, 그 후 숙녀가 넘치는 바구니를 들고 미친 듯한 웃음 속에서 당당히 떠나는 모습을 지켜보았다.\n이 기괴한 웃음소리는 캠퍼스 곳곳에서 밤새 계속되었고, 이후 미사그에는 이런 전설이 생겼다: 순성제의 그 밤, 사탕을 지닌 모든 사람은 유령처럼 몰래 다가오는 사탕 사냥 마녀에게 정확히 찾아내어지며, 성실타래하게 모든 단 것을 바치지 않으면 무서운 마녀의 손에서 탈출할 수 없다."
  },
  Item_97991_Name = {
    Text = "사탕 마녀"
  },
  Item_97992_Desc = {
    Text = "특별히 호박 모양으로 만들어진 축제 사탕, 그 안의 속은 다양한 속재료가 섞여 있으며, 매우 기괴한 맛을 먹을 기회가 있다고 합니다."
  },
  Item_97992_Name = {
    Text = "괴상한 맛의 호박사탕"
  },
  Item_97993_Desc = {
    Text = "의상 「사탕 마녀」 획득 시 개방됩니다. \n「강도다! 셋 셀 테니까, 여기 있는 사탕 전부 담아서 내놓으라구! 지금 당장!」"
  },
  Item_97993_Name = {
    Text = "머피·사탕 마녀"
  },
  Item_9799_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 비밀 문서로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
