  Item_9799_Name = {
    Text = "순백의 비편"
  },
  Item_9800_Desc = {
    Text = "인류의 존속을 위해. \n액자에 보관된 감정. 혈육 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9800_Name = {
    Text = "감정 복사본"
  },
  Item_9801_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n오레타를 반복 획득할 때 전환하여 기령을 활성화하는 데 사용됩니다."
