  Item_9801_StoryDesc = {
    Text = "오레타를 중복으로 획득하면 전환하여 사용할 수 있으며, 이를 통해 오레타의 기령을 활성화할 수 있습니다."
  },
  Item_9802_Desc = {
    Text = "빛나는 은심 결정. \n은심을 여러 번 정제하여 획득할 수 있으며, 고위 존재의 의지를 연결시킬 수 있다."
  },
  Item_9802_Name = {
    Text = "광휘의 은핵"
  },
  Item_9803_Desc = {
    Text = "특수한 시기에는 특수한 수단이 필요한 법입니다. \n윙클의 승인을 받은 린피테이프 약재로, 수호자가 신속하게 이성을 회복할 수 있도록 도와줍니다.\n사용 후, 120 린피테이프를 보충합니다"
  },
  Item_9803_Name = {
    Text = "특별 승인 약제"
  },
  Item_9805_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 문서로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9805_Name = {
    Text = "순백의 서류"
  },
  Item_9806_Desc = {
    Text = "신비로운 보라색 휘광을 반짝이며, 캄브리안 계곡에 운석이 추락할 때 남은 파편이라고 전해집니다. \n 초원차원 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다."
