  },
  Item_9807_StoryDesc = {Text = "미완성"},
  Item_9808_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9808_Name = {
    Text = "표준 밀체 SSR"
  },
  Item_9809_Desc = {
    Text = "그녀는 별들 사이의 가수이며, 빛나는 별먼지입니다. \n그녀는 귀족들의 장난감이며, 금빛 새장에 갇힌 새입니다. \n- 팀의 부정 효과 해제 \n- 적의 힘을 훔침"
  },
  Item_9809_Name = {Text = "틴커트"},
  Item_9810_Name = {
    Text = "다포딜의 기록"
  },
  Item_9812_Desc = {
    Text = "그들은 바다백합이 만개한 봄에 함께 살육하기로 약속했다.\n유인타 백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9812_Name = {
    Text = "유인타 백합"
  },
  Item_9813_Desc = {
    Text = "주 속성으로 치명타 확률, 치명타 피해, 은열쇠 충전 레벨과 광기 충전 레벨 중 랜덤으로 1개를 획득한다."
  },
  Item_9813_Name = {
    Text = "재진화 Ⅰ"
  },
  Item_9813_StoryDesc = {
    Text = "번식하라, 번식하라. 지모수의 피가 흐르는 영혼이 세상에 가득 차게 하라."
  },
  Item_9814_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n다프다일을 반복 획득할 때 전환하여 기령을 활성화하는 데 사용됩니다."
  },
