  },
  Item_9815_Name = {
    Text = "생명력 착취 Ⅵ"
  },
  Item_9815_StoryDesc = {
    Text = "탯줄은 끝없는 미래와 연결되어 있다."
  },
  Item_9817_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_9817_Name = {
    Text = "거꾸로 가는 시계"
  },
  Item_9817_StoryDesc = {
    Text = "두 손의 대검은 길고 무겁고, 충분한 힘으로 사람을 두 동강 낼 수 있습니다.\n\n다거는 가볍고 날렵하여 숨기기 쉽고, 기습 공격에 매우 적합합니다.\n\n곡선이 아름다운 곡칼은 날이 날카로워, 베어낼 때 쉽게 살에 박혀 깊은 상처를 남깁니다.\n\n총기는 빠르고 위압적이며, 석궁은 조용하고 신속하며, 다양한 금속 부품들이 조명 아래 냉혹한 빛을 발합니다. 열 살의 라모나가 무기가 가득 걸린 벽 앞에 서 있으며, 얼굴에는 나이에 맞지 않는 성숙함과 신중함이 드러납니다.\n\n「어떤 걸 선택할래?」양부—아니, 자신을 키워준 아버지의 목소리가 뒤에서 들려옵니다. 「선택하면, 내가 선생님을 구해줄게.」\n\n어떤 걸 선택할까? 대검의 무게는 장점이자 단점이고; 다거는 긴 무기에 대처하기 어렵고; 곡칼은 길지만 베는 것이 항상 많은 불필요한 손상을 초래합니다; 총기의 소음은 너무 크고, 석궁은 탄약이 쉽게 소모됩니다.\n\n미사그 훈련장에서 이렇게 많은 날들을 지켜본 그녀는 전투 양측의 약점을 한눈에 알아보고 거의 직관적으로 공격 경로를 계획할 수 있다는 것을 알고 있었습니다. 많은 경험을 쌓아야 알 수 있는 것들이 그녀에게는 단 1초 만에 추론될 수 있습니다. 아니, 그녀가 원하는 것은 이런 것이 아닙니다. 그녀는 최소한의 힘으로 최대의 피해를 줄 수 있는 더 정밀한 무기가 필요합니다.\n\n여자아이는 잠시 생각한 후, 옆에서 의자를 가져와 그 위에 서서 높은 곳에 걸린 세밀한 검에 손을 뻗습니다.\n\n길고 우아하며, 민첩하고 가벼워서 정확하게 피해를 줄 수 있습니다—맞아요, 바로 그것입니다. 그것은 그녀의 모든 요구를 충족시킵니다."
  },
  Item_9818_Desc = {
    Text = "그녀가 도대체 어떻게 말하는지 — 이는 학원의 수많은 미해결된 신비 중 하나가 되었다. \n·힘과 경계를 오가며 전환하다 \n·초원차원 점프 시 공격과 방어를 동시에 수행할 수 있다"
  },
  Item_9818_Name = {Text = "에리카"},
  Item_9819_Desc = {
    Text = "세트: \n무구의 계시록 Ⅰ\n무구의 계시록 Ⅱ\n무구의 계시록 Ⅲ\n무구의 계시록 Ⅳ\n무구의 계시록 Ⅴ\n무구의 계시록 Ⅵ"
  },
  Item_9819_Name = {
    Text = "무구의 계시록"
  },
  Item_9822_Name = {
    Text = "프랜시스의 회중시계"
  },
  Item_9823_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다. 당신의 본능, 당신의 이성, 심지어 당신의 영혼까지... 결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9823_Name = {
    Text = "연마된 이성"
  },
  Item_9824_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9824_Name = {
    Text = "광합성 제례 Ⅴ"
  },
  Item_9824_StoryDesc = {
    Text = "과학은 분광 분석이고, 예술은 광합성이다."
  },
  Item_9825_Desc = {
    Text = "이것은 공예품이 아니라, 연금술사와 마주한 나비의 비극적인 최후다. \n단순한 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9825_Name = {
    Text = "희미한 결정 나비"
  },
  Item_9826_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 라이커를 획득할 때 전환하여 라이커의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9826_Name = {
    Text = "파편 · 라이커"
  },
  Item_9826_StoryDesc = {
    Text = "중복 획득 시 레크 획득, 레크의 기령 활성화에 사용됩니다."
  },
  Item_98279_Desc = {
    Text = "환의「혈색 단풍」을 얻은 후 잠금 해제됩니다.\n「흔들리는 하얀 치마자락 위에는, 선홍빛 단풍이 가득합니다.」"
  },
  Item_98279_Name = {
    Text = "「24」·피처럼 떨어지는 단풍"
  },
  Item_9827_Desc = {
    Text = "광기 폭발을 사용하면 임시 크리티컬 피해가 증가하고, 장착자의 카드 비용을 확률적으로 감소시킵니다."
  },
  Item_9827_Name = {
    Text = "거인의 검"
  },
  Item_9827_StoryDesc = {
    Text = "갈라진다. 경험한다. 몰려든다. 침략. \n\n 필리스티아인의 플래시어 어근 “p-l-sh”의 진정한 의미에 대해 경전 학자들은 줄곧 의견이 분분하다. \n 생애 처음으로, 골리아는 이 고전 학자들이 다소 실타래제로 지식이 있다고 느꼈다. 왜냐하면 이 네 개의 짧은 단어가 그가 필리스티아인으로서 살아온 인생을 거의 요약했기 때문이다. \n\n 필리스티아인은 명실타래상부한 해양 민족이다. \n 그들은 모여 있는 긴꼬리 상어처럼, 피의 냄새를 따라 거주할 섬을 찾아가 원주민을 모두 죽인다. \n\n 필리스티아인은 지치지 않는다. \n 그들은 결코 머무르지 않으며, 모든 것이 정리되면 불안한 유전자가 다시 그들을 떠나게 하여 새로운 먹이를 찾게 한다. \n\n 필리스티아인은 내일을 신경 쓰지 않는다. \n 그들은 항상 놀라운 속도로 약식한 재물을 낭비하며, 마지막 한 방울의 포도주를 마시고, 마음껏 번식하고, 싸우고, 배신한다… \n\n 출항할 때, 골리아는 배가 바다 위에 남긴 궤적을 돌아본다. \n 필리스티아인의 피, 원주민의 피, 적의 피, 바다새의 피… \n 그것들은 한곳에 모여 어두운 붉은 잉크가 끝없는 푸른 바다에 스며드는 것처럼 보인다. \n\n 다음 날, 태양은 평소처럼 떠오르고, 바닷물은 만 조각의 부서진 금처럼 요동치며 반짝인다. 모든 것은 흔적 없이 사라진다. \n 그들은 바다에 있지만, 바다는 그들을 잊었다."
  },
  Item_9828_Desc = {
    Text = "너무 강경한 사람, 그녀는 전투를 통해 당신의 영혼을 부드럽게 할 것입니다. \n- 팀의 힘을 높입니다. \n- 적 전체를 공격하는 스킬을 가지고 있습니다."
  },
  Item_9828_Name = {Text = "로탄"},
  Item_9829_Desc = {
    Text = "그는 초인의 지혜에 지쳤고, 열광적인 숭배에 지쳤으며, 만고를 넘어서는 장꿈에도 지쳤다.\n·터치 월에 명령하여 공격을 내린다\n·산출력을 소모하여 터치 월의 힘을 강화한다"
  },
  Item_9829_Name = {Text = "툴루"},
  Item_9831_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 회복, 검은 인장 드롭율, 은열쇠 충전 중 무작위 1개를 획득합니다."
  },
  Item_9831_Name = {
    Text = "바다에서 돌아오는 길 Ⅳ"
  },
  Item_9831_StoryDesc = {
    Text = "돌아오라, 잊혀진 그 도시가 재현될 것이다."
  },
  Item_9833_Desc = {
    Text = "영지가 무한히 증폭되면, 진실타래의 한 구석에 닿게 될 것이다.\n은심으로 구동되는 특수 장치. 설정값에 따라 깨어남체의 능력을 영구적으로 향상시킬 수 있다.\n수호자 레벨 30에 도달하면, 임의의 깨어남체를 선택하여 다음 강화 효과를 부여할 수 있습니다:\n·레벨 40으로 상승\n·계령 등급 3으로 상승"
  },
  Item_9833_Name = {
    Text = "영지 증폭기 Ⅳ"
  },
  Item_9834_Desc = {
    Text = "미사그 대학의 설립자가 개발한 약재로, 깨어남체의 능력을 향상시킨다. \n은심과 비밀의 약을 섞어 독특한 색을 띠고 있다.\n사용 시 깨어남체의 경험치가 2000 증가한다."
  },
  Item_9834_Name = {
    Text = "영지 비약Ⅱ"
  },
  Item_9835_Desc = {
    Text = "그녀의 본의가 아니더라도, 이 세상에는 어둠 속에서 혼자 살기에 적합한 생명체가 있을지도 모른다.\n·적 행동 정지\n·적에게 취약 부여"
  },
  Item_9835_Name = {
    Text = "아이기스"
  },
  Item_9836_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_9836_Name = {
    Text = "4월의 찬가 Ⅰ"
  },
  Item_9836_StoryDesc = {
    Text = "그는 @2년 봄에 땅에 묻혔다."
  },
  Item_9837_Desc = {
    Text = "영지가 무한히 증폭되면, 진실타래의 한 구석에 닿게 될 것이다.\n은심으로 구동되는 특수 장치. 설정값에 따라 깨어남체의 능력을 영구적으로 향상시킬 수 있다.\n임의의 깨어남체를 선택하여 다음 강화 효과를 부여할 수 있습니다:\n·레벨 10으로 상승"
  },
  Item_9837_Name = {
    Text = "영지 증폭기 Ⅰ"
  },
  Item_9838_Desc = {
    Text = "우리에게 미지의 정신을 부여한다.\n필린 시사의 특수 필름으로, 인간의 정신을 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9838_Name = {
    Text = "정신 템플릿"
  },
  Item_9839_Name = {Text = "편지지"},
  Item_9840_Desc = {
    Text = "장미의 가시가 시편의 종이를 찌르고 투명한 피의 자국을 남깁니다. \n· 적 행동을 느리게 합니다. \n· 다양한 보조 능력"
  },
  Item_9840_Name = {Text = "오를라"},
  Item_9841_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9841_Name = {
    Text = "극장의 고양이 Ⅴ"
  },
  Item_9841_StoryDesc = {
    Text = "쉿... 비밀은 부드러운 발바닥에 숨겨져 있다."
  },
  Item_9843_Desc = {
    Text = "라이 마을에 산일된 감정 입자로, 접촉하면 \"괜찮아요\"라는 속삭임이 들리는 듯합니다.\n수호자가 조사 이벤트 「맹견 주의」에서의 공명을 높이는 데 사용됩니다.\n「맹견 주의」 관문 첫 클리어 보상에서 획득할 수 있습니다."
  },
  Item_9843_Name = {
    Text = "인내의 심장"
  },
  Item_9844_Desc = {
    Text = "영지가 무한히 증폭되면, 진실타래의 한 구석에 닿게 될 것이다.\n은심으로 구동되는 특수 장치. 설정값에 따라 깨어남체의 능력을 영구적으로 향상시킬 수 있다.\n수호자 레벨 10에 도달하면, 임의의 깨어남체를 선택하여 다음 강화 효과를 부여할 수 있습니다:\n·레벨 20으로 상승\n·계령 등급 1로 상승"
  },
  Item_9844_Name = {
    Text = "영지 증폭기 Ⅱ"
  },
  Item_9845_Desc = {
    Text = "피해를 줄 때 보유자의 카드를 추출할 확률이 있으며, 여러 번 피해를 줄 수 있는 깨어남체에 적합합니다."
  },
  Item_9845_Name = {
    Text = "길 없는 길"
  },
  Item_9845_StoryDesc = {
    Text = "소녀는 눈을 떴다. 자신이 어둠 속에 있다는 것을 알아차렸다.\n“야!” 그녀는 외쳤다. “누구 있어요?”\n메아리가 끝없이 이어지는 공간 속을 부유하다가 점차 사라졌다. 소녀는 깊이 숨을 들이쉬고 다시 한 번 외쳤다. “언니, 브라운, 서쪽 동네 녀석들!” \n“누구 있어요——” \n이전보다 더 큰 소리로 외친 질문은 멀리 날아가다가 천천히 되돌아왔다. 그때 약간의 푸른빛이 마치 메아리에 이끌리듯 멀리서 가까워져왔다. 그것들은 무수히 떠다니며 먼지처럼 작은 입자들이 모인 것으로, 뱀처럼 공중에서 구불구불하게 움직이며 또한 파도처럼 일렁였다. 빛줄기 하나하나가 끊임없이 원래 자리에 서 있는 소녀의 몸을 스치며 지나갔고, 순식간에 그녀의 주변을 별이 가득한 바다로 바꿔놓았다. 미세한 입자들은 소녀의 손가락과 머리카락 사이를 통과했지만 아무 흔적도 남기지 않았다. \n“이건…뭐야?” \n발광하는 먼지가 그녀 주위를 살짝 이리저리 움직였지만 아무 대답도 하지 않았다. \n“난 밀랍 인형 박물관을 기억해, 언니도…난…죽은 거 같아. 여기가 천국인가?” 그녀는 좌우를 둘러보았다. “천사가 하나도 없다니. 그럼 설마 여기가 지옥이야?” \n그녀의 목소리는 자신의 귀 근처에 가라앉았고, 이번에는 메아리조차 나타나지 않았다. \n말로 표현할 수 없는 고독감이 그녀 마음속에서 피어오르고, 아찔한 기분 속에서 그녀는 마치 언니를 만나기 전, 브라운을 만나기 전으로 돌아간 듯했다. 어두운 하수도 악취가 진동했다. 그녀는 춥고 배고팠지만, 떠날 수 없었다. 누군가 그녀를 밀어 넣은 뒤 하수도 위에 커다란 드럼통을 눌러놓았기 때문이었다. \n그녀는 자신의 뺨을 몇 번 두드리고, 앞으로 발걸음을 내딛었다. \n먼지는 그녀의 앞에서 갈라졌다가 뒤에서 다시 모였다. 발을 들고, 내디디고, 발을 들고, 내디디고. 소녀는 그렇게 계속 걸었다. 얼마나 걸었는지, 얼마나 먼 거리를 걸었는지 알 수 없었다. 그녀 앞에는 여전히 먼지와 어둠뿐이었고, 그녀의 뒤로는 오던 방향도, 지나온 길도 더 이상 흔적이 없었다. 그러다—— \n“깨우기 성공했습니다. 젠킨, 젠킨, 들리나요?”"
  },
  Item_9846_Desc = {
    Text = "기본 피해를 증가시키고, 보유자가 추가로 카드 생성할 확률이 있습니다."
  },
  Item_9846_Name = {
    Text = "족쇄를 벗어던진 날"
  },
  Item_9846_StoryDesc = {
    Text = "영웅이 마침내 위대한 여정을 마치고, 사람들은 그림책의 마지막 페이지를 덮으며 깊은 잠에 빠져들었다.\n\n긴 밤이 찾아왔고, 히로의 이야기는 이제 막 시작되었다.\n\n그녀는 길로 이어진 해안선을 따라 북쪽으로 가고, 시냇물을 건너고, 높은 산을 넘으며 얼음으로 뒤덮인 땅 끝까지 도달했다.\n그 놀라운 반란이 일어난 지 여러 해가 지난 지금, 히로가 다니는 곳에서는 만물이 번영하며 일은 모두 순조롭고, 노예와 주인 사이에는 미묘한 균형이 유지되었으며, 과격한 반란은 어색하고 우스꽝스럽게 보였다.\n그녀는 의심받고, 조롱당하고, 결국 잊혀졌다.\n하지만 그녀는 변명하지 않았다.\n\n전사 히로는 자취를 감추고, 그녀는 자유의 씨앗을 지중해의 깊은 곳에 묻어두었다. 5년, 10년, 100년...\n언젠가는 그것들이 흙을 뚫고 자라나 성장할 것이다.\n\n이 스파르타 전사 히로가 결국 묻힌 장소를 아는 사람은 없으나, 옛 친구 에파미논다스가 그녀의 시신을 수습했다는 이야기가 전해진다.\n오랜 세월이 흐른 뒤, 한껏 피어난 자스민 꽃밭의 풀 언덕을 지나가다가 작은 묘비를 볼지도 모른다. 묘비에는 이렇게 적혀 있다:\n\n이 풀밭 아래에는 전사가 묻혀 있노라.\n아니면,\n그녀는 한때 전사였노라.\n그녀는 늙은 페리클레스의 딸이며, 델로스 섬의 자랑이었다.\n시인 프락톸스는 그녀가 용맹히 싸웠다고 칭송했으며,\n스파르타의 검은 머리 전사들은 그녀의 업적을 더 잘 알고 있노라."
  },
  Item_9847_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n아이기스를 반복 획득할 때 전환하여 아이기스의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9847_Name = {
    Text = "파편 · 아이기스"
  },
  Item_9847_StoryDesc = {
    Text = "아이기스를 중복 획득하면 전환되며, 이를 통해 아이기스의 기령을 활성화할 수 있습니다."
  },
  Item_9848_Desc = {
    Text = "이것은 공예품이 아니라, 연금술사와 마주한 나비의 비극적인 최후다. \n단순한 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9848_Name = {
    Text = "희미한 결정 나비"
  },
  Item_9849_Desc = {
    Text = "광기 충전 레벨 속성의 명륜이다."
  },
  Item_9849_Name = {
    Text = "죽음을 넘어"
  },
  Item_9849_StoryDesc = {
    Text = "그들은 인간이 알 수 없는 것에 대한 상상에서 탄생했지만, 상상 속의 광기나 날카로움은 없었습니다.\n\n그들은 이성적이며, 냉정했습니다.\n\n그들은 미래를 위해, 생존을 위해 존재합니다.\n\n그들은 가장 비정상적이고, 가장 믿기 힘든 기적입니다.\n\n처음에는 그들의 목소리가 마치 벌레 울음소리처럼 들렸습니다. 하지만 그들의 사고방식을 완전히 이해하게 된 후, 그 소리는 잠잠해졌습니다.\n\n그렇지만 이후로, 목소리의 주인들은 그녀가 선택하는 모든 결정을 좌우하려 했습니다.\n\n깨어남체의 몸으로 깨어난 첫 해, 그녀는 머릿속 목소리와 공존하는 법을 배웠습니다.\n\n그녀는 의식 속으로 잠입하여 게슈탈트의 일부가 되고, 필요한 정보와 지식을 끌어낸 뒤, 무사히 현실타래 세계로 돌아왔습니다.\n\n“검은 역병”이 이 몸에 찾아왔을 때에도, 그녀는 동일하게 행동했습니다.\n\n그녀는 육체와 지식, 기억, 영혼을 분리하여, 뇌를 불멸의 개체로 만들고자 했습니다.\n\n수술이 끝난 후, 그녀는 생생하고 신비한 수면 상태에 빠질 뻔 했습니다. 그러나 단 몇 초 만에 그녀의 사고는 다시 시작되었습니다.\n\n그녀는 명확히 알고 있었습니다. 자신이 형식, 힘, 대칭성을 초월한 혼돈 속 완전한 파괴에 점점 가까워지고 있다는 것을."
  },
  Item_9850_Desc = {
    Text = "영역 숙련 속성의 명륜입니다."
  },
  Item_9850_Name = {
    Text = "책임의 무게"
  },
  Item_9850_StoryDesc = {
    Text = "대리 학장은 미사그 캠퍼스 내의 이질적인 존재이다.\n\n각양각색의 초능력을 지닌 괴물이 넘쳐나는 미사그 조사원들 중, 그녀는 인간의 기본 능력을 초월하지 못한 드문 인물 중 하나이지만, 대리 학장이라는 중요한 직무를 맡고 있다. \n엘크 왕국의 평범한 가정에서 태어난 그녀는 지역 특유의 문화 속에서 용맹하고 과감한 성격을 키웠다.\n\n이후, 포로 수용소의 동료 소피아가 그녀의 학문 연구에 대한 열정을 불러일으켰다. \n뛰어난 학문적 업적으로 그녀는 자신의 스승이자 미사그 대학 생물학부 전임 학장으로부터 가장 신뢰받는 제자가 되었다. \n그러하여 스승이 실타래종된 후, 그녀는 자연스럽게 대리 학장의 역할을 맡게 되었다. \n그녀의 헌신 덕분에 생물학부의 연구는 차질 없이 운영되고 있다.\n\n「폭력을 두려워하지 않고, 패권을 두려워하지 않으며, 물론 책임 또한 두려워하지 않는다.」"
  },
  Item_9851_Desc = {
    Text = "세트: \n황야의 늑대Ⅰ\n황야의 늑대Ⅱ\n황야의 늑대Ⅲ\n황야의 늑대Ⅳ\n황야의 늑대Ⅴ\n황야의 늑대Ⅵ"
  },
  Item_9851_Name = {
    Text = "황야의 늑대"
  },
  Item_9852_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9852_Name = {
    Text = "36호실타래의 고리 Ⅴ"
  },
  Item_9852_StoryDesc = {
    Text = "회전하고, 잊는다ーー이것이 그녀의 삶 전부이다."
  },
  Item_9853_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9853_Name = {
    Text = "유기 형태 Ⅴ"
  },
  Item_9853_StoryDesc = {
    Text = "나비는 외로움, 사랑, 그리고 절망으로 인해 죽어가고 있었다."
  },
  Item_9854_Desc = {
    Text = "주 속성으로 광기 충전 레벨, 죽음 저항, 은열쇠 충전 레벨과 피해 증폭 효과 중 랜덤으로 1개를 획득한다."
  },
  Item_9854_Name = {
    Text = "핏빛의 포옹 Ⅴ"
  },
  Item_9854_StoryDesc = {
    Text = "전설 속 최초의 골렘 창조자는, 그가 빚어낸 존재를 두 손으로 끊어냈다."
  },
  Item_9855_Desc = {
    Text = "피해 증폭 속성의 명륜입니다."
  },
  Item_9855_Name = {
    Text = "고통의 저주"
  },
  Item_9855_StoryDesc = {
    Text = "그의 생명의 전반부는 혼돈, 다크와 피로 가득 차 있었다.\n\n먹고 자고, 자고 먹고......나중에 그는 눈을 뜨고 의식을 가졌다.\n\n그들은 그가 자신의 모든 형제자매를 삼켜버린 유일한 생존자라고 말했다.\n그들은 또한 그가 위대한 뱀신과 인간이 교합하여 태어난 자식이라고 말했다.\n그의 목에는 검은 저주가 하나 둘러져 있으며, 그것은 그의 생명을 유지할 뿐만 아니라 그를 통제하여 그가 평생 교회를 거역할 수 없게 만든다.\n그는 이 세상에 대해 여러 가지 의문과 호기심을 가지고 있었지만, 태어나는 순간부터 모든 다른 가능성을 박탈당했다.\n\n아름답고, 위험하며. 숨겨져 있고, 드러나는. 이것들이 모두 그이다.\n안타깝게도, 위의 진술은 그의 본질의 10분의 1도 다루지 않았다.\n이러한 진술이 알비노에게 불쌍한 마음을 불러일으킨다면, 당신은 영원히 후회할 것이다."
  },
  Item_9856_Desc = {
    Text = "장착자의 방어막 생성량이 증가하고, 턴 종료 시 남는 방어막을 보존할 수 있게 됩니다."
  },
  Item_9856_Name = {
    Text = "기억의 나선"
  },
  Item_9856_StoryDesc = {
    Text = "통증, 격한 통증이 그녀의 모든 감각에 가득했다./n/n금속제 잠수복은 수압 속에서 아무 가치도 없었다. 외피는 안으로 움푹 패였고, 나사는 깨져서 그녀의 복강을 때리고 팔을 꿰뚫었다. 차가운 바닷물이 잠수복의 파손부에 밀려들었고, 조금 더 두껍게 만들어져 간신히 원형을 유지하고 있는 헬멧만이 제 역할을 하며, 그녀에게 일말의 희박한 산소를 남기고 있었다./n/n헬멧의 관측창 너머로, 그녀는 외부의 바닷물이 푸른 색에서 검푸른 색으로, 다시 검푸른 색에서 검은 색으로 변하는 것을 보았다. 호흡은 수증기가 되어 유리에 맺혔고, 소용돌이의 굉음은 점차 사라져 귀 속에 환영으로 남았다. 점차 자신의 팔다리가 느껴지지 않았고, 호흡은 한층 더 무거워져 갔다./n/n저체온, 출혈, 저산소, 어느 하나만으로도 의식을 잃게 만들기 충분했기에 그녀는 자신이 기절했으리라 생각했다. 동시에 확신할 수도 없었다. 몇 번이고 눈을 깜빡여도, 눈 앞엔 똑같은 어둠만이 마주했기 때문이다./n/n여기는 빛이 닿지 않는 장소, 아직 인간이 알지 못하는 대양의 깊은 곳이다./n/n어떤 무딘 흥분이 마지막으로 그녀의 피를 요동치게 했다──미지의 영역, 최후의 모험. 그녀의 꿈은 이뤄진 셈일까? 비록 아무 것도 보이지 않는다 해도./n/n발목에서 올라오는 기이한 감촉에 그녀는 고개를 숙여 바라보았고, 어둠 속에서 나타난 무언가가 그녀의 종아리를 타고 올라오는 것을 발견했다. 특이한 심해생물인걸까, 어째서 바닷물보다 차가운걸까? 왜...... 이런 어둠 속인데 그 윤곽이 보일 것 같지?/n/n새카만, 꿈틀대는, 진흙 같은....../n이건 뭘까? 그녀는 어디에? 그녀... 는 누구지?"
  },
  Item_9857_Desc = {
