  },
  Item_9872_Name = {
    Text = "기계장치의 신 Ⅳ"
  },
  Item_9872_StoryDesc = {
    Text = "기계는 완전히 순수하다."
  },
  Item_9873_Desc = {
    Text = "검은 인장 드롭율 속성의 명륜입니다."
  },
  Item_9873_Name = {
    Text = "기사의 맹세"
  },
  Item_9873_StoryDesc = {
    Text = "그가 대공에 의해 기사가 되기로 지명되었을 때, 그는 세상에서 단지 일곱 번의 계절을 목격했을 뿐이다. \n\n대공은 한때 어린아이를 놀리며 농담을 했지만, 모두가 진지하게 받아들였다. \n기사들은 그의 기마와 활쏘기 기술을 훈련시키고, 여관은 그의 예절을 가르쳤으며, 공주도 이 작은 기사를 신뢰하고 의지했다. \n\n아퀴단과 협곡의 광야 고원에서 젊은 기사는 공주의 말을 끌고 있었다. 공주는 힘없이 말의 등에 엎드려 있었고, 보이지 않는 어둠이 그녀의 몸을 삼키고 있었다. \n\n“공주, 더 이상 앞으로 나아갈 수 없습니다.” \n이 협곡을 지나고 이 강을 넘어서면 그들을 키운 땅을 떠나게 된다. \n전쟁의 불길이 외부에서 확산되고, 적은 강 건너에서 비옥한 땅을 노리고 있다. \n천혜의 자연이 그들 사이를 가로막고 있어, 작은 땅이 간신히 살아남아 ‘국가’의 존엄을 유지하고 있다. \n협곡의 이 쪽에서 그들은 건너편의 멸망과 고통을 목격했다. \n무고한 자들의 기도와 슬픔이 강물에 떨어져, 승자의 시가의 일부분이 되었다. \n\n아무리 위대한 국가라도 역사에 휘말리는 것을 막을 수 없다. \n\n적은 어린 손을 베어버렸고, 그는 더 이상 창과 방패를 들 수 없게 되었다. \n적은 연약한 무릎을 짓밟아 그가 철마가 행궁의 대문을 부수는 것을 그저 지켜볼 수밖에 없게 만들었다. \n기사는 적군의 전마 다리에 물어붙잡으려 애썼지만, 적의 만행을 막지는 못했다. \n\n그리고 그는 처음으로 공주가 말한 ‘검은 전염병’을 보았다. \n\n홍수처럼 쏟아진 검은 액체가 행궁의 대문을 넘어 철마의 다리갑을 덮쳤지만, 아무도 멈추지 않았다. \n격렬한 ‘검은 전염병’이 입과 코를 통해 들어가 폐를 쳤지만, 그는 여전히 여기서 쓰러지고 싶지 않았다. \n그 후, 그에게 너무나 익숙한 목소리가 머리 속에서 직접 울려 퍼졌다. \n“너는 이미 충분히 해냈어… 내가 가장 충실타래한 기사여.” \n\n마지막으로, 눈앞에는 빈 하얀 공간만 남아 있었다."
  },
  Item_9874_Desc = {
    Text = "세트: \n저주받은 토끼Ⅰ\n저주받은 토끼Ⅱ\n저주받은 토끼Ⅲ\n저주받은 토끼Ⅳ\n저주받은 토끼Ⅴ\n저주받은 토끼Ⅵ"
  },
  Item_9874_Name = {
    Text = "저주받은 토끼"
  },
  Item_9875_Desc = {
    Text = "기어가고 왜곡되며, 우리는 어두운 곳을 기어다니는……\n감염당한 번데기. 혈육 경계역 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다."
  },
  Item_9875_Name = {
    Text = "원생 번데기"
  },
  Item_9876_Desc = {
    Text = "크리티컬 확률 속성의 명륜입니다."
  },
  Item_9876_Name = {
    Text = "바다의 꿈"
  },
  Item_9876_StoryDesc = {
    Text = "오레타가 태어났을 때, 대홍수가 도시에게 준 영향은 이미 완전히 사라져 있었지만, 외딴 시골 마을에서는 사람들은 여전히 생존을 위해 발버둥치고 있었습니다.\n\n홍수는 사람들에게 바다와 강에 대한 공포를 심어주었고, 떠날 수 있는 사람들은 이미 떠났습니다. 이제 이 작은 어촌에 남아 있는 사람들은 외부에서는 발디딜 곳을 찾기 힘든 여자와 아이들뿐이었습니다.\n이 침울하고 적막한 곳에서, 오레타는 유일한 어린아이였습니다.\n\n그녀는 할머니가 들려준 동화를 고집스럽게 믿고 있었습니다. 엄마와 아빠는 이미 바다로 돌아갔다고, 그들은 오레타가 성장하기를 기다리고 있다고 말입니다. 그녀가 성장하면 모두 다시 모여 행복한 가족이 될 수 있을 거라고.\n\n말을 할 줄 모를 때, 따스한 품에 안겨 잠들었던 기억이 어렴풋하게 있었지만, 부모님에 관한 다른 기억들은 오레타에게 이미 희미해졌습니다.\n그러나 고요한 곳에서 태어나 자라난 아이로서, 오레타는 '외로움'이나 '고독'이라는 것을 이해할 수 없었습니다. 그녀에겐 나름대로 친구들이 있었습니다.\n\n홍수에 질려버린 어른들과는 달리, 오레타는 바다를 무서워하지 않았습니다.\n바다의 왕국 주민이라면, 당연히 바다와 친구가 되어야 하니까요.\n오레타는 '동네 친구들'과 놀 줄 알았습니다.\n그녀는 따개비의 움직임을 흉내 내며 춤추고, 흰동가리를 따라 바닷말 사이를 이리저리 헤엄쳤습니다.\n그녀는 바다거북의 등에 기대어 바다 물결을 타고 뭍에서 아주 멀리까지 떠내려갔습니다.\n그녀는 은은한 달빛이 넘실타래거리는 바다에서 해파리 무리와 함께 놀았죠.\n\n그녀는 기쁨이었고, 상상이었으며, 요정이었습니다.\n\n그녀는 꿈이었습니다.\n"
  },
  Item_9877_Desc = {
    Text = "소지자의 광기 폭발 피해 능력을 높이고, 광기 폭발을 해제한 후 더 많은 힘을 얻을 수 있습니다."
  },
  Item_9877_Name = {
    Text = "혈육의 광연"
  },
  Item_9877_StoryDesc = {
    Text = "오랫동안 나는 유우하시를 생각해 왔어.\n하지만 이 신전의 폐허 속에서, 나는 그를 처음으로 제대로 보게 되었어.\n나는 그의 몸에 무거운 쇠사슬이 포박되어 있는 것을 보았고, 그래서 그는 땅에 엎드려 목을 늘여 변질된 음식을 힘겹게 가까이 하려고 했어.\n마치 개처럼.\n\n칼리굴라가 죽은 후, 폭군의 공모자로서 그는 지금까지 신전의 폐허에 갇혀 있었어.\n나는 손에 있는 사슬을 끌고 토레스를 향한 노예를 끌고 갔어.\n그는 즉시 몸을 세우고, 동공이 커지며, 목구멍에서 급하게 삼키는 소리를 냈어.\n\n“잠깐만.”\n나는 사슬을 잡아 노예를 그가 손이 닿지 않는 거리로 끌어당겼어.\n“내가 한 사람을 죽이는 것을 도와줘.”\n그는 입을 벌려 날카로운 짐승의 이빨을 드러내며 웃었어.\n“너는 내게 이렇게 말한 19번째 인간이야, 그리고 나는 너를 거절해야 해.”\n나는 애써 얼굴을 굳게 하여 그의 실타래망을 보이지 않으려 했어:\n“왜?”\n“만약 네가 나에게 천 명을 죽이라고 한다면, 나는 기꺼이 할 거야. 한 명을 죽이는 건? 네가 가진 지렛대는 턱없이 부족해.”\n“그 사람이 현재의 황제라면?”\n나는 깊이 숨을 들이켰어.\n“이 지렛대는 충분해?”\n유우하시는 하하하고 웃었어:\n“이건 수학 문제야, 내 친구. 하나는 하나고, 천은 천이지.”\n\n“불이 났어, 금빛 궁전이 불타고 있어!”\n멀리서 불길이 치솟고 있었어.\n폭군, 폭군……\n나는 절망적으로 울부짖었어, 세네카를 위해서도, 그리고 곧 폐허가 될 화려한 궁전을 위해서도.\n“그렇게 슬퍼?”\n유우하시는 다가왔어.\n그는 이미 그 토레스를 향한 노예를 즐기고 있었고, 만족스러운 표정을 지으며 입술을 핥고 있었어.\n그래, 나는 그에게 약속했어, 폭군을 죽일 수 있다면, 자유 외에도 천 개의 무고한 생명을 계속해서 즐길 수 있다고.\n그는 이 대화재가 무엇을 의미하는지 이해할 수 있을까?\n그는 구제불능의 폭군을 섬기는 것이 무엇을 의미하는지 이해할 수 있을까?\n아마도 이해하지 못할 거야.\n그는 그저 짐승일 뿐이야.\n\n“로마는 폐허 같아.” 짐승이 말했어.\n“아니면, 너희 나라, 세상……\n내 눈에는 의미 없고 끝이 없는 폐허일 뿐이야.\n너희는 그것을 위해 눈물을 흘리고, 서로를 죽이며, 모든 헛된 일을 하고 있어……\n솔직히, 나는 이해하지 못해.”\n\n나는 그의 상처투성이 몸을 바라보았어.\n그것은 수백 년의 세월 속에서 수백만의 혈육으로 만들어진 마법의 형상이었고, 끊임없이 부서지고 재조합되었어, 마치 로마처럼.\n“그럼 너는? 너도 폐허인가?”\n“아마도 그렇겠지.”\n그는 기지개를 켜며, 좁은 눈에서 먼 곳의 금빛 불꽃이 반짝였어.\n“하지만 나는 신경 쓰지 않아.”"
  },
  Item_9878_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복 획득 시 소렐을 변환하여, 소렐의 기령을 활성화하는 데 사용됩니다."
  },
