  },
  Item_9879_Name = {
    Text = "뒤틀린 쌍둥이·흑 Ⅳ"
  },
  Item_9879_StoryDesc = {
    Text = "진한 검은 피의 제물."
  },
  Item_9880_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n산을 반복적으로 획득하면 전환하여 얻으며, 이를 사용하여 기령을 활성화할 수 있습니다."
  },
  Item_9880_Name = {
    Text = "파편 · 산"
  },
  Item_9880_StoryDesc = {
    Text = "산을 반복적으로 획득하면 전환하여 얻으며, 이를 사용하여 기령을 활성화할 수 있습니다."
  },
  Item_9881_Desc = {
    Text = "지속적으로 열쇠 에너지를 얻고, 열쇠의 해제로 팀에 광기를 제공하며, 추가 핸드 카드 한계와 배아 획득이 더 유연한 선택을 가져옵니다."
  },
  Item_9881_Name = {
    Text = "자비로운 양육"
  },
  Item_9881_StoryDesc = {
    Text = "역사는 항상 승자의 일언지하에 있다. 모체의 소멸, 국가의 전복, 과거에 관한 모든 것이 조용히 변화하고 있다. \n 시인은 니느웨 미인의 이야기를 전하고, 여행자는 모닥불에 둘러앉아 귀를 기울인다. \n\n “은빛 사막을 가로질러, 이국의 미인이 니느웨에 들어왔다. \n 천하의 물이 그녀의 어깨에서 미끄러져 떨어지고, 시나의 진주가 그녀의 눈에서 떨어졌다. \n 황금빛 두 눈 속에, 이국의 과거를 응시하고, \n 꿀빛 피부 위에, 니느웨의 미래를 기록한다.” \n\n 그리고 나서? 이 미인은 여왕이 되었나요? \n 노쇠한 시인이 7현악기를 튕기며 긴 한숨을 내쉰다. \n\n “그녀는 최면제, 만백성이 그녀에게 매료된다. \n 그녀는 독극물, 왕과 신하의 폐 깊숙이 스며든다. \n 그녀는 홍수, 백성은 도망칠 수 없다. \n 그녀는 검은 전염병의 사자, 그녀는 질병, 악몽, 죽음과 니느웨의 종말을 가져온다.” \n\n 악기가 아직 내려놓이지 않았고, 술상 옆에 한 사람이 일어나자 많은 술객들이 고개를 돌린다. \n 그 사람의 길고 가는 손가락 사이로 몇 개의 술돈이 떨어지고, 금과 은이 굴러 떨어져 딩동 소리를 낸다. \n 그녀가 가는 곳마다, 시선이 따라가고, 불빛이 반짝인다. \n\n “시간은 흘러가지만…… 괜찮아, 그분은 이러한 허튼 소리에 응답하지 않을 것이다. \n 언젠가 여러분은 그분의 자비와 너그러움을 이해하게 될 것이다…… 내가 이해한 것처럼……” \n 그녀는 술집의 낡은 작은 문을 밀어 열었다. 보석 상자를 여는 것처럼, 달빛이 드러난 어깨에 떨어져 반짝이는 빛을 비춘다. \n 달빛에 사랑받는 그 미인은 정말로 꿀 같은 피부를 가지고 있다."
  },
  Item_9882_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
  },
  Item_9882_Name = {
    Text = "표준 밀체 SSR"
  },
  Item_9883_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_9883_Name = {
    Text = "극장의 고양이 Ⅰ"
  },
  Item_9883_StoryDesc = {
    Text = "쉿... 비밀은 부드러운 발바닥에 숨겨져 있다."
  },
  Item_9884_Desc = {
    Text = "피해를 줄 때 이번 턴 내에서 무한히 치명타 피해를 중첩할 수 있으며, 단일 턴에 적을 연속해서 타격할 수 있는 깨어남체에 적합합니다."
  },
  Item_9884_Name = {
    Text = "장미의 이름으로"
  },
  Item_9884_StoryDesc = {
    Text = "한 시골 처녀가 화려한 드레스, 금은보화, 깃털 부채를 장착하고 상류층 엘리트들의 세계에 발을 들이는 모습이라니……\n이보다 더 부적절한 일은 없을 겁니다. 아랫사람이 윗사람을 넘보는 것, 이건 정말 월권 행위에 다름없습니다……!\n내가 보기엔 하층민들에게 그에 걸맞은 표식과 뱃지를 강제로 착용하게 해야 한다고 생각합니다. 그렇게 해야만 우리와 혼동되지 않을 겁니다.\n—— 필립 해럴드 공작\n\n렌티니언에 살고 있다면 아마 '소렐 효과'라는 것을 들어본 적이 있을 겁니다.\n아직도 집에 쌓여 있는 옷을 팔 걱정을 하고 있나요? 그렇다면 당신이 조금이라도 연줄이 있기만을 빌어야 할 것입니다. 소렐 부인의 마음에 들어야 하니까요.—네, 비록 바보 같은 돼지꼬리 모양의 모자라고 할지라도, 소렐 부인이 그 모자를 쓰기만 한다면 불티나게 팔릴 겁니다.\n그녀는 이 시대의 새로운 대중 아이콘입니다.\n—— 「소렐 부인의 인기 테스트」, 《숙녀 가이드》\n\n그날은 맑고 화창한 여름밤이었습니다.\n우리는 대리석으로 꾸며진 테라스에 함께 앉아 오랜 숙성 과정을 거친 귀부 와인을 마시며 시와 세계 평화에 대해 담소를 나눴습니다.\n그리고 나서 무언가가 발생했습니다@4\n중요한 부분만 말하라구요? 흐음, 죄송합니다……\n어쨌든, 이 여자가 제게서 삼천 레오본과 수리란의 부동산 두 채, 그리고 진심 어린 마음 하나를 속여 빼앗아 갔다니까요!\n—— 이름을 밝히기 꺼리는 한 상심의 자작"
  },
  Item_9885_Desc = {
    Text = "꽃말: 내게 멀리 떨어져. \n낮은줄기 바다백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
