  },
  Item_99102_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “허세의 색채”를 선택할 수 있습니다.\n\n썩어가는 환상이 망막 위에 변이된 네온을 남기고——\n그래서 '색채'의 개념이 허상의 세계에서 승화되어, 현실타래의 시체 위에 남은 환각적인 화려한 색채가 흐릅니다."
  },
  Item_99102_Name = {
    Text = "허세의 색채색"
  },
  Item_99102_StoryDesc = {
    Text = "썩어가는 환상이 망막 위에 왜곡된 네온을 남기고——\n 그래서 '색채'의 개념이 허상의 세계에서 승화되어, 현실타래의 시체 위에 남은 망상적인 화려한 색채가 흐른다."
  },
  Item_9910_Desc = {
