  },
  Item_9912_Name = {Text = "지갑"},
  Item_9913_Desc = {
    Text = "코르트 대리 학장 특별 승인의 풍부한 보급품입니다.\n귀중한 자재가 담긴 나무 상자로, 밀경과실타래의 일일 시험 훈련과 주간 훈련 임무를 수행하는 수호자에게 도움을 제공합니다.\n다음 자재 중 하나를 선택하세요:\n순백의 서류*12\n정신을 가다듬다*12\n감성 부캐*12\n정신 템플릿*12"
  },
  Item_9913_Name = {
    Text = "Ⅰ급 보급 (이미 폐기됨)"
  },
  Item_9914_Desc = {
    Text = "전문가의 도움을 받아 열어주세요. \n 무광의 경계에서 획득 가능한 고대 미스터리를 담은 신비로운 나무 상자입니다. \n 기계장치의 신 미스터리 세트 구성품을 획득할 수 있습니다."
  },
  Item_9914_Name = {
    Text = "무질서 계약 그릇 Ⅲ"
  },
  Item_99150_Desc = {
    Text = "세상의 물은 순환한다. 다음 신생의 근원은 지난 썩은 시체에서 온다. \n랜덤 드롭 부식질 비밀 계약 세트 부품."
  },
  Item_99150_Name = {Text = "부패질"},
  Item_99158_Desc = {
    Text = "육체를 초월하여, 영생으로 진화한다.\n무작위로 비상 비밀 계약 세트 부품이 드롭됩니다."
  },
  Item_99158_Name = {Text = "비상"},
  Item_9915_Desc = {
    Text = "그들은 바다백합이 만개한 봄에 함께 살육하기로 약속했다.\n유인타 백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9915_Name = {
    Text = "유인타 백합"
  },
  Item_99163_Desc = {
    Text = "이 물에 담가, 인간 세상에 작별을 고하세요. \n랜덤 드롭으로 스틱스 비밀 계약 세트 부품이 획득됩니다."
  },
  Item_99163_Name = {Text = "스틱스"},
  Item_9916_Desc = {
    Text = "미사그 대학의 설립자가 개발한 약재로, 깨어남체의 능력을 향상시킨다. \n은심과 비밀의 약을 섞어 독특한 색을 띠고 있다."
  },
  Item_9916_Name = {
    Text = "영지 비약"
  },
  Item_9917_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 은열쇠 충전, 광기 충전 중 무작위 1개를 획득합니다."
  },
  Item_9917_Name = {
    Text = "광합성 제례 Ⅰ"
  },
  Item_9917_StoryDesc = {
    Text = "과학은 분광 분석이고, 예술은 광합성이다."
  },
  Item_9918_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9918_Name = {
    Text = "황야의 늑대 Ⅵ"
  },
  Item_9918_StoryDesc = {
    Text = "아우우우, 아우우우."
  },
  Item_9919_Desc = {
    Text = "날개는 단지 아름다움을 더할 뿐이며, 5펜시의 값어치가 있다. \n빛나는 나비 결정. 혼돈 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9919_Name = {
    Text = "빛나는 결정 나비"
  },
  Item_9920_Name = {
    Text = "여왕 학원의 문장"
  },
  Item_99213_Desc = {
    Text = "임시 텍스트"
  },
  Item_99213_Name = {
    Text = "스틱스Ⅰ"
  },
  Item_99213_StoryDesc = {
    Text = "이 물에 담가, 인간 세상에 작별을 고하세요."
  },
  Item_99214_Desc = {
