  },
  Item_99218_Desc = {
    Text = "「비상」 비밀계약 전사 시 하나의 부속성을 잠금할 수 있으며, 재료 교환 시 「천면 인장」으로 교환할 수 있습니다.\n\n불완전한 비밀 계약 파편이 간신히 접합된 형태로 콜렉션에 보관됩니다."
  },
  Item_99218_Name = {
