  },
  Item_99221_Desc = {
    Text = "“부식질” 미스틱 트랜스크립트 시 부속성 하나를 잠글 수 있으며, 재료 교환에서 “천면인장”으로 치환할 수 있습니다.\n\n불완전한 미스틱 파편은 간신히 이어붙인 상태로 컬렉션에 추가됩니다."
