  },
  Item_99233_StoryDesc = {
    Text = "이 물에 넣고, 인간에게 작별을 고하세요."
  },
  Item_9923_Desc = {
    Text = "주 속성으로 광기 충전 레벨, 죽음 저항, 은열쇠 충전 레벨과 피해 증폭 효과 중 랜덤으로 1개를 획득한다."
  },
  Item_9923_Name = {
    Text = "재진화 Ⅴ"
  },
  Item_9923_StoryDesc = {
    Text = "번식하라, 번식하라. 지모수의 피가 흐르는 영혼이 세상에 가득 차게 하라."
  },
  Item_9924_Desc = {
    Text = "이제는 아무도 이걸로 길흉을 점치지 못할 거야. \n융해진흙으로 덮인 보라색 수정, 초월계역의 깨어남체 스킬 레벨을 올리는데 사용됩니다."
  },
  Item_9924_Name = {
    Text = "부서진 광석"
  },
  Item_9925_Desc = {
    Text = "인류의 존속을 위해. \n액자에 보관된 의식. 혈육 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9925_Name = {
    Text = "의식 복사본"
  },
  Item_9926_Desc = {
    Text = "소중한 명륜이 담긴 오렌지색 예물상자로, 순수 수공예품입니다.\n학기 과제에서 우수한 성적을 거둔 수호자를 표창하기 위해 사용됩니다.\n다음 SSR 명륜 또는 아이템 중 하나를 선택하세요:\n「아쿠트의 봄」\n「태양의 추락」\n「영혼의 탄생」\n「루멘의 핵」×5"
  },
  Item_9926_Name = {
    Text = "과제 선물상자"
  },
  Item_9927_Desc = {
    Text = "꽃말: 내게 멀리 떨어져. \n낮은줄기 바다백합의 화석. 심해 영역 깨어남체의 스킬 레벨을 올릴 때 사용됩니다."
  },
  Item_9927_Name = {
    Text = "낮은줄기 바다백합"
  },
  Item_9928_Desc = {
    Text = "우리에게 미지의 인식을 부여한다.\n필린 시사의 특수 필름으로, 인간의 인식을 그 위에 새길 수 있다.\n초차원 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9928_Name = {
    Text = "인식 템플릿"
  },
  Item_9929_Name = {
    Text = "밀랍상 머리"
  },
  Item_9930_Desc = {
    Text = "세트: \n뒤틀린 쌍둥이·백Ⅰ\n뒤틀린 쌍둥이·백Ⅱ\n뒤틀린 쌍둥이·백Ⅲ\n뒤틀린 쌍둥이·백Ⅳ\n뒤틀린 쌍둥이·백Ⅴ\n뒤틀린 쌍둥이·백Ⅵ"
  },
  Item_9930_Name = {
    Text = "뒤틀린 쌍둥이·백"
  },
  Item_9931_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9931_Name = {
    Text = "바다에서 돌아오는 길 Ⅲ"
  },
  Item_9931_StoryDesc = {
    Text = "돌아오라, 잊혀진 그 도시가 재현될 것이다."
  },
  Item_9932_Desc = {
    Text = "부는 석판에 보호의 룬을 새기고, 모든 생명에게 자비로운 기도말씀을 전합니다. \n·산출력 소모 감소 \n·방어막을 부여하면서 데미지를 입힙니다"
  },
  Item_9932_Name = {
    Text = "살바도르"
  },
  Item_9934_Desc = {
    Text = "세트: \n약재의 꿈 Ⅰ\n약재의 꿈 Ⅱ\n약재의 꿈 Ⅲ\n약재의 꿈 Ⅳ\n약재의 꿈 Ⅴ\n약재의 꿈 Ⅵ"
  },
  Item_9934_Name = {
    Text = "약재의 꿈"
  },
  Item_9935_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다. 당신의 본능, 당신의 이성, 심지어 당신의 영혼까지... 결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9935_Name = {
    Text = "연마된 본능"
  },
  Item_9938_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n고리아를 반복 획득할 때 전환하여, 고리아의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9938_Name = {
    Text = "파편 · 골리아"
  },
  Item_9938_StoryDesc = {
    Text = "고리아를 중복으로 획득했을 때 전환하여, 고리아의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9940_Desc = {
    Text = "역사는 반복되지만, 우주는 예외일지도 모른다. \n신비한 글귀가 적힌 페이지로, 혼돈 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9940_Name = {
    Text = "순백의 조각"
  },
  Item_9941_Desc = {
    Text = "규정을 준수해 주세요.\n코르트 대리 학장이 직접 승인한 허가증. 조사를 개시하거나, 더 위험한 막간 훈련을 진행할 때 필요하다."
  },
  Item_9941_Name = {
    Text = "연구 허가증 (이미 폐기됨)"
  },
  Item_9942_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 회복, 검은 인장 드롭율, 은열쇠 충전 중 무작위 1개를 획득합니다."
  },
  Item_9942_Name = {
    Text = "이율배반 Ⅳ"
  },
  Item_9942_StoryDesc = {
    Text = "필연, 우연. 유한, 무한."
  },
  Item_9943_Desc = {
    Text = "장착자의 반격 획득량이 증가하고, 피해를 받을 때마다 임시 힘을 획득합니다."
  },
  Item_9943_Name = {
    Text = "떠도는 욕망"
  },
  Item_9943_StoryDesc = {
    Text = "덩, 덩, 덩. \n 발자국 소리가 멀리서 가까워지며, 모자를 쓴 신사가 폐허를 지나, 기진맥진한 감시자 앞에 섰다. \n 신사: 여기서 뭐하고 있습니까? \n\n (신사는 심한 말더듬이를 앓고 있고, 감시자는 빙빙 돌며 이야기하는 것을 좋아한다. 독자의 편의를 위해, 필자는 대화의 요점만 발췌했다.) \n\n 감시자: 저는 감옥을 지키고 있습니다. \n 신사는 주위를 둘러보며 텅 빈 들판과 융식에 오염되어 천천히 무너져가는 폐허의 잔해를 바라보았다. \n 신사: 하지만 여기에는 감옥도 없고, 죄수도 없습니다. 당신의 왕국은 이미 존재하지 않습니다. \n 감시자: 저는 감옥을 지키고 있습니다. \n 신사: 왜요? \n 감시자는 고개를 들고, 어린아이 같은 얼굴에 혼란과 단호함이 가득했다. \n 감시자: 모르겠습니다… 집으로 돌아가고 싶어요. \n 감시자: 저는 그 분을 위해 감옥을 지키고 있습니다. 그 분이 기쁘면, 저는 집으로 돌아갈 수 있어요. \n 그 분이 누구인지, 왜 그를 대신해 지키는지, 그녀 자신도 잘 모르겠다. \n 신사는 더 이상 질문하지 않았다. 마치 그게 너무나 자연스러운 일인 것처럼. \n 신사: 당신의 고향, 어떤 곳인가요? \n 감시자: 거기에는 겨울과 밤만 있고, 끝없이 펼쳐진 숲과 바다가 있습니다. \n 신사: 듣기엔 거주하기에 부적합한 곳이네요. \n 감시자: 저는 낮이 싫어요. 보셨나요, 저는 왁스로 만들어졌어요. 태양에 닿으면, 저는 사라져요. \n 감시자: 그래서 저는 여기 숨을 수밖에 없어요, 스스로 집으로 돌아갈 수 없어요. \n 신사는 무언가를 깊이 생각하며 고개를 끄덕였다. 그는 갑자기 흥분하기 시작했다. \n 신사: 정말 우연이네요, 당신은 왁스으로 만들어졌고, 저는 바로 왁스상 제작자입니다. \n 신사: 우리 약속을 하죠—— 저는 당신이 햇빛 아래에서 걸을 수 있게 해줄 수 있고, 당신이 집으로 돌아가는 길을 찾는 것도 도와줄 수 있어요. 그 대가로, 당신은 제 조수가 되어야 해요. \n 감시자: 조수, 그건 뭐하는 건가요? \n 신사: 당신은 저를 대신해 왁스상관을 지킬 수 있어요. 그것은 이 감옥과는 다르고, 예술입니다. 예술은 무너지지 않아요. \n 감시자: 예술이 그렇게 대단한가요? \n 신사는 기쁜 듯 웃기 시작했다. \n 신사: 네, 그렇게 대단해요. \n\n 이야기의 끝에서, 감시자는 어리둥절하게 신사를 따라갔다. 마치 그녀가 이 감옥에 어리둥절하게 온 것처럼. \n 그녀는 항상 순응하는 성격이었다."
  },
  Item_9944_Desc = {
    Text = "그녀의 파일은 여러 번 학생 관리처로 이관되었지만, 그녀가 직접 받아와서 책더미 아래에 묻었습니다. \n·보조를 제공하여 전투 상황을 완화\n·강력한 방향성 지원"
  },
  Item_9944_Name = {Text = "라모나"},
  Item_9945_Desc = {
    Text = "기획자 테스트용 SSR 무기"
  },
  Item_9945_Name = {
    Text = "시험 제작 레이저 포 (경계역) 개발용"
  },
  Item_9945_StoryDesc = {Text = "미완성"},
  Item_9946_Desc = {
    Text = "인류의 존속을 위해. \n액자에 보관된 감정. 혈육 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9946_Name = {
    Text = "감정 복사본"
  },
  Item_9947_Desc = {
    Text = "보유자가 생성하는 광기를 증가시키고, 광기 폭발 후 일정량의 은열쇠 에너지를 얻습니다."
  },
  Item_9947_Name = {
    Text = "끝나지 않는 계산"
  },
  Item_9947_StoryDesc = {
    Text = "거대한 탑이 우르르 무너지며, 다른 시공과 다른 종족의 학자들이 쓴 책들이 사방에 흩어졌습니다. 단 한순간, 크고 작은 검은 삼각형들이 모든 책과 모든 벽돌 위를 뒤덮었고, 곧바로 하나로 연결되어 사방으로 확산되었습니다.\n검은 점액이 마치 용암처럼 정돈된 거리 위를 흐르기 시작했고, 사람들은 비명을 지르며, 울부짖으며 이 끔찍한 재앙에서 벗어나려 했습니다. 많은 이들이 교통수단을 이용해 탈출을 시도했으나, 혼란 속에서 건축물이나 다른 사고 난 우주선 및 차량과 충돌하였고, 더 많은 사람들은 반응할 새도 없이 검은 점액에서 멀어지는 방향으로 도망쳤지만, 마찬가지로 억겁의 두려움 속 다른 사람들에게 밀쳐져 결국 점액에 흡수되게 되었습니다. 길 모퉁이에 아이들이 큰 소리로 울었고, 몇몇 젊은이들은 남아 있는 건물 내에 숨으며, 그렇게 해서 죽음을 피할 수 있다고 헛된 희망을 품었습니다.\n「분명 아무 예고도 없었는데, 왜, 왜!」\n「왜 우리를 미리 경고하지 않았던 거지!」\n「@1, 융해야! 살려줘!」\n「빨리 의식을 전이시켜! 그 방법만——아!」\n「@2, 빨리 기기를 써!」 한 목소리가 말했다. 「우리가 시간을 벌어줄게!」\n「싫어! 나는——」\n「우리는 이미 @1에게 당했어. 하지만 너는, 너라면 희망이 남아 있어.」 한 부드러운 목소리가 답했다. 「살아남아, @2, 살아남아. 그리고——」\n\n웬컬은 갑자기 눈을 번쩍 뜨며, 그녀의 주변에 높이 쌓인 책들과 다수의 커피 얼룩이 묻은 머그잔들이 있음을 확인했습니다. 조금 떨어진 칠판에는 크고 작은 메모와 노트들이 붙어 있고, 미완성 상태의 연산 공식이 적혀 있었습니다. 지저분한 방 구석구석, 중앙, 그리고 그녀가 있는 거대한 기기 옆에는 램프들이 자리 잡고 있어, 사무실타래 전체가 환히 빛나고 있었습니다.\n그녀는 잠시 침묵하다가 몸을 더 위치 추적기 안으로 수그리며, 중단했던 연산을 계속했습니다."
  },
  Item_9948_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
