  Item_9957_Desc = {
    Text = "예의를 지키고 의리를 지키며, 자신을 엄격히 다스리는 오지에는 언제나 학생들이 가장 신뢰하고 환영하는 깨어남체입니다. \n- 강력한 방어막 부여 \n- 팀의 크리티컬 확률 상승"
