  Item_9963_Desc = {
    Text = "바람이 새는 집. 그래도 없는 것보다는 낫다.\n유적에 남겨진 번데기 껍질. 혈육 경계역 깨어남체의 스킬 레벨을 향상시키는 데 사용됩니다。"
