  Item_9965_Name = {
    Text = "마른 번데기"
  },
  Item_9966_Desc = {
    Text = "이 작은 차가운 눈물에 대해 경시하지 마세요—그것은 세계를 창조할 수 있습니다. \n눈물 모양의 액체 결정체로, “초월적 존재”의 드롭 아이템을 합성하는 데 사용할 수 있습니다."
