  },
  Item_9967_Desc = {
    Text = "그것은 고대 의지의 잃어버린 영식입니다. 미사그는 신비한 의식을 통해 깨어남체의 기령을 깨어남시키며, 깨어남된 깨어남체는 정신 능력을 영구적으로 강화시킵니다.\n중복으로 파인트를 획득할 때 변환하여, 파인트의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9967_Name = {
    Text = "파편 · 파인트"
  },
  Item_9967_StoryDesc = {
    Text = "중복으로 파인트를 획득할 때 변환하여 얻으며, 파인트의 기령을 활성화하는 데 사용됩니다."
  },
  Item_9968_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9968_Name = {
    Text = "재진화 Ⅲ"
  },
  Item_9968_StoryDesc = {
    Text = "번식하라, 번식하라. 지모수의 피가 흐르는 영혼이 세상에 가득 차게 하라."
  },
  Item_9969_Desc = {
    Text = "주 속성으로 영역 숙련, 광기 충전 레벨, 검은 인장 드롭율과 은열쇠 충전 중 랜덤으로 1개를 획득한다."
  },
  Item_9969_Name = {
    Text = "먼 곳의 잔치 Ⅳ"
  },
  Item_9969_StoryDesc = {
    Text = "즐겁게 잔치를 즐겨라, 노랫소리 속에서."
  },
  Item_9970_Name = {
    Text = "융해·돌"
  },
  Item_9971_Desc = {
    Text = "그렇다, 모든 것은 연마될 수 있다.\n당신의 본능, 당신의 이성, 심지어 당신의 영혼까지...\n결국 당신은 저들과 크게 다르지 않다는 걸 알게 될 것이다.\n심해 영역 깨어남체의 승급에 사용되는 재료입니다."
  },
  Item_9971_Name = {
    Text = "연마된 영혼"
  },
  Item_99724_Desc = {
    Text = "이 열쇠를 기록한 후, 편성 시 열쇠 능력: 「눈물 흘리는 성심」을 선택할 수 있습니다.\n\n그는 마침내 모든 기억과 힘을 되찾았지만, 그것은 지키고 싶었던 모든 것을 대가로 치른 것이었습니다.\n그는 이미 너무 늦게 왔습니다.\n 오직 분노와 후회의 피눈물이 떨리는 심장을 태우고 있습니다."
  },
  Item_99724_Name = {
    Text = "피눈물의 성심"
  },
  Item_99724_StoryDesc = {
    Text = "그는 마침내 모든 기억과 힘을 되찾았지만, 그것은 지키고 싶었던 모든 것을 대가로 치른 것이었습니다.\n그는 이미 너무 늦게 왔습니다.\n 오직 분노와 후회의 피눈물이 떨리는 심장을 태우고 있습니다."
  },
  Item_9972_Name = {
    Text = "도해자 로고 선명한 버전"
  },
  Item_9974_Desc = {
    Text = "장착자의 중독 부여 및 회복 능력이 향상되고, 광기 폭발을 사용한 후 소량의 HP를 회복합니다."
  },
  Item_9974_Name = {
    Text = "소리 없는 잔치"
  },
  Item_9974_StoryDesc = {
    Text = "예리완 사람들은 회색 돌의 도시에서 살고 있으며, 녹색의 큰 호수와 이웃하고 있습니다.\n\n큰 호수는 이름이 없으며, 예리완 사람들이 기억하기 시작한 때부터 존재해왔습니다.\n전해지기를, 사악한 여마가 호수 깊은 곳에 봉인되어 있습니다.\n그녀는 큰 호수와 마찬가지로 고대이며, 혼돈의 시작에 거칠게 형성된 무서운 존재입니다.\n천진난만하고 겁이 많은 예리완 사람들은 여마를 두려워하여 그녀를 달래려고 하며, 그녀가 영원히 호수 바닥에 조용히 머물 수 있도록 합니다.\n\n“뭘 해야 할까?”\n“그래, 뭘 해야 할까?”\n“그럼 춤을 추자! 어쨌든 춤추는 것은 항상 좋으니까.”\n\n그래서 매 보름달마다 예리완 사람들은 호숫가에 모여, 종이와 갈대로 만든 우상 앞에서 경쾌하게 춤을 춥니다.\n그때는 달이 밝고 별이 드물어 모든 것이 평화로웠습니다.\n\n수백 년 후, 예리완 사람들은 역사와 우화를 잊고, 우상도 잊었습니다.\n돌의 도시 건설 천년 기념일에 그들은 방종하게 웃고, 좋은 술을 마십니다.\n시끄러운 소음이 호수 속으로 던져지며, 마치 돌이 물에 떨어지는 것처럼, 무한한 원을 그리며 호수 중앙에서 퍼져나가 결국 깊은 곳의 존재에 닿습니다.\n그래서 보름달이 뜨던 날, 예리완 사람들은 소리의 범위를 넘어서는 소리를 듣고, 시각의 범위를 넘어서는 달과 불꽃을 보았습니다.\n그들은 결국 고요의 일부가 되었습니다.\n\n이 무한한 공간 안의 영원한 고요는 예리완 사람들에게 공포를 안겨주었습니다.\n그들은 신비주의자처럼 가만히 앉아 있어야 했고, 새로운 집단이 그들 앞에서 방종하게 웃고, 좋은 술을 마시며 오고 가는 것을 목격했습니다.\n그래서 우주는 영원히 계속 팽창하고, 은하들은 점점 더 멀어지며, 모든 것은 사라질 것입니다.\n사실타래은 이렇습니다.\n예리완 사람들이 이에 대해 외롭다고 느끼는 것은 전혀 중요하지 않습니다."
  },
  Item_9975_Desc = {
    Text = "수호자에게 제공되는 월간 린피테이프 보급품. 단순하면서도 효과가 즉시 나타난다."
  },
  Item_9975_Name = {
    Text = "일일 보급 패키지"
  },
  Item_9976_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
