  },
  Item_9977_Desc = {
    Text = "24의 머리는 조금 혼란스러웠다——그녀들은 어둠 속에서 속삭이고, 웃음을 터뜨리며 그녀의 마음을 찢어놓았다. \n·적을 처치한 후 관문 내 데미지 증가 \n·팀의 광기 폭발 데미지 강화"
  },
  Item_9978_Desc = {
    Text = "주 속성으로 크리티컬 확률, 크리티컬 피해, 영역 숙련, 검은 인장 드롭율 중 무작위 1개를 획득합니다."
