  Item_9979_Desc = {
    Text = "은열쇠 충전 속성의 명륜입니다."
  },
  Item_9979_Name = {Text = "활성"},
  Item_9979_StoryDesc = {
    Text = "죽음의 순간이 드리워질 때, 삶에 대한 갈망이 분출된다."
  },
  Item_9980_Desc = {
    Text = "주 속성으로 치명타 확률, 치명타 피해, 은열쇠 충전 레벨과 광기 충전 레벨 중 랜덤으로 1개를 획득한다."
