  },
  Item_9988_Name = {
    Text = "달콤한 달팽이 Ⅵ"
  },
  Item_9988_StoryDesc = {
    Text = "달콤하고, 끈적거린다."
  },
  Item_9989_Desc = {
    Text = "세트: \n36호실타래의 고리Ⅰ\n36호실타래의 고리Ⅱ\n36호실타래의 고리Ⅲ\n36호실타래의 고리Ⅳ\n36호실타래의 고리Ⅴ\n36호실타래의 고리Ⅵ"
