  },
  Item_9990_StoryDesc = {
    Text = "환형 시간의 틈새를 떠다니는 것."
  },
  Item_9991_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “불평등한 교환”을 선택할 수 있습니다. \n\n미사그는 항상 나와 그 상인과의 과도한 접촉을 반대해왔지만, 만약 모든 사람을 이 진흙탕에서 해방시키기 위한 것이라면……"
  },
  Item_9991_Name = {
