  Item_9994_Desc = {
    Text = "주 속성으로 광기 회복, 죽음 저항, 은열쇠 충전, 피해 증폭 중 무작위 1개를 획득합니다."
  },
  Item_9994_Name = {
    Text = "이율배반 Ⅴ"
  },
  Item_9994_StoryDesc = {
    Text = "필연, 우연. 유한, 무한."
  },
  Item_9995_Desc = {
    Text = "이 키오링을 기록한 후, 배치 시 키오링 스킬: “불멸의 장례식”을 선택할 수 있습니다. \n\n나는 그녀에게 도움을 주지 못했습니다. 그녀는 혼자서 가짜 신의 강림을 막았습니다. \n그녀의 영혼은 사라지지 않을 것이며, 그녀는 영원히 자유의 별로 빛날 것입니다."
  },
  Item_9995_Name = {
    Text = "불멸의 장례식"
  },
  Item_9995_StoryDesc = {
    Text = "나는 그녀에게 도움을 주지 못했습니다. 그녀는 혼자서 가짜 신의 강림을 막았습니다. \n그녀의 영혼은 사라지지 않을 것이며, 그녀는 영원히 자유의 별로 빛날 것입니다."
  },
  Item_9996_Desc = {
    Text = "주 속성으로 영역 숙련, 검은 인장 드롭율, 죽음 저항, 피해 증폭 중 무작위 1개를 획득합니다."
