  Item_9996_StoryDesc = {
    Text = "돌아오라, 잊혀진 그 도시가 재현될 것이다."
  },
  Item_9997_Desc = {
    Text = "영역 숙련 속성의 명륜입니다."
  },
  Item_9997_Name = {Text = "추방"},
  Item_9997_StoryDesc = {
    Text = "내 영혼은 무덤이다."
  },
  Item_9998_Desc = {
    Text = "소지자의 생명 회복 능력을 높이고, 피해를 받을 경우 이를 방패와 일시적인 힘으로 변환할 수 있습니다."
