  Item_9998_StoryDesc = {
    Text = "<Bold:1월24일>\n몸에서 악취가 난다.\n오늘 가정부 테레사와 함께 차를 타고 집으로 오다 남암프 지역을 지나갔다.\n그곳은 쾌적한 경험이 아니었다.\n그곳은 위험한 곳@2 어떤 사람들은 몸에 이상한 상처가 있었다. 삼각형 모양의 구멍 같은 것.\n테레사 가정부는 그게 이교도에게 주님의 강림이 내린 벌이라고 했다.\n\n<Bold:2월22일>\n한 달 동안 열이 났다.\n오늘 드디어 음식을 먹었다. 신선한 스테이크였다. 부드럽고 육즙이 풍부하고……\n그래, 육즙.\n붉은@2 비리고 달콤한@2 맛있는\n집안의 모든 거울이 치워졌고, 심지어 포비조차 나를 보고 싶어 하지 않았다.\n히히. 그들은 아무것도 모른다. 밤이 되면 창문의 그림자에서 내 모습을 볼 수 있다.\n내 얼굴, 목, 가슴…… 위에서 아래까지, 빽빽이\n검은@2 삼각형으로 가득 차 있다\n\n<Bold:3월17일>\n내 각막이 빨간색의 얇은 베일로 덮인 것 같다.\n세상이 피의 색으로 변했다@3\n아버지가 피안개 속에서 소리를 지르며 나를 향해 외쳤다. 그가 이렇게 큰 목소리로 나에게 이야기한 것은 처음이었다.\n그는 내 가까이에 있었지만, 목소리는 멀리 있었다. 나는 절망, 혐오, 그리고 피의 냄새를 맡았다.\n나를@2 데려가지 말아줘, 제발……"
